# argparse translates every string it formats via gettext, but `gettext.find()` does not
# cache its misses, so each call rescans the whole localedir. GEF evaluates
# `parser.format_help()` at import time for each of its 400+ commands, which makes this
# lookup the single largest part of the load time. There is no `messages` catalog for
# argparse anyway, so make the translation a no-op while this file is being imported and
# restore it at the very bottom. This is exactly what argparse itself falls back to when
# `gettext` is unavailable.
ARGPARSE_GETTEXT = argparse._
argparse._ = lambda message: message


def http_get(url):
    """Basic HTTP wrapper for GET request."""
    import urllib.request
    try:
        req = urllib.request.Request(url)
        req.add_header("Cache-Control", "no-cache, no-store")
        http = urllib.request.urlopen(req, timeout=5)
        if http.getcode() != 200:
            return None
        return http.read()
    except Exception:
        return None


def update_gef(argv):
    """Try to update `gef` to the latest version."""
    gef_local = os.path.realpath(argv[0])
    hash_gef_local = hashlib.sha512(open(gef_local, "rb").read()).digest()
    gef_remote = "https://raw.githubusercontent.com/bata24/gef/dev/gef.py"
    gef_remote_data = http_get(gef_remote)
    if gef_remote_data is None:
        print("[-] Failed to get remote gef")
        return 1

    hash_gef_remote = hashlib.sha512(gef_remote_data).digest()
    if hash_gef_local == hash_gef_remote:
        print("[-] No update")
    else:
        tmp_fd, tmp_local = tempfile.mkstemp(dir=os.path.dirname(gef_local), prefix="gef-")
        with os.fdopen(tmp_fd, "wb") as f:
            f.write(gef_remote_data)
        os.chmod(tmp_local, os.stat(gef_local).st_mode & 0o7777)
        os.replace(tmp_local, gef_local)
        print("[+] Updated")
    return 0


try:
    # GEF determines whether it is inside or outside gdb
    # based on whether it can import the gdb module.
    import gdb
except ImportError:
    # If out of gdb, the only action allowed is to update gef.py.
    # No further code will be executed.
    if len(sys.argv) == 2 and sys.argv[1].lower() in ("--update", "--upgrade", "-u"):
        ret = update_gef(sys.argv)
        sys.exit(ret)
    else:
        print("[-] gef cannot run as standalone")
        sys.exit(0)


