def perf(f): # noqa
    """Decorator wrapper to measure performance."""

    @functools.wraps(f)
    def wrapper(*args, **kwargs):
        import line_profiler
        pr = line_profiler.LineProfiler()
        pr.add_function(f)
        pr.enable()
        ret = f(*args, **kwargs)
        pr.disable()
        s = io.StringIO()
        pr.print_stats(stream=s)
        print(s.getvalue())
        return ret

    return wrapper


def cperf(f): # noqa
    """Decorator wrapper to measure performance."""

    @functools.wraps(f)
    def wrapper(*args, **kwargs):
        import cProfile
        import pstats
        pr = cProfile.Profile()
        pr.enable()
        ret = f(*args, **kwargs)
        pr.disable()
        s = io.StringIO()
        #sortby = pstats.SortKey.CUMULATIVE
        sortby = pstats.SortKey.TIME
        ps = pstats.Stats(pr, stream=s).sort_stats(sortby)
        ps.print_stats(20)
        print(s.getvalue())
        return ret

    return wrapper


class DisplayHook:
    """It enables pretty printing of list, dict, set, and so on.
    It also displays in hexadecimal by default."""

    @staticmethod
    def pp(o, idt):
        """Create a string for pretty print recursively."""

        def I1(idt):
            """Create an indent for current level."""
            return "  " * idt

        def I2(idt):
            """Create an indent for next level."""
            return "  " * (idt + 1)

        def R(o, idt):
            return [DisplayHook.pp(x, idt + 1) for x in o]

        def R1(o, idt):
            """Return a string of the elements concatenated with commas (for list, tuple, set, ...)."""
            return ", ".join(R(o, idt))

        def R2(o, idt):
            """Return a list of the elements with indentation and commas (for list, tuple, set, ...)."""
            return [I2(idt) + x + "," for x in R(o, idt)]

        def Z(s, e, o, idt):
            """Return a string of the elements concatenated with commas (for list, tuple, set, ...),
            taking into account the width of the screen."""
            # Create a string without newlines and return it if it's short enough.
            f = s + R1(o, idt) + e
            if len(f) < width:
                return f
            # Return a string with a newline for each element.
            f = [s] + R2(o, idt) + [I1(idt) + e]
            return "\n".join(f)

        def RD(o, idt):
            return [DisplayHook.pp(k, idt + 1) + ": " + DisplayHook.pp(v, idt + 1) for k, v in o]

        def RD1(o, idt):
            """Return a string of the elements concatenated with commas (for dict, ...)."""
            return ", ".join(RD(o, idt))

        def RD2(o, idt):
            """Return a list of the elements with indentation and commas (for dict, ...)."""
            return [I2(idt) + x + "," for x in RD(o, idt)]

        def ZD(s, e, o, idt):
            """Return a string of the elements concatenated with commas (for dict, ...),
            taking into account the width of the screen."""
            # Create a string without newlines and return it if it's short enough.
            f = s + RD1(o, idt) + e
            if len(f) < width:
                return f
            # Return a string with a newline for each element.
            f = [s] + RD2(o, idt) + [I1(idt) + e]
            return "\n".join(f)

        name = type(o).__name__
        width = GefUtil.get_terminal_size()[1] - len(I1(idt))

        if name in ("int", "long"):
            return hex(o)

        if name == "list":
            return Z("[", "]", o, idt)

        elif name == "tuple":
            return Z("(", ")", o, idt)

        elif name == "set":
            return Z("{", "}", o, idt)

        elif name == "dict":
            return ZD("{", "}", o.items(), idt)

        elif name == "dict_keys":
            return Z("dict_keys([", "])", o, idt)

        elif name == "dict_values":
            return Z("dict_values([", "])", o, idt)

        elif name == "dict_items":
            return ZD("dict_items([", "])", o, idt)

        elif name == "Zone":
            return re.sub(r"(zone_start=|zone_end=)(\d+)", lambda x:x.group(1) + hex(int(x.group(2))), str(o))

        elif name == "Table":
            f = "Table(arch={!r}, mode={!r}, name_table={{...}}, nr_table={{\n".format(o.arch, o.mode)
            f += "\n".join(RD2(o.nr_table.items(), idt))
            f += "\n" + I1(idt) + "})"
            return f

        elif name == "Kinfo":
            f = "Kinfo(\n"
            f += I1(idt + 1) + "text_base=" + DisplayHook.pp(o.text_base, 0) + ", "
            f += "text_size=" + DisplayHook.pp(o.text_size, 0) + ", "
            f += "text_end=" + DisplayHook.pp(o.text_end, 0) + ",\n"
            f += I1(idt + 1) + "ro_base=" + DisplayHook.pp(o.ro_base, 0) + ", "
            f += "ro_size=" + DisplayHook.pp(o.ro_size, 0) + ", "
            f += "ro_end=" + DisplayHook.pp(o.ro_end, 0) + ",\n"
            f += I1(idt + 1) + "rw_base=" + DisplayHook.pp(o.rw_base, 0) + ", "
            f += "rw_size=" + DisplayHook.pp(o.rw_size, 0) + ", "
            f += "rw_end=" + DisplayHook.pp(o.rw_end, 0) + ",\n"
            f += I1(idt + 1) + "rwx=" + DisplayHook.pp(o.rwx, 0) + ", "
            f += "has_none=" + DisplayHook.pp(o.has_none, 0) + ", "
            if o.maps is None:
                f += "maps=" + DisplayHook.pp(o.maps, 0) + ",\n"
            else:
                f += "maps=[\n"
                f += "\n".join(R2(o.maps, idt + 1))
                f += "\n" + I1(idt + 1) + "]\n"
            f += I1(idt) + ")"
            return f

        elif name == "Entry":
            f = "Entry(\n"
            f += I2(idt) + "nr={:#x},\n".format(o.nr)
            f += I2(idt) + "name={!r},\n".format(o.name)
            f += I2(idt) + "ret_regs={!s},\n".format(o.ret_regs)
            f += I2(idt) + "arg_regs={!s},\n".format(o.arg_regs)
            f += I2(idt) + "args_full={!s},\n".format(o.args_full)
            f += I2(idt) + "args={!s},\n".format(o.args)
            f += I1(idt) + ")"
            return f
        return repr(o)

    @staticmethod
    def displayhook(o): # noqa
        """An alternative to the default display function."""
        builtins._ = o # noqa

        if o is None:
            return

        out = DisplayHook.pp(o, 0)
        print(out)
        return


def hexon(): # noqa
    """Replace the print function that is implicitly called when running "python-interactive 1" etc."""
    sys.displayhook = DisplayHook.displayhook # noqa
    return


def hexoff(): # noqa
    """Revert the print function that is implicitly called when running "python-interactive 1" etc."""
    sys.displayhook = sys.__displayhook__ # noqa
    return


class Cache:
    """Manage the gef cache. The 2 types are named after what invalidates them.
    "until_next": a step, or a memory or register change.
    "this_session": the target itself changing (exit, `set_arch`, `gef reset-cache`, `--rescan`).
    A `this_session` entry declared `until_new_objfile=True` is dropped when a symbol file is loaded too.
    Note: each command may have its own cache outside this mechanism. Not all caches are centralized here."""

    __gef_caches__ = {"until_next": {}, "this_session": {}}
    __objfile_caches__ = [] # the `this_session` caches that a newly loaded symbol file stales

    @staticmethod
    def cpu_context():
        """Return the identifier of the current CPU context, i.e., the selected gdb thread.
        Some kernel heuristics return a different answer depending on which CPU is selected,
        so their cache must be separated by this value."""

        try:
            thread = gdb.selected_thread()
        except Exception:
            return None
        if thread is None:
            return None
        return getattr(thread, "global_num", None) or thread.num

    # A marker that never compares equal to a user argument, so a key built from kwargs
    # cannot collide with a key that is the bare `args` tuple.
    __kwargs_marker__ = object()

    @staticmethod
    def cache_wrap(life_time, f, cache_None=True, per_cpu=False, until_new_objfile=False):
        # The name and the per-function dict are resolved once here instead of on every call.
        # The dict is therefore kept alive across resets, so the reset clears it in place.
        fname = f"{f.__module__}:{f.__qualname__}"
        fcache = Cache.__gef_caches__[life_time].setdefault(fname, {})
        if until_new_objfile:
            Cache.__objfile_caches__.append(fcache)

        @functools.wraps(f)
        def wrapper(*args, **kwargs):
            if kwargs:
                key = (Cache.__kwargs_marker__, args, tuple(sorted(kwargs.items())))
            else:
                key = args
            if per_cpu:
                key = (Cache.cpu_context(), key)

            try:
                return fcache[key]
            except KeyError:
                ret = f(*args, **kwargs)
                if cache_None or ret is not None:
                    fcache[key] = ret
                return ret
            except TypeError as e:
                bad = []
                for i, a in enumerate(args):
                    try:
                        hash(a)
                    except TypeError:
                        bad.append("args[{:d}]: {:s}".format(i, type(a).__name__))
                for k, v in kwargs.items():
                    try:
                        hash(v)
                    except TypeError:
                        bad.append("{:s}: {:s}".format(k, type(v).__name__))
                raise TypeError(
                    "Cache: {:s} got an unhashable argument ({:s}), so it cannot be cached. "
                    "Pass a hashable value, e.g. tuple(x) instead of a list.".format(fname, ", ".join(bad))
                ) from e

        return wrapper

    @staticmethod
    def cache_until_next(f=None, *, cache_None=True, per_cpu=False):
        """Decorator for the "until_next" cache.
        Usable bare (`@Cache.cache_until_next`) or with options
        (`@Cache.cache_until_next(cache_None=False)`)."""

        if f is None: # called with options
            return functools.partial(
                Cache.cache_until_next, cache_None=cache_None, per_cpu=per_cpu,
            )
        if not callable(f):
            raise TypeError("Cache.cache_until_next: the options must be keyword arguments")
        return Cache.cache_wrap("until_next", f, cache_None=cache_None, per_cpu=per_cpu)

    @staticmethod
    def cache_this_session(f=None, *, cache_None=True, per_cpu=False, until_new_objfile=False):
        """Decorator for the "this_session" cache.
        Usable bare (`@Cache.cache_this_session`) or with options
        (`@Cache.cache_this_session(cache_None=False)`).
        Set `until_new_objfile` if loading a symbol file can change the value."""

        if f is None: # called with options
            return functools.partial(
                Cache.cache_this_session, cache_None=cache_None, per_cpu=per_cpu,
                until_new_objfile=until_new_objfile,
            )
        if not callable(f):
            raise TypeError("Cache.cache_this_session: the options must be keyword arguments")
        return Cache.cache_wrap("this_session", f, cache_None=cache_None, per_cpu=per_cpu,
                                until_new_objfile=until_new_objfile)

    @staticmethod
    def reset_gef_caches(all=False, new_objfile=False):
        """Clear the gef caches. By default only `until_next`.
        `all` also clears `this_session`.
        `new_objfile` clears the `this_session` entries declared `until_new_objfile`."""

        for fcache in Cache.__gef_caches__["until_next"].values():
            fcache.clear()
        MemoryCache.reset()
        Color.cached_disabled = None

        if all:
            for fcache in Cache.__gef_caches__["this_session"].values():
                fcache.clear()
        elif new_objfile:
            for fcache in Cache.__objfile_caches__:
                fcache.clear()

        # gdb cache
        try:
            gdb.execute("maintenance flush dcache", to_string=True)
        except Exception:
            pass
        return

    @staticmethod
    def peek_cache_for(f, *args):
        """Return the cached value of `f(*args)` without calling it, or None if it is not
        cached yet. For the callers that must not trigger the computation, e.g. to avoid
        a recursion. A function declared `cache_None=False` never stores None, so None
        always means "not resolved yet"."""

        fname = f"{f.__module__}:{f.__qualname__}"
        if hasattr(f, "__self__"):
            args = (f.__self__,) + args
        for caches in Cache.__gef_caches__.values():
            fcache = caches.get(fname)
            if fcache is not None:
                return fcache.get(args)
        return None

    @staticmethod # noqa
    def clear_cache_for(f):
        """Clear the cache of specified function."""

        fname = f"{f.__module__}:{f.__qualname__}"
        for caches in Cache.__gef_caches__.values():
            caches.get(fname, {}).clear()
        return


class MemoryCache:
    """A read-through block cache for `read_memory`.

    The cost of reading memory via a remote gdb stub is dominated by the number of
    round trips, not by the size (with qemu-system, 8 bytes costs 95us while 4096 bytes
    costs 303us). Reading a whole block at once and reusing it makes many commands
    1.2x-9.2x faster. A local inferior is much cheaper (1.41us vs 1.47us), so the gain
    is small there, but reading a whole block does not cost more either.
    Note: this reads more bytes than requested, so it may touch the neighbor registers
    of a memory mapped device. Use `gef config gef.disable_memory_cache True` in that case."""

    BLOCK_SIZE = 0x1000
    BLOCK_SIZE_SLOW = 0x40 # over a serial line, a large block costs more than it saves
    MAX_BLOCKS = 0x1000 # 16MB at most, for a huge scan like `ks -rv`

    __blocks__ = {}
    __unreadable__ = set()

    @staticmethod
    @Cache.cache_until_next
    def get_policy():
        """Return (block_size, per_cpu). block_size == 0 means the cache is disabled."""
        if Config.get_gef_setting("gef.disable_memory_cache") is True:
            return 0, False
        if is_kgdb() or is_over_serial():
            return MemoryCache.BLOCK_SIZE_SLOW, False
        # Under qemu-system, each cpu has its own page table ($cr3 differs per thread).
        # Today GDB does not switch the general thread for a memory read, so a virtual
        # address is always translated by cpu0, but do not rely on it and separate the
        # cache by the selected thread.
        return MemoryCache.BLOCK_SIZE, is_qemu_system()

    @staticmethod
    def reset():
        MemoryCache.__blocks__.clear()
        MemoryCache.__unreadable__.clear()
        return

    @staticmethod
    def read(addr, length):
        """Return a `length` long byte array at `addr`, using the block cache if available."""
        block_size, per_cpu = MemoryCache.get_policy()
        if block_size == 0 or length > block_size:
            return gdb.selected_inferior().read_memory(addr, length).tobytes()

        ctx = Cache.cpu_context() if per_cpu else gdb.selected_inferior().num
        blocks = MemoryCache.__blocks__
        base = addr & ~(block_size - 1)
        out = b""
        pos = base
        while pos < addr + length:
            key = (ctx, pos)
            data = blocks.get(key)
            if data is None:
                if key in MemoryCache.__unreadable__:
                    # The block is not entirely readable. Read only the requested range,
                    # so that a memory error is raised only if it is really unreadable.
                    return gdb.selected_inferior().read_memory(addr, length).tobytes()
                try:
                    data = gdb.selected_inferior().read_memory(pos, block_size).tobytes()
                except gdb.MemoryError:
                    if len(MemoryCache.__unreadable__) >= MemoryCache.MAX_BLOCKS:
                        MemoryCache.__unreadable__.clear()
                    MemoryCache.__unreadable__.add(key)
                    return gdb.selected_inferior().read_memory(addr, length).tobytes()
                if len(blocks) >= MemoryCache.MAX_BLOCKS:
                    blocks.clear()
                blocks[key] = data
            out += data
            pos += block_size
        offset = addr - base
        return out[offset:offset + length]


class Config:
    """Manage gef configurations. Most configs are tied to specific commands.
    They are defined in the form `command_name.config_name`.
    Internally it is stored as a triple (value, type, description)."""

    __gef_config__ = {} # keep gef configs
    __gef_config_orig__ = {} # for debugging

    @staticmethod
    @Cache.cache_until_next
    def get_gef_setting(name):
        """Read global gef settings. Return None if not found."""
        setting = Config.__gef_config__.get(name, None)
        if setting is None:
            return None # A valid config can never return None, but False, 0 or ""
        return setting[0]

    @staticmethod
    def set_gef_setting(name, value, _type=None, _desc=None):
        """Set global gef settings.
        Raise ValueError if `name` doesn't exist and `type` and `desc` are not provided."""
        Cache.reset_gef_caches()

        if name not in Config.__gef_config__:
            # create new setting
            if _type is None or _desc is None:
                raise ValueError("Setting '{}' is undefined, need to provide type and description".format(name))
            Config.__gef_config__[name] = [_type(value), _type, _desc]
            return

        # set existing setting
        func = Config.__gef_config__[name][1]
        Config.__gef_config__[name][0] = func(value)
        return


def gef_print(x="", less=False, redirect=None, skip_color=False, *args, **kwargs):
    """Wrapper around print(), with pager, redirecting and coloring."""
    if not skip_color:
        x = HighlightCommand.highlight_text(x)

    if redirect:
        with open(redirect, "w") as f:
            print(x, *args, **kwargs, file=f)
        return

    if less:
        try:
            less = GefUtil.which("less")
        except FileNotFoundError:
            less = False

    if not less:
        # if x is blank, print a blank line.
        print(x, *args, **kwargs)
        return

    # use pager but x is blank
    if not x:
        return

    always_no_pager = Config.get_gef_setting("gef.always_no_pager")
    if always_no_pager:
        print(x, *args, **kwargs)
        return

    pager_min_lines = Config.get_gef_setting("gef.pager_min_lines")
    if len(x.splitlines()) < pager_min_lines:
        print(x, *args, **kwargs)
        return

    # write to file and less
    # the trailing newline is what print() would have added on the non-pager path.
    # Without it the next output continues on the same line when stdout is not a tty.
    if isinstance(x, bytes):
        tmp_fd, tmp_path = GefUtil.mkstemp(prefix="gef_print", suffix=".txt")
        os.fdopen(tmp_fd, "wb").write(x + b"\n")
    else:
        try:
            # this is faster than converting to bytes and then writing.
            tmp_fd, tmp_path = GefUtil.mkstemp(prefix="gef_print", suffix=".txt")
            os.fdopen(tmp_fd, "w").write(x + "\n")
        except Exception:
            # fallback if a write error occurs
            # tmp_fd is closed at this point, so delete it and reopen it
            os.unlink(tmp_path)
            tmp_fd, tmp_path = GefUtil.mkstemp(prefix="gef_print", suffix=".txt")
            os.fdopen(tmp_fd, "wb").write(String.str2bytes(x) + b"\n")

    # less
    less_option = Config.get_gef_setting("gef.less_option")
    GefUtil.os_system("{!r} {:s} {!r}".format(less, less_option, tmp_path))

    # cleanup
    keep_pager_result = Config.get_gef_setting("gef.keep_pager_result")
    if keep_pager_result:
        print("result saved at {:s}".format(tmp_path))
    else:
        os.unlink(tmp_path)
    return


