def timeout(duration):
    """Decorator to handle timeout."""

    def timeout_worker(conn, function, args, kwargs):
        try:
            result = function(*args, **kwargs)
            conn.send((True, result))
        except BaseException as e:
            try:
                conn.send((False, e))
            except BaseException as send_error:
                conn.send((False, RuntimeError("failed to send child result: %r" % send_error)))
        finally:
            conn.close()

    def wrapper(function):
        import multiprocessing
        import multiprocessing.connection
        import signal

        ctx = multiprocessing.get_context("fork")

        @functools.wraps(function)
        def inner_f(*args, **kwargs):
            parent_conn, child_conn = ctx.Pipe(duplex=False)
            p = ctx.Process(target=timeout_worker, args=(child_conn, function, args, kwargs))
            p.start()
            child_conn.close()

            ready = multiprocessing.connection.wait([parent_conn, p.sentinel], duration)

            if parent_conn in ready:
                success, result = parent_conn.recv()
                parent_conn.close()
                p.join()
                if success:
                    return result
                raise result

            parent_conn.close()
            p.terminate()
            p.join(0.2)

            if p.is_alive():
                if hasattr(p, "kill"):
                    p.kill()
                else:
                    os.kill(p.pid, signal.SIGKILL)
                p.join()

            raise multiprocessing.TimeoutError

        return inner_f

    return wrapper


def to_unsigned_long(v):
    """Cast a gdb.Value to unsigned long."""
    mask = AddressUtil.get_vmem_end_mask()
    return int(v.cast(gdb.Value(mask).type)) & mask


# Don't use cache.
# This is because there is a command that performs step execution internally.
def get_register(regname, use_mbed_exec=False, use_monitor=False):
    """Return a register's value."""

    if regname[0] in ["%", "@"]:
        regname = "$" + regname[1:]

    if regname[0] != "$":
        regname = "$" + regname

    try:
        # `read_register` is about 2.7x faster than `parse_and_eval` for the same register
        # (0.97us vs 2.69us for $rax, 6.95us vs 13.78us for $pc), but it only knows the
        # real and pseudo registers of the target, so keep `parse_and_eval` as a fallback.
        try:
            value = gdb.selected_frame().read_register(regname[1:])
        except (gdb.error, ValueError):
            value = gdb.parse_and_eval(regname)

        if value.type.code == gdb.TYPE_CODE_INT:
            return to_unsigned_long(value)
        elif value.type.name == "vec128":
            if hasattr(value, "bytes"):
                return u128(value.bytes)
            else:
                return eval(str(value["uint128"]))
        else:
            return int(value)
    except gdb.error:
        if (is_hppa32() or is_hppa64()) and regname == "$r0":
            return 0
        try:
            value = gdb.selected_frame().read_register(regname[1:])
            return int(value)
        except (gdb.error, ValueError):
            pass

    if use_mbed_exec and is_qemu_system() and is_arm32():
        # Note that attempting to read a non-existent register will jump to an Undefined exception
        try:
            r = gdb.execute("read-system-register-for-qemu-arm {:s}".format(regname), to_string=True)
            if r:
                return int(r.split("=")[1], 16)
        except gdb.error:
            pass

    if use_monitor and is_qemu_system() and is_x86():
        regname = regname.lstrip("$").upper()
        res = gdb.execute("monitor info registers", to_string=True)
        r = re.search(r"{:s}=(\S+)".format(regname), res)
        if r:
            return int(r.group(1), 16)

    if use_monitor and is_vmware() and is_x86_64():
        regname = regname.lstrip("$")
        res = gdb.execute("monitor r {:s}".format(regname), to_string=True)
        r = re.search(r"{:s}=(\S+)".format(regname), res)
        if r:
            return int(r.group(1), 16)

    if use_mbed_exec and is_kgdb() and (is_x86_64() or is_arm64()):
        if ReadSystemRegisterForKgdbCommand.is_supported_reg(regname):
            try:
                r = gdb.execute("read-system-register-for-kgdb {:s}".format(regname), to_string=True)
                if r:
                    return int(r.split("=")[1], 16)
            except gdb.error:
                pass

    return None


@Cache.cache_this_session(cache_None=False)
def is_remote_debug():
    """GDB mode determination function for remote debugging."""
    if not is_alive():
        return None
    try:
        connection = gdb.selected_inferior().connection
        if connection is None:
            return False
        return connection and connection.type == "remote"
    except AttributeError:
        # before gdb 11.x: AttributeError: 'gdb.Inferior' object has no attribute 'connection'
        res = gdb.execute("maintenance print target-stack", to_string=True)
        return "remote" in res


# Removed is_remote_same_host.
# It can detect that gdb connects to a process in the same host.
# However, it cannot detect that traffic is being redirected to another host.


@Cache.cache_this_session(cache_None=False)
def is_normal_run():
    """GDB mode determination function for normal running."""
    if not is_alive():
        return None
    ret = gdb.execute("info files", to_string=True)
    return "Using the running image of child" in ret


@Cache.cache_this_session(cache_None=False)
def is_attach():
    """GDB mode determination function for attaching."""
    if not is_alive():
        return None
    try:
        return gdb.selected_inferior().was_attached
    except AttributeError:
        ret = gdb.execute("info files", to_string=True)
        return "Using the running image of attached" in ret


@Cache.cache_this_session(cache_None=False)
def is_container_attach():
    """GDB mode determination function for attaching another namespace."""
    if not is_alive():
        return None
    filename = gdb.current_progspace().filename
    if filename and filename.startswith("target:"):
        return True
    pid = Pid.get_pid()
    if pid is None:
        return False
    path = "/proc/{:d}/status".format(pid)
    if os.path.exists(path):
        content = open(path, "rb").read()
        r = re.search(rb"\nNSpid:\s+(\d+)\s+(\d+)", content)
        return bool(r)
    return False


@Cache.cache_this_session(cache_None=False)
def is_pin():
    """GDB mode determination function for pin and SDE."""
    if not is_alive():
        return None
    if not is_remote_debug():
        return False
    try:
        response = gdb.execute("maintenance packet qSupported", to_string=True, from_tty=False)
    except gdb.error as e:
        err("{}".format(e))
        os._exit(0)
    return "intel.name=" in response


