@Cache.cache_until_next
def is_in_kernel():
    """GDB mode determination function for kernel mode."""
    if not is_alive():
        return False
    if is_arm32_cortex_m():
        return False
    if is_qiling():
        return False

    # If it fails to obtain the flag register required for the judgment,
    # it will be considered as userland.
    if is_x86():
        cs = get_register("$cs")
        if cs is None:
            return False
        return (cs & 0b11) != 3
    elif is_arm32():
        if is_in_secure():
            return False
        cpsr = get_register(current_arch.flag_register)
        if cpsr is None:
            return False
        return (cpsr & 0b11111) not in [0b10000, 0b11010]
    elif is_arm64():
        if is_in_secure():
            return False
        cpsr = get_register(current_arch.flag_register)
        if cpsr is None:
            return False
        return ((cpsr >> 2) & 0b11) == 1
    elif is_riscv64() or is_riscv32():
        priv = get_register("priv")
        if priv is None:
            return False
        return priv == 1
    # All other architectures are considered userland.
    return False


@Cache.cache_until_next
def is_in_kpti_transition():
    """Return whether arm64 is stopped while switching TTBR1 for KPTI."""
    if not is_arm64() or not is_in_kernel():
        return False

    pc = current_arch.pc
    sp = current_arch.sp
    instruction_length = current_arch.instruction_length
    if pc is None or sp is None:
        return False

    # `msr ttbr1_el1, x0` is encoded as 0xd518_2020. The source register xN is
    # encoded in the low 5 bits, so mask them out when matching the instruction.
    try:
        code = read_memory(pc - 8 * instruction_length, 17 * instruction_length)
    except gdb.MemoryError:
        return False
    if not any(insn & 0xffff_ffe0 == 0xd518_2020 for insn in slice_unpack(code, 4)):
        return False

    if not is_valid_addr(sp):
        return True

    # If kallsyms was already resolved, also check a known regular kernel mapping.
    ret = Symbol.get_kallsyms(parse=False)
    if ret is None:
        return False
    kallsyms, kallsyms_map = ret
    known_addresses = kallsyms_map.get("_stext", [])
    if not known_addresses:
        return False
    return not is_valid_addr(known_addresses[0])


@Cache.cache_this_session(cache_None=False)
def is_support_secure_world():
    if not is_alive():
        return None
    if not is_arm32() and not is_arm64():
        return False
    if not is_qemu_system():
        return False
    ret = gdb.execute("monitor info mtree -f", to_string=True)
    return ".secure-ram" in ret


@Cache.cache_until_next
def is_in_secure():
    """GDB mode determination function for secure world."""
    if not is_support_secure_world():
        return False
    if is_arm32():
        scr = get_register("$SCR")
    elif is_arm64():
        scr = get_register("$SCR_EL3")
    # In environments without a secure world:
    # Older qemu versions did not have the SCR register. (return None)
    # Newer qemu versions always return 0.
    if not scr:
        return False
    return (scr & 0b1) == 0


