@register_command
class HistoryCommand(GenericCommand, BufferingOutput):
    """Show gdb command history easily."""

    _cmdline_ = "history"
    _category_ = "99. GEF Maintenance Command"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    _syntax_ = parser.format_help()

    def get_history(self):
        history = {}
        line_idx = 0
        prev_ret = None
        while True:
            ret = gdb.execute("show commands {:d}".format(line_idx), to_string=True)
            for line in ret.splitlines():
                line_idx = int(line.split()[0])
                if line_idx in history:
                    continue
                history[line_idx] = line

            if prev_ret == ret:
                break
            prev_ret = ret
        return list(history.values())

    @parse_args
    def do_invoke(self, args):
        self.out = self.get_history()
        self.print_output(skip_color=True)
        return


@register_command
class DisplayTypeCommand(GenericCommand, BufferingOutput):
    """Make it easier to use `ptype /ox TYPE` and `p ((TYPE*) ADDRESS)[0]`."""

    _cmdline_ = "dt"
    _category_ = "02-h. Process Information - Type"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("type", metavar="TYPE", help="the type name.")
    parser.add_argument("address", metavar="ADDRESS", nargs="?", type=AddressUtil.parse_address,
                        help="the address to apply the type.")
    parser.add_argument("-s", "--smart", action="store_true",
                        help="override `context.smart_cpp_function_name = True` temporarily.")
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    _syntax_ = parser.format_help()

    _example_ = [
        '{0:s} "struct malloc_state"       # shortcut for `ptype /ox struct malloc_state`',
        '{0:s} "struct malloc_state" $rsp  # shortcut for `p ((struct malloc_state*) $rsp)[0]`',
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    _note_ = [
        "This command is designed for several purposes.",
        "1. When displaying very large struct, you may want to go through a pager because the results will not fit on one screen.",
        "   However, using a pager, the color information disappears. This command calls the pager with preserving colors.",
        "2. When `ptype /ox TYPE`, interpreting member type recursively often result is too long and difficult to read.",
        "   This command keeps result compact by displaying only top-level members.",
        "3. When `p ((TYPE*) ADDRESS)[0]` for large struct, the gdb setting of `max-value-size` is too small to display.",
        "   This command adjusts it automatically.",
        "4. When debugging a binary written in the Golang, the offset information of the type is not displayed.",
        "   This command also displays the offset.",
        "5. When debugging a binary written in the Golang, the `p ((TYPE*) ADDRESS)[0]` command will be broken.",
        "   This is because the Golang helper script is automatically loaded and overwrites the behavior of `p` command.",
        "   This command creates the display results on the python side, so we can display it without any problems.",
    ]
    _note_ = "\n".join(_note_)

    def dump_type(self, tp, args_type):
        if tp.code == gdb.TYPE_CODE_STRUCT:
            type_prefix = "struct"
        elif tp.code == gdb.TYPE_CODE_UNION:
            type_prefix = "union"
        elif tp.code == gdb.TYPE_CODE_ENUM:
            type_prefix = "enum"
        else:
            err("{:s} is not struct or union".format(tp.name or args_type))
            return False

        self.out = [
            "{:s} {:s} {{".format(type_prefix, Instruction.smartify_text(tp.name or args_type)),
            "    /* offset | size   */",
        ]
        for name, field in tp.items():
            if tp.code in [gdb.TYPE_CODE_STRUCT, gdb.TYPE_CODE_UNION]:
                if hasattr(field, "bitpos") and hasattr(field.type, "sizeof"):
                    offsz_str = "/* {:#06x} | {:#06x} */".format(field.bitpos // 8, field.type.sizeof)
                elif hasattr(field.type, "sizeof"):
                    offsz_str = "/*        | {:#06x} */".format(field.type.sizeof)
                elif hasattr(field, "bitpos"):
                    offsz_str = "/* {:#06x} |        */".format(field.bitpos // 8)
                else:
                    offsz_str = "/*        |        */"
                type_str = Instruction.smartify_text(str(field.type))
                name_str = Color.cyanify(Instruction.smartify_text(name))
                if field.bitsize == 0:
                    msg = "    {:s}    {} {:s};".format(offsz_str, type_str, name_str)
                else:
                    msg = "    {:s}    {} {:s} : {:d};".format(offsz_str, type_str, name_str, field.bitsize)
            else: # gdb.TYPE_CODE_ENUM
                offsz_str = "/* {:#06x} | {:#06x} */".format(0, 4)
                type_str = "int"
                name_str = Color.cyanify(Instruction.smartify_text(name))
                msg = "    {:s}    {} {:s} = {:#x};".format(offsz_str, type_str, name_str, field.enumval)
            self.out.append(msg)
        self.out.append("}} // total: {:#x} bytes".format(tp.sizeof))
        return True

    def apply_type(self, tp, args_address):
        if not is_valid_addr(args_address):
            err("Memory read error")
            return False

        # change setting
        if tp.sizeof > 2200: # 2200 is default value of max-value-size
            gdb.execute("set max-value-size {:#x}".format(tp.sizeof))

        v = gdb.Value(args_address)
        s = v.cast(tp.pointer()).dereference()
        self.out = s.format_string(styling=True).splitlines()
        return True

    @parse_args
    @only_if_gdb_running
    def do_invoke(self, args):
        # lookup type
        tp = GefUtil.cached_lookup_type(args.type)
        if not args.type.startswith(("struct", "union", "enum")):
            if tp is None:
                tp = GefUtil.cached_lookup_type("struct {:s}".format(args.type))
            if tp is None:
                tp = GefUtil.cached_lookup_type("union {:s}".format(args.type))
            if tp is None:
                tp = GefUtil.cached_lookup_type("enum {:s}".format(args.type))

        if tp is None:
            err("Could not find {:s}".format(args.type))
            return

        # remove pointer
        while str(tp).endswith("*"):
            tp = tp.target()

        # check if valid type
        if tp.code not in [gdb.TYPE_CODE_STRUCT, gdb.TYPE_CODE_UNION, gdb.TYPE_CODE_ENUM]:
            err("{:s} is not struct or union or enum".format(tp.name or args.type))
            return

        # change setting temporarily
        if args.smart:
            old_smart_setting = Config.get_gef_setting("context.smart_cpp_function_name")
            Config.set_gef_setting("context.smart_cpp_function_name", True)

        # doit
        if args.address is None:
            ret = self.dump_type(tp, args.type)
        else:
            ret = self.apply_type(tp, args.address)

        if ret:
            self.print_output(check_terminal_size=True)

        # revert setting
        if args.smart:
            Config.set_gef_setting("context.smart_cpp_function_name", old_smart_setting)
        return


@register_command
class BreakRelativeVirtualAddressCommand(GenericCommand):
    """Set a breakpoint at relative offset from codebase."""

    _cmdline_ = "break-rva"
    _category_ = "01-b. Debugging Support - Breakpoint"
    _aliases_ = ["brva"]

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("offset", metavar="OFFSET", type=AddressUtil.parse_address,
                        help="the offset from codebase to set a breakpoint.")
    _syntax_ = parser.format_help()

    delayed_breakpoints = set()
    delayed_bp_set = False

    @parse_args
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware", "wine"))
    @require_arch_set
    def do_invoke(self, args):
        elf = Elf.get_elf()
        if elf is None or not elf.is_valid():
            err("Invalid ELF")
            return

        if not elf.is_pie():
            err("Non-PIE ELF is unsupported")
            return

        if is_alive():
            codebase = ProcessMap.get_codebase()
            if codebase is None:
                gef_print("Could not find the codebase")
                return
            gdb.execute("b *{:#x}".format(codebase + args.offset))
        else:
            # use delayed breakpoints
            BreakRelativeVirtualAddressCommand.delayed_breakpoints.add(args.offset)
            info("Add delayed breakpoint to codebase+{:#x}".format(args.offset))
        return


@register_command
class PrintFormatCommand(GenericCommand):
    """Print bytes format in high level languages."""

    _cmdline_ = "print-format"
    _category_ = "07-c. Misc - Generation"
    _aliases_ = ["pf", "gethex"]

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-f", dest="format", default="hex",
                        choices=["py", "c", "js", "asm", "hex", "hexn", "hexs", "hexsn"],
                        help="the output format. (default: %(default)s)")
    parser.add_argument("-b", dest="bitlen", type=int, default=8, choices=[8, 16, 32, 64],
                        help="the size of bit. (default: %(default)s)")
    group = parser.add_mutually_exclusive_group(required=False)
    group.add_argument("-l", dest="length", type=AddressUtil.parse_address, default=256,
                        help="the length of array. (default: %(default)s)")
    group.add_argument("-t", dest="to_addr", type=AddressUtil.parse_address,
                        help="specify the end address instead of the length.")
    parser.add_argument("location", metavar="LOCATION", type=AddressUtil.parse_address,
                        help="the address of data to dump.")
    _syntax_ = parser.format_help()

    _example_ = [
        "{0:s} -f py -b 8 -l 256 $rsp",
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    _note_ = [
        '"hexn" means hex with new-line.',
        '"hexs" means hex with separator.',
    ]
    _note_ = "\n".join(_note_)

    def __init__(self):
        super().__init__(complete=gdb.COMPLETE_LOCATION)
        return

    def extract_memory(self):
        unit_size = self.args.bitlen // 8
        if self.args.to_addr is not None:
            end_addr = self.args.to_addr
        else:
            end_addr = self.args.location + self.args.length * unit_size

        bit_format = {8: "<B", 16: "<H", 32: "<I", 64: "<Q"}[self.args.bitlen]
        data = []
        for address in range(self.args.location, end_addr, unit_size):
            try:
                mem = read_memory(address, unit_size)
            except gdb.MemoryError:
                err("Memory read error")
                return None
            value = struct.unpack(bit_format, mem)[0]
            data.append(value)
        return data

    def parse_data(self, data):
        if self.args.format in ["hexs", "hexsn"]:
            separator = " "
        else:
            separator = ""

        sdata = ""
        if self.args.format in ["hexn", "hexsn"]:
            for i, x in enumerate(data):
                sdata += "{:02x}{:s}".format(x, separator)
                if (i % 16) == 15:
                    sdata += "\n"
        elif self.args.format in ["hex", "hexs"]:
            for x in data:
                sdata += "{:02x}{:s}".format(x, separator)
        else:
            for i, x in enumerate(data):
                if (i % 8) == 0:
                    sdata += "    "
                sdata += "{:#0{}x}, ".format(x, self.args.bitlen // 4 + 2)
                if (i % 8) == 7:
                    sdata += "\n"
        sdata = sdata.rstrip()
        return sdata

    def make_format(self, sdata):
        if self.args.format == "py":
            out = "buf = [\n{:s}\n]".format(sdata)
        elif self.args.format == "c":
            c_type = {8: "char", 16: "short", 32: "int", 64: "long long"}
            out = "unsigned {:s} buf[] = {{\n{:s}\n}};".format(c_type[self.args.bitlen], sdata)
        elif self.args.format == "js":
            out = "var buf = [\n{:s}\n];".format(sdata)
        elif self.args.format == "asm":
            asm_type = {8: "db", 16: "dw", 32: "dd", 64: "dq"}
            out = "buf {:s}\n{:s}".format(asm_type[self.args.bitlen], sdata)
        elif self.args.format in ["hex", "hexn", "hexs", "hexsn"]:
            out = sdata
        return out

    @parse_args
    @only_if_gdb_running
    def do_invoke(self, args):
        if args.format in ["hex", "hexn", "hexs", "hexsn"] and args.bitlen != 8:
            err("{:s} must be bit == 8".format(args.format))
            return

        data = self.extract_memory()
        if data is None:
            return
        sdata = self.parse_data(data)
        out = self.make_format(sdata)
        gef_print(out)
        return


@register_command
class CanaryCommand(GenericCommand):
    """Display the canary value of the current process."""

    _cmdline_ = "canary"
    _category_ = "02-f. Process Information - Security"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    _syntax_ = parser.format_help()

    @staticmethod
    @Cache.cache_this_session(cache_None=False)
    def gef_read_canary():
        """Read the current stack canary and return its value and location."""
        if is_in_kernel():
            return None

        libc_version = get_libc_version(silent=True)
        if libc_version and libc_version >= (2, 44):
            # from glibc 2.44, AT_RANDOM will be refilled
            canary_offset = current_arch.get_canary_offset()
            if canary_offset is not None:
                try:
                    tls = current_arch.get_tls()
                    if tls is not None:
                        canary_location = tls + canary_offset
                        canary = read_int_from_memory(canary_location)
                        # The canary address in TLS differs between threads, so only cache its value.
                        return canary, None
                except Exception:
                    return None
            else:
                try:
                    canary_location = int(gdb.parse_and_eval("&__stack_chk_guard"))
                    canary = read_int_from_memory(canary_location)
                    return canary, canary_location
                except (gdb.error, gdb.MemoryError):
                    return None
        else:
            try:
                auxval = Auxv.get_auxiliary_values()
                if not auxval:
                    return None
                canary_location = auxval["AT_RANDOM"]
                canary = read_int_from_memory(canary_location)
                if Endian.is_big_endian():
                    if is_64bit():
                        canary &= 0x00ff_ffff_ffff_ffff
                    elif is_32bit():
                        canary &= 0x00ff_ffff
                else:
                    canary &= ~0xff
                return canary, canary_location
            except (KeyError, gdb.MemoryError):
                return None

    def dump_canary(self):
        res = CanaryCommand.gef_read_canary()
        if not res:
            err("Failed to get the canary")
            return

        canary, canary_location = res
        gef_print(titlify("Canary value"))
        if canary_location is not None:
            info("Found canary at {!s}, reading {:d} bytes".format(
                ProcessMap.lookup_address(canary_location), current_arch.ptrsize,
            ))
        info("The canary is {:s}".format(Color.colorify_hex(canary, "bold")))

        gef_print(titlify("Found canaries"))
        vmmap = ProcessMap.get_process_maps_exclude_special_regions(allow_vdso=True)
        unpack = u32 if current_arch.ptrsize == 4 else u64
        sp = current_arch.sp
        printed_flag_sp = False
        for m in vmmap:
            if not (m.permission & Permission.READ):
                continue
            if not (m.permission & Permission.WRITE):
                continue
            try:
                data = read_memory(m.page_start, m.page_end - m.page_start)
            except gdb.MemoryError:
                continue
            prev_addr = -1
            for pos in range(0, m.page_end - m.page_start, current_arch.ptrsize):
                addr = m.page_start + pos
                d = data[pos: pos + current_arch.ptrsize]
                if canary != unpack(d):
                    continue
                if m.path == "":
                    path = "unknown"
                else:
                    path = m.path
                if prev_addr <= sp <= addr:
                    if printed_flag_sp is False:
                        info("(Stack pointer is at {!s})".format(ProcessMap.lookup_address(sp)))
                        printed_flag_sp = True
                if path == "[stack]":
                    info("Found at {!s} in {!r} (sp{:+#x})".format(
                        ProcessMap.lookup_address(addr), path, addr - sp,
                    ))
                else:
                    info("Found at {!s} in {!r}".format(ProcessMap.lookup_address(addr), path))
                prev_addr = addr
        return

    @parse_args
    @only_if_gdb_running
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware"))
    @require_arch_set
    def do_invoke(self, args):
        self.dump_canary()
        return


@register_command
class AuxvCommand(GenericCommand):
    """Display ELF auxiliary vectors."""

    _cmdline_ = "auxv"
    _category_ = "02-d. Process Information - Trivial Information"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-f", "--force-heuristic", action="store_true", help="use heuristic detection.")
    _syntax_ = parser.format_help()

    AT_CONSTANTS = {
        0  : "AT_NULL",              # End of vector
        1  : "AT_IGNORE",            # Entry should be ignored
        2  : "AT_EXECFD",            # File descriptor of program
        3  : "AT_PHDR",              # Program headers for program
        4  : "AT_PHENT",             # Size of program header entry
        5  : "AT_PHNUM",             # Number of program headers
        6  : "AT_PAGESZ",            # System page size
        7  : "AT_BASE",              # Base address of interpreter
        8  : "AT_FLAGS",             # Flags
        9  : "AT_ENTRY",             # Entry point of program
        10 : "AT_NOTELF",            # Program is not ELF
        11 : "AT_UID",               # Real uid
        12 : "AT_EUID",              # Effective uid
        13 : "AT_GID",               # Real gid
        14 : "AT_EGID",              # Effective gid
        15 : "AT_PLATFORM",          # String identifying platform
        16 : "AT_HWCAP",             # Machine dependent hints about processor capabilities
        17 : "AT_CLKTCK",            # Frequency of times()
        18 : "AT_FPUCW",             #
        19 : "AT_DCACHEBSIZE",       #
        20 : "AT_ICACHEBSIZE",       #
        21 : "AT_UCACHEBSIZE",       #
        22 : "AT_IGNOREPPC",         # A special ignored type value for PPC, for glibc compatibility
        23 : "AT_SECURE",            #
        24 : "AT_BASE_PLATFORM",     # String identifying real platforms
        25 : "AT_RANDOM",            # Address of 16 random bytes
        26 : "AT_HWCAP2",            # extension of AT_HWCAP
        27 : "AT_RSEQ_FEATURE_SIZE", # seq supported feature size
        28 : "AT_RSEQ_ALIGN",        # rseq allocation alignment
        31 : "AT_EXECFN",            # Filename of executable
        32 : "AT_SYSINFO",           #
        33 : "AT_SYSINFO_EHDR",      #
        34 : "AT_L1I_CACHESHAPE",    #
        35 : "AT_L1D_CACHESHAPE",    #
        36 : "AT_L2_CACHESHAPE",     #
        37 : "AT_L3_CACHESHAPE",     #
        40 : "AT_L1I_CACHESIZE",     #
        41 : "AT_L1I_CACHEGEOMETRY", #
        42 : "AT_L1D_CACHESIZE",     #
        43 : "AT_L1D_CACHEGEOMETRY", #
        44 : "AT_L2_CACHESIZE",      #
        45 : "AT_L2_CACHEGEOMETRY",  #
        46 : "AT_L3_CACHESIZE",      #
        47 : "AT_L3_CACHEGEOMETRY",  #
        51 : "AT_MINSIGSTKSZ",       # stack needed for signal delivery
    }

    @parse_args
    @only_if_gdb_running
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware", "wine"))
    @require_arch_set
    def do_invoke(self, args):
        auxval = Auxv.get_auxiliary_values(args.force_heuristic)
        if not auxval:
            return None

        reverse_AT_CONSTS = {v: "{:#04x}".format(k) for k, v in self.AT_CONSTANTS.items()}

        gef_print(titlify("ELF auxiliary vector"))
        fmt = "{:6s} {:22s} {:s}"
        legend = ["Const", "Name", "Value"]
        gef_print(GefUtil.make_legend(fmt.format(*legend)))

        for k, v in auxval.items():
            num = reverse_AT_CONSTS.get(k, "?")
            additional_message = ""
            if k == "AT_NULL":
                additional_message = " (End of vector)"
            elif k in ["AT_EXECFN", "AT_PLATFORM"]:
                s = read_cstring_from_memory(v)
                if s is None:
                    s = "Cannot access memory"
                s = Color.yellowify(repr(s))
                additional_message = " -> {:s}".format(s)
            elif k in ["AT_RANDOM"]:
                try:
                    if is_64bit():
                        s1 = read_int_from_memory(v + current_arch.ptrsize * 0)
                        s2 = read_int_from_memory(v + current_arch.ptrsize * 1)
                        additional_message = " -> {:#018x}, {:#018x}".format(s1, s2)
                    else:
                        s1 = read_int_from_memory(v + current_arch.ptrsize * 0)
                        s2 = read_int_from_memory(v + current_arch.ptrsize * 1)
                        s3 = read_int_from_memory(v + current_arch.ptrsize * 2)
                        s4 = read_int_from_memory(v + current_arch.ptrsize * 3)
                        additional_message = " -> {:#010x}, {:#010x}, {:#010x}, {:#010x}".format(
                            s1, s2, s3, s4,
                        )
                except gdb.MemoryError:
                    s = Color.yellowify(repr("Cannot access memory"))
                    additional_message = " -> {:s}".format(s)

            if is_valid_addr(v):
                v = str(ProcessMap.lookup_address(v))
            else:
                v = hex(v)
            gef_print("{:6s} {:22s} {:s}{:s}".format(num, k + ":", v, additional_message))
        return


@register_command
class ArgvCommand(GenericCommand, BufferingOutput):
    """Display the program's argv array."""

    _cmdline_ = "argv"
    _category_ = "02-d. Process Information - Trivial Information"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-v", "--verbose", action="store_true",
                        help="print all elements. (default: outputs up to 100)")
    parser.add_argument("-i", "--increase-limit", action="store_true",
                        help="increase rounding limit from 128 bytes to 4096 bytes.")
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    _syntax_ = parser.format_help()

    def get_address_from_symbol(self, symbol):
        try:
            return AddressUtil.parse_address(symbol)
        except Exception:
            return None

    def print_from_mem(self, array):
        fmt = "{:3s} {:{:d}s}  {:{:d}s} -> {:s}"
        legend = [
            "#",
            "ArrAddr", AddressUtil.get_format_address_width(),
            "StrAddr", AddressUtil.get_format_address_width(),
            "String",
        ]
        self.out.append(GefUtil.make_legend(fmt.format(*legend)))

        max_size = get_pagesize() if self.args.increase_limit else 128

        i = 0
        while True:
            pos = array + i * current_arch.ptrsize
            addr = read_int_from_memory(pos)
            if addr == 0:
                break
            if not self.args.verbose and i >= 100:
                self.out.append("...")
                break

            s = read_cstring_from_memory(addr, get_pagesize())
            s = Color.yellowify(repr(s))
            if len(s) > max_size:
                s = s[:max_size] + "[...]"

            self.out.append("{:03d} {!s}: {!s} -> {:s}".format(
                i,
                ProcessMap.lookup_address(pos),
                ProcessMap.lookup_address(addr),
                s,
            ))
            i += 1
        return

    def print_from_proc(self, filename):
        fmt = "{:3s} {:s}"
        legend = ["#", "String"]
        self.out.append(GefUtil.make_legend(fmt.format(*legend)))

        max_size = get_pagesize() if self.args.increase_limit else 128

        lines = open(filename, "rb").read()
        lines = String.bytes2str(lines)
        for i, elem in enumerate(lines.split("\0")):
            if not elem:
                break
            if not self.args.verbose and i >= 100:
                self.out.append("...")
                break

            if len(elem) > max_size:
                elem = elem[:max_size] + "[...]"
            self.out.append("{:03d} {!s}".format(i, elem))
        return

    def dump_dl_argv(self):
        paddr = self.get_address_from_symbol("&_dl_argv")
        addr = self.get_address_from_symbol("_dl_argv")
        if paddr and addr:
            self.out.append(titlify("ARGV from _dl_argv"))
            self.info_add_out("_dl_argv @ {}".format(ProcessMap.lookup_address(paddr)))
            self.print_from_mem(addr)
            return
        elif addr == 0:
            self.err_add_out("_dl_argv is 0x0")
        else:
            self.err_add_out("Could not find _dl_argv")
        return

    def dump_libc_argv(self):
        paddr = self.get_address_from_symbol("&__libc_argv")
        addr = self.get_address_from_symbol("__libc_argv")
        if paddr and addr:
            self.out.append(titlify("ARGV from __libc_argv"))
            self.info_add_out("__libc_argv @ {}".format(ProcessMap.lookup_address(paddr)))
            self.print_from_mem(addr)
        elif addr == 0:
            self.err_add_out("__libc_argv is 0x0")
        else:
            self.err_add_out("Could not find __libc_argv")
        return

    def dump_proc_cmdline(self):
        if is_remote_debug():
            return
        self.out.append(titlify("ARGV from /proc/{:d}/cmdline".format(Pid.get_pid())))
        self.print_from_proc("/proc/{:d}/cmdline".format(Pid.get_pid()))
        return

    @parse_args
    @only_if_gdb_running
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware", "wine"))
    @require_arch_set
    def do_invoke(self, args):
        self.out = []
        self.dump_dl_argv()
        self.dump_libc_argv()
        self.dump_proc_cmdline()
        self.print_output(check_terminal_size=True)
        return


@register_command
class EnvpCommand(GenericCommand, BufferingOutput):
    """Display initial envp from __environ@ld, or modified envp from last_environ@libc."""

    _cmdline_ = "envp"
