@register_command
class FilenameCommand(GenericCommand):
    """Display current debugged filename."""

    _cmdline_ = "filename"
    _category_ = "02-d. Process Information - Trivial Information"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    _syntax_ = parser.format_help()

    @parse_args
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware"))
    def do_invoke(self, args):
        filepath = Path.get_filepath()
        if filepath:
            gef_print(repr(filepath))
            return

        elif is_remote_debug():
            filepath = gdb.current_progspace().filename
            if filepath and filepath.startswith("target:"):
                filepath = filepath[7:]
            if filepath:
                gef_print(repr(filepath))
                return

        err("Failed to get filename")
        return


@register_command
class ProcInfoCommand(GenericCommand):
    """Extend the info given by GDB `info proc`."""

    _cmdline_ = "proc-info"
    _category_ = "02-a. Process Information - General"
    _aliases_ = ["pr"]

    parser = argparse.ArgumentParser(prog=_cmdline_)
    _syntax_ = parser.format_help()

    def get_state_of(self, pid):
        try:
            status = open("/proc/{:d}/status".format(pid), "r").read()
        except (FileNotFoundError, OSError):
            return {}
        res = {}
        for line in status.splitlines():
            key, value = line.split(":", 1)
            res[key.strip()] = value.strip()
        return res

    def get_stat_of(self, pid):
        try:
            stat = open("/proc/{:d}/stat".format(pid), "r").read()
        except (FileNotFoundError, OSError):
            return []
        try:
            name = re.search(r"\((.+)\)", stat).group(1)
        except AttributeError:
            name = "???"
        other = re.sub(r"\(.+\) ", "", stat).split()
        res = [int(other[0]), name, other[1]] + [int(x) for x in other[2:]]
        return res

    def get_cmdline_of(self, pid):
        try:
            cmdline = open("/proc/{:d}/cmdline".format(pid), "r").read()
        except (FileNotFoundError, OSError):
            return ""
        return cmdline.replace("\0", " ").strip()

    def get_process_path_of(self, pid):
        try:
            return os.readlink("/proc/{:d}/exe".format(pid))
        except (FileNotFoundError, OSError):
            return "Not found"

    def get_process_cwd(self, pid):
        try:
            return os.readlink("/proc/{:d}/cwd".format(pid))
        except (FileNotFoundError, OSError):
            return "Not found"

    def get_process_root(self, pid):
        try:
            return os.readlink("/proc/{:d}/root".format(pid))
        except (FileNotFoundError, OSError):
            return "Not found"

    def get_thread_ids(self, pid):
        try:
            tids = os.listdir("/proc/{:d}/task".format(pid))
            return [int(x) for x in tids]
        except (FileNotFoundError, OSError):
            return []

    def get_children_pids(self, pid):
        try:
            ps = GefUtil.which("ps")
        except FileNotFoundError as e:
            err("{}".format(e))
            return []

        # Trick: If there are no child processes, `ps` exit code will be non-zero,
        # causing a subprocess.CalledProcessError exception to be raised.
        cmd = [ps, "-o", "pid", "--ppid", str(pid), "--noheaders"]
        try:
            return [int(x) for x in GefUtil.gef_execute_external(cmd, as_list=True)]
        except (subprocess.CalledProcessError, ValueError):
            return []

    def get_uid_map(self, pid):
        try:
            uid_map = open("/proc/{:d}/uid_map".format(pid), "r").read().strip()
        except (FileNotFoundError, OSError):
            return []
        return slicer([int(x) for x in uid_map.split()], 3)

    def get_gid_map(self, pid):
        try:
            gid_map = open("/proc/{:d}/gid_map".format(pid), "r").read().strip()
        except (FileNotFoundError, OSError):
            return []
        return slicer([int(x) for x in gid_map.split()], 3)

    def get_tty_str(self, major, minor):
        try:
            devices = open("/proc/devices", "r").read()
        except (FileNotFoundError, OSError):
            return "Not found"
        for line in devices.splitlines():
            if not line or line.endswith(":"):
                continue
            n, name = line.strip().split()
            if major == int(n):
                if not name.startswith("/dev"):
                    name = os.path.join("/dev", name)
                break
        else:
            return "Not found"

        def get_major_minor(name):
            devnum = os.stat(name).st_rdev
            major = (devnum >> 8) & 0xff
            minor = devnum & 0xff
            return major, minor

        if not os.path.exists(name):
            return "Not found"

        if os.path.islink(name):
            return "Not found"

        if os.path.isfile(name):
            if get_major_minor(name) == (major, minor):
                return name

        if os.path.isdir(name):
            for path in GefUtil.walk(name):
                if get_major_minor(path) == (major, minor):
                    return path
        return "Not found"

    def show_info_proc(self):
        gef_print(titlify("Process Information"))

        pid = Pid.get_pid()
        executable = self.get_process_path_of(pid)
        cmdline = self.get_cmdline_of(pid)
        cwd = self.get_process_cwd(pid)
        root = self.get_process_root(pid)
        gef_print("{:30s}  ->  {:d}".format("PID", pid))
        gef_print("{:30s}  ->  {!r}".format("  Executable", executable))
        gef_print("{:30s}  ->  {!r}".format("  Command Line", cmdline))
        gef_print("{:30s}  ->  {!r}".format("  Current Working Directory", cwd))
        gef_print("{:30s}  ->  {!r}".format("  Root Directory", root))
        uids = re.sub(r"\s+", " : ", self.get_state_of(pid)["Uid"])
        gids = re.sub(r"\s+", " : ", self.get_state_of(pid)["Gid"])
        gef_print("{:30s}  ->  {:s}".format("  RUID:EUID:SavedUID:FSUID", uids))
        gef_print("{:30s}  ->  {:s}".format("  RGID:EGID:SavedGID:FSGID", gids))
        seccomp_n = self.get_state_of(pid)["Seccomp"]
        seccomp_s = {"0": "Disabled", "1": "Strict", "2": "CustomFilter"}[seccomp_n]
        gef_print("{:30s}  ->  {:s} ({:s})".format("  Seccomp Mode", seccomp_n, seccomp_s))
        return

    def show_info_proc_extra(self):
        gef_print(titlify("Process Information Additional"))

        pid = Pid.get_pid()
        stat = self.get_stat_of(pid)
        pgid = stat[4]
        pgid_exec = self.get_process_path_of(pgid)
        pgid_cmdline = self.get_cmdline_of(pgid)
        gef_print("{:30s}  ->  {:d}".format("Process Group ID", pgid))
        gef_print("{:30s}  ->  {!r}".format("  Executable", pgid_exec))
        gef_print("{:30s}  ->  {!r}".format("  Command Line", pgid_cmdline))
        sid = stat[5]
        sid_exec = self.get_process_path_of(sid)
        sid_cmdline = self.get_cmdline_of(sid)
        gef_print("{:30s}  ->  {:d}".format("Session ID", sid))
        gef_print("{:30s}  ->  {!r}".format("  Executable", sid_exec))
        gef_print("{:30s}  ->  {!r}".format("  Command Line", sid_cmdline))
        tpgid = stat[7]
        tpgid_exec = self.get_process_path_of(tpgid)
        tpgid_cmdline = self.get_cmdline_of(tpgid)
        gef_print("{:30s}  ->  {:d}".format("TTY Process Group ID", tpgid))
        gef_print("{:30s}  ->  {!r}".format("  Executable", tpgid_exec))
        gef_print("{:30s}  ->  {!r}".format("  Command Line", tpgid_cmdline))
        ttynr = stat[6]
        major, minor = (ttynr >> 8) & 0xff, ((ttynr >> 20) << 8) | (ttynr & 0xff)
        ttystr = self.get_tty_str(major, minor)
        gef_print("{:30s}  ->  {:d} ({!r})".format("  TTY Device Number", ttynr, ttystr))
        return

    def show_parent(self):
        gef_print(titlify("Parent Process Information"))
        ppid = int(self.get_state_of(Pid.get_pid())["PPid"])
        ppid_exec = self.get_process_path_of(ppid)
        ppid_cmdline = self.get_cmdline_of(ppid)
        gef_print("{:30s}  ->  {:d}".format("Parent PID", ppid))
        gef_print("{:30s}  ->  {!r}".format("  Executable", ppid_exec))
        gef_print("{:30s}  ->  {!r}".format("  Command Line", ppid_cmdline))
        return

    def show_childs(self):
        gef_print(titlify("Child Process Information"))

        children = self.get_children_pids(Pid.get_pid())
        if not children:
            gef_print("No child process")
            return

        for i, cpid in enumerate(children, start=1):
            cpid_exec = self.get_process_path_of(cpid)
            cpid_cmdline = self.get_cmdline_of(cpid)
            gef_print("{:30s}  ->  {:d}".format("Child {:d} PID".format(i), cpid))
            gef_print("{:30s}  ->  {!r}".format("  Executable", cpid_exec))
            gef_print("{:30s}  ->  {!r}".format("  Command Line", cpid_cmdline))
        return

    def show_info_thread(self):
        gef_print(titlify("Thread Information"))

        pid = Pid.get_pid()
        nthreads = self.get_state_of(pid)["Threads"]
        tgid = self.get_state_of(pid)["Tgid"]
        gef_print("{:30s}  ->  {:s}".format("Num of Threads", nthreads))
        gef_print("{:30s}  ->  {:s}".format("Thread Group ID", tgid))
        tids = self.get_thread_ids(pid)
        gef_print("{:30s}  ->  {!r}".format("Thread ID List", tids))
        return

    def show_info_proc_ns(self):
        gef_print(titlify("Namespace Information"))

        pid = Pid.get_pid()
        gdb_pid = os.getpid()
        ns_symbols = ["cgroup", "ipc", "mnt", "net", "pid", "time", "user", "uts"]
        for ns in ns_symbols:
            if not os.path.exists("/proc/{:d}/ns/{:s}".format(pid, ns)):
                continue
            if not os.path.exists("/proc/{:d}/ns/{:s}".format(gdb_pid, ns)):
                continue
            sym1 = os.readlink("/proc/{:d}/ns/{:s}".format(pid, ns))
            sym2 = os.readlink("/proc/{:d}/ns/{:s}".format(gdb_pid, ns))
            m = "{:s} namespace separation".format(ns.upper())
            gef_print("{:30s}  ->  {!s}".format(m, sym1 != sym2))

        gef_print(titlify("Pid Namespace Information"))
        state = self.get_state_of(pid)
        if len(state["NSpid"].split()) > 1:
            gef_print("{:30s}  ->  {:s}".format(
                "Host PID  : Namespace PID", re.sub(r"\s+", " : ", state["NSpid"]),
            ))
            gef_print("{:30s}  ->  {:s}".format(
                "Host PGID : Namespace PGID", re.sub(r"\s+", " : ", state["NSpgid"]),
            ))
            gef_print("{:30s}  ->  {:s}".format(
                "Host SID  : Namespace SID", re.sub(r"\s+", " : ", state["NSsid"]),
            ))
            gef_print("{:30s}  ->  {:s}".format(
                "Host TGID : Namespace TGID", re.sub(r"\s+", " : ", state["NStgid"]),
            ))
        else:
            gef_print("{:30s}".format("No pid namespace"))

        gef_print(titlify("User Namespace Information"))
        for u in self.get_uid_map(pid):
            gef_print("{:30s}  ->  [{:#x} : {:#x} : {:#x}]".format(
                "UID_MAP [NameSpace:Host:Range]", u[0], u[1], u[2],
            ))
        for g in self.get_gid_map(pid):
            gef_print("{:30s}  ->  [{:#x} : {:#x} : {:#x}]".format(
                "GID_MAP [NameSpace:Host:Range]", g[0], g[1], g[2],
            ))
        return

    def get_state_string(self, proto, state):
        if proto in ["tcp", "tcp6"]:
            dic = {
                0x01: "ESTABLISHED",
                0x02: "SYN_SENT",
                0x03: "SYN_RECV",
                0x04: "FIN_WAIT1",
                0x05: "FIN_WAIT2",
                0x06: "TIME_WAIT",
                0x07: "CLOSE",
                0x08: "CLOSE_WAIT",
                0x09: "LAST_ACK",
                0x0a: "LISTEN",
                0x0b: "CLOSING",
                0x0c: "NEW_SYN_RECV",
                0x0d: "BOUND_INACTIVE",
            }
        elif proto in ["udp", "udp6"]:
            dic = {
                0x07: "LISTEN",
            }
        elif proto in ["unix"]:
            dic = {
                0x00: "FREE",
                0x01: "LISTEN", # "UNCONNECTED"
                0x02: "CONNECTING",
                0x03: "CONNECTED",
                0x04: "DISCONNECTING",
            }
        else:
            return str(int(state, 16))
        return dic.get(int(state, 16), "???")

    def get_proto_string(self, proto):
        # proto string (for raw/raw6)
        dic = {
            0x00: "IP",
            0x01: "ICMP",
            0x02: "IGMP",
            0x04: "IPIP",
            0x06: "TCP",
            0x08: "EGP",
            0x0c: "PUP",
            0x11: "UDP",
            0x16: "IDP",
            0x1d: "TP",
            0x21: "DCCP",
            0x29: "IPV6",
            0x2b: "ROUTING",
            0x2c: "FRAGMENT",
            0x2e: "RSVP",
            0x2f: "GRE",
            0x32: "ESP",
            0x33: "AH",
            0x3a: "ICMPV6",
            0x3b: "NONE",
            0x3c: "DSTOPTS",
            0x5c: "MTP",
            0x5e: "BEETPH",
            0x62: "ENCAP",
            0x67: "PIM",
            0x6c: "COMP",
            0x73: "L2TP",
            0x84: "SCTP",
            0x87: "MH",
            0x88: "UDPLITE",
            0x89: "MPLS",
            0x8f: "ETHERNET",
            0x90: "AGGFRAG",
            0xff: "RAW",
            0x100: "SMC",
            0x106: "MPTCP",
        }
        return dic.get(proto, str(proto))

    def parse_ip_port(self, addr, proto):
        # tcp/udp: return (ip, port)
        # other: return (ip, proto)

        ip, port = addr.split(":")

        import socket
        if len(ip) == 8: # ipv4
            # 0100007F -> 127.0.0.1
            ip = bytes.fromhex(ip)[::-1]
            ip = socket.inet_ntop(socket.AF_INET, ip)
        else: # ipv6
            # 00000000000000000000000001000000 -> ::1
            ip = bytes.fromhex(ip)
            ip = b"".join([x[::-1] for x in slicer(ip, 4)])
            ip = socket.inet_ntop(socket.AF_INET6, ip)
            ip = "[{:s}]".format(ip)

        if proto in ["tcp", "tcp6", "udp", "udp6"]:
            port = int(port, 16)
            return ip, port # str, int

        # other protocol
        real_proto = self.get_proto_string(int(port, 16))
        return ip, real_proto # str, str

    def get_extra_info(self):
        # e.g., inode -> "[tcp]           127.0.0.1:34588 -> 127.0.0.1:5001 (ESTABLISHED)"

        # get all sockets
        pid = Pid.get_pid()
        sockets = {}
        path = "/proc/{:d}/fd".format(pid)
        for fname in os.listdir(path):
            fullpath = os.path.join(path, fname)
            if os.path.islink(fullpath) and os.readlink(fullpath).startswith("socket:"):
                inode = os.readlink(fullpath).replace("socket:", "")[1:-1]
                sockets[int(inode)] = fname
        if not sockets:
            return sockets

        # get entries
        protocols = ["tcp", "udp", "tcp6", "udp6", "unix", "raw", "raw6"]
        entries = {}
        for prot in protocols:
            lines = open(f"/proc/{pid}/net/{prot}", "r").readlines()
            entries[prot] = [x.split() for x in lines[1:]]

        extra_info = {}
        for proto, proto_entries in entries.items():
            for proto_entry in proto_entries:
                # parse
                if proto in ["tcp", "tcp6", "udp", "udp6", "raw", "raw6"]:
                    _, local, remote, state, _, _, _, _, _, inode, *_ = proto_entry
                elif proto == "unix":
                    _, _, _, _, _, state, inode, *path = proto_entry
                    path = path[0] if path else ""

                # check if socket
                inode = int(inode)
                if inode not in sockets:
                    continue

                # get state
                state = self.get_state_string(proto, state)

                # make extra info
                if proto in ["tcp", "tcp6", "udp", "udp6"]:
                    local = self.parse_ip_port(local, proto)
                    if state == "LISTEN":
                        extra_info[inode] = "{:14s}  {:s}:{:d} ({:s})".format(
                            "[{:s}]".format(proto),
                            *local, state,
                        )
                    else:
                        remote = self.parse_ip_port(remote, proto)
                        extra_info[inode] = "{:14s}  {:s}:{:d} -> {:s}:{:d} ({:s})".format(
                            "[{:s}]".format(proto),
                            *local, *remote, state,
                        )
                elif proto in ["raw", "raw6"]:
                    local = self.parse_ip_port(local, proto)
                    remote = self.parse_ip_port(remote, proto)
                    extra_info[inode] = "{:14s}  {:s} -> {:s} (st={:s})".format(
                        "[{:s}/{:s}]".format(proto, local[1]),
                        local[0], remote[0], state,
                    )
                elif proto == "unix":
                    extra_info[inode] = "{:14s}  {!r} ({:s})".format(
                        "[{:s}]".format(proto),
                        path, state,
                    )
        return extra_info

    def show_fds(self):
        gef_print(titlify("File Descriptors"))

        pid = Pid.get_pid()
        path = "/proc/{:d}/fd".format(pid)

        gef_print("{:30s}  ->  {:s}".format("Num of FD slots", self.get_state_of(pid)["FDSize"]))
        items = os.listdir(path)
        if not items:
            gef_print("No FD opened")
            return

        extra_info = self.get_extra_info()

        for fname in items:
            fullpath = os.path.join(path, fname)
            if os.path.islink(fullpath):
                content = os.readlink(fullpath)
                if content.startswith("socket:["):
                    inode = int(content.replace("socket:", "")[1:-1])
                    extra = extra_info.get(inode, "")
                    gef_print("{:30s}  ->  {:s}  {:s}".format(fullpath, content, extra))
                else:
                    gef_print("{:30s}  ->  {:s}".format(fullpath, content))
        return

    @parse_args
    @only_if_gdb_running
    @only_if_gdb_target_local
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware", "rr"))
    def do_invoke(self, args):
        self.show_info_proc()
        self.show_info_proc_extra()
        self.show_parent()
        self.show_childs()
        self.show_info_thread()
        self.show_info_proc_ns()
        self.show_fds()
        return


@register_command
class FileDescriptorsCommand(GenericCommand):
    """Display opened file descriptors."""

    _cmdline_ = "fds"
    _category_ = "02-a. Process Information - General"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    _syntax_ = parser.format_help()

    def fd_dump(self):
        pid = Pid.get_pid()
        if not pid:
            err("Could not find the local pid")
            return
        path = "/proc/{:d}/fd".format(pid)

        items = os.listdir(path)
        if not items:
            err("No FD opened")
            return

        for fname in items:
            fullpath = os.path.join(path, fname)
            if os.path.islink(fullpath):
                gef_print("{:32s}  ->  {:s}".format(fullpath, os.readlink(fullpath)))
        return

    @parse_args
    @only_if_gdb_running
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware", "wine"))
    @require_arch_set
    def do_invoke(self, args):
        self.fd_dump()
        return


@register_command
class ProcDumpCommand(GenericCommand, BufferingOutput):
    """Dump each file under `/proc/PID`."""

    _cmdline_ = "proc-dump"
    _category_ = "02-a. Process Information - General"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    _syntax_ = parser.format_help()

    def dump_environ(self, path):
        data = open(path, "rb").read()
        for line in sorted(data.split(b"\0")):
            if line:
                line = String.bytes2str(line)
                key, val = line.split("=", 1)
                self.out.append("{:s}={:s}".format(Color.boldify(key), val))
        return

    def dump_cmdline(self, path):
        data = open(path, "rb").read()
        for line in data.split(b"\0"):
            if line:
                self.out.append(String.bytes2str(line))
        return

    def dump_auxv(self, path):
        data = open(path, "rb").read()
        data = slice_unpack(data, current_arch.ptrsize)
        for i in range(0, len(data), 2):
            typ = data[i]
            val = data[i + 1]
            self.out.append("{:#8x}: {:#x}".format(typ, val))
        return

    def dump_syscall(self, path):
        data = String.bytes2str(open(path, "rb").read())
        self.out.append(data.strip())

        self.out.append("----- parsed -----")

        if int(data.split()[0]) < 0:
            tag = ["NR", "sp", "pc"]
        else:
            tag = ["NR", "arg1", "arg2", "arg3", "arg4", "arg5", "arg6", "sp", "pc"]

        for i, elem in enumerate(data.split()):
            if i < len(tag):
                elem_name = tag[i]
            else:
                elem_name = "???"
            elem_name = Color.boldify("{:4s}".format(elem_name))

            if i == 0: # NR
                nr = int(elem)
                syscall_table = Syscall.get_syscall_table()
                if syscall_table is None:
                    self.out.append("Could not find the syscall table")
                    return
                if nr >= 0 and syscall_table and nr in syscall_table.nr_table:
                    syscall_name = syscall_table.nr_table[nr].name
                    self.out.append("{:2d} {:s}: {:s} ({:s})".format(i + 1, elem_name, elem, syscall_name))
                else:
                    self.out.append("{:2d} {:s}: {:s}".format(i + 1, elem_name, elem))
            else: # argN, sp, pc
                address = int(elem, 0)
                sym = Symbol.get_symbol_string(address)
                elem = "{!s}{:s}".format(ProcessMap.lookup_address(address), sym)
                self.out.append("{:2d} {:s}: {:s}".format(i + 1, elem_name, elem))
        return

    def dump_stat(self, path):
        data = String.bytes2str(open(path, "rb").read())
        self.out.append(data.strip())

        self.out.append("----- parsed -----")

        tag = [
            "pid", "comm", "state", "ppid", "pgrp", "session", "tty_nr", "tpgid", "flags",
            "minflt", "cminflt", "majflt", "cmajflt", "utime", "stime", "cutime", "cstime",
            "priority", "nice", "num_threads", "itrealvalue", "starttime", "vsize",
            "rss", "rsslim", "startcode", "endcode", "startstack", "kstkesp", "kstkeip",
            "signal", "blocked", "sigignore", "sigcatch", "wchan", "nswap", "cnswap",
            "exit_signal", "processor", "rt_priority", "policy", "delayacct_blkio_ticks",
            "guest_time", "cguest_time", "start_data", "end_data", "start_brk",
            "arg_start", "arg_end", "env_startr", "env_end", "exit_code",
        ]

        max_width = max(len(x) for x in tag)
        lpos = data.find("(")
        rpos = data.rfind(")") + 1
        data = [data[:lpos].strip(), data[lpos:rpos]] + data[rpos:].split()

        for i, elem in enumerate(data):
            if i < len(tag):
                elem_name = tag[i]
            else:
                elem_name = "???"
            elem_name = Color.boldify("{:{:d}s}".format(elem_name, max_width))

            if i + 1 in [25, 26, 27, 28, 29, 30, 45, 46, 47, 48, 49, 50, 51]:
                address = int(elem)
                sym = Symbol.get_symbol_string(address)
                elem = "{!s}{:s}".format(ProcessMap.lookup_address(address), sym)
            elif i + 1 in [23, 33, 34]:
                elem = hex(int(elem))
            self.out.append("{:2d} {:s}: {:s}".format(i + 1, elem_name, elem))
        return

    def dump_statm(self, path):
        data = String.bytes2str(open(path, "rb").read())
        self.out.append(data.strip())

        self.out.append("----- parsed -----")

        tag = ["size", "resident", "shared", "text", "lib", "data", "dt"]
        max_width = max(len(x) for x in tag)

        for i, elem in enumerate(data.split()):
            if i < len(tag):
                elem_name = tag[i]
            else:
                elem_name = "???"
            elem_name = Color.boldify("{:{:d}s}".format(elem_name, max_width))
            self.out.append("{:2d} {:s}: {:s}".format(i + 1, elem_name, elem))
        return

    def dump_status(self, path):
        try:
            column_command = GefUtil.which("column")
        except FileNotFoundError as e:
            self.out.append("{}".format(e))
            return

        ret = GefUtil.gef_execute_external([column_command, "-s:", "-t", path], as_list=True)
        for line in ret:
            r = line.split(maxsplit=1)
            if len(r) == 2:
                k, v = r[0], r[1]
            else:
                k, v = r[0], ""
            k = k.strip() + ":"
            v = v.replace("\t", "").strip()
            self.out.append("{:30s} {:s}".format(k, v))
        return

    def dump_rt_acct(self, path):
        try:
            hexdump_command = GefUtil.which("hexdump")
        except FileNotFoundError as e:
            self.out.append("{}".format(e))
            return

        ret = GefUtil.gef_execute_external([hexdump_command, "-C", path], as_list=True)
        self.out.extend(ret)
        return

    def dump_mounts(self, path):
        try:
            column_command = GefUtil.which("column")
        except FileNotFoundError as e:
            self.out.append("{}".format(e))
            return

        ret = GefUtil.gef_execute_external([column_command, "-t", path], as_list=True)
        self.out.extend(ret)
        return

    def dump_raw(self, path):
        try:
            column_command = GefUtil.which("column")
        except FileNotFoundError as e:
            self.out.append("{}".format(e))
            return

        data = open(path, "rb").read()
        data = data.replace(b"tx_queue ", b"tx_queue:")
        data = data.replace(b" tr ", b" tr:")
        tmp_fd, tmp_filename = GefUtil.mkstemp(prefix="proc-dump")
        with os.fdopen(tmp_fd, "wb") as fdw:
            fdw.write(data)
        ret = GefUtil.gef_execute_external([column_command, "-t", tmp_filename], as_list=True)
        os.unlink(tmp_filename)
        self.out.extend(ret)
        return

    def dump_dev(self, path):
        try:
            column_command = GefUtil.which("column")
        except FileNotFoundError as e:
            self.out.append("{}".format(e))
            return

        data = open(path, "rb").read()
        data = data.replace(b"|", b" |")
        data = re.sub(rb"\|\s*Receive", b"|Receive", data)
        data = re.sub(rb"\|\s*Transmit", b"|Transmit", data)

        tmp_fd, tmp_filename = GefUtil.mkstemp(prefix="proc-dump")
        with os.fdopen(tmp_fd, "wb") as fdw:
            fdw.write(data)
        ret = GefUtil.gef_execute_external([column_command, "-t", tmp_filename], as_list=True)
        os.unlink(tmp_filename)

        wrong = ret[0].rfind("|")
        rright = ret[1].rfind("|")
        lright = ret[1].find("|")
        ret[0] = (ret[0][:wrong] + " " * (rright - wrong) + ret[0][wrong:]).rstrip()

        ret[0] = re.sub(r"\|(\S+)", "| \\1 ", ret[0])
        ret[1] = re.sub(r"\|(\S+)", "| \\1 ", ret[1])
        for i in range(2, len(ret)):
            ret[i] = ret[i][:lright] + "  " + ret[i][lright:]
            ret[i] = ret[i][:rright] + "  " + ret[i][rright:]

        self.out.extend(ret)
        return

    def dump_igmp(self, path):
        with open(path, "rb") as fd:
            for line in fd.readlines():
                self.out.append(String.bytes2str(line.rstrip())) # no-lstrip
        return

    def dump_netstat(self, path):
        data = String.bytes2str(open(path, "rb").read())
        table = [line.split() for line in data.splitlines()]
        for idx in range(0, len(table), 2):
            for i, (k, v) in enumerate(zip(*table[idx:idx + 2])):
                if i == 0:
                    self.out.append("{:s}".format(k))
                else:
                    self.out.append("  {:30s} {:s}".format(k + ":", v))
        return

    def dump_default(self, path):
        if not os.access(path, os.R_OK):
            self.out.append("{:s} No permission to read".format(Color.colorify("[!]", "bold red")))
            return

        try:
            fd = open(path, "rb")
        except OSError:
            self.out.append("{:s} Failed to open".format(Color.colorify("[!]", "bold red")))
            return

        try:
            with fd:
                for line in fd.readlines():
                    self.out.append(String.bytes2str(line).strip())
        except OSError:
            self.out.append("{:s} Parse failed".format(Color.colorify("[!]", "bold red")))
        return

    def proc_dump(self):
        pid = Pid.get_pid()
        for root, dirs, files in os.walk("/proc/{:d}/".format(pid)):
            files = sorted(files)

            if "task" in dirs:
                dirs.remove("task") # in-place change to skip /proc/<pid>/task/

            for f in files:
                path = os.path.join(root, f)
                self.out.append(titlify(path))

                if os.path.islink(path):
                    self.out.append(Color.colorify("{:s} -> {:s}".format(path, os.readlink(path)), "blue"))
                    continue

                if f in ["pagemap", "mem"]:
                    self.out.append("{:s} skipped".format(Color.colorify("[*]", "bold yellow"))) # too large
                    continue

                if f == "environ":
                    self.dump_environ(path)
                    continue

                if f in ["cmdline", "context"]:
                    self.dump_cmdline(path)
                    continue

                if f == "auxv":
                    self.dump_auxv(path)
                    continue

                if f == "syscall":
                    self.dump_syscall(path)
                    continue

                if f == "stat":
                    self.dump_stat(path)
                    continue

                if f == "statm":
                    self.dump_statm(path)
                    continue

                if f == "rt_acct":
                    self.dump_rt_acct(path)
                    continue

                if f == "status":
                    self.dump_status(path)
                    continue

                if f in ["mounts", "mountinfo", "mountstats", "unix", "protocols"]:
                    self.dump_mounts(path)
                    continue

                if f in ["raw", "tcp", "udp", "icmp", "raw6", "tcp6", "udp6", "icmp6", "udplite", "udplite6"]:
                    self.dump_raw(path)
                    continue

                if f == "dev":
                    self.dump_dev(path)
                    continue

                if f in ["igmp", "fib_trie", "wireless"]:
                    self.dump_igmp(path)
                    continue

                if f in ["netstat", "snmp"]:
                    self.dump_netstat(path)
                    continue

                self.dump_default(path)
        return

    @parse_args
    @only_if_gdb_running
    @only_if_gdb_target_local
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware"))
    @require_arch_set
    def do_invoke(self, args):
        self.out = []
        self.proc_dump()
        self.print_output(check_terminal_size=True)
        return


@register_command
class CapabilityCommand(GenericCommand, BufferingOutput):
    """Display the capabilities of the debugging process."""

    _cmdline_ = "capability"
    _category_ = "02-f. Process Information - Security"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    parser.add_argument("-v", "--verbose", action="store_true",
                        help="also display detailed bit information other than cap_eff.")
    _syntax_ = parser.format_help()

    def get_thread_ids(self, pid):
        try:
            tids = os.listdir("/proc/{:d}/task".format(pid))
            return [int(x) for x in tids]
        except (FileNotFoundError, OSError):
            return []

    def print_cap_details(self, name, cap):
        bit_info = [
            [40, "CAP_CHECKPOINT_RESTORE", "Update /proc/sys/kernel/ns_last_pid; read /proc/[another_pid]/map_files; etc."],
            [39, "CAP_BPF", "Allow privileged BPF operations"],
            [38, "CAP_PERFMON", "Allow various performance-monitoring mechanisms; allow perf_event_open(2); allow some BPF operations"],
            [37, "CAP_AUDIT_READ", "Allow reading the audit log via a multicast netlink socket"],
            [36, "CAP_BLOCK_SUSPEND", "Allow features that can block system suspend"],
            [35, "CAP_WAKE_ALARM", "Trigger something that will wake up the system"],
            [34, "CAP_SYSLOG", "Allow privileged syslog(2) operations; View kernel addresses exposed via /proc even if kptr_restrict=1"],
            [33, "CAP_MAC_ADMIN", "Allow MAC configuration or state changes"],
            [32, "CAP_MAC_OVERRIDE", "Override MAC"],
            [31, "CAP_SETFCAP", "Set arbitrary capabilities on a file"],
            [30, "CAP_AUDIT_CONTROL", "Enable/disable kernel audit; change audit filter rules; retrieve audit status and filter rules"],
            [29, "CAP_AUDIT_WRITE", "Write records to kernel audit log"],
            [28, "CAP_LEASE", "Establish leases"],
            [27, "CAP_MKNOD", "Create special files using mknod(2)"],
            [26, "CAP_SYS_TTY_CONFIG", "Allow vhangup(2); allow various privileged ioctl(2) operations on virtual terminals"],
            [25, "CAP_SYS_TIME", "Set system clock; set real-time (hardware) clock"],
            [24, "CAP_SYS_RESOURCE", "Override disk quota limits; override RLIMIT_NPROC resource limit; etc."],
            [23, "CAP_SYS_NICE", "Lower the process nice value and change the nice value for arbitrary processes; etc."],
            [22, "CAP_SYS_BOOT", "Allow reboot(2) and kexec_load(2)"],
            [21, "CAP_SYS_ADMIN", "Allow various privileges operations"],
            [20, "CAP_SYS_PACCT", "Allow acct(2)"],
            [19, "CAP_SYS_PTRACE", "Trace arbitrary processes using ptrace(2); etc."],
            [18, "CAP_SYS_CHROOT", "Allow chroot(2); change mount namespaces using setns(2)"],
            [17, "CAP_SYS_RAWIO", "Perform I/O port operations; etc."],
            [16, "CAP_SYS_MODULE", "Load and unload kernel modules"],
            [15, "CAP_IPC_OWNER", "Bypass permission checks for operations on SystemV IPC objects"],
            [14, "CAP_IPC_LOCK", "Lock memory; allocate memory using huge pages"],
            [13, "CAP_NET_RAW", "Use RAW and PACKET sockets; bind to any address for transparent proxying"],
            [12, "CAP_NET_ADMIN", "Perform various network-related operations"],
            [11, "CAP_NET_BROADCAST", "(Unused) Make socket broadcasts, and listen to multicast"],
            [10, "CAP_NET_BIND_SERVICE", "Bind a socket to Internet domain privileged ports (less than 1024)"],
            [9, "CAP_LINUX_IMMUTABLE", "Set the FS_APPEND_FL and FS_IMMUTABLE_FL inode flags"],
            [8, "CAP_SETPCAP", "Add any capability from the calling thread's bounding set to its inheritable set; etc."],
            [7, "CAP_SETUID", "Make arbitrary manipulations of process UIDs; etc."],
            [6, "CAP_SETGID", "Make arbitrary manipulations of process GIDs and supplementary GID list; etc."],
            [5, "CAP_KILL", "Bypass permission checks for sending signals"],
            [4, "CAP_FSETID", "Don't clear SUID and SGID bits when a file is modified; etc."],
            [3, "CAP_FOWNER", "Bypass permission checks whether FSUID == file UID; set ACLs; etc."],
            [2, "CAP_DAC_READ_SEARCH", "Bypass permission checks of file read, dir read/exec; etc."],
            [1, "CAP_DAC_OVERRIDE", "Bypass permission checks of file read/write/exec"],
            [0, "CAP_CHOWN", "Make arbitrary changes to file UIDs and GIDs"],
        ]
        out = BitInfo(name, 64, bit_info).make_out(cap)
        self.out.append(titlify(""))
        self.out.extend(out)
        self.out.append(titlify(""))
        return

    def print_capability_from_pid(self):
        pid = Pid.get_pid()
        if pid is None:
            return

        tids = self.get_thread_ids(pid)
        for tid in tids:
            self.out.append(titlify("Thread capability set [PID={:d}, TID={:d}]".format(pid, tid)))
            try:
                status_path = "/proc/{:d}/task/{:d}/status".format(pid, tid)
                status = open(status_path, "r").read()
            except (FileNotFoundError, OSError):
                self.err_add_out("Failed to get the information of capability from {:s}".format(status_path))
                continue

            caps = {}
            m = re.search(r"CapInh:\s+(.+)", status)
            if m:
                caps["cap_inh"] = int(m.group(1), 16)
            m = re.search(r"CapPrm:\s+(.+)", status)
            if m:
                caps["cap_prm"] = int(m.group(1), 16)
            m = re.search(r"CapEff:\s+(.+)", status)
            if m:
                caps["cap_eff"] = int(m.group(1), 16)
            m = re.search(r"CapBnd:\s+(.+)", status)
            if m:
                caps["cap_bnd"] = int(m.group(1), 16)
            m = re.search(r"CapAmb:\s+(.+)", status)
            if m:
                caps["cap_amb"] = int(m.group(1), 16)

            if "cap_prm" in caps:
                msg = "Capability set that Effective and Inheritable are allowed to have"
                self.out.append("Permitted  : {:#018x} - {:s}".format(caps["cap_prm"], msg))
                if self.args.verbose:
                    self.print_cap_details("cap_prm", caps["cap_prm"])
            if "cap_inh" in caps:
                msg = "Capability set that can be inherited when execve(2)"
                self.out.append("Inheritable: {:#018x} - {:s}".format(caps["cap_inh"], msg))
                if self.args.verbose:
                    self.print_cap_details("cap_inh", caps["cap_inh"])
            if "cap_amb" in caps:
                msg = "Capability set that inherited when execve(2) not suid/sgid program"
                self.out.append("Ambient    : {:#018x} - {:s}".format(caps["cap_amb"], msg))
                if self.args.verbose:
                    self.print_cap_details("cap_amb", caps["cap_amb"])
            if "cap_eff" in caps:
                msg = "Capability set that kernel actually uses to determine privileges"
                self.out.append("Effective  : {:#018x} - {:s}".format(caps["cap_eff"], msg))
                if self.args.verbose:
                    self.print_cap_details("cap_eff", caps["cap_eff"])
            if "cap_bnd" in caps:
                msg = "Capability set that limits the capabilities set that can be acquired"
                self.out.append("Bounding   : {:#018x} - {:s}".format(caps["cap_bnd"], msg))
                if self.args.verbose:
                    self.print_cap_details("cap_bnd", caps["cap_bnd"])
        return

    def print_capability_from_file(self):
        filepath = Path.get_filepath()
        if filepath is None:
            return

        self.out.append(titlify("File capability set [{:s}]".format(filepath)))
        try:
            raw_caps = os.getxattr(filepath, "security.capability")
        except OSError:
            self.err_add_out("No data available")
            return

        caps = {}
        magic = struct.unpack("<I", raw_caps[:4])[0]
        caps["magic"] = magic & ~1
        caps["cap_eff"] = magic & 1
        if caps["magic"] == 0x0100_0000:
            cap_prm, cap_inh = struct.unpack("<II", raw_caps[4:12])
        elif caps["magic"] == 0x0200_0000:
            cap_prm_low, cap_inh_low, cap_prm_high, cap_inh_high = struct.unpack("<IIII", raw_caps[4:20])
            cap_prm = (cap_prm_high << 32) | cap_prm_low
            cap_inh = (cap_inh_high << 32) | cap_inh_low
        elif caps["magic"] == 0x0300_0000:
            cap_prm_low, cap_inh_low, cap_prm_high, cap_inh_high, rootid = struct.unpack("<IIIII", raw_caps[4:24])
            cap_prm = (cap_prm_high << 32) | cap_prm_low
            cap_inh = (cap_inh_high << 32) | cap_inh_low
            caps["rootid"] = rootid
        else:
            self.err_add_out("Invalid magic values: {:#x}".format(magic))
            return
        caps["cap_prm"] = cap_prm
        caps["cap_inh"] = cap_inh

        if "magic" in caps:
            msg = "Magic number: ver1: 0x01000000, ver2:0x02000000, ver3:0x03000000"
            self.out.append("Magic      : {:#010x} - {:s}".format(caps["magic"], msg))
        if "cap_eff" in caps:
            msg = "If 1, new cap_prm are added to new cap_eff after execve(2)"
            self.out.append("Effective  : {:#03x} - {:s}".format(caps["cap_eff"], msg))
        if "cap_prm" in caps:
            msg = "Capability set that permitted to the thread, regardless of the thread's cap_inh"
            self.out.append("Permitted  : {:#018x} - {:s}".format(caps["cap_prm"], msg))
            if self.args.verbose:
                self.print_cap_details("cap_prm", caps["cap_prm"])
        if "cap_inh" in caps:
            msg = "Capability set that is ANDed with thread cap_inh to determine cap_inh after execve(2)"
            self.out.append("Inheritable: {:#018x} - {:s}".format(caps["cap_inh"], msg))
            if self.args.verbose:
                self.print_cap_details("cap_inh", caps["cap_inh"])
        if "rootid" in caps:
            msg = "UID of root in user namespace"
            self.out.append("Root ID    : {:#010x} - {:s}".format(caps["rootid"], msg))
        return

    @parse_args
    @only_if_gdb_target_local
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware", "wine"))
    @require_arch_set
    def do_invoke(self, args):
        self.out = []
        self.print_capability_from_pid()
        self.print_capability_from_file()
        self.print_output(check_terminal_size=True)
        return


@register_command
class SmartMemoryDumpCommand(GenericCommand):
    """Dump the memory of the entire process smartly."""

    _cmdline_ = "smart-memory-dump"
    _category_ = "03-f. Memory - Dump/Load"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-p", "--prefix", default="",
                        help="use this name for the dump destination file prefix. (default: '')")
    parser.add_argument("-s", "--suffix", default="",
                        help="use this name for the dump destination file suffix. (default: '')")
    parser.add_argument("-f", "--filter", action="append", type=re.compile, default=[],
                        help="REGEXP include filter.")
    parser.add_argument("-e", "--exclude", action="append", type=re.compile, default=[],
                        help="REGEXP exclude filter.")
    parser.add_argument("-c", "--commit", action="store_true", help="actually perform the dump.")
    parser.add_argument("-m", "--max-region-size", type=AddressUtil.parse_address, default=0x1000_0000,
                        help="maximum size of dump region. (default: %(default)#x; 0: infinity)")
    _syntax_ = parser.format_help()

    def do_dump(self, filepath, start, size):
        if self.args.max_region_size and self.args.max_region_size < size:
            warn("Too large, so skip: {:s}".format(filepath))
            return

        size_str = GefUtil.get_size_str(size)

        if self.args.commit:
            # make dir
            if not os.path.exists(os.path.dirname(filepath)):
                os.mkdir(os.path.dirname(filepath))

            # read
            try:
                data = read_memory(start, size)
            except gdb.MemoryError:
                warn("Memory read error; skipped: {:s} ({:s})".format(filepath, size_str))
                return

            # write
            with open(filepath, "wb") as fdw:
                fdw.write(data)
            info("Saved to {:s} ({:s})".format(filepath, size_str))
        else:
            info("It will be saved to {:s} ({:s})".format(filepath, size_str))
        return

    def smart_memory_dump(self, maps, prefix, suffix):
        dirpath = os.path.join(GEF_TEMP_DIR, "mem-dump-" + GefUtil.now_str())
        width = current_arch.ptrsize * 2
        total_size = 0

        for entry in maps:
            if isinstance(entry, list):
                start = entry[0]
                end = entry[0] + entry[1]
                size = entry[1]
                perm = entry[2].lower()
                path = ""
            else:
                start = entry.page_start
                end = entry.page_end
                size = end - start
                perm = str(entry.permission)

                if not entry.path.startswith(("[", "<")):
                    path = os.path.basename(entry.path)
                else:
                    path = entry.path
                    path = path.replace("[", "").replace("]", "") # consider [heap], [stack], [vdso]
                    path = path.replace("<", "").replace(">", "") # consider <tls-th1>, <explored>
                path = path.replace(" ", "_") # consider deleted case. e.g., /path/to/file (deleted)

            dumpfile_name = "{:s}{:0{:d}x}-{:0{:d}x}_{:s}_{:s}{:s}.raw".format(
                prefix, start, width, end, width, perm, path, suffix,
            )
            filepath = os.path.join(dirpath, dumpfile_name)

            # filtering
            if self.args.filter and not any(filt.search(dumpfile_name) for filt in self.args.filter):
                continue
            if self.args.exclude and any(ex.search(dumpfile_name) for ex in self.args.exclude):
                continue

            # dump
            self.do_dump(filepath, start, size)
            total_size += size

        info("Total size: {:s}".format(GefUtil.get_size_str(total_size)))

        if not self.args.commit:
            info("The directory name is replaced with the latest timestamp")
            warn('This dry run mode skips dumping; add "--commit" to proceed')
        return

    @parse_args
    @only_if_gdb_running
    @exclude_specific_gdb_mode(mode=("kgdb", "vmware"))
    @require_arch_set
    def do_invoke(self, args):
        if is_qemu_system():
            maps = Kernel.get_maps()
        else:
            maps = ProcessMap.get_process_maps_exclude_special_regions(allow_vdso=True)
        if maps is None:
            err("Failed to get maps")
            return

        prefix = self.args.prefix
        if prefix:
            prefix = prefix + "_"

        suffix = self.args.suffix
        if suffix:
            suffix = "_" + suffix

        self.smart_memory_dump(maps, prefix, suffix)
        return


@register_command
class HijackFdCommand(GenericCommand):
    """Redirect the file descriptor during execution."""

    _cmdline_ = "hijack-fd"
    _category_ = "01-g. Debugging Support - Syscall"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("old_fd", metavar="OLD_FD", type=int, help="file descriptor number to redirect.")
    parser.add_argument("new_output", metavar="NEW_OUTPUT", type=str, help="the location redirected data is stored.")
    parser.add_argument("--fd-adjust-connect", type=int, default=0,
                        help="slide value when `connect` syscall result and the actual opened FD differ (for old qemu-user).")
    parser.add_argument("--fd-adjust-dup3", type=int, default=0,
                        help="slide value when `dup3` syscall result and the actual opened FD differ (for old qemu-user).")
    parser.add_argument("-q", "--quiet", action="store_true", help="quiet execution.")
    _syntax_ = parser.format_help()

    _example_ = [
        "{0:s} 2 /tmp/gef/stderr.txt",
        "{0:s} 2 localhost:8000  # determined as the socket by the presence of `:`.",
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    def call_syscall(self, syscall_name, args):
        args = " ".join([hex(x) if x >= 0 else str(x) for x in args])
        cmd = "call-syscall {:s} {:s}".format(syscall_name, args)
        self.quiet_info(cmd)
        res = gdb.execute(cmd, to_string=True)
        output_line = res.splitlines()[-1]
        self.quiet_info(output_line)
        return int(output_line.split()[2], 0)

    def write_stack(self, data):
        data = String.str2bytes(data)

        # get stack address
        vmmap = ProcessMap.get_process_maps()
        stack_addrs = [entry.page_start for entry in vmmap if entry.path == "[stack]"]
        if len(stack_addrs) == 0:
            err("Could not find the stack")
            return None, None
        stack_addr = stack_addrs[0]

        # read original contents
        try:
            original_contents = read_memory(stack_addr, len(data))
        except gdb.MemoryError:
            err("Failed to read stack")
            return None, None

        self.quiet_info("Original contents: {!s} @ {:#x}".format(original_contents, stack_addr))
        self.quiet_info("Overwrite data: {!s}".format(data))

        # overwrite it
        try:
            write_memory(stack_addr, data)
        except Exception:
            err("Failed to write stack")
            return None, None

        # read again and check
        if read_memory(stack_addr, len(data)) != data:
            err("Failed to write stack")
            return None, None

        return stack_addr, original_contents

    def get_fd_from_file_open(self):
        # call open
        stack_addr, original_contents = self.write_stack(self.args.new_output + "\0")
        if stack_addr is None:
            return None

        self.quiet_info("Trying to open {:s}".format(Color.boldify(self.args.new_output)))

        AT_FDCWD = -100
        flags = self.O_APPEND | self.O_CREAT | self.O_RDWR
        mode = 0o666
        # open does not exist in aarch64. So use openat instead of open.
        open_fd = self.call_syscall("openat", [AT_FDCWD, stack_addr, flags, mode])
        write_memory(stack_addr, original_contents) # revert

        if AddressUtil.is_msb_on(open_fd):
            err("Failed to open {:s}".format(self.args.new_output))
            return None

        self.quiet_info("Opened {:s} with 0o666 as fd #{:d}".format(Color.boldify(self.args.new_output), open_fd))
        return open_fd

    def get_fd_from_connect_server(self):
        import socket
        address = socket.gethostbyname(self.args.new_output.split(":")[0])
        port = int(self.args.new_output.split(":")[1])

        # call socket
        sock_fd = self.call_syscall("socket", [self.AF_INET, self.SOCK_STREAM, 0])
        if AddressUtil.is_msb_on(sock_fd):
            err("Failed to create socket")
            return None
        self.quiet_info("Created socket fd #{:d}".format(sock_fd))

        # call connect (Also supports big endian)
        sockaddr_in = p16(self.AF_INET) + struct.pack("<H", socket.htons(port)) + socket.inet_aton(address)
        stack_addr, original_contents = self.write_stack(sockaddr_in)
        if stack_addr is None:
            return None

        self.quiet_info("Trying to connect to {:s}".format(Color.boldify(self.args.new_output)))
        connect_result = self.call_syscall("connect", [sock_fd - self.args.fd_adjust_connect, stack_addr, 16])
        write_memory(stack_addr, original_contents) # revert

        if AddressUtil.is_msb_on(connect_result):
            err("Failed to connect to {:s}:{:d}".format(address, port))
            return

        self.quiet_info("Connected to {:s} as fd #{:d}".format(Color.boldify(self.args.new_output), sock_fd))
        return sock_fd

    def hijack_fd(self):
        if ":" in self.args.new_output:
            new_fd = self.get_fd_from_connect_server()
        else:
            new_fd = self.get_fd_from_file_open()
        if new_fd is None:
            return

        # call dup3
        # dup2 does not exist in aarch64. So use dup3 instead of dup2.
        dup3_result = self.call_syscall("dup3", [new_fd - self.args.fd_adjust_dup3, self.args.old_fd, 0])
        if dup3_result - self.args.fd_adjust_dup3 != self.args.old_fd:
            err("Failed to dup3 (result {:d} != fd #{:d})".format(dup3_result, self.args.old_fd))
            return
        self.quiet_info("Duplicated fd #{:d} -> #{:d}".format(new_fd, self.args.old_fd))

        # call close
        close_result = self.call_syscall("close", [new_fd])
        if AddressUtil.is_msb_on(close_result):
            err("Failed to close fd #{:d}".format(new_fd))
            return
        self.quiet_info("Closed extra fd #{:d}".format(new_fd))

        ok("Success")
        return

    @parse_args
    @only_if_gdb_running
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware", "rr", "wine"))
    @exclude_specific_arch(arch=("CRIS",))
    @require_arch_set
    def do_invoke(self, args):
        # In old version of qemu, the file descriptor was sometimes shifted by a
        # constant value on i386 (fd returned by the syscall == actual opened fd + 80).
        # This had been hard-coded as a workaround, but the issue appears to be fixed,
        # so it should now be specified via a command argument.
        # Currently supported: dup3, connect

        self.AF_INET = 2
        self.SOCK_STREAM = 1
        self.O_APPEND = 0o2000
        self.O_CREAT = 0o100
        self.O_RDWR = 0o2
        # some architecture use different consts.
        if is_mips32() or is_mips64() or is_mipsn32():
            # /usr/mipsel-linux-gnu/include/bits/socket_type.h
            # /usr/mips64el-linux-gnuabi64/include/bits/socket_type.h
            self.SOCK_STREAM = 2
            # /usr/mipsel-linux-gnu/include/bits/fcntl.h
            # /usr/mips64el-linux-gnuabi64/include/bits/fcntl.h
            self.O_APPEND = 0x0008
            self.O_CREAT = 0x0100
        elif is_sparc32() or is_sparc32plus() or is_sparc64():
            # sparcv8--uclibc--stable-2022.08-1/sparc-buildroot-linux-uclibc/sysroot/usr/include/bits/fcntl.h
            # sparc64--glibc--stable-2022.08-1/sparc64-buildroot-linux-gnu/sysroot/usr/include/bits/fcntl.h
            self.O_APPEND = 0x0008
            self.O_CREAT = 0x0200
        elif is_alpha():
            # /usr/alpha-linux-gnu/include/bits/fcntl.h
            self.O_APPEND = 0o0010
            self.O_CREAT = 0o1000
        elif is_hppa32() or is_hppa64():
            # /usr/hppa-linux-gnu/include/bits/fcntl.h
            self.O_APPEND = 0o0010
            self.O_CREAT = 0o0400

        self.hijack_fd()
        return


@register_command
class XtapCommand(GenericCommand):
    """Tap read/write syscalls on specific file descriptors and hexdump the transferred data."""

    _cmdline_ = "xtap"
    _category_ = "01-g. Debugging Support - Syscall"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("fd", metavar="FD", nargs="+", type=AddressUtil.parse_address,
                        help="the file descriptor(s) to tap.")
    parser.add_argument("--max", dest="maxlen", type=AddressUtil.parse_address,
                        help="limit the number of bytes to hexdump per transfer.")
    _syntax_ = parser.format_help()

    _example_ = [
        "{0:s} 0               # tap stdin",
        "{0:s} 4               # tap fd 4 (e.g. a socket)",
        "{0:s} 0 1 2           # tap stdin/stdout/stderr",
        "{0:s} 4 --max 0x40    # tap fd 4, dump at most 0x40 bytes per transfer",
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    _note_ = [
        "Hooked syscalls:",
        "  read-like: read, recvfrom, recvmsg, recvmmsg, recvmmsg_time64, pread64, preadv, preadv2, readv",
        "  write-like: write, sendto, sendmsg, sendmmsg, pwrite64, pwritev, pwritev2, writev",
        "",
        "- Relies on `catch syscall`.",
        "- Auto-continues; stops on a user breakpoint or Ctrl+C.",
        "- qemu-user is unsupported: its gdbstub does not update the return-value register",
        "  at syscall-return, so read-like sizes are wrong. Use a native target.",
    ]
    _note_ = "\n".join(_note_)

    syscall_spec = {
        "read":             ("in",  "buf"),
        "recvfrom":         ("in",  "buf"),
        "pread64":          ("in",  "buf"),
        "readv":            ("in",  "iovec"),
        "preadv":           ("in",  "iovec"),
        "preadv2":          ("in",  "iovec"),
        "recvmsg":          ("in",  "msghdr"),
        "recvmmsg":         ("in",  "mmsghdr"),
        "recvmmsg_time64":  ("in",  "mmsghdr"),
        "write":            ("out", "buf"),
        "sendto":           ("out", "buf"),
        "pwrite64":         ("out", "buf"),
        "writev":           ("out", "iovec"),
        "pwritev":          ("out", "iovec"),
        "pwritev2":         ("out", "iovec"),
        "sendmsg":          ("out", "msghdr"),
        "sendmmsg":         ("out", "mmsghdr"),
    }

    def read_iovec_array(self, vec_addr, vlen):
        """Return a list of (base, length) tuples from a struct iovec array."""
        entries = []
        cur = vec_addr
        for _ in range(vlen):
            iov_base = read_int_from_memory(cur)
            iov_len = read_int_from_memory(cur + current_arch.ptrsize)
            entries.append((iov_base, iov_len))
            cur += current_arch.ptrsize * 2
        return entries

    def gather_iovec_bytes(self, entries, limit):
        """Concatenate bytes described by iovec entries, capped at `limit` bytes total."""
        data = bytearray()
        for base, length in entries:
            if limit is not None and len(data) >= limit:
                break
            want = length
            if limit is not None:
                want = min(want, limit - len(data))
            if want <= 0:
                continue
            try:
                data += read_memory(base, want)
            except gdb.error:
                break
        return bytes(data)

    def read_msghdr(self, msg_addr):
        """Return iovec entries from a struct msghdr.

        struct msghdr layout:
          void*         msg_name        off 0
          socklen_t     msg_namelen     off ptrsize       (padded to ptrsize)
          struct iovec* msg_iov         off ptrsize*2
          size_t        msg_iovlen      off ptrsize*3
          ...
        """
        msg_iov = read_int_from_memory(msg_addr + current_arch.ptrsize * 2)
        msg_iovlen = read_int_from_memory(msg_addr + current_arch.ptrsize * 3)
        return self.read_iovec_array(msg_iov, msg_iovlen)

    def read_mmsghdr_entries(self, mmsg_addr, vlen):
        """Return a flat list of iovec entries across a struct mmsghdr array.

        struct mmsghdr layout:
          struct msghdr msg_hdr     off 0
          unsigned int  msg_len     off sizeof(struct msghdr)

        sizeof(struct msghdr) is 7 pointers:
          msg_name, msg_namelen(+pad), msg_iov, msg_iovlen, msg_control, msg_controllen(+pad),
          msg_flags(+pad). We step by that stride.
        """
        msghdr_size = current_arch.ptrsize * 7
        mmsghdr_stride = msghdr_size + current_arch.ptrsize  # msg_len is unsigned int but padded to ptrsize
        entries = []
        cur = mmsg_addr
        for _ in range(vlen):
            entries += self.read_msghdr(cur)
            cur += mmsghdr_stride
        return entries

    def extract_entry_data(self, name, arg_regs):
        """Read data for write-like syscalls at entry. Returns (label, bytes) or None."""
        kind = self.syscall_spec[name][1]

        if kind == "buf":
            # buf is 2nd arg, count is 3rd arg
            buf = get_register(arg_regs[1])
            count = get_register(arg_regs[2])
            if self.maxlen is not None:
                count = min(count, self.maxlen)
            try:
                data = read_memory(buf, count)
            except gdb.error:
                return None
            return ("buf={:#x} count={:#x}".format(buf, count), data)

        if kind == "iovec":
            # iov is 2nd arg, iovcnt is 3rd arg
            iov = get_register(arg_regs[1])
            iovcnt = get_register(arg_regs[2])
            entries = self.read_iovec_array(iov, iovcnt)
            data = self.gather_iovec_bytes(entries, self.maxlen)
            return ("iov={:#x} iovcnt={:#x}".format(iov, iovcnt), data)

        if kind == "msghdr":
            # msg is 2nd arg
            msg = get_register(arg_regs[1])
            entries = self.read_msghdr(msg)
            data = self.gather_iovec_bytes(entries, self.maxlen)
            return ("msghdr={:#x}".format(msg), data)

        if kind == "mmsghdr":
            # msgvec is 2nd arg, vlen is 3rd arg
            msgvec = get_register(arg_regs[1])
            vlen = get_register(arg_regs[2])
            entries = self.read_mmsghdr_entries(msgvec, vlen)
            data = self.gather_iovec_bytes(entries, self.maxlen)
            return ("mmsghdr={:#x} vlen={:#x}".format(msgvec, vlen), data)

        return None

    def extract_exit_data(self, name, entry_args, retval):
        """Read data for read-like syscalls at exit. Returns (label, bytes) or None.
        `retval` is the number of bytes actually transferred. `entry_args` carries
        the argument register values captured at entry.
        """
        kind = self.syscall_spec[name][1]

        if retval is None or retval <= 0:
            return ("returned {}".format(retval if retval is not None else "?"), b"")

        limit = retval
        if self.maxlen is not None:
            limit = min(limit, self.maxlen)

        if kind == "buf":
            buf = entry_args[1]
            try:
                data = read_memory(buf, limit)
            except gdb.error:
                return None
            return ("buf={:#x} ret={:#x}".format(buf, retval), data)

        if kind == "iovec":
            iov = entry_args[1]
            iovcnt = entry_args[2]
            entries = self.read_iovec_array(iov, iovcnt)
            data = self.gather_iovec_bytes(entries, limit)
            return ("iov={:#x} ret={:#x}".format(iov, retval), data)

        if kind == "msghdr":
            msg = entry_args[1]
            entries = self.read_msghdr(msg)
            data = self.gather_iovec_bytes(entries, limit)
            return ("msghdr={:#x} ret={:#x}".format(msg, retval), data)

        return None

    def entry_fd(self, arg_regs):
        """All hooked syscalls take fd as their first argument."""
        return get_register(arg_regs[0])

    def close_stdout_stderr(self):
        self.stdout = 1
        self.stdout_bak = os.dup(self.stdout)
        f = open("/dev/null", "w")
        os.dup2(f.fileno(), self.stdout)
        f.close()

        self.stderr = 2
        self.stderr_bak = os.dup(self.stderr)
        f = open("/dev/null", "w")
        os.dup2(f.fileno(), self.stderr)
        f.close()
        return

    def revert_stdout_stderr(self):
        os.dup2(self.stdout_bak, self.stdout)
        os.close(self.stdout_bak)
        os.dup2(self.stderr_bak, self.stderr)
        os.close(self.stderr_bak)
        return

    def force_write_stdout(self, msg):
        with open("/proc/self/fd/0", "wb") as fdw:
            fdw.write(msg)
        return

    def dump_transfer(self, name, direction, fd, label, data):
        arrow = "<-" if direction == "in" else "->"
        head = "[fd {:d}] {:s} {:s} {:s}".format(fd, name, arrow, label)
        lines = [titlify(head)]
        if data:
            lines.append(hexdump(data, base=0))
        else:
            lines.append("(no data)")
        self.force_write_stdout(String.str2bytes("\n".join(lines) + "\n"))
        return

    def setup_catchpoints(self):
        """Set a catch syscall for every supported+available syscall. Returns count set."""
        for name in self.syscall_spec:
            # only attempt syscalls the running target actually knows
            if self.syscall_table and name not in self.syscall_table.name_table:
                warn("syscall '{:s}' is unknown on this target, skipped".format(name))
                continue
            try:
                res = gdb.execute("catch syscall {:s}".format(name), to_string=True)
            except gdb.error as e:
                warn("could not set catch syscall '{:s}': {}".format(name, e))
                continue
            # gdb prints e.g. "Catchpoint 3 (syscall 'read' [0])"
            num = None
            for tok in res.split():
                if tok.isdigit():
                    num = int(tok)
                    break
            if num is None:
                warn("catch syscall '{:s}' did not return a catchpoint number, skipped".format(name))
                # best-effort: it may still have been created; try to clean up later via name match is unreliable,
                # so leave it. but do not track an unknown number.
                continue
            self.catch_numbers.append(num)
            self.hooked_names.append(name)
            self.hooked_set.add(name)
        return len(self.catch_numbers)

    def teardown_catchpoints(self):
        for num in self.catch_numbers:
            try:
                gdb.execute("delete {:d}".format(num), to_string=True)
            except gdb.error:
                pass
        self.catch_numbers = []
        return

    def syscall_nr_register(self):
        if is_x86_64():
            return "$orig_rax"
        if is_x86_32():
            return "$orig_eax"
        return None

    def current_syscall_number(self):
        """Return the syscall number at the current catch-syscall stop, or None."""
        regname = self.syscall_nr_register()
        if regname is None:
            return None
        try:
            nr = get_register(regname)
        except Exception:
            nr = None
        return nr

    def current_syscall_name(self):
        """Return the name of the syscall at the current catch-syscall stop, or None."""
        if self.syscall_table is None:
            return None
        nr = self.current_syscall_number()
        if nr is None:
            return None
        entry = self.syscall_table.nr_table.get(nr, None)
        if entry is None:
            return None
        return entry.name

    def identify_stop(self):
        """Determine if the current stop is one of our tapped syscalls."""
        try:
            tid = gdb.selected_thread().num
        except Exception:
            tid = 0

        pending_name = self.in_syscall_by_thread.get(tid, None)
        if pending_name is not None:
            # this stop is the return matching the previous entry on this thread
            self.in_syscall_by_thread[tid] = None
            if pending_name not in self.hooked_set:
                return None
            return pending_name, False

        # this stop is an entry: resolve the syscall name now and remember it
        name = self.current_syscall_name()
        self.in_syscall_by_thread[tid] = name
        if name is None or name not in self.hooked_set:
            return None
        return name, True

    def handle_entry(self, name):
        try:
            tid = gdb.selected_thread().num
        except Exception:
            tid = 0
        entry = self.syscall_table.name_table[name]
        arg_regs = entry.arg_regs
        fd = self.entry_fd(arg_regs)
        if fd not in self.target_fds:
            self.pending_by_thread.pop(tid, None)
            return
        direction = self.syscall_spec[name][0]
        if direction == "out":
            # write-like: buffer is ready now, dump immediately, nothing to wait for
            extracted = self.extract_entry_data(name, arg_regs)
            if extracted is not None:
                label, data = extracted
                self.dump_transfer(name, direction, fd, label, data)
            self.pending_by_thread.pop(tid, None)
        else:
            # read-like: snapshot args now (they may be clobbered by exit) and wait for the return
            arg_values = [get_register(r) for r in arg_regs]
            self.pending_by_thread[tid] = {"name": name, "fd": fd, "arg_values": arg_values}
        return

    def handle_return(self, name):
        try:
            tid = gdb.selected_thread().num
        except Exception:
            tid = 0
        pending = self.pending_by_thread.pop(tid, None)
        if pending is None or pending["name"] != name:
            return
        entry = self.syscall_table.name_table[name]
        retval = get_register(entry.ret_regs[0])
        # ret value is signed; treat large unsigned as negative error
        if retval >= (1 << (current_arch.ptrsize * 8 - 1)):
            retval = retval - (1 << (current_arch.ptrsize * 8))
        direction = self.syscall_spec[name][0]
        fd = pending["fd"]
        extracted = self.extract_exit_data(name, pending["arg_values"], retval)
        if extracted is not None:
            label, data = extracted
            self.dump_transfer(name, direction, fd, label, data)
        return

    def trace(self):
        bp_was_hit = False
        inferior_exited = False
        EventHooking.gef_on_stop_unhook(EventHandler.hook_stop_handler)
        self.close_stdout_stderr()
        try:
            while True:
                gdb.execute("continue", to_string=True)
                if not is_alive():
                    inferior_exited = True
                    break
                hit = self.identify_stop()
                if hit is None:
                    # stopped for some other reason (user breakpoint, signal, etc.)
                    bp_was_hit = True
                    break
                name, is_entry = hit
                if is_entry:
                    self.handle_entry(name)
                else:
                    self.handle_return(name)
        except KeyboardInterrupt:
            bp_was_hit = True
        except gdb.error as e:
            self.err = e
        finally:
            self.revert_stdout_stderr()
            EventHooking.gef_on_stop_hook(EventHandler.hook_stop_handler)
        if inferior_exited:
            info("Inferior exited")
        return bp_was_hit

    @parse_args
    @only_if_gdb_running
    @exclude_specific_gdb_mode(mode=("qemu-system", "qemu-user", "kgdb", "vmware", "wine"))
    @only_if_specific_arch(arch=("x86_32", "x86_64"))
    def do_invoke(self, args):
        self.target_fds = list(args.fd)
        self.maxlen = args.maxlen
        self.catch_numbers = []
        self.hooked_names = []
        self.hooked_set = set()
        self.in_syscall_by_thread = {}
        self.pending_by_thread = {}
        self.err = None

        if self.current_syscall_number() is None:
            err("Failed to get {:s}".format(self.syscall_nr_register()))
            return

        self.syscall_table = Syscall.get_syscall_table()
        if self.syscall_table is None:
            err("Could not obtain the syscall table for this target")
            return

        count = self.setup_catchpoints()
        if count == 0:
            err("Could not set any catch syscall; this target/gdb does not support syscall catchpoints")
            return

        info("Tapping fd {:s} on {:d} syscalls: {:s}".format(
            ", ".join(str(x) for x in self.target_fds),
            count,
            ", ".join(self.hooked_names),
        ))
        info("Running with auto-continue. Stop with a breakpoint or Ctrl+C.")

        try:
            bp_was_hit = self.trace()
        finally:
            self.teardown_catchpoints()
            Cache.reset_gef_caches()
            warn("xtap stopped, catchpoints removed")

        if self.err:
            err("{}".format(self.err))
        elif bp_was_hit and is_alive():
            gdb.execute("context")
        return


@register_command
class ScanSectionCommand(GenericCommand):
    """Find memory addresses mapped across different regions."""

    _cmdline_ = "scan-section"
    _category_ = "03-a. Memory - Search"
    _aliases_ = ["peek-pointers", "leakfind", "p2p"]

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("haystack", metavar="HAYSTACK", nargs="?", help="where to search for the needle.")
    parser.add_argument("needle", metavar="NEEDLE", nargs="?", help="what to search for.")
    _syntax_ = parser.format_help()

    _example_ = [
        "{0:s} stack binary                        # scan binary address from stack",
        "{0:s} stack libc                          # scan libc address from stack",
        "{0:s} stack heap                          # scan heap address from stack",
        "{0:s} heap libc                           # scan libc address from heap",
        "{0:s} 0x555555772000-0x555555774000 libc  # support address range",
        "{0:s} any any",
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    def scan(self, haystack, needle):
        needle_sections = []
        haystack_sections = []

        if haystack and "0x" in haystack:
            try:
                start, end = AddressUtil.parse_string_range(haystack)
                haystack_sections.append((start, end, ""))
            except ValueError:
                pass

        if needle and "0x" in needle:
            try:
                start, end = AddressUtil.parse_string_range(needle)
                needle_sections.append((start, end))
            except ValueError:
                pass

        for sect in ProcessMap.get_process_maps():
            if haystack is None or haystack in sect.path:
                haystack_sections.append((sect.page_start, sect.page_end, os.path.basename(sect.path)))
            if needle is None or needle in sect.path:
                needle_sections.append((sect.page_start, sect.page_end))

        for hstart, hend, hname in haystack_sections:
            try:
                mem = read_memory(hstart, hend - hstart)
            except gdb.MemoryError:
                continue

            for i, target in enumerate(slice_unpack(mem, current_arch.ptrsize)):
                for nstart, nend in needle_sections:
                    if not (nstart <= target < nend):
                        continue
                    # match
                    deref = AddressUtil.recursive_dereference_to_string(hstart + i * current_arch.ptrsize)
                    if hname != "":
                        name = Color.colorify(hname, "yellow")
                        gef_print("{:s}: {:s}".format(name, deref))
                    else:
                        gef_print(" {:s}".format(deref))
                    break
        return

    @parse_args
    @only_if_gdb_running
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware"))
    @require_arch_set
    def do_invoke(self, args):
        haystack = args.haystack
        needle = args.needle

        info("Searching for addresses in '{:s}' that point to '{:s}'".format(
            Color.yellowify(haystack), Color.yellowify(needle),
        ))

        if haystack == "any":
            haystack = None
        elif haystack in ["binary", "bin"]:
            haystack = Path.get_filepath(append_proc_root_prefix=False)
            if is_qemu_user() and haystack is None:
                haystack = "[code]"

        if needle == "any":
            needle = None
        elif needle in ["binary", "bin"]:
            needle = Path.get_filepath(append_proc_root_prefix=False)
            if is_qemu_user() and needle is None:
                needle = "[code]"

        self.scan(haystack, needle)
        return


@register_command
class FindSyscallCommand(GenericCommand, BufferingOutput):
    """Find the syscall gadget."""

    _cmdline_ = "find-syscall"
    _category_ = "03-a. Memory - Search"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("section", metavar="SECTION_OR_START_ADDR", nargs="?",
                        help="section name or starting address of search range.")
    parser.add_argument("size", metavar="SIZE", nargs="?",
                        help="search range size. valid only when a start address is specified.")
    parser.add_argument("-b", "--nb-insns-before", type=AddressUtil.parse_address, default=0,
                        help="the number of previous lines when print syscall instruction.")
    parser.add_argument("-s", "--max-region-size", type=AddressUtil.parse_address, default=0x1000_0000,
                        help="maximum search region size. (default: %(default)#x; 0: infinity)")
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    _syntax_ = parser.format_help()

    _example_ = [
        "{0:s} libc                   # search syscall from libc .text",
        "{0:s} binary                 # 'binary' means the area executable itself (usermode only)",
        "{0:s} 0x400000-0x404000      # search syscall from specific range",
        "{0:s} 0x400000 0x4000        # another valid format",
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    def print_section(self, section):
        if isinstance(section, Address):
            section = section.section
        if section is None:
            return
        title = "In "
        if section.path:
            title += "'{}' ".format(Color.blueify(section.path))
        title += "{:#x}-{:#x} [{}] ({:#x} bytes)".format(
            section.page_start, section.page_end,
            section.permission, section.page_end - section.page_start,
        )
        self.info_add_out(title)
        return

    def print_loc(self, loc):
        if is_x86():
            show_opcodes_size = Config.get_gef_setting("context_code.show_opcodes_size_x64_x86")
        else:
            show_opcodes_size = Config.get_gef_setting("context_code.show_opcodes_size")

        nb_lines = 1

        # fix loc and nb_lines
        if self.args.nb_insns_before > 0:
             a = Disasm.gdb_get_nth_previous_instruction_address(loc, self.args.nb_insns_before)
             if a is not None:
                loc = a
                nb_lines += self.args.nb_insns_before

        # disasm
        res = Disasm.gdb_disassemble(loc, nb_lines)
        if res:
            for insn in res:
                self.out.append(insn.colored_text(show_opcodes_size))

        # add blank line
        if self.args.nb_insns_before > 0:
            self.out.append("")
        return

    def read_data(self, chunk_addr, size, end_address):
        read_size = min(size, end_address - chunk_addr)
        try:
            mem = read_memory(chunk_addr, read_size)
        except (gdb.MemoryError, ValueError, OverflowError):
            # cannot access memory this range. It doesn't make sense to try any more
            self.err_add_out("skip due to memory access error")
            return None
        return mem

    def search_pattern_by_address(self, pattern, start_address, end_address):
        """Search for a pattern within a range defined by arguments."""
        step = 0x400 * get_pagesize()
        locations = []

        old_mem = b""
        for chunk_addr in ProgressBar(range(start_address, end_address, step)):
            # read
            mem = self.read_data(chunk_addr, step, end_address)
            if mem is None:
                break

            # cases where step boundaries are crossed
            if old_mem and mem:
                ofs = len(pattern) - 1
                tmp = old_mem[-ofs:] + mem[:ofs]
                r = tmp.find(pattern)
                if r >= 0:
                    locations.append(chunk_addr - ofs + r)

            # normal case
            for match in re.finditer(pattern, mem):
                start = chunk_addr + match.start()
                locations.append(start)

            old_mem = mem
        return locations

    def process_by_address(self, pattern, start_address, end_address):
        info("Searching for {:s} in {:#x}-{:#x}".format(
            Color.yellowify(pattern), start_address, end_address,
        ))
        ret = self.search_pattern_by_address(pattern, start_address, end_address)
        for loc in ret:
            self.print_loc(loc)
        return

    def process_by_section(self, pattern, section_name=None):
        """Search for a pattern within selected (or whole) memory."""

        if section_name is None:
            self.info_add_out("Searching for {:s} in {:s}".format(Color.yellowify(pattern), "whole memory"))
        else:
            self.info_add_out("Searching for {:s} in {:s}".format(Color.yellowify(pattern), section_name))

        maps_generator = ProcessMap.get_process_maps_exclude_special_regions(allow_vdso=True)

        for section in maps_generator:
            # too big
            if self.args.max_region_size != 0:
                if section.size >= self.args.max_region_size:
                    self.quiet_info_add_out(
                        "{:#x}-{:#x} is skipped due to size ({:#x}) >= MAX_REGION_SIZE ({:#x})".format(
                            section.page_start, section.page_end,
                            section.size, self.args.max_region_size,
                        )
                    )
                    continue

            # permission filter
            if not section.is_executable():
                continue

            # specific section name filter
            if section_name and section_name not in section.path:
                continue

            # search
            self.print_section(section)
            start = section.page_start
            end = section.page_end
            ret = self.search_pattern_by_address(pattern, start, end) # search
            for loc in ret:
                self.print_loc(loc)

            # check process is alive
            if not is_alive():
                self.err_add_out("The process is dead")
                break
        return

    @parse_args
    @only_if_gdb_running
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware"))
    @require_arch_set
    def do_invoke(self, args):
        if not current_arch.syscall_insn:
            err("Unsupported arch")
            return

        pattern = current_arch.syscall_insn
        self.out = []

        if args.section and args.size:
            # the case `find-syscall 0x400000 0x4000`
            try:
                start = int(args.section, 16)
                end = start + int(args.size, 16)
            except ValueError:
                self.usage()
                return
            self.process_by_address(pattern, start, end)

        elif args.section and re.match(r"(0x)?[0-9a-fA-F]+-(0x)?[0-9a-fA-F]+", args.section):
            # the case `find-syscall 0x400000-0x404000` etc.
            try:
                start, end = AddressUtil.parse_string_range(args.section)
            except ValueError:
                self.usage()
                return
            self.process_by_address(pattern, start, end)

        elif args.section:
            # search from specific section
            if args.section in ["binary", "bin"]:
                section_name = Path.get_filepath(append_proc_root_prefix=False)
            else:
                section_name = args.section
            self.process_by_section(pattern, section_name)

        else:
            # search whole memory
            self.process_by_section(pattern)

        self.print_output(check_terminal_size=True)
        return


@register_command
class SearchPatternCommand(GenericCommand):
    """Search for a pattern in memory."""

    _cmdline_ = "search-pattern"
    _category_ = "03-a. Memory - Search"
    _aliases_ = ["xfind", "xf"]

    parser = argparse.ArgumentParser(prog=_cmdline_)
    group1 = parser.add_mutually_exclusive_group()
    group1.add_argument("--hex", action="store_true",
                       help="interpret PATTERN as hex. invalid characters are ignored.")
    group1.add_argument("--hex-regex", action="store_true",
                       help="interpret PATTERN as hex with REGEX-style. space is ignored.")
    parser.add_argument("-d", "--disable-utf16", action="store_true",
                        help="disable utf16 search if PATTERN is ascii string.")
    parser.add_argument("-b", "--big", action="store_true",
                        help="interpret PATTERN as big endian if PATTERN is 0xXXXXXXXX style.")
    parser.add_argument("-a", "--aligned", type=AddressUtil.parse_address, default=1,
                        help="alignment unit. (default: %(default)s)")
    parser.add_argument("-p", "--perm", default="r??",
                        help="the filter by permission. (default: %(default)s)")
    parser.add_argument("-i", "--interval", type=AddressUtil.parse_address,
                        help="the interval to skip searching from the last found position within the same section.")
    parser.add_argument("-l", "--limit", type=AddressUtil.parse_address,
                        help="the limit of the search result.")
    parser.add_argument("-s", "--max-region-size", type=AddressUtil.parse_address, default=0x1000_0000,
                        help="maximum search region size. (default: %(default)#x; 0: infinity)")
    parser.add_argument("--phys", action="store_true",
                        help="treat START_ADDR as a physical address (available in qemu-system).")
    group2 = parser.add_mutually_exclusive_group()
    group2.add_argument("-k", "--kernel-only", action="store_true",
                        help="search from kernel area (available in qemu-system).")
    group2.add_argument("-u", "--user-only", action="store_true",
                        help="search from user area (available in qemu-system).")
    parser.add_argument("-v", "--verbose", action="store_true",
                        help="shows the section currently being searched.")
    parser.add_argument("-q", "--quiet", action="store_true", help="suppress warnings.")
    parser.add_argument("-Q", "--quiet-region", action="store_true", help="suppress region information.")
    parser.add_argument("-S", "--quiet-symbol", action="store_true", help="not shown even if symbol exists.")
    parser.add_argument("pattern", metavar="PATTERN",
                        help='search target value. "double-escaped string" or 0xXXXXXXXX style.')
    parser.add_argument("section", metavar="SECTION_OR_START_ADDR", nargs="?",
                        help="section name or starting address of search range.")
    parser.add_argument("size", metavar="SIZE", nargs="?",
                        help="search range size. valid only when a start address is specified.")
    _syntax_ = parser.format_help()

    _example_ = [
        "{0:s} ABCD                        # search for 'ABCD' from whole memory",
        '{0:s} "\\\\x41\\\\x42\\\\x43\\\\x44"      # double-escaped string is also valid',
        '{0:s} --hex "41 42 43 44"         # another valid format',
        '{0:s} --hex-regex "4[0-9]424344"  # hex regex search',
        "{0:s} 0x44434241                  # search for 0x44434241 (='ABCD') from whole memory",
        "{0:s} 0x555555554000 stack        # search for 0x555555554000 (6byte) from stack",
        "{0:s} 0x0000555555554000 stack    # search for 0x0000555555554000 (8byte) from stack",
        "{0:s} AAAA binary                 # 'binary' means the area executable itself (usermode only)",
        "{0:s} AAAA 0x400000-0x404000      # search for 'AAAA' from specific range",
        "{0:s} AAAA 0x400000 0x4000        # another valid format",
        "{0:s} AAAA heap --aligned 16      # search for 'AAAA' with 16-byte alignment",
        "{0:s} AAAA -p r?-                 # search for 'AAAA' from r-- or rw-, but not from r-x or rwx",
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    _note_ = [
        "To efficiently search large memory regions, the search is usually performed internally by dividing",
        "the region into chunks. The chunk size is 0x10 pages for qemu-system, and 0x400 pages for others.",
        "",
        "However, when the --hex-regex option is enabled, this chunked search is disabled,",
        "because it is difficult to implement regular expression searches that span multiple chunks.",
    ]
    _note_ = "\n".join(_note_)

    def is_aligned(self, addr):
        a = self.args.aligned or 1
        return (a <= 1) or (addr % a == 0)

    def accept_match(self, start_addr, locations):
        # alignment
        if not self.is_aligned(start_addr):
            return False

        # interval
        if self.args.interval:
            if locations:
                last_loc = locations[-1]
                if start_addr < last_loc[0] + self.args.interval:
                    return False
        return True

    def check_limit(self):
        if self.args.limit:
            if self.args.limit <= self.found_count:
                return True
        return False

    def print_section(self, section):
        if self.args.quiet_region:
            return
        if isinstance(section, Address):
            section = section.section
        if section is None:
            return
        title = "In "
        if section.path:
            title += "'{}' ".format(Color.blueify(section.path))
        title += "{:#x}-{:#x} [{}] ({:#x} bytes)".format(
            section.page_start, section.page_end, section.permission,
            section.page_end - section.page_start,
        )
        ok(title)
        return

    def print_loc(self, loc):
        if self.args.aligned and loc[0] % self.args.aligned:
            return
        h = hexdump(loc[1], 0x10, base=loc[0], show_symbol=not self.args.quiet_symbol)
        gef_print("  {:s}".format(h))
        return

    def read_data(self, chunk_addr, size, end_address):
        read_size = min(size, end_address - chunk_addr)
        try:
            if self.args.phys:
                mem = read_physmem(chunk_addr, read_size)
            else:
                mem = read_memory(chunk_addr, read_size)
        except (gdb.MemoryError, ValueError, OverflowError):
            # cannot access memory this range. It doesn't make sense to try any more
            if self.args.verbose:
                err("Skip due to memory access error")
            return None
        return mem

    def search_pattern_by_address(self, pattern, start_address, end_address):
        """Search for a pattern within a range defined by arguments."""
        if isinstance(pattern, str):
            pattern = String.str2bytes(pattern)

        if self.args.hex_regex:
            step = end_address - start_address
        elif is_qemu_system():
            step = 0x10 * get_pagesize()
        else:
            step = 0x400 * get_pagesize()

        locations = []
        old_mem = b""
        # `pattern` may contain regex escapes (e.g. rb"\\x41"), so the number of
        # bytes it matches is not len(pattern).
        try:
            ofs = len(codecs.escape_decode(pattern)[0]) - 1
        except (ValueError, UnicodeDecodeError):
            ofs = len(pattern) - 1
        for chunk_addr in ProgressBar(range(start_address, end_address, step), disable=not self.args.verbose):
            # read
            mem = self.read_data(chunk_addr, step, end_address)
            if mem is None:
                break

            # for regex
            if self.args.hex_regex:
                mem = mem.hex().encode()

            # cases where step boundaries are crossed
            # `ofs == 0` means the pattern matches only 1 byte, so it never crosses a boundary.
            # It must be skipped, otherwise `old_mem[-0:]` would rescan the whole previous chunk.
            if not self.args.hex_regex and old_mem and mem and ofs:
                # Considering cases where the step size boundary is crossed,
                # the check is performed within the range of -ofs to ofs size.
                """
                pattern "ABCD"
                ofs = len(pattern) - 1 = 3

                The scope of consideration is limited to this range.
                 <-- step --> <-- step -->
                | ...   xxxA | BCDxxx ... |
                | ...  xxxAB | CDxxx  ... |
                | ... xxxABC | Dxxx   ... |
                         <------->
                       -ofs     ofs
                """
                tmp_mem = old_mem[-ofs:] + mem[:ofs]
                m = re.search(pattern, tmp_mem)
                r = m.start() if m else -1
                if r >= 0:
                    if self.accept_match(chunk_addr - ofs + r, locations):
                        # read dump data
                        data = (old_mem[-ofs:] + mem[:ofs + 0x10])[r:][:0x10]

                        # add
                        locations.append((chunk_addr - ofs + r, data))
                        self.found_count += 1

                        # loop check
                        if self.check_limit():
                            info("Limit reached, no more matches shown")
                            return locations
                # fall through

            # normal case
            for match in re.finditer(pattern, mem):
                if self.args.hex_regex:
                    if match.start() % 2:
                        continue
                    start_pos = match.start() // 2
                else:
                    start_pos = match.start()
                start = chunk_addr + start_pos

                # check filter
                if not self.accept_match(start, locations):
                    continue

                # read dump data
                if self.args.hex_regex:
                    data = bytes.fromhex(mem[match.start():match.start() + 0x20].decode())
                else:
                    data = mem[start_pos:start_pos + 0x10]
                if len(data) < 0x10:
                    lack = self.read_data(chunk_addr + step, 0x10 - len(data), end_address)
                    if lack:
                        data += lack

                # add
                locations.append((start, data))
                self.found_count += 1

                # loop check
                if self.check_limit():
                    info("Limit reached, no more matches shown")
                    return locations

            old_mem = mem

        return locations

    def process_by_address(self, patterns, start, end):
        extra = " (phys)" if self.args.phys else ""
        for pattern in patterns:
            if not pattern:
                continue

            info("Searching for '{:s}' in {:#x}-{:#x}{:s}".format(
                Color.yellowify(pattern), start, end, extra,
            ))

            self.found_count = 0
            ret = self.search_pattern_by_address(pattern, start, end)
            for found_loc in ret:
                self.print_loc(found_loc)
        return

    def get_process_maps_qemu_system(self):
        res = PageMap.get_page_maps_by_pagewalk("pagewalk --quiet --no-pager --disable-color")
        res = sorted(set(res.splitlines()))
        res = list(filter(lambda line: line.endswith("]"), res))
        res = list(filter(lambda line: "[+]" not in line, res))
        res = list(filter(lambda line: "*" not in line, res))
        for line in res:
            if is_x86() and "ACCESSED" not in line:
                continue

            # extract
            lines = line.split()
            addr_start, addr_end = [int(x, 16) for x in lines[0].split("-")]

            # non valid addr
            if not is_valid_addr(addr_start):
                continue

            # parse
            if is_x86():
                perm = Permission.from_process_maps(lines[5][1:].lower())
            elif is_arm32():
                perm = line.split("/")[-1][:3]
                perm = Permission.from_process_maps(perm.lower())
            elif is_arm64():
                perm = line.split("/")[-1][:3]
                perm = Permission.from_process_maps(perm.lower())
            else:
                # unknown format for this architecture; do not filter by permission
                perm = Permission.from_process_maps("rwx")
            yield Section(page_start=addr_start, page_end=addr_end, permission=perm)
        return None

    def search_pattern_by_section(self, pattern, section_name=None):
        """Search for a pattern within selected (or whole) memory."""
        if is_qemu_system():
            maps_generator = self.get_process_maps_qemu_system()
        else:
            maps_generator = ProcessMap.get_process_maps_exclude_special_regions(allow_vdso=True)

        for section in maps_generator:
            # user or kernel memory address filter
            if self.args.user_only:
                if AddressUtil.is_msb_on(section.page_start):
                    continue
            if self.args.kernel_only:
                if not AddressUtil.is_msb_on(section.page_start):
                    continue

            # too big
            if self.args.max_region_size != 0:
                if section.size >= self.args.max_region_size:
                    self.quiet_info(
                        "{:#x}-{:#x} is skipped due to size ({:#x}) >= MAX_REGION_SIZE ({:#x})".format(
                            section.page_start, section.page_end,
                            section.size, self.args.max_region_size,
                        )
                    )
                    continue

            # permission filter
            if not section.is_readable():
                continue
            if self.args.perm[1] in "wW" and not section.is_writable():
                continue
            if self.args.perm[1] in "-_" and section.is_writable():
                continue
            if self.args.perm[2] in "xX" and not section.is_executable():
                continue
            if self.args.perm[2] in "-_" and section.is_executable():
                continue

            # specific section name filter
            if section_name and section_name not in section.path:
                continue

            # verbose: always print section before search
            if self.args.verbose:
                self.print_section(section)
            # search
            ret = self.search_pattern_by_address(pattern, section.page_start, section.page_end)
            # default: print section if only found
            if not self.args.verbose:
                if ret:
                    self.print_section(section)

            # print
            for loc in ret:
                self.print_loc(loc)

            # loop check
            if not is_alive():
                err("The process is dead")
                break
            if self.check_limit():
                info("Limit reached, no more matches shown")
                break
        return

    def process_by_section(self, patterns, section_name=None):
        extra = " (phys)" if self.args.phys else ""
        for pattern in patterns:
            if not pattern:
                continue

            if section_name is None:
                area = "whole memory"
            else:
                area = section_name

            gef_print(titlify(""))
            info("Searching for '{:s}' in {:s}{:s}".format(
                Color.yellowify(pattern), area, extra,
            ))
            self.found_count = 0
            self.search_pattern_by_section(pattern, section_name)
        return

    def create_patterns(self):
        if self.args.hex_regex:
            pattern = self.args.pattern.lower().replace(" ", "")
            return (pattern,)

        # create normal pattern
        if self.args.hex: # "41414141" -> "\x41\x41\x41\x41"
            pattern = re.sub(r"[^0-9a-fA-F]", "", self.args.pattern)
            if len(pattern) % 2 != 0:
                err("Hex pattern length is odd")
                return None
            pattern = "".join(["\\x" + x for x in slicer(pattern, 2)])
        elif String.is_hex(self.args.pattern): # "0x41414141" -> "\x41\x41\x41\x41"
            if self.args.big or Endian.is_big_endian():
                pattern = "".join(["\\x" + x for x in slicer(self.args.pattern[2:], 2)])
            else:
                pattern = "".join(["\\x" + x for x in slicer(self.args.pattern[2:], 2)[::-1]])
        else:
            pattern = self.args.pattern

        def isascii(string):
            val = codecs.escape_decode(string)[0]
            return all(0x20 <= c < 0x7f for c in val)

        # create utf16 pattern
        pattern_utf16 = None
        if not self.args.disable_utf16:
            if isascii(pattern) and "\\" not in pattern:
                pattern_utf16 = "".join([x + "\\x00" for x in pattern])
        return (pattern, pattern_utf16)

    @parse_args
    @only_if_gdb_running
    def do_invoke(self, args):
        if args.kernel_only or args.user_only:
            if not is_qemu_system():
                err("Unsupported in this gdb mode (qemu-system only)")
                return

        # check permission
        if args.phys:
            info("Permission is ignored")
        else:
            if len(args.perm) != 3:
                err("Invalid permission length")
                return
            if args.perm[0] not in "rR":
                err("Permission needs to start by `r`")
                return
            if args.perm[1] not in "wW-_?" or args.perm[2] not in "xX-_?":
                err("Invalid permission")
                return

        # check parameters
        if args.interval and args.interval <= 0:
            err("Invalid interval value")
            return
        if args.limit and args.limit <= 0:
            err("Invalid limit value")
            return
        if args.max_region_size and args.max_region_size < 0x1000:
            err("Invalid max-region-size")
            return

        # prepare pattern
        patterns = self.create_patterns()
        if patterns is None:
            return

        if args.section and args.size:
            # the case `find AAAA 0x400000 0x4000`
            try:
                start = int(args.section, 16)
                end = start + int(args.size, 16)
            except ValueError:
                self.usage()
                return
            self.process_by_address(patterns, start, end)

        elif args.section and re.match(r"(0x)?[0-9a-fA-F]+-(0x)?[0-9a-fA-F]+", args.section):
            # the case `find AAAA 0x400000-0x404000`
            try:
                start, end = AddressUtil.parse_string_range(args.section)
            except ValueError:
                self.usage()
                return
            self.process_by_address(patterns, start, end)

        else:
            if args.phys:
                err("--phys mode needs address information")
                return

            if args.section:
                # search from specific section
                if is_qemu_system() or is_kgdb() or is_vmware():
                    err("Unsupported")
                    return
                if args.section in ["binary", "bin"]:
                    section_name = Path.get_filepath(append_proc_root_prefix=False)
                else:
                    section_name = args.section
                self.process_by_section(patterns, section_name)

            else:
                # search whole memory
                self.process_by_section(patterns)
        return


@register_command
class PtrDemangleCommand(GenericCommand):
    """Demangle a mangled value by PTR_MANGLE."""

    _cmdline_ = "ptr-demangle"
    _category_ = "02-f. Process Information - Security"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument("value", metavar="VALUE", nargs="?", type=AddressUtil.parse_address,
                       help="the value to demangle.")
    group.add_argument("--source", action="store_true",
                       help="shows the source instead of displaying demangled value.")
    parser.add_argument("-f", "--force-heuristic", action="store_true", help="do not use symbols to detect PTR_MANGLE")
    _syntax_ = parser.format_help()

    @staticmethod
    def get_relro_range(base):
        elf = Elf.get_elf(base)
        if elf is None:
            return None
        phdr = elf.get_phdr(Elf.Phdr.PT_GNU_RELRO)
        if phdr is None:
            return None

        load_bias = base if elf.e_type == Elf.ET_DYN else 0
        start = align_to_ptrsize(load_bias + phdr.p_vaddr)
        end = align_to_ptrsize(load_bias + phdr.p_vaddr + phdr.p_memsz)
        if start + current_arch.ptrsize > end:
            return None
        return start, end

    @staticmethod
    def get_cookie_from_rtld_relro(libc_version):
        # Find _dl_argv and nearby guard variables in rtld RELRO when available.
        try:
            auxv = Auxv.get_auxiliary_values()
            if not auxv or not auxv.get("AT_BASE"):
                return None
            relro = PtrDemangleCommand.get_relro_range(auxv["AT_BASE"])
        except (gdb.error, gdb.MemoryError):
            return None
        if relro is None:
            return None

        def is_stack_address(addr):
            return ProcessMap.lookup_address(addr).is_in_stack_segment()

        start, end = relro
        ptrsize = current_arch.ptrsize
        # _dl_skip_args occupied one slot between _dl_argv and the guards until glibc 2.35.
        guard_distance = 1 + int(libc_version < (2, 36)) + int(current_arch.get_canary_offset() is None)

        """
        x86_64 glibc 2.44
        0x7ffff7ffcab0|+0x0000|+000: __pointer_chk_guard_local: 0xc1e710f8603f8d46
        0x7ffff7ffcab8|+0x0008|+001: _dl_argv                 : 0x00007fffffffe538  ->  0x00007fffffffe769  ->  ...
        0x7ffff7ffcac0|+0x0010|+002: _dl_argc                 : 0x0000000000000001

        x86_64 glibc 2.35
        0x7ffff7ffcab0|+0x0000|+000: __pointer_chk_guard_local: 0xf6bede021604f3c4
        0x7ffff7ffcab8|+0x0008|+001: _dl_skip_args            : 0x0000000000000000
        0x7ffff7ffcac0|+0x0010|+002: _dl_argv                 : 0x00007fffffffe738  ->  0x00007fffffffe93e  ->  ...
        0x7ffff7ffcac8|+0x0018|+003: _dl_argc                 : 0x0000000000000001
        """

        for argv_slot in range(start, end, ptrsize):
            try:
                argv = read_int_from_memory(argv_slot)
                if not is_stack_address(argv) or not is_stack_address(read_int_from_memory(argv)):
                    continue
            except (gdb.error, gdb.MemoryError, TypeError):
                continue

            for direction in (-1, 1):
                argc_slot = argv_slot + direction * ptrsize
                if argc_slot < start or argc_slot + 4 > end:
                    continue
                try:
                    # _dl_argc check
                    argc = u32(read_memory(argc_slot, 4))
                    if not 1 <= argc <= 0x1000:
                        continue
                    # _dl_argv_check
                    if any(not is_stack_address(read_int_from_memory(argv + i * ptrsize)) for i in range(min(argc, 4))):
                        continue
                    if read_int_from_memory(argv + argc * ptrsize) != 0:
                        continue

                    guard_slot = argv_slot - direction * ptrsize * guard_distance
                    if not start <= guard_slot or guard_slot + ptrsize > end:
                        continue
                    cookie = read_int_from_memory(guard_slot)
                    if cookie != 0:
                        return cookie
                except (gdb.error, gdb.MemoryError, TypeError):
                    pass
        return None

    @staticmethod
    def get_cookie_from_static_relro():
        # In a stripped static binary, keep only RELRO slots that are zero in the file and randomized at runtime.
        codebase = ProcessMap.get_codebase()
        if codebase is None:
            return None

        elf = Elf.get_elf(codebase)
        if elf is None or not elf.is_static():
            return None

        relro = PtrDemangleCommand.get_relro_range(codebase)
        if relro is None:
            return None

        canary = None
        try:
            res = CanaryCommand.gef_read_canary()
            if res is not None:
                canary = res[0]
        except Exception:
            pass

        start, end = relro
        ptrsize = current_arch.ptrsize
        unpack = u64 if ptrsize == 8 else u32
        bits = ptrsize * 8
        candidates = []
        for addr in range(start, end, ptrsize):
            try:
                cookie = read_int_from_memory(addr)
            except gdb.MemoryError:
                continue
            if cookie == 0 or cookie == canary or is_valid_addr(cookie):
                continue
            ones = bin(cookie).count("1")
            if not bits // 4 <= ones <= bits * 3 // 4:
                continue

            section = ProcessMap.process_lookup_address(addr)
            if section is None or not section.path or section.path.startswith("["):
                continue
            path = Path.append_proc_root(section.path) if is_container_attach() else section.path
            try:
                with open(path, "rb") as fd:
                    fd.seek(section.offset + addr - section.page_start)
                    original = fd.read(ptrsize)
                if len(original) == ptrsize and unpack(original) == 0:
                    candidates.append(cookie)
            except (OSError, ValueError):
                pass

        candidates = list(dict.fromkeys(candidates))
        return candidates[0] if len(candidates) == 1 else None

    @staticmethod
    @Cache.cache_this_session
    def get_cookie_symbols():
        """Return the pointer guard symbols that gdb is able to resolve.
        gdb keeps no cache for a symbol it failed to find, so it rescans every symtab on
        each attempt (2.5ms once the glibc debug symbols are loaded). get_cookie runs on
        every stop, so the symbols that do not exist are dropped here once."""
        symbols = []
        for symbol in ("&__pointer_chk_guard", "&__pointer_chk_guard_local"):
            try:
                AddressUtil.parse_address(symbol)
            except (gdb.error, OverflowError, ValueError):
                continue
            symbols.append(symbol)
        return symbols

    @staticmethod
    @Cache.cache_until_next
    def get_cookie(force_heuristic=False):
        if is_in_kernel():
            return None
        if is_arm32_cortex_m():
            return None
        if is_qiling():
            return None

        if not force_heuristic:
            # glibc 2.44 stores the pointer guard in a RELRO variable on every architecture.
            # rtld and several architectures used these variables before 2.44.
            for symbol in PtrDemangleCommand.get_cookie_symbols():
                try:
                    cookie_ptr = AddressUtil.parse_address(symbol)
                    return read_int_from_memory(cookie_ptr)
                except (gdb.error, OverflowError):
                    pass

        libc_version = get_libc_version(silent=True)
        if libc_version is None:
            return None

        # rtld keeps a RELRO copy of the pointer guard.
        cookie = PtrDemangleCommand.get_cookie_from_rtld_relro(libc_version)
        if cookie is not None:
            return cookie

        if libc_version >= (2, 44):
            return PtrDemangleCommand.get_cookie_from_static_relro()

        # fast path for x86/x64
        try:
            # x86 stored the pointer guard in the TCB.
            if is_x86_64():
                tls = current_arch.get_tls()
                if tls is not None:
                    return read_int_from_memory(tls + 0x30)
            if is_x86_32():
                tls = current_arch.get_tls()
                if tls is not None:
                    return read_int_from_memory(tls + 0x18)
        except (gdb.error, OverflowError):
            pass

        # generic slow path
        try:
            auxv = Auxv.get_auxiliary_values()
            if auxv is None:
                Cache.reset_gef_caches()
                auxv = Auxv.get_auxiliary_values()
            # The pointer guard is derived from the second uintptr_t at AT_RANDOM.
            if auxv and "AT_RANDOM" in auxv:
                # Old s390x instead reused the stack guard with its least significant byte cleared.
                if is_s390x():
                    cookie = read_int_from_memory(auxv["AT_RANDOM"]) & 0x00ff_ffff_ffff_ffff
                else:
                    cookie = read_int_from_memory(auxv["AT_RANDOM"] + current_arch.ptrsize)
                if cookie != 0:
                    return cookie
        except gdb.error:
            pass

        # Before glibc 2.44, try the static RELRO fallback on architectures where GEF does not have a TCB canary offset.
        if current_arch.get_canary_offset() is None:
            return PtrDemangleCommand.get_cookie_from_static_relro()
        return None

    @parse_args
    @only_if_gdb_running
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware"))
    @exclude_specific_arch(arch=("SPARC32", "XTENSA", "CRIS"))
    @require_arch_set
    def do_invoke(self, args):
        if args.source:
            s = GefUtil.get_source(current_arch.decode_cookie)
            gef_print(s)
            gef_print()
            s = GefUtil.get_source(current_arch.decode_cookie_legacy)
            gef_print(s)
            return

        cookie = PtrDemangleCommand.get_cookie(force_heuristic=args.force_heuristic)
        if cookie is None:
            return
        info("Cookie is {:s}".format(Color.colorify_hex(cookie, "bold")))

        decoded = current_arch.decode_cookie(args.value, cookie)
        decoded = ProcessMap.lookup_address(decoded)
        decoded_sym = Symbol.get_symbol_string(decoded.value)
        if is_valid_addr(decoded.value):
            valid_msg = Color.colorify("valid", "bold green")
        else:
            valid_msg = Color.colorify("invalid", "bold red")
        info("Decoded value is {!s}{:s} [{:s}]".format(decoded, decoded_sym, valid_msg))
        return


