@register_command
class GlibcHeapVisualHeapCommand(GenericCommand, BufferingOutput):
    """Visualize chunks on a heap."""

    _cmdline_ = "heap visual-heap"
    _category_ = "05-a. Heap - Glibc"
    _aliases_ = ["visual-heap"]

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("location", metavar="LOCATION", nargs="?", type=AddressUtil.parse_address,
                        help="the address interpreted as the beginning of a contiguous chunk. (default: arena.heap_base)")
    parser.add_argument("-a", dest="arena_addr", type=AddressUtil.parse_address,
                        help="the address or number to interpret as an arena. (default: main_arena)")
    parser.add_argument("-c", dest="max_count", type=AddressUtil.parse_address,
                        help="maximum number of chunks to parse; use when the number of chunks is very large.")
    parser.add_argument("-f", "--full", action="store_true",
                        help="display the same line without omitting.")
    parser.add_argument("-d", "--dark-color", action="store_true",
                        help="use the dark color if chunk is allocated.")
    parser.add_argument("-s", "--safe-linking-decode", action="store_true",
                        help="decode safe-linking encoded pointer if tcache or fastbins.")
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    _syntax_ = parser.format_help()

    normal_colors = [
        Color.redify,
        Color.greenify,
        Color.blueify,
        Color.yellowify,
    ]
    dark_colors = [
        lambda x: Color.colorify(x, "bright_black"),
        lambda x: Color.colorify(x, "graphite"),
    ]

    def __init__(self):
        super().__init__(complete=gdb.COMPLETE_LOCATION)
        return

    def generate_visual_chunk(self, chunk, idx):
        """Generate a visual, colorized representation of a heap chunk's contents,
        grouping repeated rows and annotating bin info."""
        unpack = u32 if current_arch.ptrsize == 4 else u64
        data = slicer(chunk.data, current_arch.ptrsize * 2)
        group_line_threshold = 8

        arena = chunk.arena
        addr = chunk.chunk_base_address
        width = current_arch.ptrsize * 2 + 2
        exceed_top = False
        has_bins_info = False

        out_tmp = []
        # Group rows to display rows with the same value together.
        for blk, blks in itertools.groupby(data):
            repeat_count = len(list(blks))
            d1, d2 = unpack(blk[:current_arch.ptrsize]), unpack(blk[current_arch.ptrsize:])
            dascii = "".join([chr(x) if 0x20 <= x < 0x7f else "." for x in blk])

            if self.args.full or repeat_count < group_line_threshold:
                # non-collapsed line
                for _ in range(repeat_count):
                    bins_info = arena.get_bins_info(addr)
                    if bins_info:
                        bins_info = " <-  {:s}".format(", ".join(bins_info))
                        has_bins_info = True
                    else:
                        bins_info = ""

                    if self.args.safe_linking_decode:
                        if chunk.address == addr and ("tcache" in bins_info or "fastbins" in bins_info):
                            d1 = chunk.get_fwd_ptr(True)

                    offset1 = addr - chunk.chunk_base_address
                    offset2 = addr - arena.heap_base
                    out_tmp.append("{:#x}|{:+#08x}|{:+#08x}: {:#0{:d}x} {:#0{:d}x} | {:s} | {:s}".format(
                        addr, offset1, offset2, d1, width, d2, width, dascii, bins_info,
                    ).rstrip())
                    addr += current_arch.ptrsize * 2

                    if addr > arena.top + current_arch.ptrsize * 4:
                        exceed_top = True
                        break
            else:
                # collapsed line
                bins_info = arena.get_bins_info(addr)
                if bins_info:
                    bins_info = " <-  {:s}".format(", ".join(bins_info))
                    has_bins_info = True
                else:
                    bins_info = ""

                offset1 = addr - chunk.chunk_base_address
                offset2 = addr - arena.heap_base
                out_tmp.append("{:#x}|{:+#08x}|{:+#08x}: {:#0{:d}x} {:#0{:d}x} | {:s} | {:s}".format(
                    addr, offset1, offset2, d1, width, d2, width, dascii, bins_info,
                ).rstrip())
                addr += current_arch.ptrsize * 2 * repeat_count
                out_tmp.append("* {:#d} lines, {:#x} bytes".format(
                    repeat_count - 1, (repeat_count - 1) * current_arch.ptrsize * 2,
                ))

            if exceed_top:
                break

        # coloring
        if self.args.dark_color and not has_bins_info:
            color_func = self.dark_colors[idx % len(self.dark_colors)]
        else:
            color_func = self.normal_colors[idx % len(self.normal_colors)]
        self.out.append("\n".join(map(color_func, out_tmp)))

        # corrupted case
        if exceed_top:
            self.out.append(Color.boldify("..."))
        return

    def generate_visual_heap(self, arena, dump_start, max_count):
        """Generate a visual representation of the heap by iterating over chunks,
        handling corruption and optional progress display."""
        sect = ProcessMap.process_lookup_address(dump_start)
        if sect:
            end = sect.page_end
        else:
            # If qemu-user 8.1 or higher, the `process_lookup_address` to obtain the section list
            # uses `info proc mappings` internally.
            # This is fast, but does not return an accurate list in some cases.
            # For example, sparc64 may not include the heap area.
            # So it detects the end of the page from arena.top.
            end = arena.top + GlibcHeap.GlibcChunk(arena, arena.top, from_base=True).size

        pbar = ProgressBar(total=end - dump_start)

        addr = dump_start
        i = 0
        while addr < end:
            chunk = GlibcHeap.GlibcChunk(arena, addr + current_arch.ptrsize * 2)
            # corrupt check
            if chunk.size == 0:
                msg = "{} Corrupted (chunk.size == 0)".format(Color.colorify("[!]", "bold red"))
                self.out.append(msg)
                chunk.data = read_memory(addr, max(arena.top - addr + 0x10, 0))
                self.generate_visual_chunk(chunk, i)
                break
            elif addr != arena.top and addr + chunk.size > arena.top:
                msg = "{} Corrupted (addr + chunk.size > arena.top)".format(Color.colorify("[!]", "bold red"))
                self.out.append(msg)
                chunk.data = read_memory(addr, max(arena.top - addr + 0x10, 0))
                self.generate_visual_chunk(chunk, i)
                break
            elif addr + chunk.size > end:
                msg = "{} Corrupted (addr + chunk.size > sect.page_end)".format(Color.colorify("[!]", "bold red"))
                self.out.append(msg)
                chunk.data = read_memory(addr, max(arena.top - addr + 0x10, 0))
                self.generate_visual_chunk(chunk, i)
                break
            # maybe not corrupted
            try:
                chunk.data = read_memory(addr, chunk.size)
            except gdb.MemoryError:
                break
            self.generate_visual_chunk(chunk, i)
            addr += chunk.size
            i += 1

            pbar.update(chunk.size)

            if max_count and max_count <= i:
                break

        pbar.close()
        return

    @parse_args
    @only_if_gdb_running
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware", "wine"))
    @require_arch_set
    def do_invoke(self, args):
        # parse arena
        arena = GlibcHeap.get_arena(args.arena_addr)

        if arena is None:
            err("No valid arena")
            return

        if arena.heap_base is None or not is_valid_addr(arena.heap_base):
            err("Heap is not initialized")
            return

        if args.location is None:
            dump_start = arena.heap_base
            # specific pattern
            if arena.is_main_arena:
                if (is_x86_32() or is_riscv32() or is_ppc32()) and get_libc_version() >= (2, 26):
                    dump_start += 8
        else:
            dump_start = args.location

        self.out = []
        self.generate_visual_heap(arena, dump_start, args.max_count)
        self.print_output()
        return


@register_command
class GlibcHeapDumpImageCommand(GenericCommand):
    """Visualize chunks on a heap as composition image."""

    _cmdline_ = "heap dump-image"
    _category_ = "05-a. Heap - Glibc"
    _aliases_ = ["dump-image"]

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("location", metavar="LOCATION", nargs="?", type=AddressUtil.parse_address,
                        help="the address interpreted as the beginning of a contiguous chunk. (default: arena.heap_base)")
    parser.add_argument("-a", dest="arena_addr", type=AddressUtil.parse_address,
                        help="the address or number to interpret as an arena. (default: main_arena)")
    parser.add_argument("-c", dest="max_count", type=AddressUtil.parse_address,
                        help="maximum number of chunks to parse; use when the number of chunks is very large.")
    parser.add_argument("-t", "--include-top", action="store_true", help="include top chunk.")
    parser.add_argument("-s", "--save-as-png", action="store_true", help="save as png.")
    parser.add_argument("-S", "--scale", type=float, default=1.0, help="magnification to enlarge or reduce the image.")
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    _syntax_ = parser.format_help()

    _note_ = [
        Color.colorify("In-use chunks", "underline") + " are displayed alternately in " + \
        Color.colorify("dark gray", "gray") + " and " + Color.colorify("light gray", "cloud") + ".",
        Color.colorify("Freed chunks", "underline") + " are displayed alternately in " + \
        Color.colorify("muted red", "orange") + " and " + Color.colorify("muted yellow", "lemon_yellow") + ".",
        "In both cases, the color is determined by whether the chunk's position from the beginning",
        "is odd-numbered or even-numbered.",
        "",
        "The `convert` command limits height to 32000px; output may shrink based on heap size.",
    ]
    _note_ = "\n".join(_note_)

    def __init__(self):
        super().__init__(complete=gdb.COMPLETE_LOCATION)
        return

    def collect_chunks(self, arena, dump_start, max_count):
        sect = ProcessMap.process_lookup_address(dump_start)
        if sect:
            end = sect.page_end
        else:
            # If qemu-user 8.1 or higher, the `process_lookup_address` to obtain the section list
            # uses `info proc mappings` internally.
            # This is fast, but does not return an accurate list in some cases.
            # For example, sparc64 may not include the heap area.
            # So it detects the end of the page from arena.top.
            end = arena.top + GlibcHeap.GlibcChunk(arena, arena.top, from_base=True).size

        pbar = ProgressBar(total=end - dump_start)

        chunks = []
        err_msg = None
        addr = dump_start
        i = 0
        while addr < end:
            chunk = GlibcHeap.GlibcChunk(arena, addr + current_arch.ptrsize * 2)
            # corrupt check
            if chunk.size == 0:
                err_msg = "{} Corrupted (chunk.size == 0)".format(Color.colorify("[!]", "bold red"))
                chunk.data = read_memory(addr, max(arena.top - addr + 0x10, 0))
                chunks.append(chunk)
                break
            elif addr != arena.top and addr + chunk.size > arena.top:
                err_msg = "{} Corrupted (addr + chunk.size > arena.top)".format(Color.colorify("[!]", "bold red"))
                chunk.data = read_memory(addr, max(arena.top - addr + 0x10, 0))
                chunks.append(chunk)
                break
            elif addr + chunk.size > end:
                err_msg = "{} Corrupted (addr + chunk.size > sect.page_end)".format(Color.colorify("[!]", "bold red"))
                chunk.data = read_memory(addr, max(arena.top - addr + 0x10, 0))
                chunks.append(chunk)
                break
            # maybe not corrupted
            try:
                chunk.data = read_memory(addr, chunk.size)
            except gdb.MemoryError:
                break

            if chunk.is_top():
                if not self.args.include_top:
                    break
            chunks.append(chunk)
            addr += chunk.size
            i += 1

            pbar.update(chunk.size)

            if max_count and max_count <= i:
                break

        pbar.close()
        return chunks, err_msg

    def generate_image(self, chunks):
        MIN_SIZE = GlibcHeap.HeapInfo.MIN_SIZE()
        MALLOC_ALIGNMENT = GlibcHeap.HeapInfo.MALLOC_ALIGNMENT()

        def chunk_size_to_line_number(chunk):
            line_num = ((chunk.size - MIN_SIZE) // MALLOC_ALIGNMENT) + 1
            return max(line_num, 1)

        line_nums = [chunk_size_to_line_number(c) for c in chunks]
        used_or_freed = [c.is_real_used() for c in chunks]

        total = sum(line_nums)
        if total <= 0:
            return None

        used_cols = [
            b"\xb3\xb3\xb3",  # 70% gray (179)
            b"\x4d\x4d\x4d",  # 30% gray (77)
        ]

        freed_cols = [
            b"\xc6\x6b\x5b",  # muted red
            b"\xd8\xb4\x5a",  # muted yellow
        ]

        target_h = 30000 # limit of convert command
        target_w = 1

        # assign to target_h by ratio (rounding error is absorbed by accumulator)
        data_parts = []
        acc = 0 # error accumulation (molecule side)
        for i, (h, u) in enumerate(zip(line_nums, used_or_freed)):
            if u:
                color = used_cols[i & 1]
            else:
                color = freed_cols[i & 1]

            acc += h * target_h
            px = acc // total
            acc = acc % total

            px = int(px)
            if px <= 0:
                continue

            data_parts.append(color * (px * target_w))

        data = b"".join(data_parts)

        tmp_fd, tmp_path = GefUtil.mkstemp(prefix="heap-dump-image", suffix=".raw")
        with os.fdopen(tmp_fd, "wb") as fdw:
            fdw.write(data)
        return tmp_path

    def make_command_line(self, image_path):
        img_height = os.path.getsize(image_path) // 3 # RGB
        img_width = 1

        command_options = [
            "-size {:d}x{:d}".format(img_width, img_height),
            "-depth 8",
        ]

        # terminal size (number of characters)
        term_height, term_width = GefUtil.get_terminal_size()
        # it's too tight, so make it slightly smaller.
        term_width *= 0.95
        term_height *= 0.95
        # number of pixels per character
        font_width_px = 6
        font_height_px = 12
        # pixel dimensions of the terminal
        term_width_px = int(term_width * font_width_px * self.args.scale)
        term_height_px = int(term_height * font_height_px * self.args.scale)
        # convert option
        command_options.extend([
            "-filter Box",
            "-resize {:d}x{:d}!".format(term_width_px, term_height_px),
        ])

        if self.args.save_as_png:
            cmd = "{!r} {:s} rgb:{!r} PNG:{!r}".format(
                GefUtil.which("convert"),
                " ".join(command_options),
                image_path, image_path[:-4] + ".png"
            )
        else:
            cmd = "{!r} {:s} rgb:{!r} sixel:-".format(
                GefUtil.which("convert"),
                " ".join(command_options),
                image_path,
            )
        return cmd

    @parse_args
    @only_if_gdb_running
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware", "wine"))
    @require_arch_set
    def do_invoke(self, args):
        try:
            GefUtil.which("convert") # imagemagick
        except FileNotFoundError as e:
            err("{}".format(e))
            return

        # parse arena
        arena = GlibcHeap.get_arena(args.arena_addr)

        if arena is None:
            err("No valid arena")
            return

        if arena.heap_base is None or not is_valid_addr(arena.heap_base):
            err("Heap is not initialized")
            return

        if args.location is None:
            dump_start = arena.heap_base
            # specific pattern
            if arena.is_main_arena:
                if (is_x86_32() or is_riscv32() or is_ppc32()) and get_libc_version() >= (2, 26):
                    dump_start += 8
        else:
            dump_start = args.location

        # parse chunks
        chunks, err_msg = self.collect_chunks(arena, dump_start, args.max_count)

        # make image
        image_path = self.generate_image(chunks)
        if not image_path:
            return

        # show
        cmd = self.make_command_line(image_path)
        GefUtil.os_system(cmd)
        os.unlink(image_path)

        if args.save_as_png:
            info("Saved as {!r}".format(image_path[:-4] + ".png"))
        return


@register_command
class GlibcHeapSnapshotCommand(GenericCommand):
    """Take a snapshot of heap."""

    _cmdline_ = "heap snapshot"
    _category_ = "05-a. Heap - Glibc"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-a", "--arena-addr", type=AddressUtil.parse_address,
                        help="the address or number to interpret as an arena. (default: main_arena)")
    parser.add_argument("--all", action="store_true", help="dump all arenas.")
    _syntax_ = parser.format_help()

    @staticmethod
    def dump_heap(arena):
        # data
        try:
            section = ProcessMap.lookup_address(arena.heap_base).section
            page_start = section.page_start
            region_size = section.size
        except Exception:
            err("Failed to get memory range")
            return None

        try:
            raw = read_memory(page_start, region_size)
        except gdb.MemoryError:
            err("Failed to dump memory")
            return None

        # info
        try:
            heap_base = arena.heap_base
            dump_start = heap_base
            if arena.is_main_arena:
                if (is_x86_32() or is_riscv32() or is_ppc32()) and get_libc_version() >= (2, 26):
                    dump_start += 8

            info = {
                "heap_base": arena.heap_base,
                "dump_start": dump_start,
                "top": arena.top,
            }

            chunks = []
            current_chunk = GlibcHeap.GlibcChunk(arena, dump_start, from_base=True)
            while True:
                """
                0x555555fa9500|+0x00000: 0x0000000000000020 0x0000000000000041  <- start_offset
                0x555555fa9510|+0x00010: 0x726f7272652d736c 0x2d746f6e6e61632d
                0x555555fa9520|+0x00020: 0x7269642d6e65706f 0x622d79726f746365
                0x555555fa9530|+0x00030: 0x72637365642d6461 0x696c2f726f747069  <- end_offset
                """
                start_offset = current_chunk.chunk_base_address - heap_base
                chunks.append({
                    "start_offset": start_offset,
                    "size": current_chunk.size,
                    "end_offset": start_offset + current_chunk.size - (current_arch.ptrsize * 2),
                    "used": current_chunk.is_real_used(),
                    "extra": "",
                })
                if current_chunk.chunk_base_address > arena.top:
                    break
                if current_chunk.size == 0:
                    break
                chunks[-1]["extra"] = ",".join(arena.get_bins_info(current_chunk))
                if current_chunk.chunk_base_address == arena.top:
                    break

                next_chunk = current_chunk.get_next_chunk()
                if next_chunk is None:
                    break
                if not is_valid_addr(next_chunk.address):
                    break
                current_chunk = next_chunk

            info["chunks"] = chunks
        except Exception:
            return None

        return raw, info

    @staticmethod
    def take_snapshot(arena, arena_index):
        ret = GlibcHeapSnapshotCommand.dump_heap(arena)
        if ret is None:
            return None
        raw, info = ret

        raw_fd, raw_filepath = GefUtil.mkstemp(
            prefix="heap-ss-arena{:d}".format(arena_index),
            dt=datetime.datetime.now().strftime("%H%M%S"),
            suffix=".raw",
        )
        os.fdopen(raw_fd, "wb").write(raw)

        base, _ = os.path.splitext(raw_filepath)
        json.dump(info, open(base + ".json", "w"))

        GlibcHeapSnapshotCommand.last_dumped_filepath = raw_filepath
        return raw_filepath

    @staticmethod
    def read_snapshot(filepath):
        if os.path.basename(filepath) == filepath:
            filepath = os.path.join(GEF_TEMP_DIR, filepath)

        base, _ = os.path.splitext(filepath)
        raw_path = base + ".raw"
        json_path = base + ".json"

        if not os.path.exists(raw_path) or os.path.getsize(raw_path) == 0:
            err("Invalid file path (.raw)")
            return None
        if not os.path.exists(json_path) or os.path.getsize(json_path) == 0:
            err("Invalid file path (.json)")
            return None

        try:
            raw = open(raw_path, "rb").read()
        except gdb.MemoryError:
            return None
        try:
            info = json.loads(open(json_path).read())
        except Exception:
            return None
        return raw, info

    @parse_args
    @only_if_gdb_running
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware", "wine"))
    @require_arch_set
    def do_invoke(self, args):
        # parse arena
        arena = GlibcHeap.get_arena(args.arena_addr)

        if arena is None:
            err("No valid arena")
            return

        if arena.heap_base is None or not is_valid_addr(arena.heap_base):
            err("Heap is not initialized")
            return

        if args.all:
            arenas = GlibcHeap.get_all_arenas()
        else:
            arenas = [arena]

        # doit
        for i, arena in enumerate(arenas):
            path = self.take_snapshot(arena, i)
            if path:
                info("Snapshot successful: {:s}".format(path))
        return


@register_command
class GlibcHeapSnapshotCompareCommand(GenericCommand, BufferingOutput):
    """Compare current heap with a previously saved heap-snapshot."""

    _cmdline_ = "heap snapshot-compare"
    _category_ = "05-a. Heap - Glibc"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-a", "--arena-addr", type=AddressUtil.parse_address,
                        help="the address or number to interpret as an arena. (default: main_arena)")
    parser.add_argument("file_path", metavar="FILE_PATH", nargs="?",
                        help="the filepath to compare (default: last dumped file).")
    parser.add_argument("file_path2", metavar="FILE_PATH2", nargs="?", help="the filepath to compare.")
    parser.add_argument("-e", "--extra", action="store_true", help="display extra chunk info.")
    parser.add_argument("-f", "--full", action="store_true", help="display after `top` chunk.")
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    parser.add_argument("-q", "--quiet", action="store_true", help="quiet execution.")
    _syntax_ = parser.format_help()

    _example_ = [
        "{0:s} /path/to/snapshot1                     # compare the current memory and file1",
        "{0:s} /path/to/snapshot1 /path/to/snapshot2  # compare file1 and file2",
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    _note_ = [
        "Please specify the file obtained by the `heap snapshot` command.",
        "Usually, it is saved in /tmp/gef/heap-snashot-arenaN-...",
    ]
    _note_ = "\n".join(_note_)

    def __init__(self):
        super().__init__(complete=gdb.COMPLETE_FILENAME)
        return

    class LightRangeDict:
        DEFAULT_UNSET = object()

        def __init__(self):
            self.starts = []
            self.items = []
            self.default = self.DEFAULT_UNSET
            return

        def add(self, start, stop, value):
            import bisect
            if not (start < stop):
                raise ValueError("start must be < stop")

            i = bisect.bisect_left(self.starts, start)

            if 0 < i and start < self.items[i - 1][1]:
                raise ValueError("overlapping range")

            if i < len(self.items) and self.items[i][0] < stop:
                raise ValueError("overlapping range")

            self.starts.insert(i, start)
            self.items.insert(i, (start, stop, value))
            return None

        def __getitem__(self, key):
            import bisect
            i = bisect.bisect_right(self.starts, key) - 1
            if 0 <= i:
                start, stop, value = self.items[i]
                if key < stop:
                    return value
            if self.default is not self.DEFAULT_UNSET:
                return self.default
            raise KeyError(key)

        def setdefault(self, default):
            self.default = default
            return

    def compare(self, raw1, info1, raw2, info2):
        ptrsize = current_arch.ptrsize
        assert len(raw1) % ptrsize == 0
        assert len(raw2) % ptrsize == 0

        double_ptrsize = ptrsize * 2
        hex_width = double_ptrsize + 2

        if self.args.full:
            max_size = max(len(raw1), len(raw2))
        else:
            max_size = max(
                info1["top"] + double_ptrsize - info1["heap_base"],
                info2["top"] + double_ptrsize - info2["heap_base"],
            )

        color_dict = {
            # same, is_size, is_underline, is_used
            (True, True, True, True): "underline magenta",
            (True, True, True, False): "underline magenta",
            (True, True, False, True): "magenta",
            (True, True, False, False): "magenta",
            (True, False, True, True): "underline graphite",
            (True, False, True, False): "underline",
            (True, False, False, True): "graphite",
            (True, False, False, False): "",
            (False, True, True, True): "bold underline magenta",
            (False, True, True, False): "bold underline magenta",
            (False, True, False, True): "bold magenta",
            (False, True, False, False): "bold magenta",
            (False, False, True, True): "bold underline graphite",
            (False, False, True, False): "bold underline",
            (False, False, False, True): "bold graphite",
            (False, False, False, False): "bold",
        }

        start_offset_list1 = {c["start_offset"] for c in info1["chunks"]}
        start_offset_list2 = {c["start_offset"] for c in info2["chunks"]}
        end_offset_list1 = {c["end_offset"] for c in info1["chunks"]}
        end_offset_list2 = {c["end_offset"] for c in info2["chunks"]}
        if self.args.extra:
            prefix_blank = " " * (AddressUtil.get_format_address_width() + 18)
            fwidth = (double_ptrsize + 2) * 2 + 7 + double_ptrsize
            extra_dict1 = {c["start_offset"]: c["extra"] for c in info1["chunks"]}
            extra_dict2 = {c["start_offset"]: c["extra"] for c in info2["chunks"]}

        used_dict1 = self.LightRangeDict()
        used_dict1.setdefault(False)
        for ch in info1["chunks"]:
            used_dict1.add(ch["start_offset"], ch["start_offset"] + ch["size"], ch["used"])
        used_dict2 = self.LightRangeDict()
        used_dict2.setdefault(False)
        for ch in info2["chunks"]:
            used_dict2.add(ch["start_offset"], ch["start_offset"] + ch["size"], ch["used"])

        def to_ascii(v):
            s = ""
            for i in range(ptrsize):
                c = (v >> (8 * i)) & 0xff
                s += chr(c) if 0x20 <= c < 0x7f else "."
            return s

        # process block
        for pos in ProgressBar(range(0, max_size, double_ptrsize), disable=self.args.quiet):
            # skip or not
            raw16_1 = raw1[pos : pos + double_ptrsize]
            raw16_2 = raw2[pos : pos + double_ptrsize]

            # coloring
            hex_1 = []
            hex_2 = []
            ascii_1 = []
            ascii_2 = []
            is_line_same = True

            # unpack
            values1 = slice_unpack(raw16_1, ptrsize)
            values2 = slice_unpack(raw16_2, ptrsize)

            # check size, underline, used
            is_size1 = pos in start_offset_list1
            is_size2 = pos in start_offset_list2
            is_underline1 = pos in end_offset_list1
            is_underline2 = pos in end_offset_list2
            is_used1 = used_dict1[pos]
            is_used2 = used_dict2[pos]

            # cmp
            for i in range(2):
                try:
                    v1 = values1[i]
                    h1 = "{:#0{:d}x}".format(v1, hex_width)
                    a1 = to_ascii(v1)
                except IndexError:
                    v1 = None
                    h1 = " " * hex_width
                    a1 = " " * ptrsize
                try:
                    v2 = values2[i]
                    h2 = "{:#0{:d}x}".format(v2, hex_width)
                    a2 = to_ascii(v2)
                except IndexError:
                    v2 = None
                    h2 = " " * hex_width
                    a2 = " " * ptrsize

                # element coloring
                is_same = (v1 is None) or (v2 is None) or v1 == v2
                is_line_same &= is_same
                is_size1_e = is_size1 & (i == 1)
                is_size2_e = is_size2 & (i == 1)
                hex_1.append(Color.colorify(h1, color_dict[is_same, is_size1_e, is_underline1, is_used1]))
                ascii_1.append(Color.colorify(a1, color_dict[is_same, is_size1_e, is_underline1, is_used1]))
                hex_2.append(Color.colorify(h2, color_dict[is_same, is_size2_e, is_underline2, is_used2]))
                ascii_2.append(Color.colorify(a2, color_dict[is_same, is_size2_e, is_underline2, is_used2]))

            # blank coloring
            sep1 = Color.colorify(" ", color_dict[True, False, is_underline1, is_used1])
            sep2 = Color.colorify(" ", color_dict[True, False, is_underline2, is_used2])
            hex_1_joined = sep1.join(hex_1)
            hex_2_joined = sep2.join(hex_2)
            ascii_1_joined = sep1.join(ascii_1)
            ascii_2_joined = sep2.join(ascii_2)

            if self.args.extra:
                # make extra line
                extra1 = extra_dict1.get(pos, "")
                extra2 = extra_dict2.get(pos, "")
                if extra1 or extra2:
                    line = "{:s} {:{:d}s} {:{:d}s}".format(prefix_blank, extra1, fwidth, extra2, fwidth)
                    self.out.append(line.rstrip())

            # make line
            addr = ProcessMap.lookup_address(info1["dump_start"] + pos)
            line = "{:s}{!s}|{:+#08x}|{:+06d}: {:s} | {:s} | {:s} | {:s} |".format(
                " " if is_line_same else "+",
                addr, pos, pos // double_ptrsize,
                hex_1_joined, ascii_1_joined,
                hex_2_joined, ascii_2_joined,
            )
            self.out.append(line)
        return

    @parse_args
    @only_if_gdb_running
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware", "wine"))
    @require_arch_set
    def do_invoke(self, args):
        if args.file_path is not None and args.file_path2 is not None:
            ret1 = GlibcHeapSnapshotCommand.read_snapshot(self.args.file_path)
            ret2 = GlibcHeapSnapshotCommand.read_snapshot(self.args.file_path2)
            file_path1 = os.path.basename(self.args.file_path)
            file_path2 = os.path.basename(self.args.file_path2)
        else:
            # parse arena
            arena = GlibcHeap.get_arena(args.arena_addr)

            if arena is None:
                err("No valid arena")
                return

            if arena.heap_base is None or not is_valid_addr(arena.heap_base):
                err("Heap is not initialized")
                return

            ret1 = GlibcHeapSnapshotCommand.dump_heap(arena)
            file_path1 = "Current memory"

            if args.file_path is None:
                if not hasattr(GlibcHeapSnapshotCommand, "last_dumped_filepath"):
                    err("Invalid filepath")
                    return
                ret2 = GlibcHeapSnapshotCommand.read_snapshot(GlibcHeapSnapshotCommand.last_dumped_filepath)
                file_path2 = os.path.basename(GlibcHeapSnapshotCommand.last_dumped_filepath)
            else:
                ret2 = GlibcHeapSnapshotCommand.read_snapshot(self.args.file_path)
                file_path2 = os.path.basename(self.args.file_path)

        if ret1 is None or ret2 is None:
            return
        raw1, info1 = ret1
        raw2, info2 = ret2

        # legend
        self.out = []
        fwidth = (current_arch.ptrsize * 2 + 2) * 2 + 7 + (current_arch.ptrsize * 2)
        fmt = " {:{:d}s} {:8s} {:6s}  {:{:d}s} {:{:d}s}"
        legend = [
            "Address", AddressUtil.get_format_address_width(), "Offset", "Line",
            file_path1, fwidth, file_path2, fwidth,
        ]
        self.out.append(GefUtil.make_legend(fmt.format(*legend)))

        # doit
        self.compare(memoryview(raw1), info1, memoryview(raw2), info2)
        self.print_output(check_terminal_size=True)
        return


@register_command
class RegistersCommand(GenericCommand):
    """Display many or all register values from current architecture."""

    _cmdline_ = "registers"
    _category_ = "01-a. Debugging Support - Context"
    _aliases_ = ["regs"]

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("registers", metavar="REGISTERS", nargs="*",
                        type=lambda x: x if x.startswith("$") else "$" + x,
                        help="An array of registers. (default: current_arch.all_registers)")
    parser.add_argument("-s", "--simple", action="store_true", help="skip dereference.")
    _syntax_ = parser.format_help()

    _example_ = [
        "{0:s}",
        "{0:s} $eax $eip $esp",
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    def get_all_registers(self):
        if is_x86():
            all_registers = current_arch.all_registers + current_arch.virtual_registers
        else:
            all_registers = current_arch.all_registers
        return all_registers

    @Cache.cache_this_session
    def get_unavailable_regs(self):
        """Return registers that may be unavailable when their values are displayed."""
        unavailable_regs = []
        for regname in self.get_all_registers():
            try:
                reg = gdb.parse_and_eval(regname)
            except gdb.error:
                # older qemu cannot resolve `fs_base` etc.
                continue
            if reg.type.code == gdb.TYPE_CODE_VOID:
                continue
            if str(reg) == "<unavailable>":
                unavailable_regs.append(regname)
        return tuple(unavailable_regs)

    def get_regname_color(self, regname, regvalue):
        """Return the appropriate color for a register name based on whether its value has changed."""
        unchanged_color = Config.get_gef_setting("theme.registers_register_name")
        changed_color = Config.get_gef_setting("theme.registers_value_changed")

        old_value = ContextRegistersCommand.old_registers.get(regname, 0)

        if regvalue == old_value:
            color = unchanged_color
        else:
            color = changed_color
        return color

    def dump_seg_reg_x86_16(self):
        """Format and return x86 16-bit segment register values with color and dereferencing."""
        lines = []
        for regname, (seg, reg) in current_arch.seg_extended_registers.items():
            segval = get_register(seg) & 0xffff
            regval = get_register(reg) & 0xffff
            value = current_arch.real2phys(segval, regval)

            # colorling
            color = self.get_regname_color(regname, value)

            # reg name
            line = "{}:".format(Color.colorify(regname, color))

            # dereference values
            value_s = AddressUtil.format_address(value, memalign_size=2.5)
            line += " {:04x}:{:04x}: {:s}  ->  ".format(segval, regval, value_s)
            line += AddressUtil.recursive_dereference_to_string(value, skip_idx=1)

            lines.append(line)
        return lines

    def dump_regs(self, target_regs, unavailable_regs):
        """Format and return register values for display, with color, alignment, and optional dereferencing."""
        aliased_registers = current_arch.get_aliased_registers()
        widest = current_arch.get_aliased_registers_name_max()
        special_line = ""
        flag_line = ""

        lines = []
        for regname in target_regs:
            try:
                reg = gdb.parse_and_eval(regname)
            except gdb.error:
                # invalid register
                continue

            if reg.type.code == gdb.TYPE_CODE_VOID:
                continue

            # str(reg) is slow, so skip if unneeded
            if regname in unavailable_regs:
                # for qiling framework, fs_base/gs_base (x86), cpsr/fpsr/fpcr (Aarch64) are unavailable
                if str(reg) == "<unavailable>":
                    padreg = aliased_registers.get(regname, regname).ljust(widest, " ")
                    line = "{:s}: {:s}".format(
                        Color.colorify(padreg, Config.get_gef_setting("theme.registers_register_name")),
                        Color.colorify("<unavailable>", "yellow underline"),
                    )
                    lines.append(line)
                    continue

            # value
            try:
                if hasattr(reg, "bytes"):
                    reg_len = len(reg.bytes)
                else:
                    reg_len = current_arch.ptrsize
            except gdb.error:
                # In the qiling framework, it may fail just by doing hasattr (e.g., bndstatus)
                continue
            value = AddressUtil.normalize_address(int(reg), memalign_size=reg_len)

            # colorling
            color = self.get_regname_color(regname, value)

            # special (e.g., segment) registers go on their own line
            if current_arch.special_registers and regname in current_arch.special_registers:
                special_line += "{:s}: {:#06x} ".format(
                    Color.colorify(regname, color), get_register(regname),
                )
                continue

            # reg name
            padreg = aliased_registers.get(regname, regname).ljust(widest, " ")

            # flag register
            if current_arch.flag_register and regname == current_arch.flag_register:
                flag_line += "{:s}: {:s}".format(
                    Color.colorify(padreg, color), current_arch.flag_register_to_human(),
                )
                continue

            # make one line
            line = "{:s}: ".format(Color.colorify(padreg, color))
            if self.args.simple:
                # not dereference
                line += "{:s} ".format(ProcessMap.lookup_address(value).long_fmt())
            else:
                # dereference values
                if is_x86_16():
                    line += AddressUtil.format_address(value, memalign_size=4)
                    derefs = AddressUtil.recursive_dereference_to_string(value, skip_idx=1)
                    if derefs:
                        line += "  ->  {:s}".format(derefs)
                elif is_mipsn32():
                    line += AddressUtil.format_address(value, memalign_size=8, long_fmt=True)
                    derefs = AddressUtil.recursive_dereference_to_string(value, skip_idx=1)
                    if derefs:
                        line += "  ->  {:s}".format(derefs)
                else:
                    line += AddressUtil.recursive_dereference_to_string(value)

            lines.append(line)

        if self.args.simple:
            one_width = widest + 5 + current_arch.ptrsize * 2
            nb = GefUtil.get_terminal_size()[1] // one_width
            lines = ["".join(r) for r in slicer(lines, nb)]

        if flag_line:
            lines.append(flag_line)

        if special_line:
            lines.append(special_line.rstrip())

        if not self.args.simple:
            if is_x86_16():
                lines += self.dump_seg_reg_x86_16()
        return lines

    @parse_args
    @only_if_gdb_running
    @require_arch_set
    def do_invoke(self, args):
        unavailable_regs = self.get_unavailable_regs()

        if args.registers:
            target_regs = args.registers
        else:
            target_regs = self.get_all_registers()

        out = self.dump_regs(target_regs, unavailable_regs)
        if out:
            gef_print("\n".join(out))
        return


@register_command
class RopperCommand(GenericCommand):
    """Invoke ropper to search rop gadgets."""

    _cmdline_ = "ropper"
    _category_ = "01-i. Debugging Support - Other"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("args", metavar="ROPPER_OPTIONS", nargs="*",
                        help="An array of arguments to pass as is to the ropper command. (default: %(default)s)")
    _syntax_ = parser.format_help()

    _example_ = [
        "{0:s}",
        "{0:s} -h                  # show detail of options",
        '{0:s} --jmp "rax,rcx"     # filter by jmp registers',
        '{0:s} --search "pop r?x"  # filter by pop registers',
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    _help_ = None
    _help_examples_ = None

    def print_help(self):
        self.usage()

        ropper_bin = GefUtil.which("ropper")
        if self._help_ is None:
            self._help_ = subprocess.check_output([ropper_bin, "--help"]).decode("utf-8")
        if self._help_examples_ is None:
            self._help_examples_ = subprocess.check_output([ropper_bin, "--help-examples"]).decode("utf-8")

        help_text = titlify("gef --help")
        help_text += self._help_
        help_text += titlify("gef --help-examples")
        help_text += self._help_examples_
        gef_print(help_text, less=True)
        return

    # Need not @parse_args because argparse can't stop interpreting options for ropper.
    @only_if_gdb_running
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware"))
    @ModuleLoader.load_ropper
    @require_arch_set
    def do_invoke(self, argv):
        if "-h" in argv or "--help" in argv:
            self.print_help()
            return

        if "--file" not in argv:
            filepath = Path.get_filepath()
            if filepath is None:
                err("Missing info about file. Please set: `file /path/to/target_binary`")
                return
            argv.extend(["--file", filepath])
        else:
            try:
                filepath = argv[argv.index("--file") + 1]
            except IndexError:
                self.print_help()
                return

        if not os.path.isfile(filepath):
            err("Invalid filepath")
            return

        # ropper set up own autocompleter after which gdb/gef autocomplete don't work
        # due to fork/waitpid, child will be broken but parent will not change
        gef_print(titlify(filepath))
        pid = os.fork()
        if pid == 0:
            # Reorder GdbRemoveReadlineFinder in child processes so readline can be loaded.
            finder = None
            for x in list(sys.meta_path):
                if type(x).__name__ == "GdbRemoveReadlineFinder":
                    finder = x
                    sys.meta_path.remove(x)
                    break
            if finder is not None:
                sys.meta_path.append(finder)
            # doit
            try:
                ropper = sys.modules["ropper"]
                ropper.start(argv)
            except (Exception, SystemExit):
                pass
            os._exit(0)
        else:
            os.waitpid(pid, 0)
        return


@register_command
class RpCommand(GenericCommand, BufferingOutput):
    """Invoke rp++ (v2) command to search rop gadgets (x64/x86 only)."""

    _cmdline_ = "rp"
    _category_ = "01-i. Debugging Support - Other"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument("--bin", action="store_true", help="apply rp++ to binary itself.")
    group.add_argument("--libc", action="store_true", help="apply rp++ to libc.so searched from vmmap.")
    group.add_argument("--file", help="apply rp++ to specified file.")
    group.add_argument("--kernel", action="store_true", help="dump kernel, then apply vmlinux-to-elf and rp++.")
    parser.add_argument("-f", "--filter", action="append", type=re.compile, default=[], help="REGEXP filter.")
    parser.add_argument("-r", "--rop", dest="rop_N", type=int, default=3,
                        help="the max length of rop gadget. (default: %(default)s)")
    parser.add_argument("-a", "--allow-branches", action="store_true", help="enable --allow-branches.")
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    parser.add_argument("--no-print", action="store_true",
                        help="run rp, create a temporary file, but don't display it.")
    _syntax_ = parser.format_help()

    _example_ = [
        '{0:s} --bin -f "pop r[abcd]x"',
        '{0:s} --libc -f "(xchg|mov) [re]sp, \\\\w+" -f "ret"',
        "{0:s} --bin -a                                      # show more gadgets",
        "{0:s} --kernel                                      # only under qemu-system",
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    def __init__(self):
        super().__init__(complete=gdb.COMPLETE_FILENAME)
        return

    def exec_rp(self, rp, ropN, allow_branches, path):
        """Run rp++ to search for ROP gadgets, saving output to a file and returning its path."""
        astr = "ab" if allow_branches else ""
        output_file = "rp{:d}{:s}_{:s}.txt".format(ropN, astr, os.path.basename(path))
        output_path = os.path.join(GEF_TEMP_DIR, output_file)
        aops = "--allow-branches " if allow_branches else ""
        cmd = "{!r} --file={!r} --rop={:d} {:s}--unique > {!r}".format(rp, path, ropN, aops, output_path)
        gef_print(titlify(cmd))
        if not os.path.exists(output_path):
            GefUtil.os_system(cmd)
        return output_path

    def apply_filter(self, rp_output_path, base_address):
        """Apply regex filters to rp++ output, adjust gadget addresses, and store matching lines."""
        if not os.path.exists(rp_output_path):
            err("Could not find {!r}".format(rp_output_path))
            return
        lines = open(rp_output_path, "r").read()

        for line in lines.splitlines():
            line = Color.remove_color(line)

            match = True
            for re_pattern in self.args.filter:
                if not re_pattern.search(line):
                    match = False
                    break

            if match:
                if line.startswith("0x"):
                    x = line.split(":")
                    addr, gadget = int(x[0], 16), ":".join(x[1:])
                    addr -= base_address # fix address
                    x = Color.redify("{:#08x}".format(addr)) + ":" + gadget # repaint color
                else:
                    x = line
                self.out.append(x)
        return

    @parse_args
    @only_if_gdb_running
    @exclude_specific_gdb_mode(mode=("kgdb", "vmware"))
    @only_if_specific_arch(arch=("x86_32", "x86_64"))
    def do_invoke(self, args):
        try:
            rp = GefUtil.which("rp-lin")
        except FileNotFoundError as e:
            err("{}".format(e))
            return

        if args.kernel:
            try:
                nm = GefUtil.which(Config.get_gef_setting("gef.nm_command"))
                grep = GefUtil.which("grep")
            except FileNotFoundError as e:
                err("{}".format(e))
                return

        base_address = 0
        if args.libc:
            libc_targets = ("libc-2.", "libc.so.6", "libuClibc-")
            libc = ProcessMap.process_lookup_path(libc_targets)
            if libc is None:
                err("Could not find the libc")
                return
            path = libc.path
        elif args.bin:
            binary = Path.get_filepath()
            if binary is None:
                err("Could not find the binary")
                return
            path = binary
        elif args.file:
            if not os.path.exists(args.file):
                err("Could not find {}".format(args.file))
                return
            path = args.file
        elif args.kernel:
            if not is_qemu_system():
                err("--kernel are supported under qemu-system only")
                return

            info("Wait for memory scan")
            # dump kernel then apply vmlinux-to-elf
            symboled_vmlinux_file = VmlinuxToElfApplyCommand.dump_kernel_elf()
            if symboled_vmlinux_file is None:
                err("Failed to create kernel ELF")
                return
            path = symboled_vmlinux_file

            cmd = "{!r} {!r} | {!r} ' _stext$'".format(nm, symboled_vmlinux_file, grep)
            out = GefUtil.gef_execute_external(cmd, as_list=True, shell=True)
            if len(out) != 1:
                err("Failed to resolve _stext")
                return
            base_address = int(out[0].split()[0], 16)

        # invoke rp++
        rp_output_path = self.exec_rp(rp, args.rop_N, args.allow_branches, path)

        if args.no_print:
           return

        # filtering
        self.out = []
        self.apply_filter(rp_output_path, base_address)

        # print
        self.print_output(check_terminal_size=True)
        return


@register_command
class AssembleCommand(GenericCommand):
    """Assemble inline code using Keystone."""

    _cmdline_ = "asm"
    _category_ = "01-e. Debugging Support - Assemble"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-a", dest="arch", help="specify the architecture. (default: current_arch.arch)")
    parser.add_argument("-m", dest="mode", help="specify the mode. (default: current_arch.mode)")
    parser.add_argument("-e", dest="big_endian", action="store_true", help="use big-endian.")
    parser.add_argument("-s", dest="as_shellcode", action="store_true", help="output like shellcode style.")
    parser.add_argument("-l", dest="overwrite_location", metavar="LOCATION",
                        type=AddressUtil.parse_address, help="write to memory address.")
    parser.add_argument("-H", "--hex", action="store_true", help="show in hex style.")
    parser.add_argument("instruction", metavar="INSTRUCTION", nargs="+", help="the code to assemble.")
    _syntax_ = parser.format_help()

    _example_ = [
        '{0:s} -a X86 -m 64 "mov rax, qword ptr [rax] ; inc rax ;"',
        '{0:s} -a X86 -m 32 "mov eax, dword ptr [eax] ; inc eax ;"',
        '{0:s} -a X86 -m 16 "mov ax, word ptr [ax] ; inc ax"',
        '{0:s} -a ARM -m ARM      "sub r1, r2, r3"',
        '{0:s} -a ARM -m ARM -e   "sub r1, r2, r3"',
        '{0:s} -a ARM -m THUMB    "movs r4, #0xf0"',
        '{0:s} -a ARM -m THUMB -e "movs r4, #0xf0"',
        '{0:s} -a ARM64 -m ARM    "ldr w1, [sp, #0x8]"',
        '{0:s} -a MIPS -m 32    "and $9, $6, $7"',
        '{0:s} -a MIPS -m 32 -e "and $9, $6, $7"',
        '{0:s} -a MIPS -m 64    "and $9, $6, $7"',
        '{0:s} -a MIPS -m 64 -e "and $9, $6, $7"',
        '{0:s} -a PPC -m 32 -e "add 1, 2, 3"',
        '{0:s} -a PPC -m 64    "add 1, 2, 3"',
        '{0:s} -a PPC -m 64 -e "add 1, 2, 3"',
        '{0:s} -a SPARC -m 32 -e "add %g1, %g2, %g3"',
        '{0:s} -a SPARC -m 32PLUS -e "add %g1, %g2, %g3"',
        '{0:s} -a SPARC -m 64 -e "add %g1, %g2, %g3"',
        '{0:s} -a S390X -m 64 -e "a %r0, 4095(%r15,%r1)"',
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    @parse_args
    @ModuleLoader.load_keystone
    def do_invoke(self, args):
        if (args.arch, args.mode) == (None, None):
            if is_alive() and current_arch:
                arch, mode = UnicornKeystoneCapstone.get_keystone_arch(
                    arch=current_arch.arch, mode=current_arch.mode, endian=Endian.is_big_endian(),
                )
                arch_mode_s = ":".join([current_arch.arch, current_arch.mode])
                endian_s = "big" if Endian.is_big_endian() else "little"
            else:
                # if not alive, defaults to x86-64
                arch, mode = UnicornKeystoneCapstone.get_keystone_arch(arch="X86", mode="64", endian=False)
                arch_mode_s = "X86:64"
                endian_s = "little"
        elif not args.arch:
            err("An architecture (-a) must be provided")
            return
        elif not args.mode:
            # keystone gives no error so check here
            err("A mode (-m) must be provided")
            return
        elif args.arch in ["SPARC", "S390X"] and args.big_endian is False:
            # keystone gives no error so check here
            err("A big endian flag (-e) must be provided")
            return
        else:
            try:
                arch, mode = UnicornKeystoneCapstone.get_keystone_arch(
                    arch=args.arch, mode=args.mode, endian=args.big_endian,
                )
                arch_mode_s = ":".join([args.arch, args.mode])
                endian_s = "big" if args.big_endian else "little"
            except AttributeError:
                self.usage()
                return

        insns = " ".join(args.instruction)
        insns = [x.strip() for x in insns.split(";") if x is not None and x.strip() != ""]

        info("Assembling {:d} instruction{:s} for {:s} ({:s} endian)".format(
            len(insns), "s" if len(insns) > 1 else "", arch_mode_s, endian_s,
        ))

        if args.as_shellcode:
            gef_print('sc = ""')

        raw = b""
        for insn in insns:
            res = UnicornKeystoneCapstone.keystone_assemble(insn, arch, mode, raw=True)
            if not res:
                gef_print("(Invalid)")
                continue

            if args.overwrite_location is not None:
                raw += res
                continue

            s = binascii.hexlify(res)
            if args.hex:
                res = String.bytes2str(s)
            else:
                res = b"\\x" + b"\\x".join([s[i:i + 2] for i in range(0, len(s), 2)])
                res = res.decode("utf-8")

            if args.as_shellcode:
                res = 'sc += "{:s}"'.format(res)

            gef_print("{:60s} # {:s}".format(res, insn))

        if args.overwrite_location is not None:
            hex_code = binascii.hexlify(raw).decode()
            gdb.execute("patch hex {:#x} {:s}".format(args.overwrite_location, hex_code))
        return


@register_command
class DisassembleCommand(GenericCommand):
    """Disassemble inline code using Capstone."""

    _cmdline_ = "dasm"
    _category_ = "01-e. Debugging Support - Assemble"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-a", dest="arch", help="specify the architecture. (default: current_arch.arch)")
    parser.add_argument("-m", dest="mode", help="specify the mode. (default: current_arch.mode)")
    parser.add_argument("-e", dest="big_endian", action="store_true", help="use big-endian.")
    parser.add_argument("hex_code", metavar="HEX_CODE", nargs="+", help="the hex code to disassemble.")
    _syntax_ = parser.format_help()

    _example_ = [
        '{0:s} -a X86 -m 64 "488b00 48ffc0"',
        '{0:s} -a X86 -m 32 "8b00 40"',
        '{0:s} -a X86 -m 16 "8b00 40"',
        '{0:s} -a ARM -m ARM      "031042e0"',
        '{0:s} -a ARM -m ARM -e   "e0421003"',
        '{0:s} -a ARM -m THUMB    "f024"',
        '{0:s} -a ARM -m THUMB -e "24f0"',
        '{0:s} -a ARM64 -m ARM    "e10b40b9"',
        '{0:s} -a MIPS -m 32    "2448c700"',
        '{0:s} -a MIPS -m 32 -e "00c74824"',
        '{0:s} -a MIPS -m 64    "2448c700"',
        '{0:s} -a MIPS -m 64 -e "00c74824"',
        '{0:s} -a PPC -m 32 -e "7c221a14"',
        '{0:s} -a PPC -m 64    "141a227c"',
        '{0:s} -a PPC -m 64 -e "7c221a14"',
        '{0:s} -a SPARC -m 32 -e "86004002"',
        '{0:s} -a SPARC -m 32PLUS -e "86004002"',
        '{0:s} -a SPARC -m 64 -e "86004002"',
        '{0:s} -a RISCV -m 32 "97c10600"',
        '{0:s} -a RISCV -m 64 "97c10600"',
        '{0:s} -a S390X -m 64 -e "5a0f1fff"',
        '{0:s} -a M68K -m 32 -e "9dce"',
        '{0:s} -a LOONGARCH -m 64 "89001500" # capstone v6.x~',
        '{0:s} -a LOONGARCH -m 32 "89001500" # capstone v6.x~',
        '{0:s} -a ALPHA -m 64    "0b00bd27" # capstone v6.x~',
        '{0:s} -a ALPHA -m 64 -e "27bd000b" # capstone v6.x~',
        '{0:s} -a HPPA -m 32 -e "0fc01299" # capstone v6.x~',
        '{0:s} -a HPPA -m 64 -e "0fc01299" # capstone v6.x~',
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    @parse_args
    @ModuleLoader.load_capstone
    def do_invoke(self, args):
        if (args.arch, args.mode) == (None, None):
            if is_alive() and current_arch:
                arch, mode = UnicornKeystoneCapstone.get_capstone_arch(
                    arch=current_arch.arch, mode=current_arch.mode, endian=Endian.is_big_endian(),
                )
                arch_mode_s = ":".join([current_arch.arch, current_arch.mode])
                endian_s = "big" if Endian.is_big_endian() else "little"
            else:
                # if not alive, defaults to x86-64
                arch, mode = UnicornKeystoneCapstone.get_capstone_arch(
                    arch="X86", mode="64", endian=False,
                )
                arch_mode_s = "X86:64"
                endian_s = "little"
        elif not args.arch:
            err("An architecture (-a) must be provided")
            return
        elif not args.mode:
            err("A mode (-m) must be provided")
            return
        elif args.arch in ["SPARC", "S390X", "M68K", "HPPA"] and args.big_endian is False:
            # capstone gives no error so check here
            err("A big endian flag (-e) must be provided")
            return
        else:
            try:
                arch, mode = UnicornKeystoneCapstone.get_capstone_arch(
                    arch=args.arch, mode=args.mode, endian=args.big_endian,
                )
                arch_mode_s = ":".join([args.arch, args.mode])
                endian_s = "big" if args.big_endian else "little"
            except AttributeError:
                self.usage()
                return

        insns = " ".join(args.hex_code)
        insns = insns.replace(" ", "").replace("\t", "")
        try:
            insns = binascii.unhexlify(insns)
        except binascii.Error:
            err("Invalid format")
            return

        info("Disassembling {:d} bytes for {:s} ({:s} endian)".format(
            len(insns), arch_mode_s, endian_s,
        ))

        capstone = sys.modules["capstone"]
        try:
            cs = capstone.Cs(arch, mode)
        except capstone.CsError:
            err("CsError")
            return
        cs.detail = True # noqa

        for insn in cs.disasm(insns, 0x0):
            b = binascii.hexlify(insn.bytes).decode("utf-8")
            gef_print("{:>#6x}:\t{:<10s}\t{:s}\t{:s}".format(insn.address, b, insn.mnemonic, insn.op_str))
        return


@register_command
class AsmListCommand(GenericCommand):
    """List general instructions by capstone (x64/x86 only)."""

    _cmdline_ = "asm-list"
    _category_ = "01-e. Debugging Support - Assemble"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-a", dest="arch", help="specify the architecture. (default: current_arch.arch)")
    parser.add_argument("-m", dest="mode", help="specify the mode. (default: current_arch.mode)")
    parser.add_argument("-e", dest="big_endian", action="store_true", help="use big-endian.")
    parser.add_argument("-b", dest="nbyte", type=int, help="filter by the length of asm byte.")
    parser.add_argument("-f", dest="include", action="append", help="filter by specified string.")
    parser.add_argument("-v", dest="exclude", action="append", help="filter by specified string.")
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    _syntax_ = parser.format_help()

    _example_ = [
        "{0:s} -a X86 -m 64",
        "{0:s} -a X86 -m 32",
        "{0:s} -a X86 -m 16",
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    _note_ = [
        "- F0 (LOCK prefix) is ignored",
        "- F2/F3 (REPNE/REP prefix) are ignored",
        "- 2E/36/3E/26/64/65 (CS/SS/DS/ES/FS/GS override prefix) are ignored",
        "- 2E/3E (branch hint prefix) are ignored",
        "- 66 (operand size prefix) is included",
        "- 67 (address size prefix) is ignored",
        "- 40-4F (REX prefix) are ignored",
        "- C4/C5 (VEX prefix) are ignored",
        "- 8F (XOP prefix) is ignored",
        "- 62 (EVEX prefix) is ignored",
    ]
    _note_ = "\n".join(_note_)

    cache = None

    def listup_x86(self, arch, mode):
        if self.cache:
            return self.cache

        DISP64 = "1122334455667788"
        DISP32 = "11223344"
        DISP16 = "1122"
        DISP8 = "11"

        @Cache.cache_this_session
        def get_typical_bytecodes_modrm(reg_value):
            mod_list = range(4)
            assert 0 <= reg_value <= 7
            reg_list = [reg_value]
            rm_list = [0, 0b100] # The correct value is range(8), but it is reduced for speed.
            sib_list = [0, 0b01001001] # The correct value is range(256), but it is reduced for speed.

            bytecodes = []
            for mod, reg, rm in itertools.product(mod_list, reg_list, rm_list):
                modrm = "{:02X}".format((mod << 6) | (reg << 3) | rm)
                if mod == 0b00:
                    if rm == 0b101: # special case; [REG + disp32]
                        bytecode = modrm + DISP32
                    elif rm == 0b100: # use sib; [INDEX * SCALE + BASE]
                        bytecode = []
                        for sib in sib_list:
                            b = modrm + "{:02X}".format(sib)
                            bytecode.append(b)
                    else: # [REG]
                        bytecode = modrm
                elif mod == 0b01:
                    if rm == 0b100: # use sib; [INDEX * SCALE + BASE + disp8]
                        bytecode = []
                        for sib in sib_list:
                            b = modrm + "{:02X}".format(sib) + DISP8
                            bytecode.append(b)
                    else: # [REG + disp8]
                        bytecode = modrm + DISP8
                elif mod == 0b10:
                    if rm == 0b100: # use sib; [INDEX * SCALE + BASE + disp32]
                        bytecode = []
                        for sib in sib_list:
                            b = modrm + "{:02X}".format(sib) + DISP32
                            bytecode.append(b)
                    else: # [REG + disp32]
                        bytecode = modrm + DISP32
                elif mod == 0b11: # REG
                    bytecode = modrm
                if isinstance(bytecode, list):
                    bytecodes.extend(bytecode)
                else:
                    bytecodes.append(bytecode)
            return bytecodes

        def get_typical_bytecodes(opcodes):
            bytecodes = []
            for operand in opcodes.split():
                if operand in ["ib", "cb"]:
                    bytecode = [DISP8]
                elif operand in ["iw", "cw"]:
                    bytecode = [DISP16]
                elif operand in ["id", "cd"]:
                    bytecode = [DISP32]
                elif operand in ["iq"]:
                    bytecode = [DISP64]
                elif operand in ["/0", "/1", "/2", "/3", "/4", "/5", "/6", "/7"]:
                    bytecode = get_typical_bytecodes_modrm(int(operand[1]))
                elif operand == "/r":
                    bytecode = get_typical_bytecodes_modrm(0)
                elif operand.endswith(("+r", "+i")):
                    b = int(operand.split("+")[0], 16)
                    bytecode = ["{:02X}".format(b + x) for x in range(8)]
                else:
                    bytecode = [operand]
                bytecodes.append(bytecode)
            return ["".join(b) for b in itertools.product(*bytecodes)]

        def load_x86_json():
            x86data_js = os.path.join(GEF_TEMP_DIR, "x86data.js")
            if os.path.exists(x86data_js) and os.path.getsize(x86data_js) > 0:
                x86 = open(x86data_js, "rb").read()
            else:
                url = "https://raw.githubusercontent.com/bata24/gef/dev/asmdb/x86data.js"
                x86 = http_get(url)
                if x86 is None:
                    err("Connection timed out: {:s}".format(url))
                    return None
                open(x86data_js, "wb").write(x86)

            x86 = x86.split(b"// ${JSON:BEGIN}")[1].split(b"// ${JSON:END}")[0]
            return json.loads(x86)

        # load capstone
        capstone = sys.modules["capstone"]
        try:
            cs = capstone.Cs(arch, mode)
        except capstone.CsError:
            err("CsError")
            return None

        # default instruction set
        x86 = load_x86_json()
        # manually added
        x86_insns = x86["instructions"]
        # [opcode_str, unused, unused, opcodes, attr]
        x86_insns.append(["icebp", "", "", "F1", "Undocumented"])
        x86_insns.append(["salc", "", "", "D6", "Undocumented"])
        #x86_insns.append(["umov", "", "", "0F 10 /r", "Undocumented"]) # used by another opcode
        #x86_insns.append(["umov", "", "", "0F 11 /r", "Undocumented"]) # used by another opcode
        #x86_insns.append(["umov", "", "", "0F 12 /r", "Undocumented"]) # used by another opcode
        #x86_insns.append(["umov", "", "", "0F 13 /r", "Undocumented"]) # used by another opcode
        #x86_insns.append(["loadall", "", "", "0F 05", "Undocumented"]) # used by another opcode
        #x86_insns.append(["loadall", "", "", "0F 07", "Undocumented"]) # used by another opcode
        #x86_insns.append(["xbts", "", "", "0F A6", "Undocumented"]) # removed now
        #x86_insns.append(["ibts", "", "", "0F A7", "Undocumented"]) # removed now

        # parse it
        valid_patterns = []
        seen_patterns = []
        for insn in x86_insns:
            opcodes = insn[3]
            attr = insn[4].split()

            # filter ignore prefix pattern
            if "REX.W" in opcodes.split():
                continue
            if "VEX" in opcodes.split()[0].split("."):
                continue
            if "EVEX" in opcodes.split()[0].split("."):
                continue
            if "XOP" in opcodes.split()[0].split("."):
                continue

            # e.g., "FF /2" -> ["FF10", "FF5011", ...]
            bytecodes = get_typical_bytecodes(opcodes)

            # check it is valid or not
            for hex_code in bytecodes:
                # dup check
                if hex_code in seen_patterns:
                    continue
                # disasm
                code = bytes.fromhex(hex_code)
                try:
                    asm = cs.disasm(code, 0).__next__()
                except StopIteration:
                    continue
                opstr = asm.mnemonic + " " + asm.op_str
                # add
                valid_patterns.append([hex_code, opstr, opcodes, attr])
                seen_patterns.append(hex_code)

        self.cache = valid_patterns
        return valid_patterns

    @parse_args
    @ModuleLoader.load_capstone
    @require_arch_set
    def do_invoke(self, args):
        if (args.arch, args.mode) == (None, None):
            if is_alive():
                arch, mode = UnicornKeystoneCapstone.get_capstone_arch(
                    arch=current_arch.arch, mode=current_arch.mode, endian=Endian.is_big_endian(),
                )
                arch_mode_s = ":".join([current_arch.arch, current_arch.mode])
                endian_s = "big" if Endian.is_big_endian() else "little"
            else:
                # if not alive, defaults to x86-64
                arch, mode = UnicornKeystoneCapstone.get_capstone_arch(arch="X86", mode="64", endian=False)
                arch_mode_s = "X86:64"
                endian_s = "little"
        elif not args.arch:
            err("An architecture (-a) must be provided")
            return
        elif not args.mode:
            err("A mode (-m) must be provided")
            return
        elif args.arch in ["SPARC", "S390X", "M68K"] and args.big_endian is False:
            # capstone gives no error so check here
            err("A big endian flag (-e) must be provided")
            return
        else:
            try:
                arch, mode = UnicornKeystoneCapstone.get_capstone_arch(
                    arch=args.arch, mode=args.mode, endian=args.big_endian,
                )
                arch_mode_s = ":".join([args.arch, args.mode])
                endian_s = "big" if args.big_endian else "little"
            except AttributeError:
                self.usage()
                return

        # list bytecode pattern
        if arch_mode_s.startswith("X86:"):
            if endian_s == "big":
                err("X86 is not big endian")
                return
            patterns = self.listup_x86(arch, mode)
        else:
            err("Unsupported other than x86/x64")
            return

        if patterns is None:
            err("Failed to list entries")
            return

        # filter and print
        self.out = []
        fmt = "{:22s} {:70s} {:22s} {!s}"
        legend = ["Hex code", "Assembly code", "Opcode", "Attributes"]
        self.out.append(GefUtil.make_legend(fmt.format(*legend)))

        for hex_code, opstr, opcodes, attr in patterns:
            # byte length filter
            if args.nbyte is not None and args.nbyte * 2 != len(hex_code):
                continue

            # keyword filter
            line = "{:22s} {:70s} {:22s} {!s}".format(hex_code, opstr, opcodes, ",".join(attr))
            if args.include and any(f not in line for f in args.include):
                continue
            if args.exclude and any(f in line for f in args.exclude):
                continue

            # not filtered
            self.out.append(line)

        gef_print("\n".join(self.out), less=not args.no_pager)
        return


@register_command
class ProcessSearchCommand(GenericCommand, BufferingOutput):
    """Display a smart list of processes."""

    _cmdline_ = "ps"
    _category_ = "02-a. Process Information - General"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("pattern", metavar="REGEX_PATTERN", nargs="?", help="filter by regex.")
    parser.add_argument("-a", "--attach", type=int, help="attach it.")
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    parser.add_argument("-v", "--verbose", action="store_true",
                        help="include kernel thread, socat, grep, gdb, sshd, bash, systemd, etc.")
    _syntax_ = parser.format_help()

    _example_ = [
        "{0:s}",
        "{0:s} ./a.out",
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    def get_processes(self):
        output = GefUtil.gef_execute_external([GefUtil.which("ps"), "auxww"], as_list=True)
        names = [x.lower().replace("%", "") for x in output[0].split()]

        for line in output[1:]:
            fields = line.split()
            t = {}

            for i, name in enumerate(names):
                if i == len(names) - 1:
                    t[name] = " ".join(fields[i:])
                else:
                    t[name] = fields[i]
            yield t
        return

    @parse_args
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware"))
    @require_arch_set
    def do_invoke(self, args):
        if args.pattern:
            pattern = re.compile(args.pattern)
        else:
            pattern = re.compile("^.*$")

        self.out = []
        for process in self.get_processes():
            pid = int(process["pid"])
            command = process["command"]
            process["user"] = process["user"].ljust(8)

            if not re.search(pattern, command):
                continue

            if not args.verbose:
                if command.startswith("[") and command.endswith("]"): # kernel thread
                    continue

                skip_list = [
                    # common
                    "socat ",
                    "grep ",
                    "gdb ",
                    "gdb-multiarch",
                    "-bash",
                    "sshd:",
                    "ssh-agent ",
                    # VMware tools
                    "vmhgfs-fuse",
                    "vmware-vmblock-fuse",
                    "fusermount3",
                    # system service
                    "avahi-daemon:",
                    "@dbus-daemon",
                    "(sd-pam)",
                    "gjs ",
                    "gdm-session-worker",
                    "cupsd ",
                    "cups-browsed ",
                    # common path
                    ("/bin/", "/usr/bin/"),
                    ("/sbin/", "/usr/sbin/"),
                    ("/lib/", "/usr/lib/"),
                    "/usr/libexec/",
                    "/snap/",
                    "/var/lib/pcp/pmdas",
                ]
                if any(command.startswith(x) for x in skip_list):
                    continue

            if args.attach:
                if args.attach == pid:
                    ok("Attaching to process='{:s}' pid={:d}".format(process["command"], pid))
                    gdb.execute("attach {:d}".format(pid))
                    return

            line = [process[i] for i in ("pid", "user", "cpu", "mem", "tty", "command")]
            self.out.append("\t".join(line))

        self.print_output()
        return


