@register_command
class HexdumpFlexibleCommand(GenericCommand, BufferingOutput):
    """Display the hexdump with user-defined format."""

    _cmdline_ = "hexdump-flexible"
    _category_ = "03-b. Memory - View"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("format", metavar="FORMAT", help="dump format.")
    parser.add_argument("location", metavar="LOCATION", type=AddressUtil.parse_address,
                        help="the memory address to dump.")
    parser.add_argument("count", metavar="COUNT", nargs="?", type=AddressUtil.parse_address, default=1,
                        help="the count of displayed units. (default: %(default)s)")
    parser.add_argument("--phys", action="store_true",
                        help="treat LOCATION as a physical address (qemu-system only).")
    parser.add_argument("-t", "--tag", nargs=2, action="append", metavar=("IDX", "TAG"),
                        help="display with tags.")
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    _syntax_ = parser.format_help()

    _example_ = [
        '{0:s} "2Q2I2H2B" $rsp 4  # "Show qword*2, dword*2, short*2, byte*2" from $rsp and repeat 4 times',
        '{0:s} "4Q-2Q" $rsp 4     # "Show qword*4 and skip qword*2" from $rsp and repeat 4 times',
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    def extract_each_type(self, fmt):
        out = []
        repeat = 1
        for r in re.split(r"(-?\d+|)", fmt):
            if r == "":
                continue
            try:
                repeat = int(r)
                continue
            except ValueError:
                if 0 < repeat:
                    out.extend([r] * repeat)
                else:
                    out.extend(["-" + r] * -repeat)
                repeat = 1
        return out

    def do_dump(self, fmt, size, each_type):
        base_address_color = Config.get_gef_setting("theme.dereference_base_address")

        # parse tag
        max_tag_width = 0
        tags_dic = {}
        if self.args.tag:
            for idx, tag in self.args.tag:
                idx = int(idx, 0)
                tags_dic[idx] = tag
                max_tag_width = max(max_tag_width, len(tag))

        for i in range(self.args.count):
            # read content
            address = self.args.location + size * i
            try:
                if self.args.phys:
                    data = read_physmem(address, size)
                else:
                    data = read_memory(address, size)
            except (gdb.MemoryError, ValueError, OverflowError):
                self.err_add_out("Failed to read memory")
                break

            # unpack
            values = struct.unpack(fmt.replace("-", ""), data)

            # make address line
            if max_tag_width == 0:
                line = "{:s}|{:+#06x}|{:+04d}:   ".format(
                    Color.colorify(AddressUtil.format_address(address), base_address_color),
                    size * i, i,
                )
            else:
                tag_i = tags_dic.get(i, "")
                line = "{:s}|{:+#06x}|{:+04d}: {:{:d}s}:".format(
                    Color.colorify(AddressUtil.format_address(address), base_address_color),
                    size * i, i,
                    tag_i, max_tag_width,
                )

            # dump each element
            for t, v in zip(each_type, values):
                if t.startswith("-"):
                    continue
                if t in "BHILQ":
                    line += " {:#0{:d}x}".format(v, 2 + struct.calcsize(t) * 2)
                elif t in "bhilq":
                    line += " {:+#0{:d}x}".format(v, 2 + struct.calcsize(t) * 2 + 1)
                elif t in "fd":
                    line += " {:20e}".format(v)
                else:
                    self.err_add_out("Unsupported format: {:s}".format(t))
                    return

            self.out.append(line)
        return

    @parse_args
    @only_if_gdb_running
    def do_invoke(self, args):
        if args.phys:
            if not is_qemu_system() and not is_vmware() and not is_kgdb():
                err("Unsupported in this gdb mode.")
                return

        fmt = args.format
        if not fmt.startswith(("<", ">")):
            fmt = Endian.endian_str() + fmt
        try:
            size = struct.calcsize(fmt.replace("-", ""))
        except struct.error:
            err("Format error")
            return

        each_type = self.extract_each_type(args.format)

        self.out = []
        self.do_dump(fmt, size, each_type)
        self.print_output()
        return


@register_command
class LoadFileCommand(GenericCommand):
    """Load the file into memory."""

    _cmdline_ = "load-file"
    _category_ = "03-f. Memory - Dump/Load"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("location", metavar="LOCATION", type=AddressUtil.parse_address,
                        help="the memory address to load.")
    parser.add_argument("file_path", metavar="FILE_PATH", help="the filepath to load.")
    parser.add_argument("file_offset", metavar="FILE_OFFSET", nargs="?", type=AddressUtil.parse_address, default=0,
                        help="the offset of the file to load.")
    parser.add_argument("load_size", metavar="LOAD_SIZE", nargs="?", type=AddressUtil.parse_address,
                        help="the size of the data to load.")
    _syntax_ = parser.format_help()

    _note_ = [
        "+-memory------+",
        "|             |             +-file_start--+",
        "|             |             | ^           |",
        "|             |             | |           |",
        "|             |             | v           |",
        "| LOCATION <----------------- FILE_OFFSET |",
        "| ...         | ^           | ...         |",
        "|             | | LOAD_SIZE |             |",
        "| ...         | v           | ...         |",
        "| end <---------------------- end         |",
        "|             |             |             |",
        "|             |             |             |",
        "|             |             +-file_end----+",
        "|             |",
        "+-------------+",
        "If there is not enough space, the load will fail halfway.",
    ]
    _note_ = "\n".join(_note_)

    @parse_args
    @only_if_gdb_running
    def do_invoke(self, args):
        if not os.path.exists(args.file_path):
            err("Could not find {:s}".format(args.file_path))
            return

        if args.load_size is None:
            data_size = os.path.getsize(args.file_path)
            if data_size == 0:
                err("Unsupported zero size mapping")
                return
        elif args.load_size < 0:
            err("Invalid LOAD_SIZE")
            return
        else:
            data_size = args.load_size

        if args.file_offset < 0:
            err("Invalid FILE_OFFSET")
            return

        # read file and write to memory
        with open(args.file_path, "rb") as fd:
            if args.file_offset > 0:
                fd.seek(args.file_offset, 0)

            pos = args.location
            remain_size = data_size
            while remain_size > 0:
                data = fd.read(min(0x1000, remain_size))
                if len(data) == 0:
                    break
                write_memory(pos, data)
                pos += len(data)
                remain_size -= len(data)
        return


@register_command
class LoadFileMmapCommand(GenericCommand):
    """Load the file into memory that allocated by `mmap`."""

    _cmdline_ = "load-file-mmap"
    _category_ = "03-f. Memory - Dump/Load"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("location", metavar="LOCATION", type=AddressUtil.parse_address,
                        help="the memory address to load.")
    parser.add_argument("file_path", metavar="FILE_PATH", help="the filepath to load.")
    parser.add_argument("file_offset", metavar="FILE_OFFSET", nargs="?", type=AddressUtil.parse_address, default=0,
                        help="the offset of the file to load.")
    parser.add_argument("load_size", metavar="LOAD_SIZE", nargs="?", type=AddressUtil.parse_address,
                        help="the size of the data to load.")
    _syntax_ = parser.format_help()

    _note_ = [
        "+-mmap_start--+",
        "|             |             +-file_start--+",
        "|             |             | ^           |",
        "|             |             | |           |",
        "|             |             | v           |",
        "| LOCATION <----------------- FILE_OFFSET |",
        "| ...         | ^           | ...         |",
        "|             | | LOAD_SIZE |             |",
        "| ...         | v           | ...         |",
        "| end <---------------------- end         |",
        "|             |             |             |",
        "|             |             |             |",
        "|             |             +-file_end----+",
        "|             |",
        "+-mmap_end----+",
    ]
    _note_ = "\n".join(_note_)

    @parse_args
    @only_if_gdb_running
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware"))
    @require_arch_set
    def do_invoke(self, args):
        if not os.path.exists(args.file_path):
            err("Could not find {:s}".format(args.file_path))
            return

        if args.load_size is None:
            data_size = os.path.getsize(args.file_path)
            if data_size == 0:
                err("Unsupported zero size mapping")
                return
        elif args.load_size < 0:
            err("Invalid LOAD_SIZE")
            return
        else:
            data_size = args.load_size

        if args.file_offset < 0:
            err("Invalid FILE_OFFSET")
            return

        # +-mmap_start--+               ^             ^
        # |             |               |             |
        # |             |               |             | page_size
        # | data_start  | ^             |             |
        # | ...         | |             |             |
        # +-------------+ | data_size   | mmap_size   v
        # | ...         | |             |
        # | data_end    | v             |
        # |             |               |
        # |             |               |
        # +-mmap_end----+               v

        mmap_start = args.location & get_pagesize_mask_high()
        data_start = args.location
        data_end = data_start + data_size
        mmap_end = align_to_pagesize(data_end)
        mmap_size = mmap_end - mmap_start

        # mmap
        res = gdb.execute("mmap {:#x} {:#x}".format(mmap_start, mmap_size), to_string=True)
        if "[!]" in res:
            err("Failed to mmap")
            return

        output_line = res.splitlines()[-1]
        ret = int(output_line.split()[2], 0)

        if AddressUtil.is_msb_on(ret):
            err("Failed to mmap")
            return

        # read file and write to memory
        with open(args.file_path, "rb") as fd:
            if args.file_offset > 0:
                fd.seek(args.file_offset, 0)

            pos = data_start
            remain_size = data_size
            while remain_size > 0:
                data = fd.read(min(0x1000, remain_size))
                if len(data) == 0:
                    break
                write_memory(pos, data)
                pos += len(data)
                remain_size -= len(data)
        return


@register_command
class PatchCommand(GenericCommand):
    """The base command to write specified values to the specified address."""

    _cmdline_ = "patch"
    _category_ = "03-d. Memory - Patch"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    if (sys.version_info.major, sys.version_info.minor) >= (3, 7):
        subparsers = parser.add_subparsers(title="command", required=True)
    else:
        subparsers = parser.add_subparsers(title="command")
    subparsers.add_parser("byte")
    subparsers.add_parser("word")
    subparsers.add_parser("dword")
    subparsers.add_parser("qword")
    subparsers.add_parser("string")
    subparsers.add_parser("hex")
    subparsers.add_parser("pattern")
    subparsers.add_parser("nop")
    subparsers.add_parser("inf")
    subparsers.add_parser("trap")
    subparsers.add_parser("ret")
    subparsers.add_parser("syscall")
    subparsers.add_parser("range-replace")
    subparsers.add_parser("history")
    subparsers.add_parser("revert")
    _syntax_ = parser.format_help()

    patch_history = [] # [ [patch1a, patch1b], [patch2a], ...]

    def __init__(self, *args, **kwargs):
        prefix = kwargs.get("prefix", True)
        complete = kwargs.get("complete", gdb.COMPLETE_NONE)
        super().__init__(prefix=prefix, complete=complete)
        self.format = None
        return

    class PatchInfo:
        def __init__(self, addr, data, length=None, phys=None, tag=None):
            if not isinstance(addr, int):
                raise ValueError
            self.addr = addr

            if not isinstance(data, bytes):
                raise ValueError
            self.data = data

            if length is None:
                self.length = len(self.data)
            else:
                self.length = length

            self.phys = phys

            # tag: A key to group multiple patches together
            if tag is None:
                self.tag = PatchCommand.PatchInfo.get_unique_tag()
            else:
                self.tag = tag
            return

        def __repr__(self):
            return '<{:s}.{:s} object at {:#x}, addr={:#x}, data={}, length={:#x}, phys={}, tag={}>'.format(
                self.__module__, self.__class__.__name__, id(self),
                self.addr, self.data, self.length, self.phys,
                hex(self.tag) if isinstance(self.tag, int) else self.tag,
            )

        @staticmethod
        def get_unique_tag():
            import random
            tags = PatchCommand.PatchInfo.get_tag_set()
            while True:
                v = random.randint(1, 0xffff_ffff)
                if v not in tags:
                    break
            return v

        @staticmethod
        def get_tag_set():
            return {x[0].tag for x in PatchCommand.patch_history}

        def a(self):
            a = " ".join(["{:02x}".format(x) for x in self.after_data[:0x10]])
            if len(self.after_data) > 0x10:
                a += " ..."
            return a

        def b(self):
            b = " ".join(["{:02x}".format(x) for x in self.before_data[:0x10]])
            if len(self.before_data) > 0x10:
                b += " ..."
            return b

        def patch(self, silent=False):
            orig_mode = QemuMonitor.get_current_mmu_mode()
            if orig_mode == "virt" and self.phys:
                enable_phys()
                self.before_data = read_memory(self.addr, self.length)
                write_memory(self.addr, self.data)
                self.after_data = read_memory(self.addr, self.length)
                disable_phys()
            elif orig_mode == "phys" and not self.phys:
                disable_phys()
                self.before_data = read_memory(self.addr, self.length)
                write_memory(self.addr, self.data)
                self.after_data = read_memory(self.addr, self.length)
                enable_phys()
            else:
                self.before_data = read_memory(self.addr, self.length)
                write_memory(self.addr, self.data)
                self.after_data = read_memory(self.addr, self.length)

            # print
            if not silent:
                ok("Patch success: {!s}{:s}: {:s} -> {:s}".format(
                    ProcessMap.lookup_address(self.addr), Symbol.get_symbol_string(self.addr),
                    self.b(), self.a(),
                ))

            # history
            self.insert_history()
            return

        def insert_history(self):
            for i in range(len(PatchCommand.patch_history)):
                if PatchCommand.patch_history[i][0].tag == self.tag:
                    PatchCommand.patch_history[i].append(self)
                    break
            else:
                PatchCommand.patch_history.insert(0, [self])
            return

        def revert(self, silent=False):
            orig_mode = QemuMonitor.get_current_mmu_mode()
            if orig_mode == "virt" and self.phys:
                enable_phys()
                write_memory(self.addr, self.before_data)
                disable_phys()
            elif orig_mode == "phys" and not self.phys:
                disable_phys()
                write_memory(self.addr, self.before_data)
                enable_phys()
            else:
                write_memory(self.addr, self.before_data)

            # print
            if not silent:
                ok("Revert success: {!s}{:s}: {:s} -> {:s}".format(
                    ProcessMap.lookup_address(self.addr), Symbol.get_symbol_string(self.addr),
                    self.a(), self.b(),
                ))

            # history
            self.remove_history()
            return

        def remove_history(self):
            for i in range(len(PatchCommand.patch_history)):
                if PatchCommand.patch_history[i][0].tag == self.tag:
                    PatchCommand.patch_history[i].remove(self)
                    if PatchCommand.patch_history[i] == []:
                        PatchCommand.patch_history.pop(i)
                    break
            return

        @staticmethod
        def revert_to_tag(tag, silent=False):
            tags = PatchCommand.PatchInfo.get_tag_set()
            if tag not in tags:
                err("Not found tag")
                return None
            while PatchCommand.patch_history:
                hist = PatchCommand.patch_history.pop(0)
                for patch_info in hist:
                    try:
                        patch_info.revert(silent)
                    except Exception as e:
                        err(e)
                        return
                if tag == hist[0].tag:
                    break
            return

    # for qword, dword, word, byte sub-commands
    @parse_args
    @only_if_gdb_running
    @exclude_specific_gdb_mode(mode=("rr",))
    def do_invoke(self, args):
        SUPPORTED_SIZES = {
            "qword": (8, "Q"),
            "dword": (4, "L"),
            "word": (2, "H"),
            "byte": (1, "B"),
        }
        if self.format not in SUPPORTED_SIZES:
            self.usage()
            return

        if args.phys:
            if not is_qemu_system():
                err("Unsupported in this gdb mode.")
                return

        addr = args.location
        size, fcode = SUPPORTED_SIZES[self.format]

        if args.endian_reverse is False:
            d = "<" if Endian.is_little_endian() else ">"
        else:
            d = ">" if Endian.is_little_endian() else "<"

        tag = PatchCommand.PatchInfo.get_unique_tag()
        for value in args.values:
            value = AddressUtil.parse_address(value) & ((1 << size * 8) - 1)
            vstr = struct.pack(d + fcode, value)
            try:
                self.PatchInfo(addr, vstr, size, phys=args.phys, tag=tag).patch()
            except Exception as e:
                err(e)
                return
            addr += size
        return


