@register_command
class KernelCurrentCommand(GenericCommand):
    """Display current task."""

    _cmdline_ = "kcurrent"
    _category_ = "06-c. Qemu-system/KGDB Cooperation - Linux Basic"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-q", "--quiet", action="store_true", help="enable quiet mode.")
    _syntax_ = parser.format_help()

    def __init__(self):
        super().__init__()
        self.__per_cpu_offset = None
        self.cpu_offset = None
        self.offset_comm = None
        return

    def get_cpu_offset(self):
        # use cache
        if self.cpu_offset:
            self.quiet_info("__per_cpu_offset: {:#x}".format(self.__per_cpu_offset))
            self.quiet_info("Num of cpu: {:d} (guessed)".format(len(self.cpu_offset)))
            return self.cpu_offset

        # resolve __per_cpu_offset
        __per_cpu_offset = KernelAddressHeuristicFinder.get_per_cpu_offset()

        # not found
        if __per_cpu_offset is None:
            return None

        # found
        self.quiet_info("__per_cpu_offset: {:#x}".format(__per_cpu_offset))
        self.__per_cpu_offset = __per_cpu_offset

        self.cpu_offset = Kernel.get_each_cpu_offset(__per_cpu_offset)
        self.quiet_info("Num of cpu: {:d} (guessed)".format(len(self.cpu_offset)))
        return self.cpu_offset

    def resolve_offset_comm(self, report_failure=True):
        """Resolve `offsetof(task_struct, comm)` via `ktask`.
        `ktask` resolves `init_task` from the CPU context of the selected thread and
        the answer differs between CPUs, so this must not be called while another
        thread is temporarily selected."""

        if self.offset_comm is not None:
            return self.offset_comm

        ret = gdb.execute("ktask --no-pager --meta", to_string=True)
        r = re.search(r"offsetof\(task_struct, comm\): (0x\S+)", ret)
        if r is not None:
            self.offset_comm = int(r.group(1), 16)
        elif report_failure:
            self.quiet_err("ktask failed")
            self.offset_comm = False
        return self.offset_comm

    def get_comm_str(self, task_addr):
        if self.resolve_offset_comm() is False:
            return "???"

        comm = read_cstring_from_memory(task_addr + self.offset_comm)
        return comm or "???"

    def dump_current_arm(self):
        orig_thread = gdb.selected_thread()
        try:
            orig_frame = gdb.selected_frame()
        except gdb.error:
            # The selected frame is not always readable (e.g., ARM32 halted at the exception vector,
            # where the frame pointer still holds an unmapped userland value).
            # Reverting the thread is enough because this command never selects an outer frame.
            orig_frame = None
        # Resolve `offsetof(task_struct, comm)` before switching to another thread.
        # If this CPU cannot resolve it, `get_comm_str()` retries later in the loop.
        self.resolve_offset_comm(report_failure=False)
        threads = gdb.selected_inferior().threads()
        threads = sorted(threads, key=lambda th: th.num)
        for thread in threads:
            thread.switch() # change thread
            cpu_num = thread.num - 1 # ?
            task = KernelAddressHeuristicFinder.get_current_task_for_current_thread()
            if task is None:
                if is_arm32():
                    cpsr = get_register(current_arch.flag_register)
                    if cpsr is not None and (cpsr & 0b11111) == 0b10000:
                        reason = "CPU is in USR mode; sp holds a user stack pointer"
                    else:
                        reason = "failed to resolve current task"
                    gef_print("current (cpu{:d}): unavailable ({:s})".format(cpu_num, reason))
                elif is_arm64():
                    cpsr = get_register(current_arch.flag_register)
                    if cpsr is not None and ((cpsr >> 2) & 0b11) == 0:
                        reason = "CPU is in EL0; sp_el0 holds a user stack pointer"
                    else:
                        reason = "failed to resolve current task"
                    gef_print("current (cpu{:d}): unavailable ({:s})".format(cpu_num, reason))
                continue
            gef_print("current (cpu{:d}): {:#x} {:s}".format(cpu_num, task, self.get_comm_str(task)))
        orig_thread.switch() # revert thread
        if orig_frame is not None:
            orig_frame.select()
        return

    def dump_current_x86(self):
        current_task = KernelAddressHeuristicFinder.get_current_task()
        if not current_task:
            self.quiet_err("Failed to resolve `current_task`")
            return

        cpu_bases = self.get_cpu_offset()

        if cpu_bases:
            # pattern 1. Offset from __per_cpu_offset.
            self.quiet_info("current_task: {:#x}".format(current_task))
            task_offset = current_task
            for i, cpu_base in enumerate(cpu_bases):
                task = read_int_from_memory(AddressUtil.normalize_address(cpu_base + task_offset))
                if not is_valid_addr(task):
                    break
                gef_print("current (cpu{:d}): {:#x} {:s}".format(i, task, self.get_comm_str(task)))
        else:
            # pattern 2: current_task is the address that stores a pointer to the current task (not per_cpu).
            task = read_int_from_memory(current_task)
            if is_valid_addr(task):
                self.quiet_info("__per_cpu_offset is unused")
                gef_print("current: {:#x} {:s}".format(task, self.get_comm_str(task)))
            else:
                self.quiet_err("Failed to resolve `__per_cpu_offset`")
        return

    @parse_args
    @only_if_gdb_running
    @only_if_specific_gdb_mode(mode=("qemu-system", "vmware"))
    @only_if_specific_arch(arch=("x86_32", "x86_64", "ARM32", "ARM64"))
    @only_if_in_kernel_or_kpti_disabled
    def do_invoke(self, args):
        self.quiet_info("Wait for memory scan")

        if is_arm32() or is_arm64():
            self.dump_current_arm()
        elif is_x86():
            self.dump_current_x86()
        return


@register_command
class KernelTaskCommand(GenericCommand, BufferingOutput):
    """Display process list."""

    _cmdline_ = "ktask"
    _category_ = "06-f. Qemu-system/KGDB Cooperation - Linux Task"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-hh", "--help-simple", action="store_true", help="show help without ASCII diagram.")
    parser.add_argument("-f", "--filter", action="append", type=re.compile, default=[],
                        help="comm string REGEXP filter.")
    parser.add_argument("-T", "--task-filter", action="append", type=AddressUtil.parse_address, default=[],
                        help="task address filter.")
    parser.add_argument("-m", "--print-maps", action="store_true",
                        help="print memory map for each user-land process.")
    parser.add_argument("-r", "--print-regs", action="store_true",
                        help="print general registers saved on kstack for each user-land process.")
    parser.add_argument("-i", "--print-all-id", action="store_true",
                        help="print suid, sgid, euid, egid, fsuid and fsgid.")
    parser.add_argument("-t", "--print-thread", action="store_true",
                        help="display by thread (LWP), not by process.")
    parser.add_argument("-F", "--print-fd", action="store_true",
                        help="print file descriptors for each user process.")
    parser.add_argument("-s", "--print-sighand", action="store_true",
                        help="print signal handlers for each user process.")
    parser.add_argument("-S", "--print-seccomp", action="store_true",
                        help="dump the seccomp filter. If the tool is available, it dumps orig_prog; otherwise, it disassembles bpf_func.")
    parser.add_argument("-N", "--print-namespace", action="store_true",
                        help="print namespaces for each user process.")
    parser.add_argument("-u", "--user-process-only", action="store_true",
                        help="display user-land process (+ thread) only.")
    parser.add_argument("--init-task", type=AddressUtil.parse_address,
                        help="specifies the address of init_task.")
    parser.add_argument("--meta", action="store_true", help="display offset information.")
    parser.add_argument("--all", action="store_true", help="enable all option.")
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    parser.add_argument("-q", "--quiet", action="store_true", help="enable quiet mode.")
    _syntax_ = parser.format_help()

    _example_ = [
        "{0:s} -q",
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    _note_ = [
        "This command requires CONFIG_RANDSTRUCT=n.",
        "",
        "Simplified task_struct structure:",
        "",
        "    +-init_task-+",
        "    | list_head |---+    +-->+-kstack----------+    +--->+-vm_area_struct--+",
        "    +-----------+   |    |   | (thread_info)   |    |    | vm_start        |",
        "                    |    |   | STACK_END_MAGIC |    |    | vm_end          |",
        "+-------------------+    |   | ...             |    |    | vm_next (~6.1)  |",
        "|                        |   | ...             |    |    | ...             |",
        "|   +-task_struct---+    |   | ...             |    |    | vm_flags        |",
        "|   | (thread_info) |    |   | ...             |    |    | vm_file         |-----+",
        "|   | ...           |    |   | pt_regs         |    |    | ...             |     |",
        "|   | stack         |----+   +-----------------+    |    +-----------------+     |",
        "|   | ...           |                               |                            |",
        "+-->| tasks         |-->...               +---------+<------------------------+  |",
        "    | ...           |                     |                                   |  |",
        "    | mm            |-->+-mm_struct----+  |  +-------->+-maple_node(6.1~)--+  |  |",
        "    | ...           |   | mmap (~6.1)  |--+  |         | ...               |  |  |",
        "    | pid           |   | ...          |     |         | mr64|ma64|alloc   |  |  |",
        "    | tid           |   | mm_mt (6.1~) |     |         |   ...             |  |  |",
        "    | ...           |   |   ma_root    |-----+         |   slot[]          |--+  |",
        "    | stack_canary  |   | ...          |               +-------------------+     |",
        "    | ...           |   +--------------+                                         |",
        "    | group_leader  |                                         +------------------+       +-mount----------+",
        "    | ...           |         +-->+-cred--------------+       |                          | ...            |",
        "    | thread_group  |-->...   |   | ...               |       |                          | mnt_parent     |-->mount",
        "    | ...           |         |   | uid, gid          |       |                          | mnt_mountpoint |-->dentry",
        "    | cred          |---------+   | suid, sgid        |       |                       +->| mnt (vfsmount) |",
        "    | ...           |             | euid, egid        |       |                       |  |   mnt_root     |-->dentry",
        "    | comm[16]      |             | fsuid, fsgid      |       |                       |  |   ...          |",
        "    | ...           |             | ..., user_ns, ... |       |                       |  | ...            |",
        "    | files         |--+          +-------------------+       |                       |  +----------------+",
        "    | ...           |  |                                      |                       |",
        "    | nsproxy       |------->+-nsproxy----------------+       |                       | +--->+-dentry-----+",
        "    | ...           |  |     | count                  |       |                       | |    | ...        |",
        "    | sighand       |-----+  | uts_ns, ipc_ns, mnt_ns |       |                       | |    | d_parent   |-->dentry",
        "    | ...           |  |  |  | pid_ns_for_children    |       |                       | |    | ...        |",
        "    | seccomp       |  |  |  | net_ns, time_ns, ...   |       |                       | |    | d_inode    |--+",
        "    | ...           |  |  |  +------------------------+       |                       | |    | d_iname    |  |",
        "    +---------------+  |  |                                   |                       | |    | ...        |  |",
        "                       |  +->+-sighand_struct----+            |                       | |    +------------+  |",
        "                       |     | ...               |            v                       | |                    |",
        "                       |     | action[64]        |            +-->+-file-----------+  | | +------------------+",
        "+----------------------+     +-------------------+            |   | ...            |  | | |",
        "|                                                             |   | f_path         |  | | v",
        "+-->+-files_struct-+  +-->+-fdtable---+  +-->+-file*[]-----+  |   |   mnt          |--+ | +->+-inode------+",
        "    | ...          |  |   | max_fds   |  |   | [0]         |--+   |   dentry       |----+ |  | ...        |",
        "    | fdt          |--+   | fd        |--+   | ...         |      | f_inode (3.9~) |------+  | i_ino      |",
        "    | ...          |      | ...       |      | [max_fds-1] |      | ...            |         | ...        |",
        "    +--------------+      +-----------+      +-------------+      +----------------+         +------------+",
        "",
        "This command will only track tasks that can be tracked from `init_task` or the result of `kcurrent` command.",
        "Other tasks (such as `swapper/1` if thread 1 is running some task) will not be detected.",
    ]
    _note_ = "\n".join(_note_)

    @staticmethod
    def get_task_list(task, offset_tasks):
        # `task` itself is also a task, so it is included.
        head = task + offset_tasks
        lh = Kernel.ListHead(head, offset_tasks)
        task_list = []
        forward_valid = False
        backward_valid = False
        try:
            if is_valid_addr_addr(head):
                next_head = read_int_from_memory(head)
                forward_valid = read_int_from_memory(next_head + current_arch.ptrsize) == head
        except (gdb.MemoryError, OverflowError):
            pass
        try:
            if is_valid_addr_addr(head + current_arch.ptrsize):
                prev_head = read_int_from_memory(head + current_arch.ptrsize)
                backward_valid = read_int_from_memory(prev_head) == head
        except (gdb.MemoryError, OverflowError):
            pass
        if forward_valid:
            try:
                task_list.extend(lh.iter_entries(include_head=True))
            except (gdb.MemoryError, OverflowError):
                pass
        seen = set(task_list)
        backward = []
        if backward_valid:
            try:
                backward.extend(lh.iter_entries(include_head=True, backward=True))
            except (gdb.MemoryError, OverflowError):
                pass
        task_list += [x for x in reversed(backward) if x not in seen]
        return [x for x in task_list if is_valid_addr(x)]

    @Cache.cache_this_session(cache_None=False)
    def get_offset_tasks(self, init_task):
        # fast path
        try:
            return to_unsigned_long(gdb.parse_and_eval("&((struct task_struct*)0).tasks"))
        except gdb.error:
            pass

        # slow path
        # search for init_task->tasks
        for i in range(0x200):
            offset_tasks = current_arch.ptrsize * i
            task_list = KernelTaskCommand.get_task_list(init_task, offset_tasks)
            if len(task_list) > 5:
                return offset_tasks
        return None

    @Cache.cache_this_session(cache_None=False)
    def get_offset_mm(self, offset_tasks):
        """
        struct task_struct {
            ...
            struct list_head tasks;
        #ifdef CONFIG_SMP
            struct plist_node {
                int prio;
                struct list_head prio_list;
                struct list_head node_list;
            } pushable_tasks;
            struct rb_node {
                unsigned long __rb_parent_color;
                struct rb_node *rb_right;
                struct rb_node *rb_left;
            } pushable_dl_tasks; // v3.14~
        #endif
            struct mm_struct *mm;
            struct mm_struct *active_mm;
            ...
        };
        """
        task_addr = self.task_addrs_temp[0]

        # fast path
        try:
            return to_unsigned_long(gdb.parse_and_eval("&((struct task_struct*)0).mm"))
        except gdb.error:
            pass

        # slow path
        kversion = Kernel.kernel_version()
        if kversion is None:
            return None
        if kversion < "6.17":
            offset_mm = offset_tasks + 2 * current_arch.ptrsize
            r = read_int_from_memory(task_addr + offset_mm)
            if 0 < r <= 0xffff:
                # maybe prio, so CONFIG_SMP is y
                if "3.14" <= kversion:
                    offset_mm = offset_tasks + 10 * current_arch.ptrsize
                else:
                    offset_mm = offset_tasks + 7 * current_arch.ptrsize
        else:
            offset_mm = offset_tasks + 10 * current_arch.ptrsize
        return offset_mm

    @Cache.cache_this_session(cache_None=False)
    def get_offset_comm(self):
        task_addrs = self.task_addrs_temp

        # fast path
        try:
            return to_unsigned_long(gdb.parse_and_eval("&((struct task_struct*)0).comm"))
        except gdb.error:
            pass

        # slow path
        for i in range(0x300):
            offset_comm = i * current_arch.ptrsize
            valid = True
            names = set()
            for task in task_addrs:
                if not is_ascii_string(task + offset_comm):
                    valid = False
                    break
                s = read_cstring_from_memory(task + offset_comm)
                # very common name, so for speeding up, we assume that offset is found
                if s == "swapper/0":
                    break
                if len(s) < 2:
                    valid = False
                    break
                names.add(s)
            else:
                # Every task gave the same string, so this is not `comm` but a pointer that is
                # initialized to an identical value for all tasks (e.g. posix_cputimers_work.work.func).
                # Depending on KASLR, such a pointer can be read as a short ASCII string.
                if len(names) < 2:
                    valid = False
            if valid:
                return offset_comm
        return None

    @Cache.cache_this_session(cache_None=False)
    def get_offset_cred(self, offset_comm):
        """
        struct task_struct {
            ...
            const struct cred __rcu *real_cred; // These may point to the same address
            const struct cred __rcu *cred;      // These may point to the same address
        #ifdef CONFIG_KEYS
            struct key *cached_requested_key;
        #endif
            char comm[TASK_COMM_LEN];
            ...
        };
        """
        task_addrs = self.task_addrs_temp

        # fast path
        try:
            return to_unsigned_long(gdb.parse_and_eval("&((struct task_struct*)0).cred"))
        except gdb.error:
            pass

        # slow path
        # backward search from `comm`
        for i in range(0x2):
            offset_cred = offset_comm - ((i + 1) * current_arch.ptrsize)
            for task in task_addrs:
                val1 = read_int_from_memory(task + offset_cred)
                val2 = read_int_from_memory(task + offset_cred - current_arch.ptrsize)
                if val1 == val2 and val1 != 0:
                    return offset_cred
        return None

    @Cache.cache_this_session(cache_None=False)
    def get_offset_stack(self):
        """
        struct task_struct {
            ...
        #ifdef CONFIG_THREAD_INFO_IN_TASK
            struct thread_info thread_info;
        #endif
            volatile long state;
            void *stack;
            ...
        };
        """
        task_addrs = self.task_addrs_temp

        # fast path
        try:
            return to_unsigned_long(gdb.parse_and_eval("&((struct task_struct*)0).stack"))
        except gdb.error:
            pass

        # slow path
        for i in range(0x100):
            found = False
            zcount = 0
            for task in task_addrs:
                v = read_int_from_memory(task + current_arch.ptrsize * i)
                if v == 0:
                    zcount += 1
                    continue
                if (v & 0x1fff) != 0:
                    break
                if not is_valid_addr(v):
                    zcount += 1
                    continue
            else:
                found = True

            # For unknown reasons, processes without a readable stack are sometimes observed.
            # 0xffffa122c17db000 U   106     chal.sh ... 0xffffa43100218000 0xd16ef01535a35500
            # 0xffffa122c17da000 U   108     socat   ... 0xffffa43100278000 0x3d378b9e6f59bf00
            # 0xffffa122c17dc000 U   109     chal    ... 0xffffa431002d4000 0x277c67d5e5854500
            # 0xffffa122c17dd000 K   110     3       ... 0x0000000000000000 0x22a999743f180500 <-- here
            # Therefore, a small number of NULL or unreadable pointers are allowed.
            if zcount > len(task_addrs) // 10:
                found = False

            if found is False:
                continue

            offset_stack = current_arch.ptrsize * i
            return offset_stack
        return None

    def get_thread_info(self, task_addr, offset_stack):
        # fast path
        try:
            return task_addr + to_unsigned_long(gdb.parse_and_eval("&((struct task_struct*)0).thread_info"))
        except gdb.error:
            try:
                # task_struct exists but has no thread_info member
                gdb.parse_and_eval("(struct task_struct*)0")
                return read_int_from_memory(task_addr + offset_stack)
            except gdb.error:
                pass

        # slow path
        kstack = read_int_from_memory(task_addr + offset_stack)
        if not is_valid_addr(kstack):
            return None
        stack_top_val = read_int32_from_memory(kstack)
        if stack_top_val == 0x57ac6e9d: # STACK_END_MAGIC
            """
            struct task_struct {
            #ifdef CONFIG_THREAD_INFO_IN_TASK
                struct thread_info thread_info;
            #endif
                ...
            """
            return task_addr # CONFIG_THREAD_INFO_IN_TASK=y
        else:
            return kstack # CONFIG_THREAD_INFO_IN_TASK=n

    def has_seccomp(self, task_addr):
        if self.offset_stack is None:
            return None
        thread_info = self.get_thread_info(task_addr, self.offset_stack)
        if thread_info is None:
            return None
        kversion = Kernel.kernel_version()
        if kversion is None:
            return None
        if is_x86():
            if "5.11" <= kversion:
                syscall_work = read_int_from_memory(thread_info + current_arch.ptrsize)
                return bool(syscall_work & (1 << 0)) # SYSCALL_WORK_SECCOMP
            elif "4.9" <= kversion:
                flags = read_int_from_memory(thread_info)
                return bool(flags & (1 << 8)) # TIF_SECCOMP
            elif "4.1" <= kversion:
                flags = read_int32_from_memory(thread_info + current_arch.ptrsize)
                return bool(flags & (1 << 8)) # TIF_SECCOMP
            else:
                flags = read_int32_from_memory(thread_info + current_arch.ptrsize * 2)
                return bool(flags & (1 << 8)) # TIF_SECCOMP
        elif is_arm32():
            if "6.0" <= kversion:
                flags = read_int_from_memory(thread_info)
                return bool(flags & (1 << 23)) # TIF_SECCOMP
            elif "5.16" <= kversion:
                flags = read_int_from_memory(thread_info)
                return bool(flags & (1 << 7)) # TIF_SECCOMP
            elif "5.15" <= kversion:
                flags = read_int_from_memory(thread_info)
                return bool(flags & (1 << 23)) # TIF_SECCOMP
            elif "5.11" <= kversion:
                flags = read_int_from_memory(thread_info)
                return bool(flags & (1 << 7)) # TIF_SECCOMP
            elif "5.10" <= kversion:
                flags = read_int_from_memory(thread_info)
                return bool(flags & (1 << 23)) # TIF_SECCOMP
            elif "4.3" <= kversion:
                flags = read_int_from_memory(thread_info)
                return bool(flags & (1 << 7)) # TIF_SECCOMP
            elif "3.8" <= kversion:
                flags = read_int_from_memory(thread_info)
                return bool(flags & (1 << 11)) # TIF_SECCOMP
            else:
                flags = read_int_from_memory(thread_info)
                return bool(flags & (1 << 21)) # TIF_SECCOMP
        elif is_arm64():
            if "3.16" <= kversion:
                flags = read_int_from_memory(thread_info)
                return bool(flags & (1 << 11)) # TIF_SECCOMP
            else:
                # unimplemented
                return None
        return None

    @Cache.cache_this_session(cache_None=False)
    def get_offset_ptregs(self, offset_stack):
        task_addrs = self.task_addrs_temp

        # calc kstack address pattern
        kstacks_raw = []
        for task in task_addrs:
            kstack = read_int_from_memory(task + offset_stack)
            if kstack == 0:
                continue
            kstacks_raw.append(kstack)

        # calc kstack size
        kstacks = sorted({x & 0xffff for x in kstacks_raw}) # uniq and sort
        diffs = []
        for i in range(len(kstacks) - 1):
            diff = kstacks[i + 1] - kstacks[i]
            diffs.append(diff)
        if len(diffs) == 0:
            kstack_size = get_pagesize() * 2
        else:
            kstack_size = min(diffs)

        # check
        while kstack_size >= 0x2000:
            for kstack in kstacks_raw:
                if not is_valid_addr(kstack + kstack_size - current_arch.ptrsize):
                    kstack_size //= 2
                    break # for, then retry while
            else:
                break # while

        if is_x86_64():
            """
            struct pt_regs {
                unsigned long r15;
                unsigned long r14;
                unsigned long r13;
                unsigned long r12;
                unsigned long rbp;
                unsigned long rbx;
                unsigned long r11;
                unsigned long r10;
                unsigned long r9;
                unsigned long r8;
                unsigned long rax;
                unsigned long rcx;
                unsigned long rdx;
                unsigned long rsi;
                unsigned long rdi;
                unsigned long orig_rax;
                unsigned long rip;
                unsigned long cs;
                unsigned long eflags;
                unsigned long rsp;
                unsigned long ss;
            };
            """
            ptregs_size = current_arch.ptrsize * 21

            # Sometimes register values are stored a short distance away from the bottom of the kstack.
            # It is unclear whether this depends on the kernel version.
            # In 6.10.11 it was at offset 0, and in 6.10.0-rc2 it was at offset 16.
            # For this reason, dynamic detection is used.
            # TODO: Dynamic detection may also be necessary for x86, ARM, and ARM64.
            for i in range(8):
                init_process_kstack = read_int_from_memory(task_addrs[1] + offset_stack)
                init_process_kstack_end = init_process_kstack + kstack_size
                v = read_int_from_memory(init_process_kstack_end - current_arch.ptrsize * (i + 1))
                if v == 0x2b: # ss segment default value
                    bottom_offset = current_arch.ptrsize * i
                    break
            else:
                bottom_offset = 0
        elif is_x86_32():
            """
            struct pt_regs {
                long ebx;
                long ecx;
                long edx;
                long esi;
                long edi;
                long ebp;
                long eax;
                int xds;
                int xes;
                int xfs;
                int xgs;
                long orig_eax;
                long eip;
                int xcs;
                long eflags;
                long esp;
                int xss;
            };
            """
            ptregs_size = current_arch.ptrsize * 17
            bottom_offset = current_arch.ptrsize * 2 # ?
        elif is_arm64():
            """
            struct pt_regs {
                u64 regs[31];
                u64 sp;
                u64 pc;
                u64 pstate;
                u64 orig_x0;
                u64 syscallno;
                u64 orig_addr_limit;
                u64 pmr_save;
                u64 stackframe[2];
                u64 lockdep_hardirqs;
                u64 exit_rcu;
            };
            """
            ptregs_size = current_arch.ptrsize * 35
            bottom_offset = current_arch.ptrsize * 7
        elif is_arm32():
            """
            struct pt_regs {
                unsigned long uregs[18];
            };
            """
            ptregs_size = current_arch.ptrsize * 18
            bottom_offset = current_arch.ptrsize * 2 # ?
        else:
            return None

        offset_ptregs = kstack_size - ptregs_size - bottom_offset
        return kstack_size, offset_ptregs

    def get_regs(self, kstack, offset_ptregs):
        if is_x86_64():
            regs_name = [
                "r15", "r14", "r13", "r12", "rbp", "rbx", "r11", "r10",
                "r9", "r8", "rax", "rcx", "rdx", "rsi", "rdi", "orig_rax",
                "rip", "cs", "eflags", "rsp", "ss",
            ]
        elif is_x86_32():
            regs_name = [
                "ebx", "ecx", "edx", "esi", "edi", "ebp", "eax", "ds",
                "es", "fs", "gs", "orig_eax", "eip", "cs", "eflags", "esp", "ss",
            ]
        elif is_arm64():
            regs_name = [
                "x0", "x1", "x2", "x3", "x4", "x5", "x6", "x7",
                "x8", "x9", "x10", "x11", "x12", "x13", "x14", "x15",
                "x16", "x17", "x18", "x19", "x20", "x21", "x22", "x23",
                "x24", "x25", "x26", "x27", "x28", "x29", "x30",
                "sp", "pc", "pstate", "orig_x0",
            ]
        elif is_arm32():
            regs_name = [
                "r0", "r1", "r2", "r3", "r4", "r5", "r6",
                "r7", "r8", "r9", "r10", "r11", "r12",
                "sp", "lr", "pc", "cpsr", "orig_r0",
            ]

        ptregs_addr = kstack + offset_ptregs
        ptregs_size = len(regs_name) * current_arch.ptrsize
        regs_data = read_memory(ptregs_addr, ptregs_size)

        # maybe kernel thread
        if is_x86():
            if regs_data == b"\0" * len(regs_data):
                return None
        elif is_arm32():
            kernel_thread_regs = p32(0) * (len(regs_name) - 2) + p32(0x13) + p32(0)
            if regs_data == kernel_thread_regs:
                return None
        elif is_arm64():
            kernel_thread_regs = p64(0) * (len(regs_name) - 2) + p64(0x5) + p64(0)
            if regs_data == kernel_thread_regs:
                return None

        # get regs value
        regs_data = slice_unpack(regs_data, current_arch.ptrsize)
        regs = {}
        for name, value in zip(regs_name, regs_data):
            regs[name] = value
        return regs

    @Cache.cache_this_session(cache_None=False)
    def get_offset_pid(self):
        """
        struct task_struct {
            ...
            pid_t pid; // int
            pid_t tgid; // int
            ...
        };

        0xc6d1e888:     0xc6d1f048      0xc6d1c1c8      0x0000008c      0xc6d1e894
        0xc6d1e898:     0xc6d1e894      0xc6d1e89c      0xc6d1e89c      0xc6d1e8a4
        0xc6d1e8a8:     0x00000000      0x00000000      0xc7830660      0xc7830660
        0xc6d1e8b8:     0x00000008      0x00000000      0xc6d51300      0x00000000
        0xc6d1e8c8:     0x00000000      0xc6d514e0      0x00000017      0x000000a9
        0xc6d1e8d8:     0x00000005      0x00000000      0x00000000      0x00000000
        0xc6d1e8e8:     0x00000000      0x00000011      0x00000000      0x00000000
        0xc6d1e8f8:     0x00000000      0x00000000      0x00000000      0x00000000
        0xc6d1e908:     0xc245a8d0      0x00000000      0x00000000      0x00000000
        0xc6d1e918:     0x00000000      0x00000000      0x00000000      0x00000000
        0xc6d1e928:     0x00000031*     0x00000031      0xc7834000      0xc7834000
        """
        task_addrs = self.task_addrs_temp

        # fast path
        try:
            return to_unsigned_long(gdb.parse_and_eval("&((struct task_struct*)0).pid"))
        except gdb.error:
            pass

        # slow path
        pid_max = 0x400000 if is_64bit() else 0x8000
        for i in range(0x400):
            found = False
            seen_pid = []
            # swapper/0 has pid 0. Don't use it as it will cause false positives.
            for j, task in enumerate(task_addrs[1:]):
                v1 = read_int32_from_memory(task + (i + 0) * 4)
                v2 = read_int32_from_memory(task + (i + 1) * 4)
                if j == 0 and v1 != 1: # init process has always 1
                    break
                if v1 == 0 or pid_max < v1: # pid is 1 ~ pid_max
                    break
                if v2 == 0 or pid_max < v2: # tgid is 1 ~ pid_max
                    break
                if v1 in seen_pid:
                    break
                seen_pid.append(v1)
            else:
                found = True

            if found is False:
                continue

            offset_pid = i * 4
            return offset_pid
        return None

    @Cache.cache_this_session(cache_None=False)
    def get_offset_canary(self, offset_pid):
        """
        struct task_struct {
            ...
            pid_t pid;
            pid_t tgid;
        #ifdef CONFIG_STACKPROTECTOR
            unsigned long stack_canary;
        #endif
            struct task_struct __rcu *real_parent;
            struct task_struct __rcu *parent;
            ...
        };
        """
        task_addrs = self.task_addrs_temp

        # fast path
        try:
            return to_unsigned_long(gdb.parse_and_eval("&((struct task_struct*)0).stack_canary"))
        except gdb.error:
            try:
                # task_struct exists but has no stack_canary member
                gdb.parse_and_eval("(struct task_struct*)0")
                return None
            except gdb.error:
                pass

        # slow path
        kversion = Kernel.kernel_version()
        if kversion is None:
            return None
        offset_stack_canary = align_to_ptrsize(offset_pid + 4 + 4)
        found = True
        for task in task_addrs:
            v1 = read_int_from_memory(task + offset_stack_canary)
            v2 = read_int_from_memory(task + offset_stack_canary + current_arch.ptrsize)

            if v1 == v2: # stack canary != real_parent
                found = False
                break

            if kversion and "4.13" <= kversion:
                if is_64bit() and (v1 & 0xff) != 0: # 32-bit canary does not have 0xXXXXXX00
                    found = False
                    break

        if found:
            return offset_stack_canary
        return None

    @Cache.cache_this_session(cache_None=False)
    def get_offset_group_leader(self, offset_pid, offset_kcanary):
        """
        struct task_struct {
            ...
            pid_t pid;
            pid_t tgid;
        #ifdef CONFIG_STACKPROTECTOR
            unsigned long stack_canary;
        #endif
            struct task_struct __rcu *real_parent;
            struct task_struct __rcu *parent;
            struct list_head children;
            struct list_head sibling;
            struct task_struct *group_leader;
            ...
        };
        """
        # fast path
        try:
            return to_unsigned_long(gdb.parse_and_eval("&((struct task_struct*)0).group_leader"))
        except gdb.error:
            pass

        # slow path
        if offset_kcanary is None:
            offset_real_parent = align_to_ptrsize(offset_pid + 4 + 4)
        else:
            offset_real_parent = offset_kcanary + current_arch.ptrsize
        offset_group_leader = offset_real_parent + current_arch.ptrsize * (1 + 1 + 2 + 2)
        return offset_group_leader

    @Cache.cache_this_session(cache_None=False)
    def get_offset_thread_group(self, offset_group_leader):
        """
        struct task_struct {
            ...
            struct task_struct *group_leader;
            struct list_head ptraced;
            struct list_head ptrace_entry;
            struct pid *thread_pid;           // v4.19~
            struct hlist_node pid_links[4];   // v4.19~
            struct pid_link pids[3];          // ~v4.18
            struct list_head thread_group;
            ...
        };
        """
        # fast path
        try:
            return to_unsigned_long(gdb.parse_and_eval("&((struct task_struct*)0).thread_group"))
        except gdb.error:
            pass

        # slow path
        kversion = Kernel.kernel_version()
        if kversion is None:
            return None
        if "4.19" <= kversion:
            offset_thread_group = offset_group_leader + current_arch.ptrsize * (1 + 2 + 2 + 1 + (2 * 4))
        else:
            offset_thread_group = offset_group_leader + current_arch.ptrsize * (1 + 2 + 2 + (3 * 3))
        return offset_thread_group

