            if w <= 0:
                raise ValueError("w must be positive")
            if not isinstance(x, (bytes, bytearray, memoryview)):
                raise TypeError("x must be bytes-like")
            x = bytes(x)

            z = bytearray()
            z.extend(self.left_encode(w))
            z.extend(x)
            while (len(z) % w) != 0:
                z.append(0x00)
            return bytes(z)

