    class BBLAKEBase:
        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.ensure_tables()
            self.left = self.create_left()
            self.right = self.create_right()
            self.buf = bytearray()
            self.msg_len = 0
            self.block_index = 0
            self.finalized = False
            self.final_digest = None
            if data:
                self.update(data)
            return

        @classmethod
        def ensure_tables(cls):
            return

        def create_core(self):
            return getattr(Hash, self.core_name)()

        def copy_core(self, h):
            other = h.__class__()
            other.h = h.h[:]
            other.buf = h.buf
            other.total = h.total
            other.processed = h.processed
            return other

        def create_left(self):
            h = self.create_core()
            if hasattr(self.__class__, "left_iv"):
                h.h = list(self.__class__.left_iv)
            if hasattr(self.__class__, "left_prefix"):
                h.update(self.__class__.left_prefix)
            return h

        def create_right(self):
            h = self.create_core()
            if hasattr(self.__class__, "right_iv"):
                h.h = list(self.__class__.right_iv)
            if hasattr(self.__class__, "right_prefix"):
                h.update(self.__class__.right_prefix)
            return h

        def copy(self):
            other = self.__class__()
            other.left = self.copy_core(self.left)
            other.right = self.copy_core(self.right)
            other.buf = bytearray(self.buf)
            other.msg_len = self.msg_len
            other.block_index = self.block_index
            other.finalized = self.finalized
            other.final_digest = None if self.final_digest is None else bytes(self.final_digest)
            return other

        def update(self, data):
            if self.finalized:
                raise ValueError("hash object already finalized")
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            if not data:
                return self

            self.msg_len += len(data)
            self.buf.extend(data)

            bs = self.branch_block_size
            left = self.left
            right = self.right
            block_index = self.block_index
            buf = self.buf

            while len(buf) >= bs:
                block = bytes(buf[:bs])
                del buf[:bs]
                if block_index & 1:
                    right.update(block)
                else:
                    left.update(block)
                block_index += 1

            self.block_index = block_index
            return self

        def finalize(self):
            if self.finalized:
                return

            if self.buf:
                if self.block_index & 1:
                    self.right.update(bytes(self.buf))
                else:
                    self.left.update(bytes(self.buf))
                self.buf.clear()

            h = self.create_core()
            h.update(self.left.digest())
            h.update(self.right.digest())
            self.final_digest = h.digest()
            self.finalized = True
            return

        def digest(self):
            if self.finalized:
                return bytes(self.final_digest)
            c = self.copy()
            c.finalize()
            return bytes(c.final_digest)

        def hexdigest(self):
            return self.digest().hex()

    class BBLAKE256(BBLAKEBase):
        block_size = 64
        digest_size = 32
        branch_block_size = 64
        core_name = "BLAKE256"
        left_prefix = b"\x00" * 64
        right_prefix = b"\x01" + b"\x00" * 63

    class BBLAKE512(BBLAKEBase):
        block_size = 128
        digest_size = 64
        branch_block_size = 128
        core_name = "BLAKE512"

        @classmethod
        def ensure_tables(cls):
            if hasattr(Hash.BBLAKE512, "left_iv"):
                return
            left_digest = Hash.BLAKE512(b"\x00").digest()
            right_digest = Hash.BLAKE512(b"\x01").digest()
            Hash.BBLAKE512.left_iv = tuple(int.from_bytes(left_digest[i:i + 8], "big") for i in range(0, 64, 8))
            Hash.BBLAKE512.right_iv = tuple(int.from_bytes(right_digest[i:i + 8], "big") for i in range(0, 64, 8))
            return

    class BLAKE2pBase:
        block_size = 512

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.digest_size = self.digest_bits // 8
            self.buf = bytearray()
            self.msg_len = 0
            self.block_index = 0
            self.finalized = False
            self.final_digest = None
            self.leaves = [self.create_leaf(i) for i in range(self.parallelism)]
            if data:
                self.update(data)
            return

        def create_leaf(self, node_offset):
            return self.blake2_func(
                digest_size=self.digest_size,
                fanout=self.parallelism,
                depth=2,
                leaf_size=0,
                node_offset=node_offset,
                node_depth=0,
                inner_size=self.inner_size,
                last_node=(node_offset == self.parallelism - 1),
            )

        def create_root(self):
            return self.blake2_func(
                digest_size=self.digest_size,
                fanout=self.parallelism,
                depth=2,
                leaf_size=0,
                node_offset=0,
                node_depth=1,
                inner_size=self.inner_size,
                last_node=True,
            )

        def copy(self):
            other = self.__class__()
            other.buf = bytearray(self.buf)
            other.msg_len = self.msg_len
            other.block_index = self.block_index
            other.finalized = self.finalized
            other.final_digest = None if self.final_digest is None else bytes(self.final_digest)
            other.leaves = [h.copy() for h in self.leaves]
            return other

        def update(self, data):
            if self.finalized:
                raise ValueError("hash object already finalized")
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.msg_len += len(data)
            self.buf.extend(data)

            bs = self.leaf_block_size
            while len(self.buf) >= bs:
                block = bytes(self.buf[:bs])
                del self.buf[:bs]
                lane = self.block_index % self.parallelism
                self.leaves[lane].update(block)
                self.block_index += 0x01
            return self

        def finalize(self):
            if self.finalized:
                return
            if self.buf:
                lane = self.block_index % self.parallelism
                self.leaves[lane].update(bytes(self.buf))
                self.buf.clear()

            root = self.create_root()
            for h in self.leaves:
                root.update(h.digest())

            self.final_digest = root.digest()
            self.finalized = True
            return

        def digest(self):
            if self.finalized:
                return bytes(self.final_digest)
            c = self.copy()
            c.finalize()
            return bytes(c.final_digest)

        def hexdigest(self):
            return self.digest().hex()

