        @classmethod
        def ensure_table(cls):
            if hasattr(Hash.GroestlBase, "mul2"):
                return

            def gf_mul(a, b):
                res = 0
                for _ in range(8):
                    if b & 1:
                        res ^= a
                    hi = a & 0x80
                    a = (a << 1) & 0xff
                    if hi:
                        a ^= 0x1b
                    b >>= 1
                return res

            m2, m3, m4, m5, m7 = [], [], [], [], []
            for i in range(256):
                m2.append(gf_mul(i, 2))
                m3.append(gf_mul(i, 3))
                m4.append(gf_mul(i, 4))
                m5.append(gf_mul(i, 5))
                m7.append(gf_mul(i, 7))

            Hash.GroestlBase.mul2 = tuple(m2)
            Hash.GroestlBase.mul3 = tuple(m3)
            Hash.GroestlBase.mul4 = tuple(m4)
            Hash.GroestlBase.mul5 = tuple(m5)
            Hash.GroestlBase.mul7 = tuple(m7)
            return

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.digest_size = self.digest_bits // 8
            self.buf = bytearray()
            self.msg_len = 0
            self.ensure_table()
            self.h = self.init_state()
            if data:
                self.update(data)
            return

        def init_state(self):
            iv = bytearray(self.block_size)
            size = self.digest_size * 8
            p = len(iv) - 1
            while size > 0:
                iv[p] = size & 0xff
                size >>= 8
                p -= 1
            return self.bytes_to_state(bytes(iv))

        def copy(self):
            other = self.__class__()
            other.buf = bytearray(self.buf)
            other.msg_len = self.msg_len
            other.h = [row[:] for row in self.h]
            return other

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.msg_len += len(data)
            self.buf.extend(data)
            while len(self.buf) >= self.block_size:
                block = bytes(self.buf[:self.block_size])
                del self.buf[:self.block_size]
                self.compress(block)
            return self

        def digest(self):
            c = self.copy()
            c.finalize()
            return c.output()

        def hexdigest(self):
            return self.digest().hex()

        def finalize(self):
            bs = self.block_size
            ml = self.msg_len
            zeros_pad = (-(ml + 1 + 8)) % bs
            total_blocks = (ml + 1 + zeros_pad + 8) // bs
            self.buf.append(0x80)
            self.buf.extend(b"\x00" * zeros_pad)
            self.buf.extend(struct.pack(">Q", total_blocks))
            while len(self.buf) >= bs:
                block = bytes(self.buf[:bs])
                del self.buf[:bs]
                self.compress(block)
            return

        def output(self):
            hp = self.permutation([row[:] for row in self.h], "P")
            res = self.xor_state(hp, self.h)
            out = self.state_to_bytes(res)
            return out[-self.digest_size:]

        def compress(self, block):
            m = self.bytes_to_state(block)
            pside = self.permutation(self.xor_state(self.h, m), "P")
            qside = self.permutation([row[:] for row in m], "Q")
            self.h = self.xor_state(self.xor_state(pside, qside), self.h)
            return

        def permutation(self, state, which):
            for rnd in range(self.rounds):
                self.add_round_constant(state, which, rnd)
                self.sub_bytes(state)
                self.shift_bytes(state, which)
                self.mix_bytes(state)
            return state

        def add_round_constant(self, state, which, rnd):
            cols = self.block_size // 8
            if which == "P":
                for c in range(cols):
                    state[0][c] ^= ((c << 4) ^ rnd) & 0xff
            else:
                for r in range(8):
                    for c in range(cols):
                        if r == 7:
                            state[r][c] ^= (((0xff - ((c << 4) & 0xff)) & 0xff) ^ rnd) & 0xff
                        else:
                            state[r][c] ^= 0xff
            return

        def sub_bytes(self, state):
            s = self.sbox
            for r in range(8):
                state[r] = [s[x] for x in state[r]]
            return

        def shift_bytes(self, state, which):
            cols = self.block_size // 8
            sigma = self.sigma_p if which == "P" else self.sigma_q
            for r in range(8):
                sh = sigma[r] % cols
                if sh:
                    row = state[r]
                    state[r] = row[sh:] + row[:sh]
            return

        def mix_bytes(self, state):
            cols = self.block_size // 8
            m2, m3, m4, m5, m7 = self.mul2, self.mul3, self.mul4, self.mul5, self.mul7
            for c in range(cols):
                s0, s1, s2, s3, s4, s5, s6, s7 = (state[r][c] for r in range(8))
                state[0][c] = m2[s0] ^ m2[s1] ^ m3[s2] ^ m4[s3] ^ m5[s4] ^ m3[s5] ^ m5[s6] ^ m7[s7]
                state[1][c] = m7[s0] ^ m2[s1] ^ m2[s2] ^ m3[s3] ^ m4[s4] ^ m5[s5] ^ m3[s6] ^ m5[s7]
                state[2][c] = m5[s0] ^ m7[s1] ^ m2[s2] ^ m2[s3] ^ m3[s4] ^ m4[s5] ^ m5[s6] ^ m3[s7]
                state[3][c] = m3[s0] ^ m5[s1] ^ m7[s2] ^ m2[s3] ^ m2[s4] ^ m3[s5] ^ m4[s6] ^ m5[s7]
                state[4][c] = m5[s0] ^ m3[s1] ^ m5[s2] ^ m7[s3] ^ m2[s4] ^ m2[s5] ^ m3[s6] ^ m4[s7]
                state[5][c] = m4[s0] ^ m5[s1] ^ m3[s2] ^ m5[s3] ^ m7[s4] ^ m2[s5] ^ m2[s6] ^ m3[s7]
                state[6][c] = m3[s0] ^ m4[s1] ^ m5[s2] ^ m3[s3] ^ m5[s4] ^ m7[s5] ^ m2[s6] ^ m2[s7]
                state[7][c] = m2[s0] ^ m3[s1] ^ m4[s2] ^ m5[s3] ^ m3[s4] ^ m5[s5] ^ m7[s6] ^ m2[s7]
            return

        def bytes_to_state(self, block):
            cols = self.block_size // 8
            return [[block[c * 8 + r] for c in range(cols)] for r in range(8)]

        def state_to_bytes(self, state):
            cols = self.block_size // 8
            out = bytearray(self.block_size)
            for r in range(8):
                row = state[r]
                for c in range(cols):
                    out[c * 8 + r] = row[c]
            return bytes(out)

        def xor_state(self, a, b):
            return [[x ^ y for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]

