    class ShabalBase:
        block_size = 64
        shabal_block_words = 16
        shabal_param_r = 12
        shabal_param_p = 3
        shabal_param_e = 3
        o1 = 13
        o2 = 9
        o3 = 6

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.a = [0] * self.shabal_param_r
            self.b = [0] * self.shabal_block_words
            self.c = [0] * self.shabal_block_words
            self.wlow = 0xffff_ffff
            self.whigh = 0xffff_ffff
            self.buf = bytearray()
            self.msg_len = 0
            self.init_state()
            if data:
                self.update(data)
            return

        def copy(self):
            other = self.__class__()
            other.a = self.a[:]
            other.b = self.b[:]
            other.c = self.c[:]
            other.wlow = self.wlow
            other.whigh = self.whigh
            other.buf = bytearray(self.buf)
            other.msg_len = self.msg_len
            return other

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.msg_len += len(data)
            self.buf.extend(data)
            while len(self.buf) >= self.block_size:
                block = bytes(self.buf[:self.block_size])
                del self.buf[:self.block_size]
                self.process_block(block)
            return self

        def digest(self):
            c = self.copy()
            c.finalize()
            words = c.digest_size * 8 // 32
            start = self.shabal_block_words - words
            out = bytearray()
            for i in range(start, self.shabal_block_words):
                out.extend(struct.pack("<I", c.b[i] & 0xffff_ffff))
            return bytes(out)

        def hexdigest(self):
            return self.digest().hex()

        def finalize(self):
            while len(self.buf) >= self.block_size:
                block = bytes(self.buf[:self.block_size])
                del self.buf[:self.block_size]
                self.process_block(block)

            self.buf.append(0x80)
            while len(self.buf) < self.block_size:
                self.buf.append(0x00)

            m = self.decode_block(bytes(self.buf[:self.block_size]))
            self.buf = bytearray()

            self.input_block_add(m)
            self.xor_counter()
            self.apply_perm(m)

            for _ in range(self.shabal_param_e):
                self.swap_bc()
                self.xor_counter()
                self.apply_perm(m)
            return

        def init_state(self):
            digest_bits = self.digest_size * 8
            m = [0] * self.shabal_block_words
            for j in range(0, 2 * self.shabal_block_words, self.shabal_block_words):
                for i in range(self.shabal_block_words):
                    m[i] = digest_bits + j + i
                self.input_block_add(m)
                self.xor_counter()
                self.apply_perm(m)
                self.input_block_sub(m)
                self.swap_bc()
                self.incr_counter()
            return

        def swap_bc(self):
            self.b, self.c = self.c, self.b
            return

        def decode_block(self, block):
            if len(block) != self.block_size:
                raise ValueError("block must be 64 bytes")
            return list(struct.unpack("<16I", block))

        def input_block_add(self, m):
            for i in range(self.shabal_block_words):
                self.b[i] = (self.b[i] + m[i]) & 0xffff_ffff
            return

        def input_block_sub(self, m):
            for i in range(self.shabal_block_words):
                self.c[i] = (self.c[i] - m[i]) & 0xffff_ffff
            return

        def xor_counter(self):
            self.a[0] ^= self.wlow
            self.a[1] ^= self.whigh
            return

        def incr_counter(self):
            self.wlow = (self.wlow + 1) & 0xffff_ffff
            if self.wlow == 0:
                self.whigh = (self.whigh + 1) & 0xffff_ffff
            return

        def apply_perm(self, m):

            def rol32(x, n):
                x &= 0xffff_ffff
                return ((x << n) | (x >> (32 - n))) & 0xffff_ffff

            for i in range(self.shabal_block_words):
                t = self.b[i]
                self.b[i] = ((t << 17) | (t >> 15)) & 0xffff_ffff

            for j in range(self.shabal_param_p):
                for i in range(self.shabal_block_words):
                    idx_a = (i + self.shabal_block_words * j) % self.shabal_param_r
                    idx_am1 = (i + self.shabal_block_words * j + (self.shabal_param_r - 1)) % self.shabal_param_r

                    xa = self.a[idx_a]
                    xam1 = self.a[idx_am1]

                    rot15 = ((xam1 << 15) | (xam1 >> 17)) & 0xffff_ffff
                    v = (5 * rot15) & 0xffff_ffff
                    u_in = xa ^ v ^ self.c[(8 + self.shabal_block_words - i) % self.shabal_block_words]
                    u = (3 * u_in) & 0xffff_ffff

                    x_new = u ^ self.b[(i + self.o1) % self.shabal_block_words]
                    x_new ^= self.b[(i + self.o2) % self.shabal_block_words] & \
                            (~self.b[(i + self.o3) % self.shabal_block_words]) & 0xffff_ffff
                    self.a[idx_a] = x_new ^ m[i]

                    tb = self.b[i]
                    self.b[i] = (rol32(tb, 1) ^ ((~self.a[idx_a]) & 0xffff_ffff)) & 0xffff_ffff

            for j in range(3 * self.shabal_param_r):
                idx_a = (3 * self.shabal_param_r - 1 - j) % self.shabal_param_r
                idx_c = (3 * self.shabal_param_r * self.shabal_block_words + 6 - j) % self.shabal_block_words
                self.a[idx_a] = (self.a[idx_a] + self.c[idx_c]) & 0xffff_ffff
            return

        def process_block(self, block):
            m = self.decode_block(block)
            self.input_block_add(m)
            self.xor_counter()
            self.apply_perm(m)
            self.input_block_sub(m)
            self.swap_bc()
            self.incr_counter()
            return

