            tl = len(tail)
            if tl == 3:
                h = (h + (tail[2] << 16)) & 0xffff_ffff
                h = (h + (tail[1] << 8)) & 0xffff_ffff
                h = (h + tail[0]) & 0xffff_ffff
                h = (h * m) & 0xffff_ffff
                h ^= (h >> r)
                h &= 0xffff_ffff
            elif tl == 2:
                h = (h + (tail[1] << 8)) & 0xffff_ffff
                h = (h + tail[0]) & 0xffff_ffff
                h = (h * m) & 0xffff_ffff
                h ^= (h >> r)
                h &= 0xffff_ffff
            elif tl == 1:
                h = (h + tail[0]) & 0xffff_ffff
                h = (h * m) & 0xffff_ffff
                h ^= (h >> r)
                h &= 0xffff_ffff
            else:
                pass

            h = (h * m) & 0xffff_ffff
            h ^= (h >> 10)
