    class FORK256:
        block_size = 64   # 512 bits
        digest_size = 32  # 256 bits

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            # IV0 (same as SHA-256 IV)
            self.h0 = 0x6a09_e667
            self.h1 = 0xbb67_ae85
            self.h2 = 0x3c6e_f372
            self.h3 = 0xa54f_f53a
            self.h4 = 0x510e_527f
            self.h5 = 0x9b05_688c
            self.h6 = 0x1f83_d9ab
            self.h7 = 0x5be0_cd19

            self.buf = bytearray()
            self.msg_len = 0  # in bytes

            if data:
                self.update(data)
            return

        def copy(self):
            other = self.__class__()
            other.h0 = self.h0
            other.h1 = self.h1
            other.h2 = self.h2
            other.h3 = self.h3
            other.h4 = self.h4
            other.h5 = self.h5
            other.h6 = self.h6
            other.h7 = self.h7
            other.buf = bytearray(self.buf)
            other.msg_len = self.msg_len
            return other

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.msg_len += len(data)
            self.buf.extend(data)

            while len(self.buf) >= 64:
                block = bytes(self.buf[:64])
                del self.buf[:64]
                self.compress(block)
            return self

        def digest(self):
            c = self.copy()
            c.finalize()
            return struct.pack(">8I", c.h0, c.h1, c.h2, c.h3, c.h4, c.h5, c.h6, c.h7)

        def hexdigest(self):
            return self.digest().hex()

        def finalize(self):
            bit_len = self.msg_len * 8

            self.buf.append(0x80)
            while (len(self.buf) % 64) != 56:
                self.buf.append(0x00)
            self.buf.extend(struct.pack(">Q", bit_len))

            while len(self.buf) >= 64:
                block = bytes(self.buf[:64])
                del self.buf[:64]
                self.compress(block)
