            t34 = add_words(outs[2], outs[3])
            mixed = xor_words(t12, t34)
            new_cv = add_words(cv, mixed)

            self.h0, self.h1, self.h2, self.h3, self.h4, self.h5, self.h6, self.h7 = new_cv
            return

