        def farmhash32_len13to24(self, data, seed):
            n = len(data)
            seed &= 0xffff_ffff
            a = self.u32le(data, (n >> 1) - 4)
            b = self.u32le(data, 4)
            c = self.u32le(data, n - 8)
            d = self.u32le(data, n >> 1)
            e = self.u32le(data, 0)
            f = self.u32le(data, n - 4)
            h = (d * self.c1 + n + seed) & 0xffff_ffff
