            h = (self.cityhash32_mur(c, h) + a) & 0xffff_ffff
            a = (self.ror32(a, 3) + c) & 0xffff_ffff
            h = (self.cityhash32_mur(e, h) + a) & 0xffff_ffff
            a = (self.ror32((a + f) & 0xffff_ffff, 12) + d) & 0xffff_ffff
            h = (self.cityhash32_mur(b ^ seed, h) + a) & 0xffff_ffff
