    class DEKHash:
        digest_size = 4

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.buf = bytearray()
            if data:
                self.update(data)
            return

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.buf += data
            return self

        def digest(self):
            h = len(self.buf)
            for c in self.buf:
                h = ((h << 5) ^ (h >> 27) ^ c) & 0xffff_ffff
            return h.to_bytes(4, "big")

        def hexdigest(self):
            return self.digest().hex()

    class APHash:
        digest_size = 4

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.hash = 0xaaaa_aaaa
            if data:
                self.update(data)
            return

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            for i, c in enumerate(bytes(data)):
                if (i & 1) == 0:
                    self.hash ^= (self.hash << 7) ^ (c * (self.hash >> 3))
                else:
                    self.hash ^= ~((self.hash << 11) + (c ^ (self.hash >> 5)))
                self.hash &= 0xffff_ffff
            return self

        def digest(self):
            return self.hash.to_bytes(4, "big")

        def hexdigest(self):
            return self.digest().hex()

    class JOAAT:  # Jenkins One-At-A-Time
        digest_size = 4

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.hash = 0
            if data:
                self.update(data)
            return

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            for c in bytes(data):
                self.hash = (self.hash + c) & 0xffff_ffff
                self.hash = (self.hash + (self.hash << 10)) & 0xffff_ffff
                self.hash = (self.hash ^ (self.hash >> 6)) & 0xffff_ffff
            return self

        def digest(self):
            h = self.hash
            h = (h + (h << 3)) & 0xffff_ffff
            h = (h ^ (h >> 11)) & 0xffff_ffff
            h = (h + (h << 15)) & 0xffff_ffff
            return h.to_bytes(4, "big")

        def hexdigest(self):
            return self.digest().hex()

    class Adler:
        digest_size = 4

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.a = 1
            self.b = 0
            if data:
                self.update(data)
            return

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            for d in data:
                self.a = (self.a + d) % 65521
                self.b = (self.a + self.b) % 65521
            return

        def digest(self):
            h = (self.b << 16) + self.a
            return h.to_bytes(4, "big")

        def hexdigest(self):
            return self.digest().hex()

