            self.count0 = (self.count0 + (ptr << 3)) & 0xffff_ffff
            count0 = self.count0
            count1 = self.count1
            count2 = self.count2
            count3 = self.count3
            if ptr == 0:
                buf[0] = 0x80
                for i in range(1, 110):
                    buf[i] = 0
