        def __init__(self, n=64, data=b""):
            if not isinstance(n, int) or n <= 0:
                raise ValueError("n must be a positive int")
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.n = n
            self.block_size = n
            self.bshiftn = n % 32
            self.buf = bytearray(n)
            self.state = 0
            self.bufpos = 0
            self.overflow = False
            if data:
                self.update(data)
            return

        def update_byte(self, data):

            def rol32(x, n):
                x &= 0xffff_ffff
                n &= 31
                if n == 0:
                    return x
                return ((x << n) | (x >> (32 - n))) & 0xffff_ffff

            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            if len(data) != 1:
                raise ValueError("data must be exactly 1 byte")
            b = data[0]

            if self.bufpos == self.n:
                self.overflow = True
                self.bufpos = 0

            state = self.state
            state = rol32(state, 1)

            if self.overflow:
                toshift = self.bytehash[self.buf[self.bufpos]]
                state ^= rol32(toshift, self.bshiftn)

            self.buf[self.bufpos] = b
            self.bufpos += 1

            state ^= self.bytehash[b]
            self.state = state
            return state

