        def rol(self, x, n):
            x &= self.mask
            if n == 0:
                return x
            return ((x << n) | (x >> (self.word_bits - n))) & self.mask

        def make_step_constants(self):
            if self.word_bits == 32:
                sc0 = self.sc0_32
            else:
                sc0 = self.sc0_64

            sc = [list(sc0)]
            for j in range(1, self.ns):
                prev = sc[j - 1]
                sc.append([(prev[l] + self.rol(prev[l], 8)) & self.mask for l in range(8)])  # noqa: E741
            return sc

        def compress(self, block):

            def msg_add(x, y):
                return [x[i] ^ y[i] for i in range(16)]

            def alpha_beta(j):
                if self.word_bits == 32:
                    if (j & 1) == 0:
                        return 0x1d, 0x01
                    return 0x05, 0x11
                if (j & 1) == 0:
                    return 0x17, 0x3b
                return 0x07, 0x03

            def gamma(l):  # noqa: E741
                if self.word_bits == 32:
                    return self.gamma32[l]
                return self.gamma64[l]

            def mix_pair(j, l, x, y):  # noqa: E741
                alpha, beta = alpha_beta(j)
                g = gamma(l)

                x = (x + y) & self.mask
                x = self.rol(x, alpha)
                x ^= self.sc[j][l]

                y = (x + y) & self.mask
                y = self.rol(y, beta)

                x = (x + y) & self.mask
                y = self.rol(y, g)
                return x, y

            def mix(j, t):
                t = list(t)
                for l in range(8):  # noqa: E741
                    x, y = mix_pair(j, l, t[l], t[l + 8])
                    t[l] = x
                    t[l + 8] = y
                return t

            def word_perm(x):
                return [x[self.sigma[i]] for i in range(16)]

            def step(j, t, mj):
                t = msg_add(t, mj)
                t = mix(j, t)
                t = word_perm(t)
                return t

            def msg_expand(m32):
                sub = [m32[:16], m32[16:32]]
                for j in range(2, self.ns + 1):
                    prev1 = sub[j - 1]
                    prev2 = sub[j - 2]
                    sub.append([(prev1[l] + prev2[self.tau[l]]) & self.mask for l in range(16)])  # noqa: E741
                return sub

            if self.word_bits == 32:
                fmt = "<32I"
            else:
                fmt = "<32Q"
            m = list(struct.unpack(fmt, block))

            sub = msg_expand(m)
            t = list(self.cv)
            for j in range(self.ns):
                t = step(j, t, sub[j])
            self.cv = msg_add(t, sub[self.ns])
            return

