                S[2] ^= S[24]
                S[25] ^= S[18]
                S[21] ^= S[25]
                S[22] ^= S[26]
                S[23] ^= S[27]
                S[6] ^= S[25]
                S[7] ^= S[26]
                S[8] ^= S[27]
                self.smix(21, 22, 23, 24)
                S[18] ^= S[22]
                S[19] ^= S[23]
                S[20] ^= S[24]
                S[3] ^= S[22]
                S[4] ^= S[23]
                S[5] ^= S[24]
                self.smix(18, 19, 20, 21)
