                S[19] ^= S[12]
                S[15] ^= S[19]
                S[16] ^= S[20]
                S[17] ^= S[21]
                S[0] ^= S[19]
                S[1] ^= S[20]
                S[2] ^= S[21]
                self.smix(15, 16, 17, 18)
                S[12] ^= S[16]
                S[13] ^= S[17]
                S[14] ^= S[18]
                S[27] ^= S[16]
                S[28] ^= S[17]
                S[29] ^= S[18]
