    class LuffaBase:
        block_size = 32
        # Appendix A: Starting Variables
        V = (
            (0x6d25_1e69, 0x44b0_51e0, 0x4eaa_6fb4, 0xdbf7_8465, 0x6e29_2011, 0x9015_2df4, 0xee05_8139, 0xdef6_10bb),
            (0xc3b4_4b95, 0xd9d2_f256, 0x70ee_e9a0, 0xde09_9fa3, 0x5d9b_0557, 0x8fc9_44b3, 0xcf1c_cf0e, 0x746c_d581),
            (0xf7ef_c89d, 0x5dba_5781, 0x0401_6ce5, 0xad65_9c05, 0x0306_194f, 0x666d_1836, 0x24aa_230a, 0x8b26_4ae7),
            (0x8580_75d5, 0x36d7_9cce, 0xe571_f7d7, 0x204b_1f67, 0x3587_0c6a, 0x57e9_e923, 0x14bc_b808, 0x7cde_72ce),
            (0x6c68_e9be, 0x5ec4_1e22, 0xc825_b7c7, 0xaffb_4363, 0xf5df_3999, 0x0fc6_88f1, 0xb072_24cc, 0x03e8_6cea),
        )
        # Appendix B-1: Constant generator initial values (c^(0)_{j,L}, c^(0)_{j,R})
        C_INIT = (
            (0x181c_ca53, 0x380c_de06),
            (0x5b6f_0876, 0xf16f_8594),
            (0x7e10_6ce9, 0x3897_9cb0),
            (0xbb62_f364, 0x92e9_3c29),
            (0x9a02_5047, 0xcff2_a940),
        )
        # Section 3.2.1: Message Injection matrices (coefficients in GF(2^8))
        MI_MAT = {
            0x03: (
                (0x03, 0x02, 0x02, 0x01),
                (0x02, 0x03, 0x02, 0x02),
                (0x02, 0x02, 0x03, 0x04),
            ),
            0x04: (
                (0x04, 0x06, 0x06, 0x07, 0x01),
                (0x07, 0x04, 0x06, 0x06, 0x02),
                (0x06, 0x07, 0x04, 0x06, 0x04),
                (0x06, 0x06, 0x07, 0x04, 0x08),
            ),
            0x05: (
                (0x0f, 0x08, 0x0a, 0x0a, 0x08, 0x01),
                (0x08, 0x0f, 0x08, 0x0a, 0x0a, 0x02),
                (0x0a, 0x08, 0x0f, 0x08, 0x0a, 0x04),
                (0x0a, 0x0a, 0x08, 0x0f, 0x08, 0x08),
                (0x08, 0x0a, 0x0a, 0x08, 0x0f, 0x10),
            ),
        }
        C_TEMPLATE = r"""
        #include <stdint.h>

        static uint32_t rol32(uint32_t x, int n)
        {
            return ((x << n) | (x >> (32 - n))) & 0xffffffffU;
        }

        static void scalar_mul(const uint32_t *vec, unsigned int coeff, uint32_t *out)
        {
            uint32_t tmp[8];
            uint32_t res[8];
            int i, k;

            coeff &= 0xffU;
            for (k = 0; k < 8; k++) {
                tmp[k] = vec[k];
                res[k] = 0;
            }
            if (coeff == 0) {
                for (k = 0; k < 8; k++) {
                    out[k] = 0;
                }
                return;
            }
            if (coeff == 1) {
                for (k = 0; k < 8; k++) {
                    out[k] = vec[k];
                }
                return;
            }
            for (i = 0; i < 8; i++) {
                if ((coeff >> i) & 1U) {
                    for (k = 0; k < 8; k++) {
                        res[k] ^= tmp[k];
                    }
                }
                {
                    uint32_t a0 = tmp[0];
                    uint32_t a1 = tmp[1];
                    uint32_t a2 = tmp[2];
                    uint32_t a3 = tmp[3];
                    uint32_t a4 = tmp[4];
                    uint32_t a5 = tmp[5];
                    uint32_t a6 = tmp[6];
                    uint32_t a7 = tmp[7];
                    uint32_t t = a7;
                    tmp[0] = t;
                    tmp[1] = a0 ^ t;
                    tmp[2] = a1;
                    tmp[3] = a2 ^ t;
                    tmp[4] = a3 ^ t;
                    tmp[5] = a4;
                    tmp[6] = a5;
                    tmp[7] = a6;
                }
            }
            for (k = 0; k < 8; k++) {
                out[k] = res[k];
            }
        }

        static void subcrumb(uint32_t *r0, uint32_t *r1, uint32_t *r2, uint32_t *r3)
        {
            uint32_t t4 = *r0;
            *r0 |= *r1;
            *r2 ^= *r3;
            *r1 = (~(*r1)) & 0xffffffffU;
            *r0 ^= *r3;
            *r3 &= t4;
            *r1 ^= *r3;
            *r3 ^= *r2;
            *r2 &= *r0;
            *r0 = (~(*r0)) & 0xffffffffU;
            *r2 ^= *r1;
            *r1 |= *r3;
            t4 ^= *r1;
            *r3 ^= *r2;
            *r2 &= *r1;
            *r1 ^= *r0;
            *r0 = t4;
        }

        static void mixword(uint32_t *xk, uint32_t *xk4)
        {
            uint32_t yk4 = *xk4 ^ *xk;
            uint32_t yk = rol32(*xk, 2);
            yk ^= yk4;
            yk4 = rol32(yk4, 14);
            yk4 ^= yk;
            yk = rol32(yk, 10);
            yk ^= yk4;
            yk4 = rol32(yk4, 1);
            *xk = yk;
            *xk4 = yk4;
        }

        void luffa_round(uint32_t *state, const uint32_t *m, int w, const uint32_t *step_const, const uint8_t *mi_mat)
        {
            uint32_t xs[5][8];
            uint32_t term[8];
            int j, k, idx, r;
            int input_count = w + 1;

            for (j = 0; j < w; j++) {
                for (k = 0; k < 8; k++) {
                    xs[j][k] = 0;
                }
                for (idx = 0; idx < input_count; idx++) {
                    unsigned int coeff = mi_mat[j * input_count + idx];
                    const uint32_t *vec;
                    if (coeff == 0) {
                        continue;
                    }
                    if (idx < w) {
                        vec = state + (idx * 8);
                    } else {
                        vec = m;
                    }
                    if (coeff == 1) {
                        for (k = 0; k < 8; k++) {
                            xs[j][k] ^= vec[k];
                        }
                    } else {
                        scalar_mul(vec, coeff, term);
                        for (k = 0; k < 8; k++) {
                            xs[j][k] ^= term[k];
                        }
                    }
                }
            }

            for (j = 0; j < w; j++) {
                uint32_t a[8];
                for (k = 0; k < 8; k++) {
                    a[k] = xs[j][k] & 0xffffffffU;
                }
                for (k = 4; k < 8; k++) {
                    if (j != 0) {
                        a[k] = rol32(a[k], j);
                    }
                }
                for (r = 0; r < 8; r++) {
                    uint32_t t0, t1, t2, t3;

                    subcrumb(&a[0], &a[1], &a[2], &a[3]);
                    t0 = a[5];
                    t1 = a[6];
                    t2 = a[7];
                    t3 = a[4];
                    subcrumb(&t0, &t1, &t2, &t3);
                    a[5] = t0;
                    a[6] = t1;
                    a[7] = t2;
                    a[4] = t3;

                    for (k = 0; k < 4; k++) {
                        mixword(&a[k], &a[k + 4]);
                    }
                    a[0] ^= step_const[j * 16 + (r * 2) + 0];
                    a[4] ^= step_const[j * 16 + (r * 2) + 1];
                }
                for (k = 0; k < 8; k++) {
                    state[j * 8 + k] = a[k];
                }
            }
        }
        """
        DEF_TEMPLATE = r"""
        void luffa_round(uint32_t *state, const uint32_t *m, int w, const uint32_t *step_const, const uint8_t *mi_mat);
        """

        def init_cffi_backend(self):
            try:
                import cffi
                import warnings
            except ImportError:
                self.USE_CFFI = False
                return

            key = self.__class__
            base_class = Hash.LuffaBase

            if not hasattr(base_class, "cffi_cache"):
                base_class.cffi_cache = {}

            # fast return
            if key in base_class.cffi_cache:
                self.cffi = base_class.cffi_cache[key]
                self.USE_CFFI = True
                return

            # ffi, lib
            if base_class in base_class.cffi_cache:
                ffi, lib = base_class.cffi_cache[base_class]
            else:
                try:
                    with warnings.catch_warnings():
                        warnings.filterwarnings(
                            "ignore",
                            message=r"reimporting '_cffi__.*' might overwrite older definitions",
                            category=UserWarning,
                            module=r"cffi\.vengine_cpy",
                        )
                        ffi = cffi.FFI()
                        ffi.cdef(base_class.DEF_TEMPLATE)
                        lib = ffi.verify(base_class.C_TEMPLATE, extra_compile_args=["-O2"])
                    base_class.cffi_cache[base_class] = (ffi, lib)
                except Exception:
                    self.USE_CFFI = False
                    return

            # Different for each class
            try:
                step_const = ffi.new("uint32_t[]", self.step_const_flat)
                mi_mat = ffi.new("uint8_t[]", self.mi_mat_flat)
            except Exception:
                self.USE_CFFI = False
                return

            # add to cache
            cffi_obj = collections.namedtuple("CFFI", "ffi lib step_const mi_mat")(
                ffi, lib, step_const, mi_mat,
            )
            self.cffi = base_class.cffi_cache[key] = cffi_obj
            self.USE_CFFI = True
            return

        @classmethod
        def prepare_constants(cls):
            if not hasattr(cls, "step_const"):
                # Section 4.4: generates (c_{j,0}, c_{j,4}) for r=0..7 using the constant generator
                out = []
                for j in range(cls.w):
                    tl, tr = cls.C_INIT[j]
                    jconst = []
                    for _ in range(8):
                        # Section 4.4: one step of constant generator (pseudo code in the spec)
                        c = (tl >> 31) & 1
                        tl2 = ((tl << 1) | (tr >> 31)) & 0xffff_ffff
                        tr2 = (tr << 1) & 0xffff_ffff
                        if c == 1:
                            tl2 ^= 0xc4d6_496c
                            tr2 ^= 0x55c6_1c8d
                        tl, tr = tr2, tl2
                        c0 = tr

                        c = (tl >> 31) & 1
                        tl2 = ((tl << 1) | (tr >> 31)) & 0xffff_ffff
                        tr2 = (tr << 1) & 0xffff_ffff
                        if c == 1:
                            tl2 ^= 0xc4d6_496c
                            tr2 ^= 0x55c6_1c8d
                        tl, tr = tr2, tl2
                        c4 = tr
                        jconst.append((c0, c4))
                    out.append(tuple(jconst))
                cls.step_const = tuple(out)

            if not hasattr(cls, "step_const_flat"):
                step_const_flat = []
                for j in range(cls.w):
                    for r in range(8):
                        c0, c4 = cls.step_const[j][r]
                        step_const_flat.append(c0)
                        step_const_flat.append(c4)
                cls.step_const_flat = tuple(step_const_flat)

            if not hasattr(cls, "mi_mat_flat"):
                mi_mat_flat = []
                for row in cls.MI_MAT[cls.w]:
                    mi_mat_flat.extend(row)
                cls.mi_mat_flat = bytes(mi_mat_flat)
            return

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.digest_size = self.digest_bits // 8
            self.H = [list(self.V[i]) for i in range(self.w)]
            self.buf = bytearray()
            self.msg_len = 0
            self.prepare_constants()
            self.init_cffi_backend()
            if data:
                self.update(data)
            return

        def copy(self):
            other = self.__class__()
            other.H = [list(block) for block in self.H]
            other.buf = bytearray(self.buf)
            other.msg_len = self.msg_len
            return other

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            data = bytes(data)
            self.msg_len += len(data)
            self.buf.extend(data)
            while len(self.buf) >= self.block_size:
                block = bytes(self.buf[:self.block_size])
                del self.buf[:self.block_size]
                self.compress(block)
            return self

        def digest(self):
            c = self.copy()
            c.finalize()
            return c.output_digest_bytes()

        def hexdigest(self):
            return self.digest().hex()

        def finalize(self):
            # Section 3.1: append '1' bit then '0' until length is multiple of 256 bits
            self.buf.append(0x80)
            while (len(self.buf) % self.block_size) != 0:
                self.buf.append(0x00)
            while len(self.buf) >= self.block_size:
                block = bytes(self.buf[:self.block_size])
                del self.buf[:self.block_size]
                self.compress(block)
            return

        def compress(self, block):
            if not isinstance(block, (bytes, bytearray, memoryview)):
                raise TypeError("block must be bytes-like")
            block = bytes(block)
            if len(block) != self.block_size:
                raise ValueError("block must be 32 bytes")
            m = list(struct.unpack(">8I", block))
            self.round_function(m)
            return

        def output_digest_bytes(self):
            # Section 3.3: finalization (blank round + OF, then additional rounds with 0 as needed)
            zero_m = [0] * 8
            self.round_function(zero_m)
            z0 = self.output_function()
            words = []
            if self.digest_size == 0x1c:
                words.extend(z0[:7])
            elif self.digest_size == 0x20:
                words.extend(z0[:8])
            elif self.digest_size == 0x30:
                words.extend(z0[:8])
                self.round_function(zero_m)
                z1 = self.output_function()
                words.extend(z1[:4])
            elif self.digest_size == 0x40:
                words.extend(z0[:8])
                self.round_function(zero_m)
                z1 = self.output_function()
                words.extend(z1[:8])
            else:
                raise ValueError("unsupported digest size")
            out = b"".join(struct.pack(">I", w) for w in words)
            return out

        def output_function(self):
            z = [0] * 8
            for j in range(self.w):
                for k in range(8):
                    z[k] ^= self.H[j][k]
            return z

        def round_function(self, m):
            if self.USE_CFFI:
                state_flat = []
                for j in range(self.w):
                    state_flat.extend(self.H[j])
                state_buf = self.cffi.ffi.new("uint32_t[]", state_flat)
                m_buf = self.cffi.ffi.new("uint32_t[]", m)
                self.cffi.lib.luffa_round(state_buf, m_buf, self.w, self.cffi.step_const, self.cffi.mi_mat)
                for j in range(self.w):
                    base = j * 8
                    self.H[j] = [int(state_buf[base + k]) for k in range(8)]
                return

            # --- pure Python ---
            xs = self.message_injection(m)
            for j in range(self.w):
                self.H[j] = self.permute(xs[j], j)
            return

        def message_injection(self, m):
            mat = self.MI_MAT[self.w]
            inputs = [self.H[j] for j in range(self.w)] + [m]
            outs = []
            for row in mat:
                acc = [0] * 8
                for coeff, vec in zip(row, inputs):
                    if coeff == 0:
                        continue
                    if coeff == 1:
                        term = vec
                    else:
                        term = self.scalar_mul(vec, coeff)
                    for k in range(8):
                        acc[k] ^= term[k]
                outs.append(acc)
            return outs

        def scalar_mul(self, vec, coeff):
            coeff &= 0xff
            if coeff == 0:
                return [0] * 8
            if coeff == 1:
                return list(vec)
            res = [0] * 8
            tmp = list(vec)
            for i in range(8):
                if (coeff >> i) & 1:
                    for k in range(8):
                        res[k] ^= tmp[k]
                # Appendix E: multiplication by x in GF(2^8)^32 (phi(x)=x^8+x^4+x^3+x+1)
                t = tmp[7]
                tmp = [t, tmp[0] ^ t, tmp[1], tmp[2] ^ t, tmp[3] ^ t, tmp[4], tmp[5], tmp[6]]
            return res

        def permute(self, words, j):

            def rol32(x, n):
                return ((x << n) | (x >> (32 - n))) & 0xffff_ffff

            def mixword(xk, xk4):
                # Section 4.3 (sigma1=2,sigma2=14,sigma3=10,sigma4=1), rotations
                yk4 = xk4 ^ xk
                yk = rol32(xk, 2)
                yk ^= yk4
                yk4 = rol32(yk4, 14)
                yk4 ^= yk
                yk = rol32(yk, 10)
                yk ^= yk4
                yk4 = rol32(yk4, 1)
                return yk, yk4

            def subcrumb(r0, r1, r2, r3):
                # Appendix D Table 4: bit-sliced Sbox schedule
                r4 = r0
                r0 |= r1
                r2 ^= r3
                r1 = (~r1) & 0xffff_ffff
                r0 ^= r3
                r3 &= r4
                r1 ^= r3
                r3 ^= r2
                r2 &= r0
                r0 = (~r0) & 0xffff_ffff
                r2 ^= r1
                r1 |= r3
                r4 ^= r1
                r3 ^= r2
                r2 &= r1
                r1 ^= r0
                return r4, r1, r2, r3

            # Section 4.1: Permute(a, j) = Q_j
            a = [w & 0xffff_ffff for w in words]
            # Section 4.5: tweak (rotate least significant four words by j bits to the left)
            for k in range(4, 8):
                a[k] = rol32(a[k], j)
            for r in range(8):
                a[0], a[1], a[2], a[3] = subcrumb(a[0], a[1], a[2], a[3])
                # IMPORTANT: the latter four words are input to SubCrumb in different order
                a[5], a[6], a[7], a[4] = subcrumb(a[5], a[6], a[7], a[4])
                for k in range(4):
                    a[k], a[k + 4] = mixword(a[k], a[k + 4])
                c0, c4 = self.step_const[j][r]
                a[0] ^= c0
                a[4] ^= c4
            return a

    class Luffa224(LuffaBase):
        digest_bits = 224
        w = 3

    class Luffa256(LuffaBase):
        digest_bits = 256
        w = 3

    class Luffa384(LuffaBase):
        digest_bits = 384
        w = 4

    class Luffa512(LuffaBase):
        digest_bits = 512
        w = 5

    class ESCHBase:
        rcon = (
            0xb7e1_5162, 0xbf71_5880, 0x38b4_da56, 0x324e_7738, 0xbb11_85eb, 0x4f7c_7b57, 0xcfbf_a1c8, 0xc2b3_293d,
        )
        const_m0 = 0x01_00_00_00
        const_m1 = 0x02_00_00_00
        pack4 = struct.Struct("<4I")
        unpack4 = struct.Struct("<4I")

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.state = [0] * (2 * self.branches)
            self.buf = bytearray()
            self.msg_len = 0
            if data:
                self.update(data)
            return

        def copy(self):
            other = self.__class__()
            other.state = list(self.state)
            other.buf = bytearray(self.buf)
            other.msg_len = self.msg_len
            return other

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            mv = memoryview(data)
            data_len = len(mv)
            self.msg_len += data_len
            block_size = self.block_size
            off = 0
            if self.buf:
                need = block_size - len(self.buf)
                if data_len <= need:
                    self.buf.extend(mv)
                    return self
                self.buf.extend(mv[:need])
                self.absorb_block(self.buf)
                self.buf.clear()
                off = need
            limit = data_len - block_size
            while off < limit:
                self.absorb_block(mv[off:off + block_size])
                off += block_size
            if off < data_len:
                self.buf.extend(mv[off:])
            return self

        def digest(self):
            c = self.copy()
            c.finalize()
            return c.squeeze()

        def hexdigest(self):
            return self.digest().hex()

        def finalize(self):
            if len(self.buf) == self.block_size:
                last = self.buf
                const_m = self.const_m1
            else:
                self.buf.append(0x80)
                pad_len = self.block_size - len(self.buf)
                if pad_len:
                    self.buf.extend(b"\x00" * pad_len)
                last = self.buf
                const_m = self.const_m0
            self.absorb_last_block(last, const_m)
            self.buf.clear()
            return

        def squeeze(self):
            out = bytearray()
            need = self.digest_size
            pack4 = self.pack4.pack
            state = self.state
            out.extend(pack4(state[0], state[1], state[2], state[3]))
            while len(out) < need:
                self.sparkle(self.slim_steps)
                state = self.state
                out.extend(pack4(state[0], state[1], state[2], state[3]))
            return bytes(out[:need])

        def alzette(self, x, y, c):
            x = (x + ((y >> 31) | ((y << 1) & 0xffff_ffff))) & 0xffff_ffff
            y ^= ((x >> 24) | ((x << 8) & 0xffff_ffff))
            x ^= c

            x = (x + ((y >> 17) | ((y << 15) & 0xffff_ffff))) & 0xffff_ffff
            y ^= ((x >> 17) | ((x << 15) & 0xffff_ffff))
            x ^= c

            x = (x + y) & 0xffff_ffff
            y ^= ((x >> 31) | ((x << 1) & 0xffff_ffff))
            x ^= c

            x = (x + ((y >> 24) | ((y << 8) & 0xffff_ffff))) & 0xffff_ffff
            y ^= ((x >> 16) | ((x << 16) & 0xffff_ffff))
            x ^= c
            return x, y

        def inject_block_xor(self, block):
            w0, w1, w2, w3 = self.unpack4.unpack(block)
            state = self.state

            tx = w0 ^ w2
            ty = w1 ^ w3
            tx ^= (tx << 16) & 0xffff_ffff
            ty ^= (ty << 16) & 0xffff_ffff
            lx = ((tx >> 16) | ((tx << 16) & 0xffff_ffff)) & 0xffff_ffff
            ly = ((ty >> 16) | ((ty << 16) & 0xffff_ffff)) & 0xffff_ffff

            state[0] ^= w0 ^ ly
            state[1] ^= w1 ^ lx
            state[2] ^= w2 ^ ly
            state[3] ^= w3 ^ lx
            state[4] ^= ly
            state[5] ^= lx

            if self.m_w == 4:
                state[6] ^= ly
                state[7] ^= lx
            return

        def absorb_block(self, block):
            self.inject_block_xor(block)
            self.sparkle(self.slim_steps)
            return

        def absorb_last_block(self, block, const_m_word):
            self.inject_block_xor(block)
            self.state[2 * self.m_w - 1] ^= const_m_word
            self.sparkle(self.big_steps)
            return

        def sparkle_6(self, steps):
            state = self.state
            rcon = self.rcon

            for s in range(steps):
                state[1] ^= rcon[s & 7]
                state[3] ^= s

                for i in range(6):
                    state[i * 2], state[i * 2 + 1] = self.alzette(state[i * 2], state[i * 2 + 1], rcon[i])

                tx = state[0] ^ state[2] ^ state[4]
                ty = state[1] ^ state[3] ^ state[5]
                tx ^= (tx << 16) & 0xffff_ffff
                ty ^= (ty << 16) & 0xffff_ffff
                tx = ((tx >> 16) | ((tx << 16) & 0xffff_ffff)) & 0xffff_ffff
                ty = ((ty >> 16) | ((ty << 16) & 0xffff_ffff)) & 0xffff_ffff

                s0 = state[0]
                s1 = state[1]
                s2 = state[2]
                s3 = state[3]
                s4 = state[4]
                s5 = state[5]
                s6 = state[6] ^ s0 ^ ty
                s7 = state[7] ^ s1 ^ tx
                s8 = state[8] ^ s2 ^ ty
                s9 = state[9] ^ s3 ^ tx
                s10 = state[10] ^ s4 ^ ty
                s11 = state[11] ^ s5 ^ tx

                state[0] = s8
                state[1] = s9
                state[2] = s10
                state[3] = s11
                state[4] = s6
                state[5] = s7
                state[6] = s0
                state[7] = s1
                state[8] = s2
                state[9] = s3
                state[10] = s4
                state[11] = s5
            return

        def sparkle_8(self, steps):
            state = self.state
            rcon = self.rcon

            for s in range(steps):
                state[1] ^= rcon[s & 7]
                state[3] ^= s

                for i in range(8):
                    state[i * 2], state[i * 2 + 1] = self.alzette(state[i * 2], state[i * 2 + 1], rcon[i])

                tx = state[0] ^ state[2] ^ state[4] ^ state[6]
                ty = state[1] ^ state[3] ^ state[5] ^ state[7]
                tx ^= (tx << 16) & 0xffff_ffff
                ty ^= (ty << 16) & 0xffff_ffff
                tx = ((tx >> 16) | ((tx << 16) & 0xffff_ffff)) & 0xffff_ffff
                ty = ((ty >> 16) | ((ty << 16) & 0xffff_ffff)) & 0xffff_ffff

                s0 = state[0]
                s1 = state[1]
                s2 = state[2]
                s3 = state[3]
                s4 = state[4]
                s5 = state[5]
                s6 = state[6]
                s7 = state[7]
                s8 = state[8] ^ s0 ^ ty
                s9 = state[9] ^ s1 ^ tx
                s10 = state[10] ^ s2 ^ ty
                s11 = state[11] ^ s3 ^ tx
                s12 = state[12] ^ s4 ^ ty
                s13 = state[13] ^ s5 ^ tx
                s14 = state[14] ^ s6 ^ ty
                s15 = state[15] ^ s7 ^ tx

                state[0] = s10
                state[1] = s11
                state[2] = s12
                state[3] = s13
                state[4] = s14
                state[5] = s15
                state[6] = s8
                state[7] = s9
                state[8] = s0
                state[9] = s1
                state[10] = s2
                state[11] = s3
                state[12] = s4
                state[13] = s5
                state[14] = s6
                state[15] = s7
            return

        def sparkle(self, steps):
            if self.branches == 6:
                self.sparkle_6(steps)
            else:
                self.sparkle_8(steps)
            return

    class ESCH256(ESCHBase):
        block_size = 16
        digest_size = 32
        branches = 6
        slim_steps = 7
        big_steps = 11
        m_w = 3

    class ESCH384(ESCHBase):
        block_size = 16
        digest_size = 48
        branches = 8
        slim_steps = 8
        big_steps = 12
        m_w = 4

    class SIMDBase:
        P = (
            0x04, 0x06, 0x00, 0x02, 0x07, 0x05, 0x03, 0x01, 0x0f, 0x0b, 0x0c, 0x08, 0x09, 0x0d, 0x0a, 0x0e,
            0x11, 0x12, 0x17, 0x14, 0x16, 0x15, 0x10, 0x13, 0x1e, 0x18, 0x19, 0x1f, 0x1b, 0x1d, 0x1c, 0x1a,
        )
        round_pis = (
            (0x03, 0x17, 0x11, 0x1b),
            (0x1c, 0x13, 0x16, 0x07),
            (0x1d, 0x09, 0x0f, 0x05),
            (0x04, 0x0d, 0x0a, 0x19),
        )
        C_TEMPLATE = r"""
        #include <stdint.h>

        static uint32_t rol32(uint32_t x, int n)
        {
            return ((x << n) | (x >> (32 - n))) & 0xffffffffU;
        }

        static int lift257(int v)
        {
            if (v > 0x80)
                return v - 0x101;
            return v;
        }

        static uint32_t pack_code(int x, int y, int c)
        {
            uint32_t lo = ((uint32_t)(c * lift257(x))) & 0xffffU;
            uint32_t hi = ((uint32_t)(c * lift257(y))) & 0xffffU;
            return lo | (hi << 16);
        }

        static const uint8_t perm_table[32] = {
            0x04, 0x06, 0x00, 0x02, 0x07, 0x05, 0x03, 0x01, 0x0f, 0x0b, 0x0c, 0x08, 0x09, 0x0d, 0x0a, 0x0e,
            0x11, 0x12, 0x17, 0x14, 0x16, 0x15, 0x10, 0x13, 0x1e, 0x18, 0x19, 0x1f, 0x1b, 0x1d, 0x1c, 0x1a,
        };

        static const uint8_t round_pis[4][4] = {
            {0x03, 0x17, 0x11, 0x1b}, {0x1c, 0x13, 0x16, 0x07}, {0x1d, 0x09, 0x0f, 0x05}, {0x04, 0x0d, 0x0a, 0x19},
        };

        static void step_if(
            uint32_t *a, uint32_t *b, uint32_t *c, uint32_t *d, const uint32_t *w_vec, int lanes, int r, int s, int p)
        {
            uint32_t new_a[8], new_b[8], new_c[8], new_d[8];
            int j;

            for (j = 0; j < lanes; j++) {
                uint32_t phi = c[j] ^ (a[j] & (b[j] ^ c[j]));
                uint32_t t = (d[j] + w_vec[j] + phi) & 0xffffffffU;
                uint32_t u = 0;

                t = rol32(t, s);
                u = rol32(a[j ^ p], r);

                new_a[j] = (t + u) & 0xffffffffU;
                new_b[j] = rol32(a[j], r);
                new_c[j] = b[j];
                new_d[j] = c[j];
            }

            for (j = 0; j < lanes; j++) {
                a[j] = new_a[j];
                b[j] = new_b[j];
                c[j] = new_c[j];
                d[j] = new_d[j];
            }
        }

        static void step_maj(
            uint32_t *a, uint32_t *b, uint32_t *c, uint32_t *d, const uint32_t *w_vec, int lanes, int r, int s, int p)
        {
            uint32_t new_a[8];
            uint32_t new_b[8];
            uint32_t new_c[8];
            uint32_t new_d[8];
            int j;

            for (j = 0; j < lanes; j++) {
                uint32_t phi = (a[j] & b[j]) | (c[j] & (a[j] | b[j]));
                uint32_t t = (d[j] + w_vec[j] + phi) & 0xffffffffU;
                uint32_t u = 0;

                t = rol32(t, s);
                u = rol32(a[j ^ p], r);

                new_a[j] = (t + u) & 0xffffffffU;
                new_b[j] = rol32(a[j], r);
                new_c[j] = b[j];
                new_d[j] = c[j];
            }

            for (j = 0; j < lanes; j++) {
                a[j] = new_a[j];
                b[j] = new_b[j];
                c[j] = new_c[j];
                d[j] = new_d[j];
            }
        }

        static void compress_generic(
            uint32_t *state, const uint8_t *block, int final_flag, const uint16_t *rows_normal,
            const uint16_t *rows_final, const uint8_t *p_xor_table, int lanes, int block_size, int ntt_n, int z_stride)
        {
            const uint16_t *rows = final_flag ? rows_final : rows_normal;
            int row_stride = block_size + 1;
            int half_n = ntt_n / 2;
            int offset0 = ntt_n + half_n - 1;
            int offset1 = ntt_n - 1;

            int y[256];
            uint32_t z[32][8];
            uint32_t w[32][8];
            uint32_t m_words[32];
            uint32_t a[8], b[8], c[8], d[8];

            int i = 0;
            int j = 0;

            for (i = 0; i < ntt_n; i++) {
                int acc = rows[i * row_stride + block_size];
                for (j = 0; j < block_size; j++) {
                    acc += ((int)block[j]) * ((int)rows[i * row_stride + j]);
                }
                y[i] = acc % 0x101;
            }

            for (i = 0; i < 32; i++) {
                int base = z_stride * i;
                for (j = 0; j < lanes; j++) {
                    int idx = base + 2 * j;

                    if (i <= 15) {
                        z[i][j] = pack_code(y[idx], y[idx + 1], 0xb9);
                    } else if (i <= 23) {
                        z[i][j] = pack_code(y[idx - ntt_n], y[idx - half_n], 0xe9);
                    } else {
                        z[i][j] = pack_code(y[idx - offset0], y[idx - offset1], 0xe9);
                    }
                }
            }

            for (i = 0; i < 32; i++) {
                int src = perm_table[i];
                for (j = 0; j < lanes; j++) {
                    w[i][j] = z[src][j];
                }
            }

            for (i = 0; i < lanes * 4; i++) {
                int off = i * 4;
                m_words[i] = (
                    ((uint32_t)block[off + 0]) |
                    ((uint32_t)block[off + 1] << 8) |
                    ((uint32_t)block[off + 2] << 16) |
                    ((uint32_t)block[off + 3] << 24)
                );
            }

            for (j = 0; j < lanes; j++) {
                a[j] = state[j] ^ m_words[j];
                b[j] = state[lanes + j] ^ m_words[lanes + j];
                c[j] = state[(lanes * 2) + j] ^ m_words[(lanes * 2) + j];
                d[j] = state[(lanes * 3) + j] ^ m_words[(lanes * 3) + j];
            }

            {
                int step_index = 0;

                for (i = 0; i < 4; i++) {
                    int pi0 = round_pis[i][0];
                    int pi1 = round_pis[i][1];
                    int pi2 = round_pis[i][2];
                    int pi3 = round_pis[i][3];

                    step_if(a, b, c, d, w[step_index], lanes, pi0, pi1, p_xor_table[step_index]);
                    step_index++;
                    step_if(a, b, c, d, w[step_index], lanes, pi1, pi2, p_xor_table[step_index]);
                    step_index++;
                    step_if(a, b, c, d, w[step_index], lanes, pi2, pi3, p_xor_table[step_index]);
                    step_index++;
                    step_if(a, b, c, d, w[step_index], lanes, pi3, pi0, p_xor_table[step_index]);
                    step_index++;

                    step_maj(a, b, c, d, w[step_index], lanes, pi0, pi1, p_xor_table[step_index]);
                    step_index++;
                    step_maj(a, b, c, d, w[step_index], lanes, pi1, pi2, p_xor_table[step_index]);
                    step_index++;
                    step_maj(a, b, c, d, w[step_index], lanes, pi2, pi3, p_xor_table[step_index]);
                    step_index++;
                    step_maj(a, b, c, d, w[step_index], lanes, pi3, pi0, p_xor_table[step_index]);
                    step_index++;
                }

                step_if(a, b, c, d, state, lanes, 0x04, 0x0d, p_xor_table[step_index]);
                step_index++;
                step_if(a, b, c, d, state + lanes, lanes, 0x0d, 0x0a, p_xor_table[step_index]);
                step_index++;
                step_if(a, b, c, d, state + (lanes * 2), lanes, 0x0a, 0x19, p_xor_table[step_index]);
                step_index++;
                step_if(a, b, c, d, state + (lanes * 3), lanes, 0x19, 0x04, p_xor_table[step_index]);
            }

            for (j = 0; j < lanes; j++) {
                state[j] = a[j];
                state[lanes + j] = b[j];
                state[(lanes * 2) + j] = c[j];
                state[(lanes * 3) + j] = d[j];
            }
        }

        void compress_small(
            uint32_t *state, const uint8_t *block, int final_flag, const uint16_t *rows_normal,
            const uint16_t *rows_final, const uint8_t *p_xor_table)
        {
            compress_generic(state, block, final_flag, rows_normal, rows_final, p_xor_table, 4, 64, 128, 8);
        }

        void compress_big(
            uint32_t *state, const uint8_t *block, int final_flag, const uint16_t *rows_normal,
            const uint16_t *rows_final, const uint8_t *p_xor_table)
        {
            compress_generic(state, block, final_flag, rows_normal, rows_final, p_xor_table, 8, 128, 256, 16);
        }
        """
        DEF_TEMPLATE = r"""
        void compress_small(
            uint32_t *state, const uint8_t *block, int final_flag, const uint16_t *rows_normal,
            const uint16_t *rows_final, const uint8_t  *p_xor_table);
        void compress_big(
            uint32_t *state, const uint8_t *block, int final_flag, const uint16_t *rows_normal,
            const uint16_t *rows_final, const uint8_t *p_xor_table);
        """

        def init_cffi_backend(self):
            try:
                import cffi
                import warnings
            except ImportError:
                self.USE_CFFI = False
                return

            key = self.__class__
            base_class = Hash.SIMDBase

            if not hasattr(base_class, "cffi_cache"):
                base_class.cffi_cache = {}

            # fast return
            if key in base_class.cffi_cache:
                self.cffi = base_class.cffi_cache[key]
                self.USE_CFFI = True
                return

            # ffi, lib
            if base_class in base_class.cffi_cache:
                ffi, lib = base_class.cffi_cache[base_class]
            else:
                try:
                    with warnings.catch_warnings():
                        warnings.filterwarnings(
                            "ignore",
                            message=r"reimporting '_cffi__.*' might overwrite older definitions",
                            category=UserWarning,
                            module=r"cffi\.vengine_cpy",
                        )
                        ffi = cffi.FFI()
                        ffi.cdef(base_class.DEF_TEMPLATE)
                        lib = ffi.verify(base_class.C_TEMPLATE, extra_compile_args=["-O2"])
                    base_class.cffi_cache[base_class] = (ffi, lib)
                except Exception:
                    self.USE_CFFI = False
                    return

            # Different for each class
            def flatten_ntt_rows(rows):
                flat = []
                for coeffs, add_const in rows:
                    flat.extend(coeffs)
                    flat.append(add_const)
                return tuple(flat)

            try:
                if self.lanes == 4:
                    rows_normal = ffi.new("uint16_t[]", flatten_ntt_rows(self.ntt_rows_normal))
                    rows_final = ffi.new("uint16_t[]", flatten_ntt_rows(self.ntt_rows_final))
                    p_xor_table = ffi.new("uint8_t[]", tuple(self.p_xor_table))
                elif self.lanes == 8:
                    rows_normal = ffi.new("uint16_t[]", flatten_ntt_rows(self.ntt_rows_normal))
                    rows_final = ffi.new("uint16_t[]", flatten_ntt_rows(self.ntt_rows_final))
                    p_xor_table = ffi.new("uint8_t[]", tuple(self.p_xor_table))
            except Exception:
                self.USE_CFFI = False
                return

            # add to cache
            cffi_obj = collections.namedtuple("CFFI", "ffi lib rows_normal rows_final p_xor_table")(
                ffi, lib, rows_normal, rows_final, p_xor_table,
            )
            self.cffi = base_class.cffi_cache[key] = cffi_obj
            self.USE_CFFI = True
            return

        def prepare_constants(self):
            cls = self.__class__
            if not hasattr(cls, "root_pows"):
                root_pows = [1] * self.order
                for i in range(1, self.order):
                    root_pows[i] = (root_pows[i - 1] * self.root) % 0x101
                cls.root_pows = root_pows
            if not hasattr(cls, "ntt_rows_normal"):
                root_pows = self.root_pows
                ntt_rows_normal = [None] * self.ntt_n
                ntt_rows_final = [None] * self.ntt_n
                for i in range(self.ntt_n):
                    row = [0] * self.block_size
                    for j in range(self.block_size):
                        row[j] = root_pows[(i * j) % self.order]
                    add_normal = root_pows[(self.const_exps[0] * i) % self.order]
                    add_final = add_normal + root_pows[(self.const_exps[1] * i) % self.order]
                    ntt_rows_normal[i] = (tuple(row), add_normal)
                    ntt_rows_final[i] = (tuple(row), add_final)
                cls.ntt_rows_normal = tuple(ntt_rows_normal)
                cls.ntt_rows_final = tuple(ntt_rows_final)
            return

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.state = list(self.iv_words)
            self.buf = bytearray()
            self.msg_len = 0
            self.prepare_constants()
            self.init_cffi_backend()
            if data:
                self.update(data)
            return

        def copy(self):
            other = self.__class__()
            other.state = list(self.state)
            other.buf = bytearray(self.buf)
            other.msg_len = self.msg_len
            return other

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.msg_len += len(data)
            self.buf.extend(data)
            while len(self.buf) >= self.block_size:
                block = bytes(self.buf[:self.block_size])
                del self.buf[:self.block_size]
                self.compress(block, 0)
            return self

        def digest(self):
            c = self.copy()
            c.finalize()
            words = c.state[: c.lanes * 2][: c.out_words]
            out = b"".join(struct.pack("<I", w) for w in words)
            return out

        def hexdigest(self):
            return self.digest().hex()

        def finalize(self):
            if len(self.buf) != 0:
                if len(self.buf) < self.block_size:
                    self.buf.extend(b"\x00" * (self.block_size - len(self.buf)))
                block = self.buf[:self.block_size]
                del self.buf[:self.block_size]
                self.compress(block, 0)
            bit_len = self.msg_len * 8
            bit_len = bit_len % (1 << (self.block_size * 8))
            length_block = bit_len.to_bytes(self.block_size, "little")
            self.compress(length_block, 1)
            return

        def compress(self, block, final_flag):

            def ntt(block, rows):
                y = [0] * self.ntt_n
                for i in range(self.ntt_n):
                    coeffs, add_const = rows[i]
                    acc = add_const
                    for j in range(self.block_size):
                        acc += block[j] * coeffs[j]
                    y[i] = acc % 0x101
                return y

            def lift257(v):
                if v > 0x80:
                    return v - 0x101
                return v

            def pack_code(x, y, c):
                lo = (c * lift257(x)) & 0xffff
                hi = (c * lift257(y)) & 0xffff
                return lo | (hi << 0x10)

            def message_expansion(block, final_flag):
                if final_flag:
                    y = ntt(block, self.ntt_rows_final)
                else:
                    y = ntt(block, self.ntt_rows_normal)
                z = [None] * 32
                lanes = self.lanes
                z_stride = self.z_stride
                ntt_n = self.ntt_n
                half_n = ntt_n // 2

                for i in range(32):
                    row = [0] * lanes
                    base = z_stride * i

                    if i <= 15:
                        for j in range(lanes):
                            idx = base + 2 * j
                            row[j] = pack_code(y[idx], y[idx + 1], 0xb9)
                    elif i <= 23:
                        for j in range(lanes):
                            idx = base + 2 * j
                            row[j] = pack_code(y[idx - ntt_n], y[idx - half_n], 0xe9)
                    else:
                        offset0 = ntt_n + half_n - 1
                        offset1 = ntt_n - 1
                        for j in range(lanes):
                            idx = base + 2 * j
                            row[j] = pack_code(y[idx - offset0], y[idx - offset1], 0xe9)
                    z[i] = row

                w = [None] * 32
                for i in range(32):
                    w[i] = z[self.P[i]]
                return w

            def rol32(x, n):
                return ((x << n) | (x >> (0x20 - n))) & 0xffff_ffff

            def step_if(a, b, c, d, w_vec, r, s, p):
                new_a = [0] * self.lanes
                new_b = [0] * self.lanes
                new_c = [0] * self.lanes
                new_d = [0] * self.lanes
                for j in range(self.lanes):
                    phi = c[j] ^ (a[j] & (b[j] ^ c[j]))
                    t = (d[j] + w_vec[j] + phi) & 0xffff_ffff
                    t = rol32(t, s)
                    u = rol32(a[j ^ p], r)
                    new_a[j] = (t + u) & 0xffff_ffff
                    new_b[j] = rol32(a[j], r)
                    new_c[j] = b[j]
                    new_d[j] = c[j]
                return new_a, new_b, new_c, new_d

            def step_maj(a, b, c, d, w_vec, r, s, p):
                new_a = [0] * self.lanes
                new_b = [0] * self.lanes
                new_c = [0] * self.lanes
                new_d = [0] * self.lanes
                for j in range(self.lanes):
                    phi = (a[j] & b[j]) | (c[j] & (a[j] | b[j]))
                    t = (d[j] + w_vec[j] + phi) & 0xffff_ffff
                    t = rol32(t, s)
                    u = rol32(a[j ^ p], r)
                    new_a[j] = (t + u) & 0xffff_ffff
                    new_b[j] = rol32(a[j], r)
                    new_c[j] = b[j]
                    new_d[j] = c[j]
                return new_a, new_b, new_c, new_d

            if len(block) != self.block_size:
                raise ValueError("invalid block size")

            if self.USE_CFFI:
                state_buf = self.cffi.ffi.new("uint32_t[]", self.state)
                block_buf = self.cffi.ffi.new("uint8_t[]", bytes(block))
                if self.lanes == 4:
                    clib_compress = self.cffi.lib.compress_small
                else:
                    clib_compress = self.cffi.lib.compress_big
                clib_compress(
                    state_buf, block_buf, int(final_flag),
                    self.cffi.rows_normal, self.cffi.rows_final, self.cffi.p_xor_table,
                )
                self.state = [state_buf[i] for i in range(self.lanes * 4)]
                return

            w = message_expansion(block, final_flag)
            m_words = struct.unpack("<" + "I" * (self.lanes * 4), block)
            s_words = [0] * (self.lanes * 4)
            for i in range(self.lanes * 4):
                s_words[i] = self.state[i] ^ m_words[i]
            lanes = self.lanes

            a = list(s_words[0 : lanes])
            b = list(s_words[lanes : lanes * 2])
            c = list(s_words[lanes * 2 : lanes * 3])
            d = list(s_words[lanes * 3 : lanes * 4])
            ptab = self.p_xor_table
            step_index = 0
            for rnd in range(4):
                pi0, pi1, pi2, pi3 = self.round_pis[rnd]

                a, b, c, d = step_if(a, b, c, d, w[step_index], pi0, pi1, ptab[step_index])
                step_index += 1
                a, b, c, d = step_if(a, b, c, d, w[step_index], pi1, pi2, ptab[step_index])
                step_index += 1
                a, b, c, d = step_if(a, b, c, d, w[step_index], pi2, pi3, ptab[step_index])
                step_index += 1
                a, b, c, d = step_if(a, b, c, d, w[step_index], pi3, pi0, ptab[step_index])
                step_index += 1

                a, b, c, d = step_maj(a, b, c, d, w[step_index], pi0, pi1, ptab[step_index])
                step_index += 1
                a, b, c, d = step_maj(a, b, c, d, w[step_index], pi1, pi2, ptab[step_index])
                step_index += 1
                a, b, c, d = step_maj(a, b, c, d, w[step_index], pi2, pi3, ptab[step_index])
                step_index += 1
                a, b, c, d = step_maj(a, b, c, d, w[step_index], pi3, pi0, ptab[step_index])
                step_index += 1

            iv_a = self.state[0 : lanes]
            iv_b = self.state[lanes : lanes * 2]
            iv_c = self.state[lanes * 2 : lanes * 3]
            iv_d = self.state[lanes * 3 : lanes * 4]

            a, b, c, d = step_if(a, b, c, d, iv_a, 0x04, 0x0d, ptab[step_index])
            step_index += 1
            a, b, c, d = step_if(a, b, c, d, iv_b, 0x0d, 0x0a, ptab[step_index])
            step_index += 1
            a, b, c, d = step_if(a, b, c, d, iv_c, 0x0a, 0x19, ptab[step_index])
            step_index += 1
            a, b, c, d = step_if(a, b, c, d, iv_d, 0x19, 0x04, ptab[step_index])
            self.state = list(a + b + c + d)
            return

