        @classmethod
        def ensure_tables(cls):

            def gf16_mul(a, b):
                x = a
                y = b
                z = 0
                for _ in range(4):
                    if (y & 0x01) != 0:
                        z ^= x
                    carry = x & 0x08
                    x = (x << 1) & 0x0f
                    if carry != 0:
                        x ^= 0x03
