                q = p
                q = ((q >> 7) | (q << 1)) & 0xff
                p ^= q
                q = ((q >> 7) | (q << 1)) & 0xff
                p ^= q
                q = ((q >> 7) | (q << 1)) & 0xff
                p ^= q
                q = ((q >> 7) | (q << 1)) & 0xff
