            def ff_mult(a, b):
                if a == 0 or b == 0:
                    return 0
                return pow_tab[(log_tab[a] + log_tab[b]) % 255]

            f2 = [0] * 256
            f3 = [0] * 256
            f4 = [0] * 256
            f8 = [0] * 256
            f9 = [0] * 256
            fa = [0] * 256
            for i in range(256):
                f2[i] = ff_mult(i, 2)
                f3[i] = ff_mult(i, 3)
                f4[i] = ff_mult(i, 4)
