        block_size = 64
        word_size = 32
        word_mask = 0xffff_ffff
        length_size = 8
        length_block_threshold = 512 - 65
        pack_fmt = ">I"
        unpack_fmt = ">16I"
        tt = (0x5a82_7999, 0x6ed9_eba1, 0x8f1b_bcdc)

        def reduce_temp(self, value):
            value = ((value >> 17) ^ value) & 0x1f_fff
            value = ((value >> 10) ^ value) & 0x3ff
            value = ((value >> 5) ^ value) & 0x1f
            return value

