    class EnRUPTBase:
        word_bits = 64
        parallelism = 2
        security_parameter = 4

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.digest_size = self.digest_bits // 8
            self.word_bytes = self.word_bits // 8
            self.state_words = (
                (
                    self.digest_bits * 2
                    + self.word_bits * self.parallelism
                    - 1
                )
                // (self.word_bits * self.parallelism)
            ) * self.parallelism
            self.x = [0] * self.state_words
            self.d = [0] * self.parallelism
            self.r = 0
            self.buf = bytearray()
            self.finalized = False
            if data:
                self.update(data)
            return

        def copy(self):
            other = self.__class__()
            other.x = self.x[:]
            other.d = self.d[:]
            other.r = self.r
            other.buf = bytearray(self.buf)
            other.finalized = self.finalized
            return other

        def update(self, data):
            if self.finalized:
                raise ValueError("hash object already finalized")
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.buf.extend(bytes(data))
            while len(self.buf) >= self.word_bytes:
                word = int.from_bytes(self.buf[:self.word_bytes], "big")
                del self.buf[:self.word_bytes]
                self.absorb_word(word)
            return self

        def digest(self):
            other = self.copy()
            other.finalize()
            return other.squeeze()

        def hexdigest(self):
            return self.digest().hex()

        def absorb_word(self, word):

            def ror(x, n):
                return ((x >> n) | (x << (self.word_bits - n))) & 0xffff_ffff_ffff_ffff

            for _ in range(2 * self.security_parameter):
                r = self.r
                h = self.state_words
                p = self.parallelism
                a = (r // p * p + (r + 1) % p) % h
                b = (r + 2 * p) % h
                f = ror(
                    ((self.x[a] * 2) ^ self.x[b] ^ self.d[r % p] ^ r) & 0xffff_ffff_ffff_ffff,
                    self.word_bits // 4,
                )
                f = (f * 9) & 0xffff_ffff_ffff_ffff
                self.x[(r + p) % h] ^= f
                self.d[r % p] ^= f ^ self.x[(h * p // 2 + p % 2 + r) % h]
                self.r = (r + 1) & 0xffff_ffff_ffff_ffff
            self.d[self.parallelism - 1] ^= word
            return

        def finalize(self):
            if self.finalized:
                return
            padded = bytearray(self.buf)
            padded.append(0x80)
            while len(padded) % self.word_bytes != 0:
                padded.append(0x00)
            for i in range(0, len(padded), self.word_bytes):
                word = int.from_bytes(padded[i:i + self.word_bytes], "big")
                self.absorb_word(word)
            self.absorb_word(self.digest_bits)
            for _ in range(self.state_words):
                self.absorb_word(0)
            self.buf.clear()
            self.finalized = True
            return

        def squeeze(self):
            out = bytearray()
            full_words = self.digest_bits // self.word_bits
            remain_bits = self.digest_bits % self.word_bits
            for _ in range(full_words):
                self.absorb_word(0)
                out.extend(self.d[self.parallelism - 1].to_bytes(self.word_bytes, "big"))
            if remain_bits:
                self.absorb_word(0)
                out.extend(
                    self.d[self.parallelism - 1].to_bytes(self.word_bytes, "big")[
                        : (remain_bits + 7) // 8
                    ]
                )
            return bytes(out)

