                if self.word_bits == 64:
                    table = self.l64_table
                    shift = 56
                    count = 8
                else:
                    table = self.l32_table
                    shift = 24
                    count = 4

                i = 0
                while i < count:
                    value = table[value >> shift] ^ ((value << 8) & self.word_mask)
                    i += 1
