        @classmethod
        def ensure_tables(cls):
            if hasattr(Hash.LUXBase, "MUL1"):
                return

            def xtime(x):
                y = x << 1
                if x & 0x80:
                    y ^= 0x1b
                return y & 0xff

            mul2 = bytearray(256)
            mul3 = bytearray(256)
            mul4 = bytearray(256)
            mul6 = bytearray(256)
            mul8 = bytearray(256)
            mul12 = bytearray(256)
            for x in range(256):
                x2 = xtime(x)
                x4 = xtime(x2)
                x8 = xtime(x4)
                mul2[x] = x2
                mul3[x] = x2 ^ x
                mul4[x] = x4
                mul6[x] = x4 ^ x2
                mul8[x] = x8
                mul12[x] = x8 ^ x4
            Hash.LUXBase.MUL1 = bytes(range(256))
            Hash.LUXBase.MUL2 = bytes(mul2)
            Hash.LUXBase.MUL3 = bytes(mul3)
            Hash.LUXBase.MUL4 = bytes(mul4)
            Hash.LUXBase.MUL6 = bytes(mul6)
            Hash.LUXBase.MUL8 = bytes(mul8)
            Hash.LUXBase.MUL12 = bytes(mul12)
            return

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.digest_size = self.digest_bits // 8
            self.cr = [bytearray(8) for _ in range(self.mrows)]
            self.bf = [bytearray(16) for _ in range(self.mrows)]
            self.buf = bytearray()
            self.total_bits = 0
            self.partial_bits = 0
            self.partial_byte = 0
            self.finalized = False
            self.ensure_tables()
            if data:
                self.update(data)
            return

        def copy(self):
            other = self.__class__()
            other.cr = [bytearray(row) for row in self.cr]
            other.bf = [bytearray(row) for row in self.bf]
            other.buf = bytearray(self.buf)
            other.total_bits = self.total_bits
            other.partial_bits = self.partial_bits
            other.partial_byte = self.partial_byte
            other.finalized = self.finalized
            return other

        def update(self, data):
            if self.finalized:
                raise ValueError("hash object already finalized")
            if self.partial_bits:
                raise ValueError("cannot update after partial-bit input")
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            data = bytes(data)
            self.total_bits += len(data) * 8
            self.buf.extend(data)
            self.process_buffer()
            return self

        def finalize(self):
            if self.finalized:
                return
            rem = self.final_bytes()
            self.compress(rem)
            length_block = self.total_bits.to_bytes(8, "big")
            if self.digest_bits <= 256:
                self.compress(length_block[:4])
                self.compress(length_block[4:])
            else:
                self.compress(length_block)
            zero = bytes(self.mrows)
            for _ in range(16):
                self.compress(zero)
            out = bytearray()
            if self.digest_bits <= 256:
                for _ in range(self.digest_bits // 32):
                    self.compress(zero)
                    out.extend((self.cr[3][3], self.cr[2][3], self.cr[1][3], self.cr[0][3]))
            else:
                for _ in range(self.digest_bits // 64):
                    self.compress(zero)
                    out.extend((
                        self.cr[7][3], self.cr[6][3], self.cr[5][3], self.cr[4][3],
                        self.cr[3][3], self.cr[2][3], self.cr[1][3], self.cr[0][3],
                    ))
            self.result = bytes(out)
            self.finalized = True
            return

        def digest(self):
            other = self.copy()
            other.finalize()
            return other.result

        def hexdigest(self):
            return self.digest().hex()

        def process_buffer(self):
            block_size = self.mrows
            compress = self.compress
            buf = self.buf
            while len(buf) >= block_size:
                block = bytes(buf[:block_size])
                del buf[:block_size]
                compress(block)
            return

        def compress(self, block):

            def sub_bytes():
                sbox = self.SBOX
                for i in range(self.mrows):
                    row = self.cr[i]
                    for j in range(8):
                        row[j] = sbox[row[j]]
                return

            def shift_rows():
                if self.mrows == 4:
                    shifts = self.SHIFT_ROWS_4
                else:
                    shifts = self.SHIFT_ROWS_8

                for i, shift in enumerate(shifts):
                    if shift:
                        row = self.cr[i]
                        self.cr[i] = row[shift:] + row[:shift]
                return

            def mix_columns4():
                m1 = self.MUL1
                m2 = self.MUL2
                m3 = self.MUL3
                cr = self.cr
                out = [bytearray(8) for _ in range(4)]
                for j in range(8):
                    a0 = cr[0][j]
                    a1 = cr[1][j]
                    a2 = cr[2][j]
                    a3 = cr[3][j]
                    out[0][j] = m2[a0] ^ m3[a1] ^ m1[a2] ^ m1[a3]
                    out[1][j] = m1[a0] ^ m2[a1] ^ m3[a2] ^ m1[a3]
                    out[2][j] = m1[a0] ^ m1[a1] ^ m2[a2] ^ m3[a3]
                    out[3][j] = m3[a0] ^ m1[a1] ^ m1[a2] ^ m2[a3]
                self.cr = out
                return

            def mix_columns8():
                m1 = self.MUL1
                m2 = self.MUL2
                m4 = self.MUL4
                m6 = self.MUL6
                m8 = self.MUL8
                m12 = self.MUL12
                cr = self.cr
                out = [bytearray(8) for _ in range(8)]
                for j in range(8):
                    a0 = cr[0][j]
                    a1 = cr[1][j]
                    a2 = cr[2][j]
                    a3 = cr[3][j]
                    a4 = cr[4][j]
                    a5 = cr[5][j]
                    a6 = cr[6][j]
                    a7 = cr[7][j]
                    out[0][j] = m1[a0] ^ m4[a1] ^ m1[a2] ^ m1[a3] ^ m2[a4] ^ m12[a5] ^ m6[a6] ^ m8[a7]
                    out[1][j] = m8[a0] ^ m1[a1] ^ m4[a2] ^ m1[a3] ^ m1[a4] ^ m2[a5] ^ m12[a6] ^ m6[a7]
                    out[2][j] = m6[a0] ^ m8[a1] ^ m1[a2] ^ m4[a3] ^ m1[a4] ^ m1[a5] ^ m2[a6] ^ m12[a7]
                    out[3][j] = m12[a0] ^ m6[a1] ^ m8[a2] ^ m1[a3] ^ m4[a4] ^ m1[a5] ^ m1[a6] ^ m2[a7]
                    out[4][j] = m2[a0] ^ m12[a1] ^ m6[a2] ^ m8[a3] ^ m1[a4] ^ m4[a5] ^ m1[a6] ^ m1[a7]
                    out[5][j] = m1[a0] ^ m2[a1] ^ m12[a2] ^ m6[a3] ^ m8[a4] ^ m1[a5] ^ m4[a6] ^ m1[a7]
                    out[6][j] = m1[a0] ^ m1[a1] ^ m2[a2] ^ m12[a3] ^ m6[a4] ^ m8[a5] ^ m1[a6] ^ m4[a7]
                    out[7][j] = m4[a0] ^ m1[a1] ^ m1[a2] ^ m2[a3] ^ m12[a4] ^ m6[a5] ^ m8[a6] ^ m1[a7]
                self.cr = out
                return

            def add_constant():
                if self.mrows == 4:
                    for i, val in enumerate(self.ADD_CONSTANT):
                        self.cr[i][0] ^= val
                else:
                    for i, val in enumerate(self.ADD_CONSTANT):
                        self.cr[i + 4][0] ^= val
                return

            def functionF():
                sub_bytes()
                shift_rows()
                if self.mrows == 4:
                    mix_columns4()
                else:
                    mix_columns8()
                add_constant()
                return

            def functionG():
                bf = self.bf
                temp = [bf[i][15] for i in range(self.mrows)]

                for j in range(15, 0, -1):
                    for i in range(self.mrows):
                        bf[i][j] = bf[i][j - 1]

                for i in range(self.mrows):
                    bf[i][0] = temp[i]
                return

            for i in range(self.mrows):
                x = block[self.mrows - 1 - i]
                self.bf[i][0] ^= x
                self.cr[i][0] ^= x

            functionG()
            functionF()

            for j in range(8):
                for i in range(self.mrows):
                    self.bf[i][j + 4] ^= self.cr[i][j]

            for i in range(self.mrows):
                self.cr[i][7] ^= self.bf[i][15]
            return

        def final_bytes(self):
            rem = bytearray(self.mrows)
            used = len(self.buf)
            rem[:used] = self.buf
            if self.partial_bits:
                idx = used
                rem[idx] = self.partial_byte & (0xff << (8 - self.partial_bits))
                rem[idx] ^= 0x01 << (7 - self.partial_bits)
            elif used:
                rem[used] = 0x80
            else:
                rem[0] = 0x80
            return rem

