    class SpectralHashBase:
        block_size = 64
        X_INVERSE_TABLE = (0, 1, 15, 10, 8, 6, 5, 9, 4, 7, 3, 14, 13, 12, 11, 2)
        AFFINE_TRANSFORM_TABLE = (7, 0, 8, 2, 12, 4, 13, 11, 10, 3, 14, 15, 6, 1, 5, 9)
        SG_TABLES = {
            128: (0x01, 0x02, 0x04, 0x08),
            160: (0x03, 0x02, 0x04, 0x08),
            192: (0x03, 0x06, 0x04, 0x08),
            224: (0x03, 0x06, 0x0c, 0x08),
            256: (0x03, 0x07, 0x0c, 0x08),
            288: (0x03, 0x07, 0x0e, 0x08),
            320: (0x03, 0x07, 0x0e, 0x0c),
            352: (0x07, 0x07, 0x0e, 0x0c),
            384: (0x07, 0x0f, 0x0e, 0x0c),
            416: (0x07, 0x0f, 0x0f, 0x0c),
            448: (0x07, 0x0f, 0x0f, 0x0e),
            480: (0x0f, 0x0f, 0x0f, 0x0e),
            512: (0x0f, 0x0f, 0x0f, 0x0f),
        }

        @classmethod
        def ensure_tables(cls):
            if hasattr(Hash.SpectralHashBase, "IJ_COLUMNS"):
                return

            IJ_COLUMNS = []
            for i in range(4):
                for j in range(4):
                    IJ_COLUMNS.append([(i << 5) | (j << 3) | k for k in range(8)])
            Hash.SpectralHashBase.IJ_COLUMNS = IJ_COLUMNS

            IK_ROWS = []
            for i in range(4):
                for k in range(8):
                    IK_ROWS.append([(i << 5) | (j << 3) | k for j in range(4)])
            Hash.SpectralHashBase.IK_ROWS = IK_ROWS

            JK_ROWS = []
            for j in range(4):
                for k in range(8):
                    JK_ROWS.append([(i << 5) | (j << 3) | k for i in range(4)])
            Hash.SpectralHashBase.JK_ROWS = JK_ROWS
            return

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.digest_size = self.digest_bits // 8
            self.s_prism = [0] * 128
            self.p_prism = list(range(128))
            self.h_prism = [0] * 128
            self.buf = bytearray()
            self.msg_len = 0
            self.started = False
            self.ensure_tables()
            if data:
                self.update(data)
            return

        def copy(self):
            other = self.__class__()
            other.s_prism = self.s_prism[:]
            other.p_prism = self.p_prism[:]
            other.h_prism = self.h_prism[:]
            other.buf = bytearray(self.buf)
            other.msg_len = self.msg_len
            other.started = self.started
            return other

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            data = bytes(data)
            self.msg_len += len(data)
            self.buf.extend(data)
            while len(self.buf) >= 64:
                block = bytes(self.buf[:64])
                del self.buf[:64]
                self.process_block(block, apply_initial_swap=not self.started)
                self.started = True
            return self

        def digest(self):
            c = self.copy()
            c.finalize()
            return c.make_digest()

        def hexdigest(self):
            return self.digest().hex()

        def process_block(self, block, apply_initial_swap):

            def fill_s_prism(block):
                out = self.s_prism
                n = 0
                for b in block:
                    out[n] = b >> 4
                    out[n + 1] = b & 0x0f
                    n += 2
                return

            def initial_swap_control():
                p = self.p_prism
                s = self.s_prism
                for i in range(4):
                    base_i = i << 5
                    for j in range(4):
                        base = base_i | (j << 3)
                        for k in range(8):
                            idx = base | k
                            st = s[idx]
                            sh = st >> 2
                            sl = st & 0x03
                            idx2 = (sh << 5) | (sl << 3) | k
                            p[idx], p[idx2] = p[idx2], p[idx]
                return

            fill_s_prism(block)
            if apply_initial_swap:
                initial_swap_control()
            self.compress()
            return

        def compress(self):

            def affine_transform():
                table = self.AFFINE_TRANSFORM_TABLE
                s = self.s_prism
                for idx in range(128):
                    s[idx] = table[s[idx]]
                return

            def k1_swap():
                s = self.s_prism
                p = self.p_prism
                for i in range(4):
                    base_i = i << 5
                    for j in range(4):
                        base = base_i | (j << 3)
                        current = s[base] ^ s[base | 4]
                        for b in range(4):
                            if ((current >> b) & 1) == 0:
                                a = base | b
                                z = base | (7 - b)
                                p[a], p[z] = p[z], p[a]
                return

            def k2_swap():
                s = self.s_prism
                p = self.p_prism
                for i in range(4):
                    base_i = i << 5
                    for j in range(4):
                        base = base_i | (j << 3)
                        current = s[base | 1]
                        if (current & 1) == 0:
                            p[base | 0], p[base | 1] = p[base | 1], p[base | 0]
                        if ((current >> 1) & 1) == 0:
                            p[base | 2], p[base | 3] = p[base | 3], p[base | 2]
                        if ((current >> 2) & 1) == 0:
                            p[base | 1], p[base | 2] = p[base | 2], p[base | 1]
                        if ((current >> 3) & 1) == 0:
                            p[base | 0], p[base | 3] = p[base | 3], p[base | 0]
                for i in range(4):
                    base_i = i << 5
                    for j in range(4):
                        base = base_i | (j << 3)
                        current = s[base | 5]
                        if (current & 1) == 0:
                            p[base | 4], p[base | 5] = p[base | 5], p[base | 4]
                        if ((current >> 1) & 1) == 0:
                            p[base | 6], p[base | 7] = p[base | 7], p[base | 6]
                        if ((current >> 2) & 1) == 0:
                            p[base | 5], p[base | 6] = p[base | 6], p[base | 5]
                        if ((current >> 3) & 1) == 0:
                            p[base | 4], p[base | 7] = p[base | 7], p[base | 4]
                return

            def j_swap():
                s = self.s_prism
                p = self.p_prism
                for i in range(4):
                    base_i = i << 5
                    for k in range(8):
                        current = s[base_i | 16 | k]
                        if (((current >> 0) & 1) ^ (k & 1)) == 0:
                            a = base_i | 0 | k
                            b = base_i | 8 | k
                            p[a], p[b] = p[b], p[a]
                        if (((current >> 1) & 1) ^ ((k >> 1) & 1)) == 0:
                            a = base_i | 16 | k
                            b = base_i | 24 | k
                            p[a], p[b] = p[b], p[a]
                        if (((current >> 2) & 1) ^ ((k >> 2) & 1)) == 0:
                            a = base_i | 8 | k
                            b = base_i | 16 | k
                            p[a], p[b] = p[b], p[a]
                        if (((current >> 3) & 1) ^ (i & 1)) == 0:
                            a = base_i | 0 | k
                            b = base_i | 24 | k
                            p[a], p[b] = p[b], p[a]
                return

            def i_swap():
                s = self.s_prism
                p = self.p_prism
                for j in range(4):
                    base_j = j << 3
                    for k in range(8):
                        current = s[96 | base_j | k]
                        if (((current >> 0) & 1) ^ (k & 1)) == 0:
                            a = 0 | base_j | k
                            b = 32 | base_j | k
                            p[a], p[b] = p[b], p[a]
                        if (((current >> 1) & 1) ^ ((k >> 1) & 1)) == 0:
                            a = 64 | base_j | k
                            b = 96 | base_j | k
                            p[a], p[b] = p[b], p[a]
                        if (((current >> 2) & 1) ^ ((k >> 2) & 1)) == 0:
                            a = 32 | base_j | k
                            b = 64 | base_j | k
                            p[a], p[b] = p[b], p[a]
                        if (((current >> 3) & 1) ^ (j & 1)) == 0:
                            a = 0 | base_j | k
                            b = 96 | base_j | k
                            p[a], p[b] = p[b], p[a]
                return

            def eight_point_dft(c0, c1, c2, c3, c4, c5, c6, c7):
                t20 = c0 + c4
                t21 = c0 - c4
                t22 = c2 + c6
                t23 = (c2 - c6) * 4
                t24 = c1 + c5
                t25 = c1 - c5
                t26 = c3 + c7
                t27 = (c3 - c7) * 4

                t0 = t20 + t22
                t1 = t21 + t23
                t2 = t20 - t22
                t3 = t21 - t23

                t4 = t24 + t26
                t5 = (t25 + t27) * 2
                t6 = (t24 - t26) * 4
                t7 = (t25 - t27) * 8

                return [
                    (t0 + t4) % 17, (t1 + t5) % 17, (t2 + t6) % 17, (t3 + t7) % 17,
                    (t0 - t4) % 17, (t1 - t5) % 17, (t2 - t6) % 17, (t3 - t7) % 17,
                ]

            def four_point_dft(a0, a1, a2, a3):
                a = a0 + a2
                b = a0 - a2
                c = a1 + a3
                d = a1 - a3
                return [
                    (a + c) % 17,
                    (b + d * 4) % 17,
                    (a - c) % 17,
                    (b - d * 4) % 17,
                ]

            def apply_k_dft():
                s = self.s_prism
                for idxs in self.IJ_COLUMNS:
                    out = eight_point_dft(
                        s[idxs[0]], s[idxs[1]], s[idxs[2]], s[idxs[3]],
                        s[idxs[4]], s[idxs[5]], s[idxs[6]], s[idxs[7]],
                    )
                    for idx, val in zip(idxs, out):
                        s[idx] = val
                return

            def apply_j_dft():
                s = self.s_prism
                for idxs in self.IK_ROWS:
                    out = four_point_dft(s[idxs[0]], s[idxs[1]], s[idxs[2]], s[idxs[3]])
                    for idx, val in zip(idxs, out):
                        s[idx] = val
                return

            def apply_i_dft():
                s = self.s_prism
                for idxs in self.JK_ROWS:
                    out = four_point_dft(s[idxs[0]], s[idxs[1]], s[idxs[2]], s[idxs[3]])
                    for idx, val in zip(idxs, out):
                        s[idx] = val
                return

            def nlst():
                s = self.s_prism
                p = self.p_prism
                h = self.h_prism
                xinv = self.X_INVERSE_TABLE
                new_s = [0] * 128
                for idx in range(128):
                    stemp = s[idx]
                    ptemp = p[idx]
                    sp = stemp & 0x0f
                    pl = ptemp & 0x0f
                    ph = ((stemp & 0x10) >> 1) | ((ptemp >> 4) & 0x07)
                    spp = s[ptemp] & 0x0f
                    new_s[idx] = xinv[sp ^ pl] ^ xinv[spp ^ ph] ^ h[idx]
                self.s_prism = new_s
                self.h_prism = new_s[:]
                return

            def rubic_rot():
                p = self.p_prism
                new_p = [0] * 128
                for i in range(4):
                    base_i = i << 5
                    for j in range(4):
                        base = base_i | (j << 3)
                        for k in range(8):
                            idx = base | k
                            if (k & 3) == 0:
                                new_p[idx] = p[idx]
                            elif (k & 3) == 1:
                                new_p[idx] = p[((3 - j) << 5) | (i << 3) | k]
                            elif (k & 3) == 2:
                                new_p[idx] = p[(j << 5) | (i << 3) | k]
                            else:
                                new_p[idx] = p[(j << 5) | ((3 - i) << 3) | k]
                self.p_prism = new_p
                return

            affine_transform()
            k1_swap()
            k2_swap()
            apply_k_dft()
            j_swap()
            apply_j_dft()
            i_swap()
            apply_i_dft()
            nlst()
            rubic_rot()
            return

        def finalize(self):

            def pad_block_from_buffer():
                buf = bytearray(self.buf)
                bit_len = self.msg_len * 8
                buf.append(0x80)
                while (len(buf) % 64) != 56:
                    buf.append(0x00)
                buf.extend(bit_len.to_bytes(8, "big"))
                return [bytes(buf[i:i + 64]) for i in range(0, len(buf), 64)]

            blocks = pad_block_from_buffer()
            for block in blocks:
                self.process_block(block, apply_initial_swap=True)
            return

        def make_digest(self):

            def mark_bits():
                sg = self.SG_TABLES[self.digest_bits]
                marks = [0] * 128
                p = self.p_prism
                for idx in range(128):
                    marks[idx] = sg[p[idx] & 0x03]
                return marks

            marks = mark_bits()
            out = bytearray(self.digest_size)
            bit_num = 0
            byte_num = 0
            for idx in range(128):
                mark = marks[idx]
                cell = self.h_prism[idx]
                for l in range(4):  # noqa: E741
                    if ((1 << l) & mark) != 0:
                        out[byte_num] |= ((cell >> l) & 1) << (7 - bit_num)
                        bit_num += 1
                        if bit_num >= 8:
                            byte_num += 1
                            bit_num = 0
                            if byte_num >= self.digest_size:
                                return bytes(out)
            return bytes(out)

    class SpectralHash128(SpectralHashBase):
        digest_bits = 128

    class SpectralHash160(SpectralHashBase):
        digest_bits = 160

    class SpectralHash192(SpectralHashBase):
        digest_bits = 192

    class SpectralHash224(SpectralHashBase):
        digest_bits = 224

    class SpectralHash256(SpectralHashBase):
        digest_bits = 256

    class SpectralHash288(SpectralHashBase):
        digest_bits = 288

    class SpectralHash320(SpectralHashBase):
        digest_bits = 320

    class SpectralHash352(SpectralHashBase):
        digest_bits = 352

    class SpectralHash384(SpectralHashBase):
        digest_bits = 384

    class SpectralHash416(SpectralHashBase):
        digest_bits = 416

    class SpectralHash448(SpectralHashBase):
        digest_bits = 448

    class SpectralHash480(SpectralHashBase):
        digest_bits = 480

    class SpectralHash512(SpectralHashBase):
        digest_bits = 512

