        @classmethod
        def ensure_tables(cls):
            if hasattr(Hash.WaMMBase, "initial_matrix"):
                return

            def make_primes(count):
                primes = [0]
                candidate = 2
                while len(primes) < count:
                    is_prime = True
                    for prime in primes[1:]:
                        if prime * prime > candidate:
                            break
                        if candidate % prime == 0:
                            is_prime = False
                            break
                    if is_prime:
                        primes.append(candidate)
                    if candidate == 2:
                        candidate = 3
                    else:
                        candidate += 2
                return primes

            base = Hash.WaMMBase.operator_base
            offset = Hash.WaMMBase.operator_offset
            Hash.WaMMBase.initial_matrix = tuple(bytes(((base[j] + offset[i]) & 0xff) for j in range(32)) for i in range(32))
            Hash.WaMMBase.tapping_prime = tuple(make_primes(257))
            return

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.digest_size = self.digest_bits // 8
            self.ensure_tables()
            self.state = [bytearray(row) for row in self.initial_matrix]
            self.buf = bytearray()
            self.msg_len = 0
            self.curr_row = 0
            if data:
                self.update(data)
            return

        def copy(self):
            other = self.__class__()
            other.state = [bytearray(row) for row in self.state]
            other.buf = bytearray(self.buf)
            other.msg_len = self.msg_len
            other.curr_row = self.curr_row
            return other

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            data = bytes(data)
            self.msg_len += len(data)
            self.buf.extend(data)
            while len(self.buf) >= 32:
                block = self.buf[:32]
                del self.buf[:32]
                self.compress(block)
            return self

        def digest(self):
            c = self.copy()
            c.finalize()
            return bytes(c.digest_value)

        def hexdigest(self):
            return self.digest().hex()

        def finalize(self):
            if self.buf:
                block = bytes(self.buf) + (b"\x00" * (32 - len(self.buf)))
                self.compress(block)
                self.buf.clear()
            bit_len = (self.msg_len * 8) % (1 << 256)
            self.compress(bit_len.to_bytes(32, "big"))
            if self.curr_row != 0:
                self.square()
            self.digest_value = self.tap()
            return

        def compress(self, block):
            row = self.state[self.curr_row]
            for i, x in enumerate(block):
                row[i] ^= x
            self.curr_row = (self.curr_row + 1) % 32
            if self.curr_row == 0:
                self.square()
            return

        def square(self):
            base = self.__class__.operator_base
            offset = self.__class__.operator_offset
            matrix = self.state
            round_count = 0
            while round_count < self.rounds:
                col_sum = [0] * 32
                for row in matrix:
                    for j in range(32):
                        col_sum[j] += base[row[j]]
                for j in range(32):
                    col_sum[j] &= 0xff

                out = []
                for row in matrix:
                    row_sum = 0
                    for x in row:
                        row_sum += offset[x]
                    row_sum &= 0xff
                    out.append(bytearray(((row_sum + x) & 0xff) for x in col_sum))
                matrix = out
                round_count += 1
            self.state = matrix
            return

        def tap(self):
            digest_size = self.digest_size
            index = self.digest_bits // 32
            prime_offset = self.__class__.tapping_prime[index]
            prime_multiplier = self.__class__.tapping_prime[index - 2]
            matrix = self.state
            out = bytearray(digest_size)
            for n in range(digest_size):
                r = ((n * prime_multiplier) + prime_offset) % 1024
                out[n] = matrix[r // 32][r % 32]
            return bytes(out)

