        x_size = 16
        capacity_size = 40
        c_words = 5
        rounds = 7
        accumulate_factor = 2
        x_idx_width = 2
        x_idx_mask = 0x03
        mpr_input_width = 10
        mpr_input_mask = 0x03ff
        mix_phase_rounds = 14

