        ("CrcBase", 0, 0x0, 0x0, False, False, 0x0),
        ("Crc8Base", 8, 0x7, 0x0, False, False, 0x0),
        ("Crc16Base", 16, 0x1021, 0x0, False, False, 0x0),
        ("Crc32Base", 32, 0x4c11db7, 0xffffffff, True, True, 0xffffffff),
        ("Crc3Gsm", 3, 0x3, 0x0, False, False, 0x7),
