@register_command
class IsMemoryZeroCommand(GenericCommand):
    """Check if all the memory in the specified range is 0x00, 0xff."""

    _cmdline_ = "is-mem-zero"
    _category_ = "03-e. Memory - Calculation"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("--phys", action="store_true", help="treat ADDRESS as a physical address.")
    parser.add_argument("addr", metavar="ADDRESS", type=AddressUtil.parse_address, help="target address for checking.")
    parser.add_argument("size", metavar="SIZE", type=AddressUtil.parse_address, help="the size for checking.")
    _syntax_ = parser.format_help()

    def __init__(self):
        super().__init__(complete=gdb.COMPLETE_LOCATION)
        return

    def memcheck(self, phys_mode, addr, size):
        page_size = get_pagesize()
        start = addr
        end = addr + size
        is_zero = True
        is_ff = True
        current = addr
        while current < end:
            read_size = min(end - current, page_size)
            try:
                if phys_mode:
                    data = read_physmem(current, read_size)
                else:
                    data = read_memory(current, read_size)
            except (gdb.MemoryError, ValueError, OverflowError):
                err("Read error {:#x}".format(current))
                return
            if data == b"\0" * len(data):
                is_ff = False
            elif data == b"\xff" * len(data):
                is_zero = False
            else:
                is_zero = False
                is_ff = False
            if is_zero is False and is_ff is False:
                end = current + read_size
                break
            current += read_size

        if is_zero:
            info("{:#x} - {:#x} is {:s}".format(start, end, Color.colorify("All 0x00", "bold yellow")))
            return

        if is_ff:
            info("{:#x} - {:#x} is {:s}".format(start, end, Color.colorify("All 0xFF", "bold yellow")))
            return

        # find non-zero address
        for i, d in enumerate(data):
            if d != 0:
                found_addr = ProcessMap.lookup_address(current + i)
                break
        else:
            warn("Scan failed to find non-zero byte unexpectedly")
            return
        info("{:#x} - {:#x} is {:s}".format(start, end, Color.colorify("NON-ZERO", "bold red")))
        info("Around {!s} is NON-ZERO".format(found_addr))
        info("Length of 0x00: {:d}".format(found_addr.value - start))
        return

    @parse_args
    @only_if_gdb_running
    def do_invoke(self, args):
        if args.phys:
            if not is_qemu_system():
                err("Unsupported `--phys` option in this gdb mode")
                return

        if args.size == 0:
            info("The size is zero, maybe wrong")

        self.memcheck(args.phys, args.addr, args.size)
        return


@register_command
class StringLengthCommand(GenericCommand):
    """Detect the length of the string."""

    _cmdline_ = "strlen"
    _category_ = "03-e. Memory - Calculation"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("--phys", action="store_true", help="treat ADDRESS as a physical address.")
    parser.add_argument("addr", metavar="ADDRESS", type=AddressUtil.parse_address,
                        help="target address for checking.")
    _syntax_ = parser.format_help()

    def check(self, phys_mode, addr):
        count = 0
        current = addr
        while True:
            # calc read_size
            if current & get_pagesize_mask_low():
                read_size = align_to_pagesize(current) - current
            else:
                read_size = get_pagesize()
            # read
            try:
                if phys_mode:
                    data = read_physmem(current, read_size)
                else:
                    data = read_memory(current, read_size)
            except (gdb.MemoryError, ValueError, OverflowError):
                err("Read error {:#x}".format(addr))
                return None
            # count
            idx = data.find(b"\0")
            if idx != -1:
                return count + idx
            # goto next
            count += len(data)
            current += len(data)
        return None

    @parse_args
    @only_if_gdb_running
    def do_invoke(self, args):
        if args.phys:
            if not is_qemu_system():
                err("Unsupported `--phys` option in this gdb mode")
                return

        length = self.check(args.phys, args.addr)
        if length is None:
            return

        gef_print("{:s} bytes".format(Color.colorify_hex(length, "bold")))
        return


@register_command
class SequenceLengthCommand(GenericCommand):
    """Detect consecutive length of the same sequence."""

    _cmdline_ = "seq-length"
    _category_ = "03-e. Memory - Calculation"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("--phys", action="store_true", help="treat ADDRESS as a physical address.")
    parser.add_argument("addr", metavar="ADDRESS", type=AddressUtil.parse_address,
                        help="target address for checking.")
    parser.add_argument("unit", metavar="UNIT", nargs="?", type=AddressUtil.parse_address, default=1,
                        help="the size for a target value (default: %(default)s).")
    _syntax_ = parser.format_help()

    def __init__(self):
        super().__init__(complete=gdb.COMPLETE_LOCATION)
        return

    def check(self, phys_mode, addr, unit):
        target = None
        data = b""
        count = 0
        current = addr
        while True:
            # calc read_size
            if current & get_pagesize_mask_low():
                read_size = align_to_pagesize(current) - current
            else:
                read_size = get_pagesize()
            while read_size < unit:
                read_size += get_pagesize()
            # read
            try:
                if phys_mode:
                    data += read_physmem(current, read_size)
                else:
                    data += read_memory(current, read_size)
            except (gdb.MemoryError, ValueError, OverflowError):
                err("Read error {:#x}".format(addr))
                return None
            # init target
            if target is None:
                target = data[:unit]
            # count
            for elem in slicer(data, unit):
                if elem == target:
                    # Equal in length and content
                    count += 1
                elif len(elem) == len(target):
                    # The length is sufficient, but the content is different.
                    return count, target
            # Consider the case where the length of the final element is insufficient
            if len(elem) != len(target):
                data = elem
            else:
                data = b""
            # goto next
            current += read_size
        return None

    @parse_args
    @only_if_gdb_running
    def do_invoke(self, args):
        if args.phys:
            if not is_qemu_system():
                err("Unsupported `--phys` option in this gdb mode")
                return

        if args.unit >= 0x100_000:
            err("Too large unit size")
            return

        addr = ProcessMap.lookup_address(args.addr)
        info("Check from {!s} in units of {:s} bytes".format(
            addr, Color.colorify_hex(args.unit, "bold"),
        ))

        ret = self.check(args.phys, args.addr, args.unit)
        if ret is None:
            return

        count, target = ret
        size = args.unit * count
        end = ProcessMap.lookup_address(args.addr + size)

        if len(target) > 0x100:
            target = target[:0x100] + b"..."

        gef_print("{!s} - {!s} is same value".format(addr, end))
        gef_print("{!s} is found {:s} times, {:s} bytes".format(
            target,
            Color.colorify_hex(count, "bold"),
            Color.colorify_hex(size, "bold"),
        ))
        return


@register_command
class MultiLineCommand(GenericCommand):
    """Execute multiple GDB commands in sequence."""

    _cmdline_ = "multi-line"
    _category_ = "01-c. Debugging Support - Basic Command Extension"
    _aliases_ = ["ml"]

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("cmd", metavar="GDB_CMD;", nargs="+", help="semicolon-separated gdb command.")
    _syntax_ = parser.format_help()

    _example_ = [
        "{0:s} x/4xg $rax; x/4xg $rbx",
        "{0:s} x/4xg $rax; -; x/4xg $rbx         # `-`:   newline separator",
        "{0:s} x/4xg $rax; --; x/4xg $rbx        # `--`:  bold white line (`-`) separator",
        "{0:s} x/4xg $rax; ---; x/4xg $rbx       # `---`: bold white line (`=`) separator",
        "{0:s} x/4xg $rax; -t TAG; x/4xg $rbx    # `-t TAG`:   newline separator with TAG",
        "{0:s} x/4xg $rax; --t TAG; x/4xg $rbx   # `--t TAG`:  bold white line (`-`) separator with TAG",
        "{0:s} x/4xg $rax; ---t TAG; x/4xg $rbx  # `---t TAG`: bold white line (`=`) separator with TAG",
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    def __init__(self):
        super().__init__(complete=gdb.COMPLETE_COMMAND)
        return

    def do_command(self, commands):
        if commands == []:
            return True

        # make comnand string
        cmd = ""
        for c in commands:
            if "\\" in c or " " in c:
                cmd += " " + repr(c)
            else:
                cmd += " " + c
        cmd = cmd.strip()

        # blank command, so skip
        if cmd.replace(" ", "") == "":
            return True

        # separator 1
        if cmd == "-":
            gef_print("")
            return True
        if cmd.startswith("-t"):
            gef_print(Color.boldify(cmd[2:].strip()))
            return True

        # separator 2
        if cmd == "--":
            gef_print(titlify("", color="bold"))
            return True
        if cmd.startswith("--t"):
            gef_print(titlify(cmd[3:].strip(), color="bold", msg_color="bold"))
            return True

        # separator 3
        if cmd == "---":
            gef_print(titlify("", color="bold", horizontal_line="="))
            return True
        if cmd.startswith("---t"):
            gef_print(titlify(cmd[4:].strip(), color="bold", msg_color="bold", horizontal_line="="))
            return True

        gef_print(titlify(cmd))
        try:
            gdb.execute(cmd)
        except gdb.error as e:
            gef_print(e)
            return False # fail
        return True

    # Need not @parse_args because argparse can't stop interpreting options for user specified command.
    def do_invoke(self, argv):
        if len(argv) == 1 and argv[0] == "-h":
            self.usage()
            return

        commands = []
        for arg in argv:
            if arg.endswith(";"):
                commands.append(arg.rstrip(";").lstrip(";"))
                if self.do_command(commands) is False:
                    break
                commands = []
            elif arg.startswith(";"):
                if self.do_command(commands) is False:
                    break
                commands = []
                commands.append(arg.lstrip(";"))
            elif arg == ";":
                if self.do_command(commands) is False:
                    break
                commands = []
            else:
                commands.append(arg)
        else:
            self.do_command(commands)
        return


@register_command
class TimeCommand(GenericCommand):
    """Measure the time of the GDB command."""

    _cmdline_ = "time"
    _category_ = "01-c. Debugging Support - Basic Command Extension"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("cmd", metavar="GDB_CMD", help="gdb command.")
    parser.add_argument("arg", metavar="ARG", nargs="*", help="arguments of gdb command.")
    _syntax_ = parser.format_help()

    def __init__(self):
        super().__init__(complete=gdb.COMPLETE_COMMAND)
        return

    # Need not @parse_args because argparse can't stop interpreting options for user specified command.
    def do_invoke(self, argv):
        if len(argv) == 1 and argv[0] == "-h":
            self.usage()
            return

        start_time_real = time.perf_counter()
        start_time_proc = time.process_time()

        cmd = ""
        for c in argv:
            if "\\" in c or " " in c:
                cmd += " " + repr(c)
            else:
                cmd += " " + c
        cmd = cmd.strip()

        gef_print(titlify(cmd))
        try:
            gdb.execute(cmd)
        except gdb.error:
            exc_type, exc_value, exc_traceback = sys.exc_info()
            gef_print(exc_value)
            return

        end_time_real = time.perf_counter()
        end_time_proc = time.process_time()
        gef_print(titlify("time elapsed"))
        gef_print("Real: {:.3f} s".format(end_time_real - start_time_real))
        gef_print("CPU:  {:.3f} s".format(end_time_proc - start_time_proc))
        return


@register_command
class SaveOutputCommand(GenericCommand):
    """Save the command outputs."""

    _cmdline_ = "saveo"
    _category_ = "07-f. Misc - Diff"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("cmd", metavar="GDB_CMD", help="gdb command.")
    parser.add_argument("arg", metavar="ARG", nargs="*", help="arguments of gdb command.")
    _syntax_ = parser.format_help()

    _note_ = [
        "Saving the output of external commands is unsupported (e.g., pipe, !ls).",
    ]
    _note_ = "\n".join(_note_)

    def __init__(self):
        super().__init__(prefix=False, complete=gdb.COMPLETE_COMMAND)
        return

    # Need not @parse_args because argparse can't stop interpreting options for user specified command.
    def do_invoke(self, argv):
        if len(argv) == 1 and argv[0] == "-h":
            self.usage()
            return

        # get settings
        always_no_pager = Config.get_gef_setting("gef.always_no_pager")

        # parse command
        cmd = ""
        for c in argv:
            if "\\" in c or " " in c:
                cmd += " " + repr(c)
            else:
                cmd += " " + c
        cmd = cmd.strip()
        if not cmd:
            self.usage()
            return

        # do the command
        try:
            Config.set_gef_setting("gef.always_no_pager", True) # change temporarily
            current_output = Color.remove_color(gdb.execute(cmd, to_string=True))
            Config.set_gef_setting("gef.always_no_pager", always_no_pager) # revert settings
        except gdb.error:
            Config.set_gef_setting("gef.always_no_pager", always_no_pager) # revert settings
            exc_type, exc_value, exc_traceback = sys.exc_info()
            gef_print(exc_value)
            return

        # remove clear_screen code
        if current_output.startswith("\x1b[H\x1b[2J"):
            current_output = current_output[7:]

        # save
        dloc = os.path.join(GEF_TEMP_DIR, "diff")
        if not os.path.exists(dloc):
            os.mkdir(dloc)
        tmp_fd, tmp_path = GefUtil.mkstemp(dir=dloc, suffix=".txt")
        os.fdopen(tmp_fd, "w").write(current_output)
        open(tmp_path[:-4] + ".cmd", "w").write(cmd)
        info("The output is saved to {:s}.(txt|cmd)".format(tmp_path[:-4]))

        # print
        gef_print(current_output, less=not always_no_pager)
        return


@register_command
class DiffOutputCommand(GenericCommand):
    """The base command to diff of the command outputs."""

    _cmdline_ = "diffo"
    _category_ = "07-f. Misc - Diff"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    if (sys.version_info.major, sys.version_info.minor) >= (3, 7):
        subparsers = parser.add_subparsers(title="command", required=True)
    else:
        subparsers = parser.add_subparsers(title="command")
    subparsers.add_parser("colordiff")
    subparsers.add_parser("git-diff")
    subparsers.add_parser("list")
    subparsers.add_parser("clear")
    _syntax_ = parser.format_help()

    def __init__(self, *args, **kwargs):
        prefix = kwargs.get("prefix", True)
        super().__init__(prefix=prefix)
        self.add_setting("colordiff_option", "--left-column -y -W 200", "The option used by colordiff.")
        return

    def get_saved_files(self):
        dloc = os.path.join(GEF_TEMP_DIR, "diff")
        if not os.path.exists(dloc):
            return []

        saved_files = []
        for path in GefUtil.walk(dloc):
            if not path.endswith(".txt"):
                continue
            saved_files.append(path)

        return sorted(saved_files, key=lambda x:os.path.getmtime(x[:-4] + ".cmd"))

    @parse_args
    def do_invoke(self, args):
        self.usage()
        return


@register_command
class DiffOutputColordiffCommand(DiffOutputCommand):
    """Diff the two outputs by colordiff."""

    _cmdline_ = "diffo colordiff"
    _category_ = "07-f. Misc - Diff"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("n1", metavar="N", type=int, help="first diff target got from `diffo list`.")
    parser.add_argument("n2", metavar="M", type=int, help="second diff target got from `diffo list`.")
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    _syntax_ = parser.format_help()

    _example_ = [
        "{0:s} 0 1  # diff between 0 and 1",
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    _note_ = [
        "You can check the available indexes with `diffo list`.",
    ]
    _note_ = "\n".join(_note_)

    def __init__(self):
        super().__init__(prefix=False)
        return

    def make_diff(self, path1, path2):
        option = Config.get_gef_setting("diffo.colordiff_option")
        cmd = "{:s} {:s} '{:s}' '{:s}'".format(self.colordiff, option, path1, path2)
        result = subprocess.getoutput(cmd)
        return result

    @parse_args
    def do_invoke(self, args):
        try:
            self.colordiff = GefUtil.which("colordiff")
        except FileNotFoundError as e:
            err("{}".format(e))
            return

        saved_files = self.get_saved_files()
        try:
            f1 = saved_files[args.n1]
            f2 = saved_files[args.n2]
        except IndexError:
            err("Out of index error")
            return

        if not os.path.exists(f1):
            err("Could not find {:s}".format(f1))
            return
        if not os.path.exists(f2):
            err("Could not find {:s}".format(f2))
            return

        output = self.make_diff(f1, f2)

        if output:
            gef_print(output, less=not args.no_pager)
        else:
            gef_print("No difference")
        return


