    def pagewalk_L2(self):
        self.quiet_add_out(titlify("Level 2 Entry"))
        L2E = []
        PTE = []
        COUNT = 0
        bit_shift = sum([
            self.bits["L1_BITS"],
            self.bits["OFFSET"],
        ])
        for va_base, table_base, parent_flags in self.TABLES:
            entries = self.read_physmem_cache(table_base, 2 ** self.bits["L2_BITS"] * self.bits["ENTRY_SIZE"])
