        self.quiet_info_add_out("Number of entries: {:d}".format(COUNT))
        self.quiet_info_add_out("L2 Entry (2MB): {:d}".format(len(L2E)))
        self.quiet_info_add_out("Invalid entries: {:d}".format(COUNT - len(L2E)))
