@register_command
class BytearrayCommand(GenericCommand):
    """Generate a bytearray to be compared with possible badchars (ported from mona.py)."""

    _cmdline_ = "bytearray"
    _category_ = "07-c. Misc - Generation"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-b", dest="badchars", default=[], action="append", help="characters to exclude.")
    parser.add_argument("-d", dest="dump", action="store_true", help="dump to /tmp/gef/bytearray.{txt,bin}.")
    _syntax_ = parser.format_help()

    _example_ = [
        "{0:s} -b 414243 -b 51-53 -b 61..63",
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    def expand_hex(self, x):
        """4142..45 -> 4142434445"""
        if ".." not in x:
            return x

        if len(x) < 6:
            return False

        if "..." in x:
            return False

        while ".." in x:
            pos = x.find("..")
            if pos % 2 != 0:
                return False

            if pos < 2 or len(x) - 4 < pos:
                return False

            xa, xb = int(x[pos - 2:pos], 16), int(x[pos + 2:pos + 4], 16)
            if xa >= xb:
                return False
            middle = "".join("{:02x}".format(c) for c in range(xa, xb))
            x = x[:pos - 2] + middle + x[pos + 2:]
        return x

    @parse_args
    def do_invoke(self, args):
        excluded = set()
        for b in args.badchars:
            b = b.lower().replace("-", "..")

            if not re.match(r"[0-9a-f]+", b):
                err("{:s} is not valid hex (not match `[0-9a-f]+`)".format(b))
                return

            if (len(b) % 2) != 0:
                err("{:s} is not valid hex (odd length)".format(b))
                return

            eb = self.expand_hex(b)
            if eb is False:
                err("{:s} is not valid hex (failed to expand `..`)".format(b))
                return

            excluded |= {int(c, 16) for c in slicer(eb, 2)}

        info("Generating table, excluding {:d} bad chars...".format(len(excluded)))

        included = sorted(set(range(0, 256)) - excluded)

        if len(included) == 0:
            info("Nothing to dump")
            return

        info("Dumping table")
        outt_arr = []
        outb_arr = []
        for c in included:
            outt_arr.append("\\x{:02x}".format(c))
            outb_arr.append(bytes([c]))

        bytesperline = 32
        outt = ""
        for s in slicer(outt_arr, bytesperline):
            outt += '"{:s}"\n'.format("".join(s))
        outb = b"".join(outb_arr)

        gef_print(outt.rstrip())

        if args.dump:
            arrayfile = os.path.join(GEF_TEMP_DIR, "bytearray.txt")
            open(arrayfile, "w").write(outt)
            info("Done, wrote {:d} bytes to file {:s}".format(len(outt_arr), arrayfile))
            binfilename = os.path.join(GEF_TEMP_DIR, "bytearray.bin")
            open(binfilename, "wb").write(outb)
            info("Binary output saved in {:s}".format(binfilename))
        return


@register_command
class SixelMemoryCommand(GenericCommand):
    """Show image (png, jpg, bmp, etc.) to terminal by imagemagick."""

    _cmdline_ = "sixel-memory"
    _category_ = "03-g. Memory - Investigation"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("location", metavar="LOCATION", type=AddressUtil.parse_address,
                        help="start address of the image.")
    parser.add_argument("size", metavar="SIZE", nargs="?", type=AddressUtil.parse_address,
                        help="the size of the image.")
    parser.add_argument("-b", "--decode-barcode", action="store_true", help="decode barcode if found.")
    _syntax_ = parser.format_help()

    def get_jpg_size(self, start_address):
        # parse header
        pos = start_address + 2
        while True:
            marker = read_memory(pos, 2)
            pos += 2
            if marker[0] != 0xff:
                return None
            length = struct.unpack(">H", read_memory(pos, 2))[0]
            pos += length
            if marker == b"\xff\xda":
                break
        header_size = pos - start_address

        # saerch EOI
        if pos % get_pagesize():
            read_size = get_pagesize() - (pos % get_pagesize())
        else:
            read_size = get_pagesize()

        MAX_FILE_SIZE = get_pagesize() * 4096 # 16MB
        jpg_data = b"" # except header
        while len(jpg_data) < MAX_FILE_SIZE:
            try:
                jpg_data += read_memory(pos, read_size)
            except (gdb.MemoryError, MemoryError):
                return None
            if b"\xff\xd9" in jpg_data:
                image_data_size = jpg_data.index(b"\xff\xd9") + 2
                return header_size + image_data_size
            pos += read_size
            read_size = get_pagesize()
        return None

    def get_png_size(self, start_address):
        pos = start_address

        if start_address % get_pagesize():
            read_size = get_pagesize() - (start_address % get_pagesize())
        else:
            read_size = get_pagesize()

        MAX_FILE_SIZE = get_pagesize() * 4096 # 16MB
        png_data = b""
        while len(png_data) < MAX_FILE_SIZE:
            try:
                png_data += read_memory(pos, read_size)
            except (gdb.MemoryError, MemoryError):
                return None
            if b"IEND" in png_data:
                image_data_size = png_data.index(b"IEND") + 4
                return image_data_size + 4 # crc
            pos += read_size
            read_size = get_pagesize()
        return None

    def decode_barcode(self, path):
        try:
            import PIL.Image
            import pyzbar.pyzbar
        except ImportError as e:
            err("Import error {}".format(e))
            return

        image = PIL.Image.open(path)
        decoded = pyzbar.pyzbar.decode(image)
        if decoded == []:
            err("Not found")
            return

        for i, data in enumerate(decoded):
            gef_print("[{}] type:{} data:{}".format(i, data.type, data.data))
        return

    @parse_args
    @only_if_gdb_running
    def do_invoke(self, args):
        try:
            convert_command = GefUtil.which("convert") # imagemagick
        except FileNotFoundError as e:
            err("{}".format(e))
            return

        if not is_valid_addr(args.location):
            err("Memory read error")
            return

        try:
            if args.size is not None:
                size = args.size
            elif read_memory(args.location, 2) == b"BM": # BMP
                size = read_int32_from_memory(args.location + 2)
            elif read_memory(args.location, 2) == b"\xff\xd8": # JPG
                size = self.get_jpg_size(args.location)
            elif read_memory(args.location, 4) == b"\x89PNG": # PNG
                size = self.get_png_size(args.location)
            else:
                err("Specify the SIZE parameter")
                return
            data = read_memory(args.location, size)
        except (gdb.MemoryError, MemoryError, TypeError):
            err("Memory read error")
            return

        tmp_fd, tmp_path = GefUtil.mkstemp(prefix="sixel-memory", suffix=".img")
        with os.fdopen(tmp_fd, "wb") as fdw:
            fdw.write(data)
        GefUtil.os_system("{!r} {!r} sixel:-".format(convert_command, tmp_path))

        if args.decode_barcode:
            self.decode_barcode(tmp_path)

        os.unlink(tmp_path)
        return


@register_command
class FrequencyAnalysisCommand(GenericCommand, BufferingOutput):
    """Visualize the frequency of occurrence of each byte."""

    _cmdline_ = "freq-analysis"
    _category_ = "03-g. Memory - Investigation"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("location", metavar="LOCATION", type=AddressUtil.parse_address,
                        help="start address to analyze.")
    parser.add_argument("size", metavar="SIZE", nargs="?", type=AddressUtil.parse_address,
                        help="the size to analyze; if omitted, calculated from the end of the area.")
    parser.add_argument("-e", "--exclude", action="append", default=[], type=lambda x: int(x, 16),
                        help="exclude character in hex.")
    parser.add_argument("-a", "--ascii-gradation", action="store_true",
                        help="show heatmap with ascii range word.")
    parser.add_argument("-t", "--topn", type=AddressUtil.parse_address, default=16,
                        help="outputs the top N numbers. (default: %(default)s)")
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    _syntax_ = parser.format_help()

    _example_ = [
        "{0:s} $rax 0x1000               # ragne: $rax ~ $rax + 0x1000",
        "{0:s} $rax                      # range: $rax ~ end of the region to which $rax belongs",
        "{0:s} $rax 0x1000 -a            # use ascii compatible result",
        "{0:s} $rax 0x1000 -e 00 -e 01   # exclude some characters",
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    def hist256(self, data):
        h = [0] * 256
        for b in data:
            if b in self.args.exclude:
                continue
            h[b] += 1
        return h

    def print_heatmap(self, h):
        if self.args.ascii_gradation:
            GRAD = ".:-=+*$#%@"
        else:
            GRAD = u" _\u2582\u2583\u2584\u2585\u2586\u2587\u2588"

        def scale_to_grad(value, vmax):
            if vmax <= 0:
                return GRAD[0]
            idx = int((value * (len(GRAD) - 1)) / vmax)
            return GRAD[idx]

        legend = "Legend: [few] {!r} [many]".format(GRAD)
        self.out.append(legend)

        col_labels = "   " + " ".join(f"{x:X}" for x in range(16))
        self.out.append(col_labels)

        vmax = max(h) if h else 0
        for hi in range(16):
            line = [f"{hi:X} "]
            for lo in range(16):
                idx = (hi << 4) | lo
                ch = scale_to_grad(h[idx], vmax)
                line.append(ch * 1)
            self.out.append(" ".join(line))

        self.out.append(f"Total bytes: {sum(h)}  Max bin count: {vmax}")
        self.out.append("")
        return

    def top_n(self, h, n):
        order = sorted(range(256), key=lambda b: (-h[b], b))
        rows = []
        for i in range(min(n, 256)):
            b = order[i]
            c = h[b]
            if c == 0:
                break
            rows.append((b, c))
        return rows

    def print_top_n(self, h, n):
        rows = self.top_n(h, n)
        if not rows:
            self.out.append("No data.")
            return
        maxc = rows[0][1]
        width = 40
        self.out.append("Top frequencies:")
        for b, c in rows:
            bar_len = int(width * c / maxc) if maxc > 0 else 0
            bar = "#" * bar_len
            self.out.append(f"  {b:02X}: {c:>10d} |{bar}")
        return

    @parse_args
    @only_if_gdb_running
    def do_invoke(self, args):

        if args.size is None:
            loc = ProcessMap.lookup_address(args.location)
            if loc.valid:
                size = loc.section.page_end - args.location
            else:
                err("The size could not be calculated")
                return
        else:
            size = args.size

        try:
            data = read_memory(args.location, size)
        except (gdb.MemoryError, MemoryError, TypeError):
            err("Memory read error")
            return

        self.out = []
        hist = self.hist256(data)
        self.print_heatmap(hist)
        self.print_top_n(hist, self.args.topn)

        self.print_output()
        return


@register_command
class VisualDumpCommand(GenericCommand):
    """Visualize memory data like an image."""

    _cmdline_ = "vdump"
    _category_ = "03-g. Memory - Investigation"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("location", metavar="LOCATION", type=AddressUtil.parse_address,
                        help="start address to dump.")
    parser.add_argument("size", metavar="SIZE", nargs="?", type=AddressUtil.parse_address,
                        help="the size to dump; if omitted, calculated from the end of the area.")
    parser.add_argument("-d", "--disable-autoscale", action="store_true",
                        help="disable autoscaling to fit the terminal.")
    parser.add_argument("-w", "--width", type=AddressUtil.parse_address,
                        help="the number of wrap bytes. (default: sqrt(len(content)))")
    parser.add_argument("-c", "--color", choices=("r", "g", "b"),
                        help="convert the grayscale tone to either r,g,b.")
    parser.add_argument("-n", "--negate", action="store_true",
                        help="negate the grayscale tone.")
    parser.add_argument("-A", "--auto-width-inclement", action="store_true",
                        help="repeat the display while shifting the interpretation of the width.")
    parser.add_argument("-Ab", "--auto-inclement-begin-width", type=AddressUtil.parse_address, default=16,
                        help="auto inclement begin width. (default: %(default)s)")
    parser.add_argument("-Ae", "--auto-inclement-end-width", type=AddressUtil.parse_address,
                        help="auto inclement end width. (default: min(len(data) // begin_width, 512)")
    parser.add_argument("-As", "--auto-inclement-step-width", type=AddressUtil.parse_address, default=2,
                        help="auto inclement step width. (default: %(default)s)")
    _syntax_ = parser.format_help()

    _example_ = [
        "{0:s} $rsp 0x1000                                 # width =~ sqrt(len(content))",
        "{0:s} -w 0x100 $rsp 0x1000                        # use fixed width",
        "{0:s} -c r $rsp 0x1000                            # change color: gray -> red",
        "{0:s} -c r -n $rsp 0x1000                         # change color: gray -> red and negate",
        "{0:s} -A $rsp 0x1000                              # bruteforce the width",
        "{0:s} -A -Ab 0x100 -Ae 0x200 -As 0x10 $rsp 0x1000 # bruteforce the width (w=0x100; w<0x200; w+=0x10)",
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    def make_command_line(self, img_width, img_height, tmp_path):
        command_options = [
            "-size {:d}x{:d}".format(img_width, img_height),
            "-depth 8",
        ]

        if not self.args.disable_autoscale:
            # terminal size (number of characters)
            term_height, term_width = GefUtil.get_terminal_size()
            # it's too tight, so make it slightly smaller.
            term_width = int(term_width * 0.95)
            term_height = int(term_height * 0.95)
            # number of pixels per character
            font_width_px = 6
            font_height_px = 12
            # pixel dimensions of the terminal
            term_width_px = term_width * font_width_px
            term_height_px = term_height * font_height_px
            # scaling factor to fit the terminal
            scale_width = term_width_px * 100 / img_width
            scale_height = term_height_px * 100 / img_height
            resize_scale = min(scale_height, scale_width)
            # convert option
            command_options.extend([
                "-filter Box",
                "-resize {:d}%".format(int(resize_scale)),
            ])

        if self.args.color == "r":
            command_options.append("-colorspace Gray -colorize 0,100,100")
        elif self.args.color == "g":
            command_options.append("-colorspace Gray -colorize 100,0,100")
        elif self.args.color == "b":
            command_options.append("-colorspace Gray -colorize 100,100,0")

        if self.args.negate:
            command_options.append("-negate")

        cmd = "{!r} {:s} GRAY:{!r} sixel:-".format(
            GefUtil.which("convert"),
            " ".join(command_options),
            tmp_path,
        )
        return cmd

    @parse_args
    @only_if_gdb_running
    def do_invoke(self, args):
        try:
            GefUtil.which("convert") # imagemagick
        except FileNotFoundError as e:
            err("{}".format(e))
            return

        if args.size is None:
            loc = ProcessMap.lookup_address(args.location)
            if loc.valid:
                size = loc.section.page_end - args.location
            else:
                err("The size could not be calculated")
                return
        else:
            size = args.size

        try:
            data = read_memory(args.location, size)
        except (gdb.MemoryError, MemoryError, TypeError):
            err("Memory read error")
            return

        if args.width and args.width > 0:
            img_width = args.width
        else:
            img_width = int(math.sqrt(len(data)))
        while len(data) % img_width:
            data += b"\0"
        img_height = len(data) // img_width

        tmp_fd, tmp_path = GefUtil.mkstemp(prefix="vhexdump", suffix=".raw")
        with os.fdopen(tmp_fd, "wb") as fdw:
            fdw.write(data)

        if args.auto_width_inclement:
            # if the width is too large, processing will be slow
            min_width = args.auto_inclement_begin_width
            if args.auto_inclement_end_width is not None:
                max_width = args.auto_inclement_end_width
            else:
                max_width = min(len(data) // min_width, 512)
            step = args.auto_inclement_step_width
            # processing while changing the width
            for img_width in range(min_width, max_width + 1, step):
                img_height = len(data) // img_width
                cmd = self.make_command_line(img_width, img_height, tmp_path)
                info(cmd)
                # Ctrl+C is consumed by os.system, so it cannot escape from the python loop.
                # Therefore, it is judged by the execution result.
                e = GefUtil.os_system(cmd)
                if e != 0:
                    break
        else:
            cmd = self.make_command_line(img_width, img_height, tmp_path)
            info(cmd)
            GefUtil.os_system(cmd)

        os.unlink(tmp_path)
        return


@register_command
class FiletypeMemoryCommand(GenericCommand):
    """Scan memory by file and magika."""

    _cmdline_ = "filetype-memory"
    _category_ = "03-g. Memory - Investigation"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("address", metavar="ADDRESS", type=AddressUtil.parse_address,
                        help="target address.")
    parser.add_argument("end_address", metavar="END_ADDRESS", nargs="?", type=AddressUtil.parse_address,
                        help="target end address. (default: the end of section of ADDRESS)")
    _syntax_ = parser.format_help()

    def filetype_memory(self, start_address, end_address, size):
        try:
            data = read_memory(start_address, size)
        except gdb.MemoryError:
            err("Memory read error")
            return

        dumpfile_name = "filetype_{:#x}-{:#x}.dat".format(start_address, end_address)
        filepath = os.path.join(GEF_TEMP_DIR, dumpfile_name)
        with open(filepath, "wb") as fdw:
            fdw.write(data)

        try:
            gef_print(titlify("file {!r}".format(filepath)))
            file_command = GefUtil.which("file")
            GefUtil.os_system("{!r} {!r}".format(file_command, filepath))
        except FileNotFoundError as e:
            warn("{}".format(e))

        try:
            gef_print(titlify("magika {!r}".format(filepath)))
            magika_command = GefUtil.which("magika")
            GefUtil.os_system("{!r} {!r}".format(magika_command, filepath))
        except FileNotFoundError as e:
            warn("{}".format(e))

        os.unlink(filepath)
        return

    @parse_args
    @only_if_gdb_running
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware"))
    def do_invoke(self, args):
        if not is_valid_addr(args.address):
            err("Memory read error")
            return

        try:
            start_address = args.address
            if args.end_address is not None:
                size = args.end_address - args.address
            else:
                section = ProcessMap.lookup_address(args.address).section
                size = section.page_end - args.address
            end_address = start_address + size
        except (AttributeError, ValueError):
            self.usage()
            return

        self.filetype_memory(start_address, end_address, size)
        return


@register_command
class BinwalkMemoryCommand(GenericCommand):
    """Scan memory by binwalk."""

    _cmdline_ = "binwalk-memory"
    _category_ = "03-g. Memory - Investigation"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-f", "--filter", action="append", type=re.compile, default=[],
                        help="REGEXP include filter.")
    parser.add_argument("-e", "--exclude", action="append", type=re.compile, default=[],
                        help="REGEXP exclude filter.")
    parser.add_argument("-m", "--maxsize", type=AddressUtil.parse_address, default=0x1000_0000,
                        help="maximum size of a section to be dumped. (default: 256 MB)")
    parser.add_argument("-c", "--commit", action="store_true", help="actually perform binwalk.")
    _syntax_ = parser.format_help()

    def memory_binwalk(self):
        import binwalk

        maps = ProcessMap.get_process_maps_exclude_special_regions(allow_vdso=True)
        if maps is None:
            err("Failed to get maps")
            return

        addr_len = current_arch.ptrsize * 2
        for entry in maps:
            start = entry.page_start
            end = entry.page_end
            perm = str(entry.permission)

            if entry.size > self.args.maxsize:
                continue

            if not entry.path.startswith(("[", "<")):
                path = os.path.basename(entry.path)
            else:
                path = entry.path
                path = path.replace("[", "").replace("]", "") # consider [heap], [stack], [vdso]
                path = path.replace("<", "").replace(">", "") # consider <tls-th1>, <explored>
            path = path.replace(" ", "_") # consider deleted case. e.g., /path/to/file (deleted)

            dumpfile_name = "binwalk-{:0{}x}-{:0{}x}_{:s}_{:s}.raw".format(
                start, addr_len, end, addr_len, perm, path,
            )

            if self.args.filter and not any(filt.search(dumpfile_name) for filt in self.args.filter):
                continue

            if self.args.exclude and any(ex.search(dumpfile_name) for ex in self.args.exclude):
                continue

            filepath = os.path.join(GEF_TEMP_DIR, dumpfile_name)

            if self.args.commit:
                gef_print(titlify("{:#x}-{:#x} [{}] {:s}".format(
                    entry.page_start, entry.page_end, entry.permission, entry.path,
                )))
                try:
                    data = read_memory(start, end - start)
                except gdb.MemoryError:
                    continue
                with open(filepath, "wb") as fdw:
                    fdw.write(data)
                binwalk.scan(filepath, signature=True)
                os.unlink(filepath)
            else:
                gef_print(dumpfile_name)

        if not self.args.commit:
            warn('This dry run mode skips executing binwalk; add "--commit" to proceed')
        return

    @parse_args
    @only_if_gdb_running
    @exclude_specific_gdb_mode(mode=("qemu-system", "kgdb", "vmware"))
    @ModuleLoader.load_binwalk
    def do_invoke(self, args):
        self.memory_binwalk()
        return


@register_command
class BincompareCommand(GenericCommand, BufferingOutput):
    """Compare an binary file with the memory position looking for badchars."""

    _cmdline_ = "bincompare"
    _category_ = "03-c. Memory - Compare"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("filename", metavar="FILENAME", help="specifies the binary file to be compared.")
    parser.add_argument("address", metavar="ADDRESS", type=AddressUtil.parse_address,
                        help="specifies the memory address.")
    parser.add_argument("size", metavar="SIZE", nargs="?", type=AddressUtil.parse_address,
                        help="specifies the size.")
    parser.add_argument("--file-offset", type=AddressUtil.parse_address, default=0,
                        help="specifies the file offset.")
    parser.add_argument("-f", "--full", action="store_true", help="display the same line without omitting.")
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    _syntax_ = parser.format_help()

    def __init__(self):
        super().__init__(complete=gdb.COMPLETE_FILENAME)
        return

    def compare(self, from1data, from2data, size):
        diff_found = False
        asterisk = False

        hex_pad_len = {
            1: 37,
            2: 35,
            3: 32,
            4: 30,
            5: 27,
            6: 25,
            7: 22,
            8: 20,
            9: 17,
            10: 15,
            11: 12,
            12: 9,
            13: 7,
            14: 5,
            15: 2,
            16: 0,
        }

        width = len(hex(size))

        for pos in range(0, size, 16):
            # determining continuity
            f1_bin = from1data[pos : pos + 16]
            f2_bin = from2data[pos : pos + 16]
            if not self.args.full:
                if f1_bin == f2_bin:
                    if asterisk is False:
                        self.out.append("*")
                        asterisk = True
                    continue

            diff_found = True
            asterisk = False

            # coloring
            f1_hex = []
            f2_hex = []
            f1_ascii = []
            f2_ascii = []
            for i in range(min(len(f1_bin), 16)):
                if f1_bin[i] == f2_bin[i]:
                    color_func = lambda x: x
                else:
                    color_func = Color.boldify
                f1_hex.append(color_func("{:02x}".format(f1_bin[i])))
                f2_hex.append(color_func("{:02x}".format(f2_bin[i])))
                f1_ascii.append(color_func(chr(f1_bin[i]) if 0x20 <= f1_bin[i] < 0x7f else "."))
                f2_ascii.append(color_func(chr(f2_bin[i]) if 0x20 <= f2_bin[i] < 0x7f else "."))

            # formatting
            # ["00", "00", "00" "00", ...] -> ["0000", "0000", ...]
            f1_hex2 = ["".join(x) for x in slicer(f1_hex, 2)]
            f2_hex2 = ["".join(x) for x in slicer(f2_hex, 2)]

            # padding
            # ["0000", "0000", ...] -> "0000 0000 ..."
            f1_hex_s = " ".join(f1_hex2) + " " * hex_pad_len[len(f1_hex)]
            f2_hex_s = " ".join(f2_hex2) + " " * hex_pad_len[len(f2_hex)]
            # [".", ".", ...] -> "................"
            f1_ascii_s = "".join(f1_ascii) + " " * (16 - len(f1_ascii))
            f2_ascii_s = "".join(f2_ascii) + " " * (16 - len(f2_ascii))

            # make line
            addr1 = "{:#{:d}x}".format(self.args.file_offset + pos, width)
            addr2 = ProcessMap.lookup_address(self.args.address + pos)
            self.out.append("{:s}: {:s} |{:s}| {!s}: {:s} |{:s}|".format(
                addr1, f1_hex_s, f1_ascii_s,
                addr2, f2_hex_s, f2_ascii_s,
            ))

        if diff_found is False:
            self.info_add_out("No difference")
        return

    @parse_args
    @only_if_gdb_running
    def do_invoke(self, args):
        # file_data
        if not os.path.isfile(args.filename):
            err("Specified file '{:s}' does not exist".format(args.filename))
            return
        file_data = open(args.filename, "rb").read()
        file_data = file_data[args.file_offset:]
        file_size = len(file_data)

        # size
        if args.size is None:
            size = file_size
        else:
            if args.size > file_size:
                err("The file size is too short")
                return
            size = args.size
            file_data = file_data[:size]

        if size == 0:
            err("Comparing size is 0, nothing to do")
            return

        # memory_data
        try:
            memory_data = read_memory(args.address, size)
        except gdb.MemoryError:
            err("Cannot reach memory {:#x}".format(args.address))
            return

        self.out = []
        self.compare(file_data, memory_data, size)
        self.print_output(check_terminal_size=True)
        return


@register_command
class SymbolsCommand(GenericCommand, BufferingOutput):
    """List all symbols (shortcut for `maintenance print msymbols`) with coloring."""

    _cmdline_ = "symbols"
    _category_ = "02-g. Process Information - Symbol"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-t", "--type", action="append", default=[], help="filter by symbol type.")
    parser.add_argument("-c", "--use-cache", action="store_true", help="use previous result.")
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    parser.add_argument("-q", "--quiet", action="store_true", help="quiet execution.")
    _syntax_ = parser.format_help()

    def get_build_id(self, filename):
        e = Elf.get_elf(filename)
        if e is None or not e.is_valid():
            return None
        try:
            build_id = e.read_shdr(".note.gnu.build-id")
        except Exception:
            return None
        return build_id

    def get_build_ids(self):
        build_id_dict = {}
        for filename in ProcessMap.get_loaded_files():
            build_id = self.get_build_id(filename)
            if build_id is None:
                continue
            build_id_dict[build_id] = filename
        return build_id_dict

    def get_symbols(self):
        """Parse and display symbol information from GDB, including file/object info
        and symbol addresses, with filtering."""
        ret = gdb.execute("maintenance print msymbols", to_string=True).strip()
        SYMBOL_INFO_LINE_PATTERN = re.compile(r"^(\[ ?\d+\]) (.) (0x[0-9a-f]+) (.*)")
        SYMBOL_FILE_PATTERN = re.compile(r"^Object file (/.*):$")
        build_id_dict = self.get_build_ids()

        for line in ProgressBar(ret.splitlines(), disable=self.args.quiet):
            line = line.strip()

            # blank line
            if not line:
                self.out.append(line)
                continue

            # filename line
            # e.g., Object file /root/.cache/debuginfod_client/1c8db5f83bba514f8fd5f1fb6d7be975be1bb855/debuginfo:
            r = SYMBOL_FILE_PATTERN.search(line)
            if r:
                self.out.append(line)

                filename = r.group(1)
                build_id = self.get_build_id(filename)
                if build_id in build_id_dict:
                    if build_id_dict[build_id] != filename:
                        self.out.append("(={:s})".format(build_id_dict[build_id]))
                continue

            # symbol info line
            # e.g., [2875] T 0x7ffff7cad650 malloc section .text  sofini.c
            r = SYMBOL_INFO_LINE_PATTERN.search(line)
            if r:
                # type filtering
                typ = r.group(2)
                if self.args.type:
                    if typ.lower() not in self.args.type:
                        continue

                # invalid address filtering
                addr = int(r.group(3), 16)
                if not is_valid_addr(addr):
                    self.out.append(line)
                    continue
                addr = ProcessMap.lookup_address(addr)

                index = r.group(1)
                remain = r.group(4)
                self.out.append("{:s} {:s} {!s} {:s}".format(index, typ, addr, remain))
                continue

            # other line
            self.out.append(line)

        return

    @parse_args
    @only_if_gdb_running
    def do_invoke(self, args):
        if args.use_cache and hasattr(self, "cache") and self.cache:
            self.out = self.cache[::]
            self.print_output()
            return

        self.out = []
        self.get_symbols()
        self.print_output()
        self.cache = self.out[::]
        return


@register_command
class TypesCommand(GenericCommand, BufferingOutput):
    """List all types (shortcut for `info types`) with compaction."""

    _cmdline_ = "types"
    _category_ = "02-h. Process Information - Type"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-s", "--smart", action="store_true",
                        help="temporarily override by `context.smart_cpp_function_name = True`.")
    parser.add_argument("-f", "--filter", action="append", type=re.compile, default=[],
                        help="REGEXP include filter.")
    parser.add_argument("-e", "--exclude", action="append", type=re.compile, default=[],
                        help="REGEXP exclude filter.")
    parser.add_argument("-E", "--no-enum", action="store_true", help="without enum.")
    parser.add_argument("-S", "--no-struct", action="store_true", help="without struct.")
    parser.add_argument("-T", "--no-typedef", action="store_true", help="without typedef.")
    parser.add_argument("-U", "--no-union", action="store_true", help="without union.")
    parser.add_argument("-c", "--use-cache", action="store_true", help="use previous result.")
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    parser.add_argument("-v", "--verbose", action="store_true", help="with the output of `dt` command.")
    _syntax_ = parser.format_help()

    def get_type_names(self):
        """Parse and filter type names from GDB's 'info types', skipping basic types and applying
        user-specified filters."""
        basic_types = [
            "char", "unsigned char", "signed char",
            "int", "unsigned int", "signed int",
            "short", "unsigned short", "signed short",
            "long", "unsigned long", "signed long",
            "long long", "unsigned long long", "signed long long",
            "float",
            "double", "long double",
            "void",
            "bool",
        ]

        ret = gdb.execute("info types", to_string=True).strip()

        type_names = []
        for line in ret.splitlines():
            if line == "All defined types:":
                continue
            if line == "":
                continue
            if line.startswith("File "):
                continue

            line = re.sub(r"^\d+:|;$", "", line).strip()
            if line in basic_types:
                continue
            if self.args.filter and not any(filt.search(line) for filt in self.args.filter):
                continue
            if self.args.exclude and any(filt.search(line) for filt in self.args.exclude):
                continue
            if self.args.no_enum and line.startswith("enum "):
                continue
            if self.args.no_struct and line.startswith("struct "):
                continue
            if self.args.no_typedef and line.startswith("typedef "):
                continue
            if self.args.no_union and line.startswith("union "):
                continue
            type_names.append(line)

        type_names = sorted(set(type_names))
        return type_names

    def get_types(self):
        """Display type information for each type name, optionally using verbose output and smart formatting."""
        type_names = self.get_type_names()

        # temporarily changed
        if self.args.smart:
            old_smart_setting = Config.get_gef_setting("context.smart_cpp_function_name")
            Config.set_gef_setting("context.smart_cpp_function_name", True)

        # formatting typenames
        for type_name in ProgressBar(type_names):
            if self.args.verbose:
                ret = gdb.execute("dt -n {!r}".format(type_name), to_string=True)
                if not ret or (" is not struct or union" in ret) or ("Could not find " in ret):
                    self.out.append(Instruction.smartify_text(type_name))
                    self.out.append("")
                    continue
                self.out.append(ret)
            else:
                self.out.append(Instruction.smartify_text(type_name))

        # revert
        if self.args.smart:
            Config.set_gef_setting("context.smart_cpp_function_name", old_smart_setting)
        return

    @parse_args
    @only_if_gdb_running
    def do_invoke(self, args):
        if args.use_cache and hasattr(self, "cache") and self.cache:
            self.out = self.cache[::]
            self.print_output()
            return

        self.out = []
        self.get_types()
        self.print_output()
        self.cache = self.out[::]
        return


