@register_command
class GefPyObjListCommand(GenericCommand, BufferingOutput):
    """Display defined global python object."""

    _cmdline_ = "gef pyobj-list"
    _category_ = "99. GEF Maintenance Command"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    _syntax_ = parser.format_help()

    def listup_pyobject(self):
        skip_name_list = [
            "__name__",
            "__loader__",
            "__doc__",
            "__spec__",
            "__package__",
            "__annotations__",
            "__warningregistry__",
            "GdbRemoveReadlineFinder",
        ]

        skip_type_list = [
            type(re.compile("")), # regex object
            type(sys), # module
        ]

        function_type = type(lambda x:x)
        class_type = type(GefCommand)

        arch_list = []
        queue = Architecture.__subclasses__()
        while queue:
            cls = queue.pop(0)
            arch_list.append(cls)
            queue = cls.__subclasses__() + queue

        global_configs = []
        classes = []
        command_classes = []
        bp_classes = []
        arch_classes = []
        arch_determinations = []
        gdb_mode_determinations = []
        decorators = []
        syscall_defines = []
        gef_print_wrappers = []
        read_write_mems = []
        others = []

        for gobj in dir(sys.modules["__main__"]): # for global object
            # skip specific
            if gobj in skip_name_list:
                continue

            obj = getattr(sys.modules["__main__"], gobj)
            t = type(obj)

            # skip specific type
            if t in skip_type_list:
                continue

            # classify
            if gobj.startswith("__") and t is not function_type:
                global_configs.append("{!s} {!s}".format(t, gobj))
            elif gobj in ["current_arch"]:
                t = type(get_current_arch())
                global_configs.append("{!s} {!s}".format(t, gobj))
            elif gobj.upper() == gobj and t is not class_type:
                global_configs.append("{!s} {!s}".format(t, gobj))
            elif t is class_type:
                if gobj.endswith("Command"):
                    command_classes.append("{!s} {!s}".format(t, gobj))
                elif gobj.endswith("Breakpoint") or gobj.endswith("Watchpoint"):
                    bp_classes.append("{!s} {!s}".format(t, gobj))
                elif obj in arch_list:
                    arch_classes.append("{!s} {!s}".format(t, gobj))
                else:
                    classes.append("{!s} {!s}".format(t, gobj))
            elif obj.__doc__ and obj.__doc__.startswith("Architecture determination function"):
                arch_determinations.append("{!s} {!s}".format(t, gobj))
            elif obj.__doc__ and obj.__doc__.startswith("GDB mode determination function"):
                gdb_mode_determinations.append("{!s} {!s}".format(t, gobj))
            elif obj.__doc__ and obj.__doc__.startswith("Decorator"):
                decorators.append("{!s} {!s}".format(t, gobj))
            elif gobj.endswith(("syscall_tbl", "syscall_list")) or gobj.startswith("syscall_defs"):
                syscall_defines.append("{!s} {!s}".format(t, gobj))
            elif obj.__doc__ and obj.__doc__.startswith("The wrapper of gef_print"):
                gef_print_wrappers.append("{!s} {!s}".format(t, gobj))
            elif re.match(r"(read|write)_.*(memory|physmem).*", gobj):
                read_write_mems.append("{!s} {!s}".format(t, gobj))
            else:
                others.append("{!s} {!s}".format(t, gobj))

        self.out.append(titlify("GEF global configs"))
        self.out.extend(sorted(global_configs))
        self.out.append(titlify("Command classes"))
        self.out.extend(sorted(command_classes))
        self.out.append(titlify("Breakpoint classes"))
        self.out.extend(sorted(bp_classes))
        self.out.append(titlify("Architecture classes"))
        self.out.extend(sorted(arch_classes))
        self.out.append(titlify("Architecture determination function"))
        self.out.extend(sorted(arch_determinations))
        self.out.append(titlify("GDB mode determination function"))
        self.out.extend(sorted(gdb_mode_determinations))
        self.out.append(titlify("Classes"))
        self.out.extend(sorted(classes))
        self.out.append(titlify("Syscall defines"))
        self.out.extend(sorted(syscall_defines))
        self.out.append(titlify("Decorators"))
        self.out.extend(sorted(decorators))
        self.out.append(titlify("gef_print wrapper"))
        self.out.extend(sorted(gef_print_wrappers))
        self.out.append(titlify("read/write memory functions"))
        self.out.extend(sorted(read_write_mems))
        self.out.append(titlify("Other functions"))
        self.out.extend(sorted(others))
        return

    @parse_args
    def do_invoke(self, args):
        self.out = []
        self.listup_pyobject()
        self.print_output()
        return


@register_command
class GefAvailableCommandListCommand(GenericCommand, BufferingOutput):
    """Display a list of commands available for the current architecture and gdb execution mode."""

    _cmdline_ = "gef avail-comm-list"
    _category_ = "99. GEF Maintenance Command"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-s", "--sort", action="store_true", help="sort by command name.")
    parser.add_argument("-a", "--only-available", action="store_true", help="show only available commands.")
    parser.add_argument("-u", "--only-unavailable", action="store_true", help="show only unavailable commands.")
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    _syntax_ = parser.format_help()

    def check_require_arch_set(self, decorators):
        for line in decorators:
            if "@require_arch_set" in line:
                return current_arch is None
        return False

    def check_include_mode(self, decorators):
        for line in decorators:
            if "@only_if_specific_gdb_mode" in line:
                if is_pin():
                    return '"pin"' in line
                if is_qemu_system():
                    return '"qemu-system"' in line
                if is_qemu_user():
                    return '"qemu-user"' in line
                if is_vmware():
                    return '"vmware"' in line
                if is_qiling():
                    return '"qiling"' in line
                if is_rr():
                    return '"rr"' in line
                if is_wine():
                    return '"wine"' in line
                if is_kgdb():
                    return '"kgdb"' in line
                return False
        return True

    def check_exclude_mode(self, decorators):
        for line in decorators:
            if "@exclude_specific_gdb_mode" in line:
                if is_pin():
                    return '"pin"' in line
                if is_qemu_system():
                    return '"qemu-system"' in line
                if is_qemu_user():
                    return '"qemu-user"' in line
                if is_vmware():
                    return '"vmware"' in line
                if is_qiling():
                    return '"qiling"' in line
                if is_rr():
                    return '"rr"' in line
                if is_wine():
                    return '"wine"' in line
                if is_kgdb():
                    return '"kgdb"' in line
                return False
        return False

    def get_arch_name(self):
        s = GefUtil.get_source(only_if_specific_arch).replace("\n", "")
        r = re.search(r"dic = (\{.*\})", s)
        dic = eval(r.group(1))

        for arch, func in dic.items():
            if func():
                return '"{:s}"'.format(arch)
        return None

    def check_include_arch(self, decorators, arch_name):
        for line in decorators:
            if "@only_if_specific_arch" in line:
                return str(arch_name) in line
        return True

    def check_exclude_arch(self, decorators, arch_name):
        for line in decorators:
            if "@exclude_specific_arch" in line:
                return str(arch_name) in line
        return False

    def check_load_package(self, decorators, dec_name, import_name):
        for line in decorators:
            if dec_name in line:
                try:
                    readline = sys.modules.get("readline", None)
                    sys.modules["readline"] = None
                    __import__(import_name)
                    sys.modules["readline"] = readline
                except ImportError:
                    return False
                return True
        return True

    def add_out(self, cmdline, avail, msg=""):
        if self.args.only_available and not avail:
            return
        if self.args.only_unavailable and avail:
            return
        if avail:
            self.out.append("{:<34s}: {:s}".format(
                cmdline, Color.colorify("Available", "bold green"),
            ))
        else:
            self.out.append("{:<34s}: {:s} ({:s})".format(
                cmdline, Color.colorify("Unavailable", "bold red"), msg,
            ))
        return

    def listup_avail_comms(self):
        arch_name = self.get_arch_name()
        for cmdline, instance in __gef_command_instances__.items():
            s = GefUtil.get_source(instance.do_invoke)
            decorators = [line for line in s.splitlines() if line.lstrip().startswith("@")]
            if self.check_require_arch_set(decorators):
                self.add_out(cmdline, False, "current_arch is None")
                continue
            if not self.check_include_arch(decorators, arch_name):
                self.add_out(cmdline, False, "Unsupported arch")
                continue
            if self.check_exclude_arch(decorators, arch_name):
                self.add_out(cmdline, False, "Unsupported arch")
                continue
            if not self.check_include_mode(decorators):
                self.add_out(cmdline, False, "Unsupported gdb mode")
                continue
            if self.check_exclude_mode(decorators):
                self.add_out(cmdline, False, "Unsupported gdb mode")
                continue
            if not self.check_load_package(decorators, "@ModuleLoader.load_capstone", "capstone"):
                self.add_out(cmdline, False, "capstone package is unavailable")
                continue
            if not self.check_load_package(decorators, "@ModuleLoader.load_unicorn", "unicorn"):
                self.add_out(cmdline, False, "unicorn package is unavailable")
                continue
            if not self.check_load_package(decorators, "@ModuleLoader.load_keystone", "keystone"):
                self.add_out(cmdline, False, "keystone-engine package is unavailable")
                continue
            if not self.check_load_package(decorators, "@ModuleLoader.load_ropper", "ropper"):
                self.add_out(cmdline, False, "ropper package is unavailable")
                continue
            if not self.check_load_package(decorators, "@ModuleLoader.load_binwalk", "binwalk"):
                self.add_out(cmdline, False, "binwalk package is unavailable")
                continue
            if not self.check_load_package(decorators, "@ModuleLoader.load_codext", "codext"):
                self.add_out(cmdline, False, "codext package is unavailable")
                continue
            if not self.check_load_package(decorators, "@ModuleLoader.load_angr", "angr"):
                self.add_out(cmdline, False, "angr package is unavailable")
                continue
            self.add_out(cmdline, True)
        return

    @parse_args
    @only_if_gdb_running
    def do_invoke(self, args):
        self.out = []
        self.listup_avail_comms()
        if args.sort:
            self.out = sorted(self.out)
        self.print_output(check_terminal_size=True)
        return


@register_command
class GefDumpCommandsCommand(GenericCommand):
    """Dump GEF command documentation as Markdown."""

    _cmdline_ = "gef dump-commands"
    _category_ = "99. GEF Maintenance Command"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("output", metavar="OUTPUT", nargs="?", default="COMMANDS.md",
                        help="output file path. (default: %(default)s)")
    _syntax_ = parser.format_help()

    def normalize_text(self, value):
        """Normalize a value for Markdown output."""
        if value is None:
            return ""

        text = str(value).strip()
        return text

    def make_code_block(self, value, lang="text"):
        """Render a fenced Markdown code block."""
        text = self.normalize_text(value)
        if not text:
            return ""

        fence = "```"
        while fence in text:
            fence += "`"

        return "{:s}{:s}\n{:s}\n{:s}".format(fence, lang, text, fence)

    def make_inline_code(self, value):
        """Render inline Markdown code."""
        text = self.normalize_text(value)
        if not text:
            return ""

        return "`{:s}`".format(text.replace("`", "\\`"))

    def get_aliases(self, instance):
        """Return aliases as a normalized list."""
        aliases = getattr(instance, "_aliases_", [])

        if aliases is None:
            return []

        if isinstance(aliases, str):
            if aliases:
                return [aliases]
            return []

        if hasattr(aliases, "__iter__"):
            return [str(alias) for alias in aliases]

        return [str(aliases)]

    def get_summary(self, instance):
        summary = getattr(instance.__class__, "__doc__", "")
        return self.normalize_text(summary)

    def syntax_for_dump(self, instance):
        """Render the command syntax with an effectively infinite width."""
        parser = getattr(instance, "parser", None)
        if parser is None:
            return getattr(instance, "_syntax_", None)

        old_formatter = parser.formatter_class
        parser.formatter_class = lambda prog: argparse.HelpFormatter(prog, width=10**7)
        try:
            return parser.format_help()
        finally:
            parser.formatter_class = old_formatter

    def render_command(self, command_name, instance):
        """Render a single command as Markdown."""
        syntax = self.syntax_for_dump(instance)
        example = getattr(instance, "_example_", None)
        note = getattr(instance, "_note_", None)
        aliases = self.get_aliases(instance)
        summary = self.get_summary(instance)

        lines = []
        lines.append("## {:s}".format(command_name))
        lines.append("")

        if summary:
            lines.append(summary)
            lines.append("")

        if aliases:
            rendered_aliases = ", ".join(self.make_inline_code(alias) for alias in aliases)
            lines.append("- Alias: {:s}".format(rendered_aliases))

        lines.append("")

        if syntax:
            lines.append("### Syntax")
            lines.append("")
            lines.append(self.make_code_block(syntax, "text"))
            lines.append("")

        if example:
            lines.append("### Examples")
            lines.append("")
            lines.append(self.make_code_block(example, "gdb"))
            lines.append("")

        if note:
            lines.append("### Notes")
            lines.append("")
            lines.append(self.make_code_block(note, "text"))
            lines.append("")

        return "\n".join(lines).rstrip()

    def render_commands(self):
        """Render all registered GEF commands as Markdown."""
        lines = []
        lines.append("# GEF Commands")
        lines.append("")

        commands = []
        categories = set()
        for command_name, instance in __gef_command_instances__.items():
            if not getattr(instance, "_cmdline_", None):
                continue
            category = instance._category_
            categories.add(category)
            commands.append((category, command_name, instance))
        commands = sorted(commands, key=lambda item: (item[0], item[1]))

        lines.append("## Table of contents")
        lines.append("")
        for cat_orig in sorted(categories):
            cat = cat_orig[::]
            cat = cat.replace(" ", "-")
            cat = cat.replace("/", "")
            cat = cat.replace(".", "")
            cat = cat.lower()
            lines.append("- [{:s}](#{:s})".format(cat_orig, cat))
        lines.append("")

        prev_category = None
        for category, command_name, instance in commands:
            if category != prev_category:
                lines.append("# {:s}".format(category))
                prev_category = category
            lines.append(self.render_command(command_name, instance))
            lines.append("")

        return "\n".join(lines).rstrip() + "\n"

    @parse_args
    def do_invoke(self, args):
        output = self.render_commands()
        with open(args.output, "w", encoding="utf-8") as f:
            f.write(output)
        return


@register_command
class GefSetArchCommand(GenericCommand):
    """Set a specific architecture to gef."""

    _cmdline_ = "gef set-arch"
    _category_ = "99. GEF Maintenance Command"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument("arch", metavar="ARCH", nargs="?", help="target architecture.")
    group.add_argument("-l", "--list", action="store_true", help="show supported architecture words.")
    _syntax_ = parser.format_help()

    def arch_listup(self):
        fmt = "{:12s} {:s}"
        legend = ["Arch", "Available names (Case insensitive)"]
        gef_print(GefUtil.make_legend(fmt.format(*legend)))

        queue = Architecture.__subclasses__()
        while queue:
            cls = queue.pop(0)
            queue = cls.__subclasses__() + queue

            arch = Color.boldify("{:12s}".format(cls.__name__))
            words = ", ".join(filter(lambda x: isinstance(x, str), cls.load_condition))
            gef_print("{:s} {:s}".format(arch, words))
        return

    @parse_args
    def do_invoke(self, args):
        if args.list:
            self.arch_listup()
            return

        try:
            set_arch(args.arch)
            info("set_arch({:s}) is successfully".format(args.arch))
            Cache.reset_gef_caches(all=True)
        except OSError:
            err("set_arch({:s}) is failed".format(args.arch))
        return


@register_command
class GefStatusCommand(GenericCommand):
    """Display current gef status."""

    _cmdline_ = "gef status"
    _category_ = "99. GEF Maintenance Command"
    _aliases_ = ["arch-info"]

    parser = argparse.ArgumentParser(prog=_cmdline_)
    _syntax_ = parser.format_help()

    @parse_args
    def do_invoke(self, args):
        gef_print(titlify("GDB/ELF settings"))
        show_arch = gdb.execute("show architecture", to_string=True).rstrip()
        gef_print("{:30s}  ->  {:s}".format("show architecture", show_arch))
        if is_64bit():
            bit_str = "64-bit"
        else:
            bit_str = "32-bit"
        if Endian.is_big_endian():
            endian_str = "big"
        else:
            endian_str = "little"
        gef_print("{:30s}  ->  {:s}".format("bit", bit_str))
        gef_print("{:30s}  ->  {:s}".format("endian", endian_str))

        gef_print(titlify("GDB mode"))
        gef_print("{:30s}  ->  {!s}".format("is_normal_run()", is_normal_run()))
        gef_print("{:30s}  ->  {!s}".format("is_attach()", is_attach()))
        gef_print("{:30s}  ->  {!s}".format("is_remote_debug()", is_remote_debug()))
        gef_print("{:30s}  ->  {!s}".format("is_container_attach()", is_container_attach()))
        gef_print("{:30s}  ->  {!s}".format("is_qemu_system()", is_qemu_system()))
        gef_print("{:30s}  ->  {!s}".format("is_qemu_user()", is_qemu_user()))
        gef_print("{:30s}  ->  {!s}".format("is_pin()", is_pin()))
        gef_print("{:30s}  ->  {!s}".format("is_over_serial()", is_over_serial()))
        kgdb_forced = " (forced)" if Config.get_gef_setting("gef.kgdb_force") is True else ""
        gef_print("{:30s}  ->  {!s}{:s}".format("is_kgdb()", is_kgdb(), kgdb_forced))
        gef_print("{:30s}  ->  {!s}".format("is_kdb()", is_kdb()))
        gef_print("{:30s}  ->  {!s}".format("is_qiling()", is_qiling()))
        gef_print("{:30s}  ->  {!s}".format("is_vmware()", is_vmware()))
        gef_print("{:30s}  ->  {!s}".format("is_in_kernel()", is_in_kernel()))
        gef_print("{:30s}  ->  {!s}".format("is_in_secure()", is_in_secure()))
        gef_print("{:30s}  ->  {!s}".format("is_rr()", is_rr()))
        gef_print("{:30s}  ->  {!s}".format("is_wine()", is_wine()))

        gef_print(titlify("Others"))
        gef_print("{:30s}  ->  {!s}".format("is_alive()", is_alive()))
        gef_print("{:30s}  ->  {!s}".format("is_kvm_enabled()", is_kvm_enabled()))
        gef_print("{:30s}  ->  {!s}".format("is_smp_enabled()", is_smp_enabled()))
        gef_print("{:30s}  ->  {!s}".format("is_support_secure_world()", is_support_secure_world()))
        gef_print("{:30s}  ->  {!s}".format("is_supported_physmode()", is_supported_physmode()))
        if is_supported_physmode():
            gef_print("{:30s}  ->  {!s}".format("get_current_mmu_mode()", QemuMonitor.get_current_mmu_mode()))

        gef_print(titlify("GEF architecture information"))
        if current_arch is None:
            gef_print("{:30s}  ->  None".format("current_arch"))
            gef_print("{:30s}  ->  {!s}".format("ptrsize", AddressUtil.ptr_width()))
            return
        gef_print("{:30s}  ->  {!s}".format("current_arch.arch", current_arch.arch))
        gef_print("{:30s}  ->  {!s}".format("current_arch.mode", current_arch.mode))
        if is_arm32() or is_arm32_cortex_m():
            gef_print("{:30s}  ->  {!s}".format("current_arch.is_cortex_m()", current_arch.is_cortex_m()))
        gef_print("{:30s}  ->  {!s}".format("current_arch.ptrsize", current_arch.ptrsize))

        if current_arch.instruction_length is None:
            inst_len = "variable length"
        else:
            inst_len = str(current_arch.instruction_length)
        gef_print("{:30s}  ->  {!s}".format("instruction length", inst_len))

        if current_arch.return_register is None:
            ret_regs = "different for each system call"
        else:
            ret_regs = str(current_arch.return_register)
        gef_print("{:30s}  ->  {!s}".format("return register", ret_regs))

        fparams = ", ".join(current_arch.function_parameters)
        if len(current_arch.function_parameters) == 1:
            fparams += " (passing via stack)"
        gef_print("{:30s}  ->  {!s}".format("function parameters", fparams))

        gef_print("{:30s}  ->  {!s}".format("syscall register", current_arch.syscall_register))

        if current_arch.syscall_parameters is None:
            sparams = "different for each system call"
        else:
            sparams = ", ".join(current_arch.syscall_parameters)
        gef_print("{:30s}  ->  {!s}".format("syscall parameters", sparams))

        if is_x86() or is_arm32() or is_arm64():
            gef_print("{:30s}  ->  {!s}".format("32bit-emulated (compat mode)", is_emulated32()))
        gef_print("{:30s}  ->  {!s}".format("Has a call/jump delay slot", current_arch.has_delay_slot))
        gef_print("{:30s}  ->  {!s}".format("Has a syscall delay slot", current_arch.has_syscall_delay_slot))
        gef_print("{:30s}  ->  {!s}".format("Has a ret delay slot", current_arch.has_ret_delay_slot))
        gef_print("{:30s}  ->  {!s}".format("Stack grow down", current_arch.stack_grow_down))
        gef_print("{:30s}  ->  {!s}".format("Thread Local Storage support", current_arch.tls_supported))
        gef_print("{:30s}  ->  {!s}".format("keystone support", current_arch.keystone_support))
        gef_print("{:30s}  ->  {!s}".format("capstone support", current_arch.capstone_support))
        gef_print("{:30s}  ->  {!s}".format("unicorn support", current_arch.unicorn_support))
        return


@register_command
class GefVersionCommand(GenericCommand):
    """Display GEF version info."""

    _cmdline_ = "gef version"
    _category_ = "99. GEF Maintenance Command"
    _aliases_ = ["version"]

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("--compact", action="store_true", help="show compact style.")
    _syntax_ = parser.format_help()

    def os_version(self):
        try:
            lsb_release_command = GefUtil.which("lsb_release")
            res = GefUtil.gef_execute_external([lsb_release_command, "-d"], as_list=True)
            for line in res:
                if line.startswith("Description:"):
                    return line.split(":")[1].strip()
        except FileNotFoundError:
            pass

        if os.path.exists("/etc/issue.net"):
            content = open("/etc/issue.net").read().strip()
            if content:
                return content

        if os.path.exists("/etc/issue"):
            content = open("/etc/issue").read().strip()
            content = content.replace(" \\n \\l", "")
            if content:
                return content

        if os.path.exists("/etc/os-release"):
            content = open("/etc/os-release").read()
            for line in content.splitlines():
                r = re.search(r'PRETTY_NAME="(.+)"', line)
                if r:
                    return r.group(1)

        return "Not found"

    def kernel_version_from_uname(self):
        try:
            uname_command = GefUtil.which("uname")
            res = GefUtil.gef_execute_external([uname_command, "-a"], as_list=True)
            return res[0]
        except FileNotFoundError:
            return "Not found"

    def kernel_version_from_proc(self):
        try:
            return open("/proc/version").read().strip()
        except FileNotFoundError:
            return "Not found"

    def system_libc_version(self):
        res = GefUtil.gef_execute_external(["cat", "/proc/self/maps"], as_list=True)
        libc_targets = ("libc-2.", "libc.so.6", "libuClibc-")
        for line in res:
            if not any(kw in line for kw in libc_targets):
                continue
            path = line.split()[-1]
            if not os.path.exists(path):
                continue
            data = open(path, "rb").read()
            pos = re.search(b"(GNU C Library|uClibc-ng release) [\x20-\x7e]*", data)
            if pos:
                return String.bytes2str(pos.group(0))
        return "Not found"

    def qemu_system_version(self):
        return gdb.execute("monitor info version", to_string=True).strip()

    def qemu_user_version(self):
        pid = Pid.get_pid()
        try:
            res = GefUtil.gef_execute_external(["/proc/{:d}/exe".format(pid), "--version"], as_list=True)
            return res[0].strip()
        except (IndexError, FileNotFoundError):
            return "Not recognized"

    def gef_version(self):
        gef_hash = hashlib.sha1(open(GEF_FILEPATH, "rb").read()).hexdigest()
        dt = datetime.datetime.fromtimestamp(os.stat(GEF_FILEPATH).st_mtime)
        return "Last modified: {} SHA1: {}".format(dt.strftime("%Y-%m-%d %H:%M:%S"), gef_hash)

    def gdb_version(self):
        try:
            return gdb.VERSION # GDB >= 8.1 (or earlier?)
        except AttributeError:
            return gdb.execute("show version", to_string=True).split("\n")[0]

    def python_version(self):
        return sys.version.replace("\n", " ")

    def capstone_version(self):

        @ModuleLoader.load_capstone
        def _capstone_version():
            capstone = sys.modules["capstone"]
            return ".".join(map(str, capstone.cs_version()))

        try:
            return _capstone_version()
        except (KeyError, ImportWarning):
            return "Not found"

    def keystone_version(self):

        @ModuleLoader.load_keystone
        def _keystone_version():
            keystone = sys.modules["keystone"]
            return ".".join(map(str, keystone.ks_version()))

        try:
            return _keystone_version()
        except (KeyError, ImportWarning):
            return "Not found"

    def unicorn_version(self):

        @ModuleLoader.load_unicorn
        def _unicorn_version():
            unicorn = sys.modules["unicorn"]
            return unicorn.__version__

        try:
            return _unicorn_version()
        except (KeyError, ImportWarning):
            return "Not found"

    def ropper_version(self):

        @ModuleLoader.load_ropper
        def _ropper_version():
            ropper = sys.modules["ropper"]
            return ".".join(map(str, ropper.VERSION))

        try:
            return _ropper_version()
        except (KeyError, ImportWarning, AttributeError):
            return "Not found"

    def angr_version(self):

        @ModuleLoader.load_angr
        def _angr_version():
            angr = sys.modules["angr"]
            return angr.__version__

        try:
            return _angr_version()
        except (KeyError, ImportWarning, AttributeError):
            return "Not found"

    def gcc_version(self):
        try:
            gcc_command = GefUtil.which("gcc")
        except FileNotFoundError:
            return "Not found"
        res = GefUtil.gef_execute_external([gcc_command, "--version"], as_list=True)
        return res[0]

    def readelf_version(self):
        try:
            readelf_command = GefUtil.which(Config.get_gef_setting("gef.readelf_command"))
        except FileNotFoundError:
            return "Not found"
        res = GefUtil.gef_execute_external([readelf_command, "-v"], as_list=True)
        return res[0]

    def objdump_version(self):
        try:
            objdump_command = GefUtil.which(Config.get_gef_setting("gef.objdump_command"))
        except FileNotFoundError:
            return "Not found"
        res = GefUtil.gef_execute_external([objdump_command, "-v"], as_list=True)
        return res[0]

    def seccomp_tools_version(self):
        try:
            seccomp_tools_command = GefUtil.which("seccomp-tools")
        except FileNotFoundError:
            return "Not found"
        res = GefUtil.gef_execute_external([seccomp_tools_command, "--version"], as_list=True)
        return res[0]

    def ceccomp_version(self):
        try:
            ceccomp_command = GefUtil.which("ceccomp")
        except FileNotFoundError:
            return "Not found"
        res = GefUtil.gef_execute_external([ceccomp_command, "version"], as_list=True)
        return res[0]

    def one_gadget_version(self):
        try:
            one_gadget_command = GefUtil.which("one_gadget")
        except FileNotFoundError:
            return "Not found"
        res = GefUtil.gef_execute_external([one_gadget_command, "--version"], as_list=True)
        return res[0]

    def rp_version(self):
        try:
            rp_lin_command = GefUtil.which("rp-lin")
        except FileNotFoundError:
            return "Not found"
        res = GefUtil.gef_execute_external([rp_lin_command, "--version", "--file", "a"], as_list=True)
        if "You are currently using " in res[0]:
            return res[0].replace("You are currently using ", "")
        return "Not found"

    def show_compact_info(self):
        gef_print("gdb:     {:s}".format(self.gdb_version()))
        gef_print("python:  {:s}".format(self.python_version()))
        gef_print("OS:      {:s}".format(self.os_version()))
        gef_print("kernel:  {:s}".format(self.kernel_version_from_uname()))
        if is_qemu_system():
            gef_print("qemu:    {:s}".format(self.qemu_system_version()))
        return

    def show_full_info(self):
        gef_print(titlify("versions"))
        gef_print("OS:                     {:s}".format(self.os_version()))
        gef_print("kernel (uname -a):      {:s}".format(self.kernel_version_from_uname()))
        gef_print("kernel (/proc/version): {:s}".format(self.kernel_version_from_proc()))
        gef_print("System libc:            {:s}".format(self.system_libc_version()))
        if is_qemu_system():
            gef_print("qemu:                   {:s}".format(self.qemu_system_version()))
        if is_qemu_user():
            gef_print("qemu:                   {:s}".format(self.qemu_user_version()))
        gef_print("GEF:                    {:s}".format(self.gef_version()))
        gef_print("gdb:                    {:s}".format(self.gdb_version()))
        gef_print("python:                 {:s}".format(self.python_version()))
        gef_print("capstone:               {:s}".format(self.capstone_version()))
        gef_print("keystone:               {:s}".format(self.keystone_version()))
        gef_print("unicorn:                {:s}".format(self.unicorn_version()))
        gef_print("ropper:                 {:s}".format(self.ropper_version()))
        gef_print("angr:                   {:s}".format(self.angr_version()))
        gef_print("gcc:                    {:s}".format(self.gcc_version()))
        gef_print("readelf:                {:s}".format(self.readelf_version()))
        gef_print("objdump:                {:s}".format(self.objdump_version()))
        gef_print("seccomp-tools:          {:s}".format(self.seccomp_tools_version()))
        gef_print("ceccomp:                {:s}".format(self.ceccomp_version()))
        gef_print("one_gadget:             {:s}".format(self.one_gadget_version()))
        gef_print("rp:                     {:s}".format(self.rp_version()))

        gef_print(titlify("gdb build config"))
        gdb.execute("show configuration")
        return

    @parse_args
    def do_invoke(self, args):
        if args.compact:
            self.show_compact_info()
        else:
            self.show_full_info()
        return


@register_command
class GefCheckUpdateCommand(GenericCommand):
    """Check for gef updates."""

    _cmdline_ = "gef check-update"
    _category_ = "99. GEF Maintenance Command"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    _syntax_ = parser.format_help()

    @parse_args
    def do_invoke(self, args):
        gef_remote = "https://raw.githubusercontent.com/bata24/gef/dev/gef.py"
        gef_remote_data = http_get(gef_remote)

        if gef_remote_data is None:
            err("[-] Failed to get remote gef")
            return

        hash_gef_local = hashlib.sha512(open(GEF_FILEPATH, "rb").read()).digest()
        hash_gef_remote = hashlib.sha512(gef_remote_data).digest()

        if hash_gef_local == hash_gef_remote:
            info("No update")
        else:
            info("Update found, try `python3 {:s} --upgrade`".format(GEF_FILEPATH))
        return


@register_command
class GefTmuxSetupCommand(GenericCommand):
    """Setup a comfortable tmux environment."""

    _cmdline_ = "gef tmux-setup"
    _category_ = "99. GEF Maintenance Command"
    _aliases_ = ["tmux-setup"]

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-r", "--reset", action="store_true", help="reset all panes.")
    _syntax_ = parser.format_help()

    _note_ = [
        "- `screen` is no longer supported.",
        "",
        "- `tmux` settings are predefined and cannot be customized in this command.",
        "- If you want to customize it, edit `tmux_setup.py` and run `source /path/to/tmux_setup.py`.",
        "- It can be found in https://github.com/bata24/gef/blob/dev/dev/tmux/tmux_setup.py.",
        "",
        "- There is experimental support for `zellij` using a similar script.",
        "- Try starting `zellij-wrapper.py` in your shell (before starting `zellij` and `gdb`).",
        "- It can be found in https://github.com/bata24/gef/blob/dev/dev/zellij/zellij-wrapper.py.",
    ]
    _note_ = "\n".join(_note_)

    @staticmethod
    def get_redirect_configs():
        configs = [
            "context.redirect",
            "context_args.redirect",
            "context_code.redirect",
            "context_extra.redirect",
            "context_legend.redirect",
            "context_mem_access.redirect",
            "context_mem_watch.redirect",
            "context_regs.redirect",
            "context_source.redirect",
            "context_stack.redirect",
            "context_threads.redirect",
            "context_trace.redirect",
        ]
        return configs

    @staticmethod
    def get_tty_gef_used():
        """Return a set of TTYs currently used by GEF for tmux redirection."""
        tty_gef_used = [Config.get_gef_setting(c) for c in GefTmuxSetupCommand.get_redirect_configs()]
        tty_gef_used = [x for x in tty_gef_used if x] # filter ""
        return set(tty_gef_used)

    @staticmethod
    def reset_panes():
        """Reset tmux panes used by GEF, killing relevant panes and clearing related configurations."""
        # list panes
        tmux = GefUtil.which("tmux")
        res = subprocess.check_output([
            tmux, "list-panes", "-F#{pane_active}:#{pane_id}:#{pane_tty}"
        ]).decode("utf-8").strip()

        # kill panes
        tty_gef_used = GefTmuxSetupCommand.get_tty_gef_used()
        for line in res.splitlines():
            pane_active, pane_id, pane_tty = line.split(":")
            if pane_active == "1":
                continue
            if pane_tty not in tty_gef_used:
                continue
            subprocess.run([tmux, "kill-pane", "-t", pane_id])

        # reset config
        for config in GefTmuxSetupCommand.get_redirect_configs():
            gdb.execute('gef config {:s} ""'.format(config))

        # remove destructor
        import atexit
        try:
            atexit.unregister(GefTmuxSetupCommand.reset_panes)
        except Exception:
            pass
        return

    def tmux_setup(self):
        """Prepare the tmux environment by vertically splitting and redirect context output."""
        # reset previous settings
        tmux = GefUtil.which("tmux")
        if self.get_tty_gef_used():
            warn("Since it is already split, discard previous screen")
            GefTmuxSetupCommand.reset_panes()

        # split
        ok("tmux session found, splitting window...")
        pane_id, pane_tty = subprocess.check_output([
            tmux, "splitw", "-h", "-F#{pane_id}:#{pane_tty}", "-P",
        ]).decode("utf-8").strip().split(":")

        # add destructor
        import atexit
        atexit.register(GefTmuxSetupCommand.reset_panes)

        # clear the screen and let it wait for input forever
        gdb.execute(f"!'{tmux}' send-keys -t {pane_id} 'clear ; cat' C-m")
        gdb.execute(f"!'{tmux}' select-pane -L")

        ok(f"Setting `context.redirect` to '{pane_tty}'...")
        gdb.execute(f"gef config context.redirect {pane_tty}")

        Cache.reset_gef_caches(all=True)
        return

    @parse_args
    def do_invoke(self, args):
        try:
            GefUtil.which("tmux")
        except FileNotFoundError as e:
            err("{}".format(e))
            return

        if args.reset:
            GefTmuxSetupCommand.reset_panes()
            return

        if os.getenv("TMUX"):
            self.tmux_setup()
            return

        warn("Not in a tmux session")
        return


class GefAlias(gdb.Command):
    """Simple aliasing wrapper because GDB doesn't do what it should."""

    _category_ = "99. GEF Maintenance Command"

    def __init__(self, alias, command, force_repeat=None, pre_defined=False):
        p = command.split()
        if not p:
            return

        # initialize
        self._alias_ = alias
        self._command_ = command
        if force_repeat is None:
            self._repeat_ = False
        else:
            self._repeat_ = force_repeat
        self._pre_defined_ = pre_defined # default alias settings of GEF
        self.__doc__ = "Alias for '{:s}'".format(Color.greenify(command))

        # Inherit settings from the aliased command
        instance = __gef_command_instances__.get(command, None)
        if instance:
            # repeat settings
            if force_repeat is None:
                self._repeat_ = instance._repeat_

            # doc
            self.__doc__ += ": {:s}".format(instance.__doc__)

            # complete settings
            if hasattr(instance, "complete"):
                self.complete = instance.complete

        # define aliased command
        if hasattr(instance, "complete"):
            # Aliased commands support only user completion.
            super().__init__(alias, gdb.COMMAND_NONE)
        else:
            super().__init__(alias, gdb.COMMAND_NONE, gdb.COMPLETE_NONE)

        # add or overwrite
        global __gef_alias_instances__
        __gef_alias_instances__[alias] = self
        return

    def invoke(self, args, from_tty): # noqa
        if not self._repeat_:
            self.dont_repeat()
        gdb.execute("{} {}".format(self._command_, args), from_tty=from_tty)
        return


@register_command
class AliasesCommand(GenericCommand):
    """The base command to add, remove or list aliases."""

    _cmdline_ = "aliases"
    _category_ = "99. GEF Maintenance Command"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    if (sys.version_info.major, sys.version_info.minor) >= (3, 7):
        subparsers = parser.add_subparsers(title="command", required=True)
    else:
        subparsers = parser.add_subparsers(title="command")
    subparsers.add_parser("add")
    subparsers.add_parser("rm")
    subparsers.add_parser("ls")
    _syntax_ = parser.format_help()

    def __init__(self, *args, **kwargs):
        prefix = kwargs.get("prefix", True)
        super().__init__(prefix=prefix)
        return

    @parse_args
    def do_invoke(self, args):
        self.usage()
        return


@register_command
class AliasesAddCommand(AliasesCommand):
    """Add the command alias."""

    _cmdline_ = "aliases add"
    _category_ = "99. GEF Maintenance Command"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("alias", metavar="ALIAS", help="the name of new alias.")
    parser.add_argument("command", metavar="COMMAND", nargs="+", help="the command of new alias.")
    parser.add_argument("-r", "--repeat", action="store_true", help="enforce repeat feature.")
    _syntax_ = parser.format_help()

    _example_ = [
        "{0:s} scope telescope",
    ]
    _example_ = "\n".join(_example_).format(_cmdline_)

    def __init__(self):
        super().__init__(prefix=False)
        return

    @parse_args
    def do_invoke(self, args):
        if args.alias in __gef_command_instances__:
            err("Not allowed due to circular references")
            return
        command = " ".join(args.command)
        GefAlias(args.alias, command, force_repeat=args.repeat)
        gef_print("{:s} = {:s}".format(args.alias, command))
        return


@register_command
class AliasesRmCommand(AliasesCommand):
    """Remove the command alias."""

    _cmdline_ = "aliases rm"
    _category_ = "99. GEF Maintenance Command"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("alias", metavar="ALIAS", help="the name of alias to be deleted.")
    _syntax_ = parser.format_help()

    def __init__(self):
        super().__init__(prefix=False)
        return

    @parse_args
    def do_invoke(self, args):
        global __gef_alias_instances__

        if args.alias in __gef_alias_instances__:
            del __gef_alias_instances__[args.alias]
        else:
            err("Could not find {:s} in aliases".format(args.alias))
        return


@register_command
class AliasesListCommand(AliasesCommand, BufferingOutput):
    """List the command alias."""

    _cmdline_ = "aliases ls"
    _category_ = "99. GEF Maintenance Command"

    parser = argparse.ArgumentParser(prog=_cmdline_)
    parser.add_argument("-n", "--no-pager", action="store_true", help="do not use the pager.")
    _syntax_ = parser.format_help()

    def __init__(self):
        super().__init__(prefix=False)
        return

    @parse_args
    def do_invoke(self, args):
        width = max(len(x) for x in __gef_alias_instances__.keys())

        self.out = []
        self.out.append(titlify("Pre-defined aliases"))
        for _, a in sorted(__gef_alias_instances__.items(), key=lambda x:x[0]):
            if a._pre_defined_:
                self.out.append("{:{:d}s}  ->  {:s}".format(a._alias_, width, a._command_))

        self.out.append(titlify("User defined aliases"))
        for _, a in sorted(__gef_alias_instances__.items(), key=lambda x:x[0]):
            if not a._pre_defined_:
                self.out.append("{:{:d}s}  ->  {:s}".format(a._alias_, width, a._command_))

        self.print_output(check_terminal_size=True)
        return


class GefUtil:
    """A collection of utility functions that are related to GEF basic features."""

    @staticmethod
    @Cache.cache_until_next
    def cached_lookup_type(_type):
        """Look up a GDB type by name and strip typedefs, returning None on failure."""
        try:
            return gdb.lookup_type(_type).strip_typedefs()
        except RuntimeError:
            return None

    @staticmethod
    def get_architecture():
        """Return the gdb.Architecture of the current target. It raises gdb.error if unavailable.

        The inferior is preferred over the selected frame because it keeps the architecture
        without building a frame. The selected frame does not exist before the process starts,
        and building it can fail (e.g., ARM32 halted at the exception vector, where the frame
        pointer still holds an unmapped userland value)."""
        if hasattr(gdb.Inferior, "architecture"): # gdb 10.1~
            return gdb.selected_inferior().architecture()
        return gdb.selected_frame().architecture()

    __gef_convenience_vars_index__ = 0 # $_gef1, $_gef2, ...

    @staticmethod
    def gef_convenience(value):
        """Define a new convenience value."""
        var_name = "_gef{:d}".format(GefUtil.__gef_convenience_vars_index__)
        GefUtil.__gef_convenience_vars_index__ += 1
        gdb.set_convenience_variable(var_name, value)
        return "${:s}".format(var_name)

    class ArgparseExitProxyException(Exception):
        pass

    @staticmethod
    def get_terminal_size(redirect=""):
        """Return the current terminal size."""
        if redirect and os.getenv("TMUX"):
            res = subprocess.check_output([
                GefUtil.which("tmux"), "list-panes", "-F#{pane_tty}:#{pane_height}:#{pane_width}",
            ]).decode("utf-8").strip()

            for line in res.splitlines():
                tty, height, width = line.split(":")
                if tty == redirect:
                    return int(height), int(width)

        try:
            tty_columns, tty_rows = os.get_terminal_size()
            return tty_rows, tty_columns
        except OSError:
            return 600, 100

    @staticmethod
    def get_source(function):
        """Return the source of function."""
        import inspect
        s = inspect.getsource(function)
        return s.rstrip()

    @staticmethod
    @Cache.cache_this_session
    def log2(x):
        return int(math.log2(x))

    @staticmethod
    def fromhex_ignore_invalid(value, to_str=False):
        """Convert a hex string to bytes or string, ignoring invalid characters."""
        sanitized_value = ""
        for c in value.lower():
            if c in "0123456789abcdef":
                sanitized_value += c
        if len(sanitized_value) % 2 != 0:
            err("Hex value length is odd")
            return None
        if to_str:
            values = ["\\x" + hh for hh in slicer(sanitized_value, 2)]
            values = "".join(values)
        else:
            values = bytes.fromhex(sanitized_value)
        return values

    @staticmethod
    @Cache.cache_this_session
    def which(program):
        """Locate a command on the filesystem."""

        def is_exe(fpath):
            return os.path.isfile(fpath) and os.access(fpath, os.X_OK)

        if not program:
            raise FileNotFoundError("Missing program name")

        if os.path.split(program)[0]: # check dirname
            if is_exe(program):
                return program
        else:
            # search from PATH
            env_path_default = "/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
            env_path = os.getenv("PATH", env_path_default)
            env_path = env_path.split(os.pathsep)

            if hasattr(Gef, "GEF_VENV_BIN_PATH"):
                env_path.insert(0, Gef.GEF_VENV_BIN_PATH)

            if "/usr/local/bin" not in env_path:
                env_path.insert(0, "/usr/local/bin") # for rp-lin, vmlinux-to-elf

            for path in env_path:
                exe_file = os.path.join(path.strip('"'), program)
                if is_exe(exe_file):
                    return exe_file

        raise FileNotFoundError("Missing file `{:s}`".format(program))

    @staticmethod
    def show_last_exception():
        """Display the last Python exception."""

        def _show_code_line(fname, idx):
            fname = os.path.expanduser(os.path.expandvars(fname))
            with open(fname, "r") as f:
                data = f.read().splitlines()
            return data[idx - 1] if 0 < idx <= len(data) else ""

        gef_print("")
        exc_type, exc_value, exc_traceback = sys.exc_info()

        HORIZONTAL_LINE = "-"
        gef_print(" Exception raised ".center(80, HORIZONTAL_LINE))
        gef_print("{}: {}".format(Color.colorify(exc_type.__name__, "bold red underline"), exc_value))
        gef_print(" Detailed stacktrace ".center(80, HORIZONTAL_LINE))

        for fs in traceback.extract_tb(exc_traceback)[::-1]:
            filename, lineno, method, code = fs

            if not code or not code.strip():
                code = _show_code_line(filename, lineno)

            filename_c = Color.yellowify(filename)
            method_c = Color.greenify(method)
            gef_print('File "{}", line {:d}, in {}()'.format(filename_c, lineno, method_c))
            gef_print("    ->     {}".format(code))

        gef_print(" Last 10 GDB commands ".center(80, HORIZONTAL_LINE))
        gdb.execute("show commands")
        gef_print(" Runtime environment ".center(80, HORIZONTAL_LINE))
        gdb.execute("gef version --compact")
        gef_print(HORIZONTAL_LINE * 80)
        gef_print("")
        return

    @staticmethod
    def os_system(cmd):
        """Execute an external command, letting it write to our stdout directly.

        The child inherits our stdout, so anything still sitting in the python buffer
        has to go out first. Otherwise the child's output jumps ahead of it whenever
        stdout is not a tty (e.g. gdb -batch redirected to a file)."""
        sys.stdout.flush()
        return os.system(cmd)

    @staticmethod
    def gef_execute_external(command, as_list=False, *args, **kwargs):
        """Execute an external command and return the result."""
        env = os.environ.copy()
        env["LANG"] = "C"

        res = subprocess.check_output(
            command, stderr=subprocess.STDOUT, env=env,
            shell=kwargs.get("shell", False),
        )
        if as_list:
            return [String.bytes2str(x) for x in res.splitlines()]
        return String.bytes2str(res)

    @staticmethod
    def walk(directory):
        """Return all file path excluding directories and symbolic links."""
        for root, _dirs, files in os.walk(directory):
            for f in sorted(files):
                path = os.path.join(root, f)
                if os.path.islink(path):
                    continue
                yield path
        return

    @staticmethod
    def now_str():
        """Return formatted time."""
        dt = datetime.datetime.now().strftime("%Y%m%d-%H%M%S")
        return dt

    @staticmethod
    def mkstemp(prefix="", dir=None, suffix=None, dt=None):
        """Create a temporary file."""
        if dt is None:
            dt = GefUtil.now_str()

        s = []
        if prefix:
            s.append(prefix)
        if dt:
            s.append(dt)
        real_prefix = "-".join(s)
        if real_prefix:
            real_prefix += "-"

        if dir is None:
            dir = GEF_TEMP_DIR
        return tempfile.mkstemp(dir=dir, prefix=real_prefix, suffix=suffix)

    @staticmethod
    def rmdir(directory, verbose=False, keep_root=False):
        """Recursively delete the target directory."""
        for root, dirs, files in os.walk(directory, topdown=False):
            for file in files:
                file_path = os.path.join(root, file)
                if verbose:
                    info("Removed: {:s}".format(file_path))
                os.remove(file_path)

            for dir in dirs:
                dir_path = os.path.join(root, dir)
                if verbose:
                    info("Removed: {:s}".format(dir_path))
                os.rmdir(dir_path)

        if not keep_root:
            os.rmdir(directory)
        return

    @staticmethod
    def make_position_table(bin_list):
        """Return dict[element] = "1-origin positions joined by comma".

        e.g.: [0xa, 0xb, 0xa] -> {0xa: "1,3", 0xb: "2"}
        Making the table at once is much faster than scanning bin_list for each element,
        which is O(n^2) and gets very slow when a bin has thousands of chunks.
        """
        positions = {}
        for i, x in enumerate(bin_list):
            positions.setdefault(x, []).append(str(i + 1))
        return {x: ",".join(pos) for x, pos in positions.items()}

    @staticmethod
    def make_legend(msg):
        """Apply color settings and generate legend string."""
        color = Config.get_gef_setting("theme.table_heading")
        return Color.colorify(msg.rstrip(), color)

    @staticmethod
    def get_size_str(size, enable_color=True):
        if 0 <= size < 1024:
            return "{:5.1f} B".format(size)
        elif 1024 <= size < 1024 ** 2:
            return "{:5.1f} KB".format(size / 1024)
        elif 1024 ** 2 <= size < 100 * (1024 ** 2): # 1MB~100MB
            return "{:5.1f} MB".format(size / 1024 / 1024)
        elif 100 * (1024 ** 2) <= size < 1024 ** 3: # 100MB~1GB
            if enable_color:
                return Color.colorify("{:5.1f} MB".format(size / 1024 / 1024), "bold yellow")
            else:
                return "{:5.1f} MB".format(size / 1024 / 1024)
        elif 1024 ** 3 <= size:
            if enable_color:
                return Color.colorify("{:5.1f} GB".format(size / 1024 / 1024 / 1024), "bold red")
            else:
                return "{:5.1f} GB".format(size / 1024 / 1024 / 1024)
        return "???"


class Gef:
    """A collection of utility functions that are related to GEF start up."""

    missing_commands = {}

    @staticmethod
    def list_current_commands():
        command_list = []
        res = gdb.execute("help all", to_string=True)
        for line in res.splitlines():
            line = line.strip()
            if " -- " not in line:
                continue
            commands = line.split(" -- ")[0]
            commands = commands.split(", ")
            command_list.extend(commands)
        return command_list

    @staticmethod
    def load_commands():
        """Load all the commands and functions defined by GEF into GDB."""
        global __gef_command_instances__

        DEBUG_PERF_TIME = False
        DEBUG_CHECK_COMMAND_CONFLICT = False

        if DEBUG_CHECK_COMMAND_CONFLICT:
            loaded_commands = Gef.list_current_commands()
            FIRST_TIME = "gef reload" not in loaded_commands # skip check when `gef reload`

        nb_missing = 0
        time_elapsed = []
        for cmd_class in __gef_commands__:
            try:
                if DEBUG_PERF_TIME:
                    start_time_real = time.perf_counter()
                    start_time_proc = time.process_time()

                if DEBUG_CHECK_COMMAND_CONFLICT and FIRST_TIME:
                    if cmd_class._cmdline_ in loaded_commands:
                        warn("{:s} is already loaded".format(Color.boldify(cmd_class._cmdline_)))

                instance = cmd_class() # command loading is here
                __gef_command_instances__[cmd_class._cmdline_] = instance

                if DEBUG_PERF_TIME:
                    end_time_real = time.perf_counter()
                    end_time_proc = time.process_time()

                    time_elapsed.append((
                        cmd_class._cmdline_,
                        end_time_real - start_time_real,
                        end_time_proc - start_time_proc,
                    ))

                if hasattr(cmd_class._aliases_, "__iter__"):
                    if isinstance(cmd_class._aliases_, str):
                        cmd_class_aliases = [cmd_class._aliases_]
                    elif isinstance(cmd_class._aliases_, list):
                        cmd_class_aliases = cmd_class._aliases_
                    else:
                        cmd_class_aliases = []

                    for alias in cmd_class_aliases:
                        if DEBUG_CHECK_COMMAND_CONFLICT and FIRST_TIME:
                            if alias in loaded_commands:
                                warn("{:s} is already loaded".format(Color.boldify(alias)))
                        GefAlias(alias, cmd_class._cmdline_, pre_defined=True)

            except Exception as reason:
                Gef.missing_commands[cmd_class._cmdline_] = reason
                nb_missing += 1

        if DEBUG_PERF_TIME:
            gef_print(titlify("Top 10 commands that took the longest to load"))
            for cmdline, real, cpu in sorted(time_elapsed, key=lambda x: x[1], reverse=True)[:10]:
                gef_print("{:30s} Real:{:.10f} s, CPU:{:.10f} s".format(cmdline, real, cpu))
            gef_print(titlify(""))

        # print message
        gef_print("{:s} is ready, type '{:s}' to start, '{:s}' to configure".format(
            Color.greenify("GEF"),
            Color.colorify("gef", "underline yellow"),
            Color.colorify("gef config", "underline magenta")
        ))

        ver = "{:d}.{:d}".format(sys.version_info.major, sys.version_info.minor)
        gef_print("Loaded {:s} commands (+{:s} aliases) for GDB {:s} using Python engine {:s}".format(
            Color.colorify(len(__gef_command_instances__), "bold green"),
            Color.colorify(len(__gef_alias_instances__), "bold green"),
            Color.colorify(gdb.VERSION, "bold yellow"),
            Color.colorify(ver, "bold red")
        ))

        if nb_missing:
            warn("{:s} command{} could not be loaded, run `{:s}` to know why.".format(
                Color.colorify(nb_missing, "bold red"),
                "s" if nb_missing > 1 else "",
                Color.colorify("gef missing", "underline magenta")
            ))
        return

    @staticmethod
    def gef_prompt(_current_prompt):
        """GEF custom prompt function."""
        if Config.get_gef_setting("gef.readline_compat") is True:
            return "gef> "
        if Color.disable_color():
            return "gef> "
        if is_alive():
            return "\001\033[1;32m\002gef> \001\033[0m\002"
        return "\001\033[1;31m\002gef> \001\033[0m\002"

    @staticmethod
    def fix_venv():
        """Detect if you are in a venv environment and adjust GEF settings."""

        def fast_path():
            """If you installed it with the latest installer, there should be a gev.venv.conf file.
            Interpreting this file will speed up the process."""
            gef_venv_conf = os.path.join(os.path.dirname(GEF_FILEPATH), "gef.venv.conf")
            if not os.path.exists(gef_venv_conf):
                return False

            with open(gef_venv_conf, "rb") as fdw:
                content = fdw.read().decode()
            for line in content.splitlines():
                if line.startswith("GEF_VENV_SYS_PATH="):
                    Gef.GEF_VENV_SYS_PATH = line[len("GEF_VENV_SYS_PATH="):]
                    to_add = []
                    for path in Gef.GEF_VENV_SYS_PATH.split(":"):
                        if path and path not in sys.path:
                            to_add.append(path)
                    sys.path = to_add + sys.path
                    continue

                if line.startswith("GEF_VENV_BIN_PATH="):
                    Gef.GEF_VENV_BIN_PATH = line[len("GEF_VENV_BIN_PATH="):] # used by GefUtil.which()
                    continue

                if line.startswith("GEF_VENV_GEM_HOME="):
                    Gef.GEF_VENV_GEM_HOME = line[len("GEF_VENV_GEM_HOME="):]
                    os.environ["GEM_HOME"] = Gef.GEF_VENV_GEM_HOME
                    continue

            if hasattr(Gef, "GEF_VENV_SYS_PATH"):
                return True
            return False

        def create_skip_config():
            # If .venv-gef is in the default location, it is likely that the user simply forgot to activate the venv.
            # Therefore, for convenience, skip-venv-check is not created.
            default_venv = os.path.join(os.path.dirname(GEF_FILEPATH), ".venv-gef")
            if os.path.exists(default_venv):
                return

            skip_config = os.path.join(GEF_TEMP_DIR, "skip-venv-check")
            open(skip_config, "w").close()
            return

        def slow_path():
            """For those who used the old installer or installed manually.
            It launches python via shell and collects and imports its configuration."""
            # venv check is very slow, so skip if unneeded
            skip_config = os.path.join(GEF_TEMP_DIR, "skip-venv-check")
            if os.path.exists(skip_config):
                return

            # GEF supports pyenv, venv, uv, etc.
            # To achieve this, you need to run python outside of gdb.
            # Modify sys.path based on the results of the execution.

            # check python3 command to get prefix
            try:
                pythonbin = GefUtil.which("python3")
            except FileNotFoundError:
                create_skip_config()
                return

            # check prefix
            cmds = [pythonbin, "-c", "import os,sys;print(sys.prefix)"]
            PREFIX = subprocess.check_output(cmds).decode("utf-8").strip()
            if PREFIX == sys.base_prefix:
                create_skip_config()
                return

            # add path
            cmds = [pythonbin, "-c", "import os,sys;print(os.linesep.join(sys.path).strip())"]
            SITE_PACKAGES_DIRS = subprocess.check_output(cmds).decode("utf-8").split()
            to_add = []
            for path in SITE_PACKAGES_DIRS:
                if path not in sys.path:
                    to_add.append(path)
            sys.path = to_add + sys.path
            return

        fast_path() or slow_path()
        return

    @staticmethod
    def main():
        # check gdb version
        GDB_VERSION = tuple(map(int, re.search(r"(\d+)[^\d]+(\d+)", gdb.VERSION).groups()))
        GDB_MIN_VERSION = (9, 2) # ubuntu 20.04
        if GDB_VERSION < GDB_MIN_VERSION:
            err("GDB version ({:s}) is too old (<{:d}.{:d}). Try upgrading it.".format(
                gdb.VERSION, GDB_MIN_VERSION[0], GDB_MIN_VERSION[1],
            ))
            return

        # create tmp dir
        if not os.path.exists(GEF_TEMP_DIR):
            os.mkdir(GEF_TEMP_DIR) # 0o755
            # GEF runs with root privileges, but it may attach to a normal privileges program.
            # If you want to execute a command that involves stdout redirection for that program,
            # you will need write permission to /tmp/gef.
            os.chmod(GEF_TEMP_DIR, 0o777)

        # check tmp dir access permission
        # This check takes into account the cases where GEF is run with root privileges and with normal user privileges.
        if not os.access(GEF_TEMP_DIR, os.W_OK|os.R_OK|os.X_OK):
            err("Permission denied to {:s}. Please delete it first.".format(GEF_TEMP_DIR))
            return

        # When using a python virtual environment (pyenv, venv, etc.), GDB still loads
        # the system-installed python, so GEF doesn't load site-packages dir from environment.
        # In order to fix it, from the shell we run the python3 binary,
        # take and parse its path, add the path to the current python process.
        Gef.fix_venv()

        # setup prompt
        gdb.prompt_hook = Gef.gef_prompt # noqa

        # common config
        gdb.execute("set confirm off")
        gdb.execute("set verbose off")
        gdb.execute("set pagination off")
        gdb.execute("set output-radix 0x10")

        # gdb history
        gdb.execute("set history save on")
        gdb.execute("set history size 1000")
        gdb.execute("set history filename ~/.gdb_history")

        # print
        gdb.execute("set print elements 0") # remove element count limit
        gdb.execute("set print pretty on")
        gdb.execute("set print array on") # use multi-line when print
        gdb.execute("set print array-indexes on") # add index when print
        gdb.execute("set print asm-demangle on") # demangle
        gdb.execute("set print object on")
        gdb.execute("set print vtbl on")

        try:
            # this will raise a gdb.error unless we're on x86
            gdb.execute("set disassembly-flavor intel")
        except gdb.error:
            # we can safely ignore this
            pass

        # SIGALRM will simply display a message, but gdb won't forward the signal to the process
        gdb.execute("handle SIGALRM print nopass")

        # SIGSEGV/SIGTERM/SIG32(for thread creation)
        gdb.execute("handle SIGSEGV print nopass")
        gdb.execute("handle SIGTERM print nopass")
        gdb.execute("handle SIG32 nostop")

        # stops at first instruction of functions without debug info when stepping
        gdb.execute("set step-mode on")

        # frame
        gdb.execute("set backtrace past-main on")
        gdb.execute("set print frame-arguments all")

        # load all commands that has @register_command decorator.
        Gef.load_commands()

        # load the saved settings
        gdb.execute("gef restore")

        # follow mode
        if Config.get_gef_setting("gef.follow_child"):
            gdb.execute("set follow-fork-mode child")

        # index file
        gdb.execute("save gdb-index {:s}".format(GEF_TEMP_DIR)) # don't use {!r}

        # gdb events configuration
        EventHooking.gef_on_continue_hook(EventHandler.continue_handler)
        EventHooking.gef_on_stop_hook(EventHandler.hook_stop_handler)
        EventHooking.gef_on_new_hook(EventHandler.new_objfile_handler)
        EventHooking.gef_on_exit_hook(EventHandler.exit_handler)
        EventHooking.gef_on_memchanged_hook(EventHandler.memchanged_handler)
        EventHooking.gef_on_regchanged_hook(EventHandler.regchanged_handler)

        if gdb.current_progspace().filename is not None:
            # if here, we are sourcing gef from a gdb session already attached
            # we must force a call to the new_objfile handler
            EventHandler.new_objfile_handler(None)

        # python-interactive
        hexon()

        # If GEF is loaded after gdb is connected
        if is_alive():
            if current_arch is None:
                set_arch()
        return


# restore the translation neutralized just after the imports
argparse._ = ARGPARSE_GETTEXT
del ARGPARSE_GETTEXT


if __name__ == "__main__":
    Gef.main()
